const RTP_FULL_REGISTRY_IDENTITY_643 = true;
const RTP_FULL_REGISTRY_IDENTITY_NOTE = "Persistent BDL-Rotowire player identity registry with player_id-first resolution, alias indexing, unresolved logging, and shared canonical identity layer.";

function _rtpPlayerIndexKey(season){
  return `nba:player:index:v1:S${Number(season || 2026)}`;
}

function _rtpRegistryCanonicalName(name){
  return _rtpCanonicalPlayerName(name || "");
}

async function loadPlayerIndex(env, season){
  try{
    if(!env?.RTP_CACHE?.get) return null;
    const key = _rtpPlayerIndexKey(season);
    const pack = await env.RTP_CACHE.get(key, { type: "json" });
    if(pack && typeof pack === "object") return pack;
  }catch(_){}
  return {
    schema: "rtp_player_identity_registry_v1",
    season: Number(season || 2026),
    by_id: {},
    by_player_id: {},
    alias_to_id: {},
    unresolved: [],
    ts: nowIso()
  };
}

async function ingestBDLPlayerIndex(env, season){
  const index = await loadPlayerIndex(env, season);

  const headers = { "Accept":"application/json" };
  const apiKey = env?.BDL_API_KEY || env?.BDL_KEY || env?.BALLDONTLIE_API_KEY;

  if(apiKey){
    headers["Authorization"] = apiKey.startsWith("Bearer ")
      ? apiKey
      : `Bearer ${apiKey}`;
  }

  let cursor = null;
  let scanned = 0;

  for(let page=0; page<40; page++){
    const u = new URL("https://api.balldontlie.io/v1/players");
    u.searchParams.set("per_page","100");

    if(cursor) u.searchParams.set("cursor", String(cursor));

    const res = await fetch(u.toString(), { headers });

    if(!res.ok) break;

    const json = await res.json();
    const rows = Array.isArray(json?.data) ? json.data : [];

    scanned += rows.length;

    for(const p of rows){
      const pid = p?.id;

      if(pid == null) continue;

      const fullName = String(
        p?.full_name ||
        [p?.first_name, p?.last_name].filter(Boolean).join(" ")
      ).trim();

      const canonical = _rtpRegistryCanonicalName(fullName);

      const aliases = _rtpBuildMinutesAliases(fullName);

      const entry = {
        player_id: pid,
        full_name: fullName,
        canonical_name: canonical,
        first_name: p?.first_name || null,
        last_name: p?.last_name || null,
        team: canonTeamAbbr(
          p?.team?.abbreviation ||
          p?.team_abbreviation ||
          ""
        ),
        position: p?.position || null
      };

      index.by_id[String(pid)] = entry;
      index.by_player_id[String(pid)] = entry;

      for(const alias of aliases){
        if(alias){
          index.alias_to_id[alias] = String(pid);
        }
      }

      if(canonical){
        index.alias_to_id[canonical] = String(pid);
      }
    }

    cursor = json?.meta?.next_cursor;

    if(!cursor) break;
  }

  index.scanned = scanned;
  index.ts = nowIso();

  if(env?.RTP_CACHE?.put){
    await env.RTP_CACHE.put(
      _rtpPlayerIndexKey(season),
      JSON.stringify(index)
    );
  }

  return index;
}

function _rtpResolvePlayerIdentity(index, playerName, playerId){
  if(!index) return null;

  if(playerId != null){
    const byId =
      index.by_player_id?.[String(playerId)] ||
      index.by_id?.[String(playerId)];

    if(byId){
      return {
        resolved: byId,
        matched_by: "player_id"
      };
    }
  }

  const aliases = _rtpBuildMinutesAliases(playerName);

  for(const alias of aliases){
    const foundId = index.alias_to_id?.[alias];

    if(foundId){
      const row =
        index.by_player_id?.[String(foundId)] ||
        index.by_id?.[String(foundId)];

      if(row){
        return {
          resolved: row,
          matched_by: "alias",
          alias
        };
      }
    }
  }

  return {
    resolved: null,
    matched_by: "unresolved",
    aliases
  };
}

async function _rtpLogUnresolvedPlayer(env, season, payload){
  try{
    if(!env?.RTP_CACHE?.put) return;

    const key = `nba:player:index:unresolved:S${Number(season || 2026)}`;
    const existing = await env.RTP_CACHE.get(key, { type:"json" }).catch(()=>null);

    const arr = Array.isArray(existing) ? existing : [];

    arr.push({
      ...payload,
      ts: nowIso()
    });

    await env.RTP_CACHE.put(key, JSON.stringify(arr.slice(-5000)));
  }catch(_){}
}
// ===== END RTP v6.4.3 FULL REGISTRY IDENTITY LAYER =====

