function _rtpPickRawPlayerId(row){
  const keys = ["player_id","playerId","bdl_player_id","id","PlayerID","PLAYER_ID"];
  for (const k of keys) {
    const n = Number(row?.[k]);
    if (Number.isFinite(n) && n > 0) return String(Math.trunc(n));
  }
  return null;
}

function _rtpIdentityAliasesForRecord(rawPlayer, identity){
  const aliases = new Set(_rtpBuildMinutesAliases(rawPlayer));
  const names = [
    identity?.full_name,
    identity?.display_name,
    identity?.canonical_name,
    [identity?.first_name, identity?.last_name].filter(Boolean).join(" ")
  ];
  for (const n of names) {
    for (const a of _rtpBuildMinutesAliases(n)) aliases.add(a);
  }
  return Array.from(aliases).filter(Boolean);
}
