const RTP_LIVE_RUNTIME_REGISTRY_RESOLVER_645 = true;
const RTP_LIVE_RUNTIME_REGISTRY_RESOLVER_NOTE = "Props runtime resolves player minutes through BDL player_id + registry aliases first, reads by_player_id/by_team minutes packs, and only falls back to name matching without synthetic minutes.";

function _rtp645MinutesFromPackById(pack, playerId){
  try{
    const pid = String(playerId || "").trim();
    if(!pid || !pack || typeof pack !== "object") return null;
    const d = pack && pack.data ? pack.data : pack;
    const row = d?.by_player_id?.[pid] || d?.by_id?.[pid] || null;
    if(row && typeof row === "object") return { ...row, source: row.source || row.source_type || "registry_by_player_id" };
  }catch(_){}
  return null;
}

function _rtp645MinutesRuntimeFind(pack, map, index, { playerId, playerName, teamAbbr } = {}){
  // v6.7.7: runtime minutes are resolved ONLY from v676 minutes pack maps.
  // No legacy v641 map lookup, no synthetic fallback, no old loose runtime finder.
  const team = canonTeamAbbr(teamAbbr || "");
  const d = pack && pack.data ? pack.data : pack;
  const names = Array.isArray(playerName) ? playerName.filter(Boolean) : [playerName].filter(Boolean);
  const debug = { minutes_v676_runtime_only_v677:true, attempted:[], team, player_id: playerId != null ? String(playerId) : null };

  if(!d || typeof d !== "object") return { row:null, matched_by:"none", debug:{ ...debug, reason:"missing_minutes_pack" } };

  const normKeysForName = (nm) => {
    const keys = new Set();
    const s = String(nm || "").trim();
    if(!s) return [];
    try { for(const a of (typeof _rtpBuildMinutesAliases === "function" ? _rtpBuildMinutesAliases(s) : [s])) keys.add(String(a||"").trim()); } catch(_) {}
    try { keys.add(_normName(s)); } catch(_) {}
    try { keys.add(_rtpCanonicalPlayerName(s)); } catch(_) {}
    keys.add(s.toLowerCase().replace(/[^a-z0-9]/g,""));
    keys.add(s.toLowerCase().replace(/[^a-z0-9]+/g," ").trim());
    return Array.from(keys).filter(Boolean);
  };

  const decorate = (row, matched_by, extra={}) => {
    if(!row || typeof row !== "object") return null;
    return {
      row: { ...row, source: row.source || row.source_type || "minutes_v676_pack" },
      matched_by,
      resolved_id: row.player_id != null ? String(row.player_id) : (playerId != null ? String(playerId) : null),
      registry_match: null,
      debug: { ...debug, ...extra, matched_by }
    };
  };

  // 1) Direct v676 player id map.
  const pid = String(playerId || "").trim();
  if(pid && d.by_player_id && typeof d.by_player_id === "object"){
    debug.attempted.push("by_player_id");
    const hit = d.by_player_id[pid];
    if(hit) return decorate(hit, "v676_by_player_id", { matched_key:pid });
  }

  // 2) Team-scoped alias map: d.by_team[TEAM][alias]. This is the safest for same-name collisions.
  if(team && d.by_team && d.by_team[team] && typeof d.by_team[team] === "object"){
    debug.attempted.push("by_team_alias");
    for(const nm of names){
      for(const key of normKeysForName(nm)){
        const hit = d.by_team[team][key];
        if(hit) return decorate(hit, "v676_by_team_alias", { matched_key:key, matched_name:nm });
      }
    }
    if(pid && d.by_team[team][pid]) return decorate(d.by_team[team][pid], "v676_by_team_player_id", { matched_key:pid });
  }

  // 3) Global alias map: d.by_name[alias].
  if(d.by_name && typeof d.by_name === "object"){
    debug.attempted.push("by_name_alias");
    for(const nm of names){
      for(const key of normKeysForName(nm)){
        const hit = d.by_name[key];
        if(hit && (!team || canonTeamAbbr(hit.team || hit.team_abbr || "") === team)) return decorate(hit, "v676_by_name_alias", { matched_key:key, matched_name:nm });
      }
    }
  }

  // 4) Final v676 rows scan only, using strict same-team normalized aliases.
  if(Array.isArray(d.rows)){
    debug.attempted.push("rows_scan_alias");
    const wanted = new Set(names.flatMap(normKeysForName));
    for(const r of d.rows){
      const rTeam = canonTeamAbbr(r?.team || r?.team_abbr || "");
      if(team && rTeam !== team) continue;
      const rKeys = normKeysForName(r?.player_name || r?.name || r?.player || r?.full_name || "");
      if(rKeys.some(k => wanted.has(k))) return decorate(r, "v676_rows_alias", { matched_key:rKeys.find(k=>wanted.has(k)) || null });
    }
  }

  return { row:null, matched_by:"none", debug:{ ...debug, reason:"no_v676_map_match" } };
}
// ===== END RTP v6.4.5 LIVE RUNTIME REGISTRY RESOLVER =====


