async function _rtp713PrepareArchiveMinutesAlias(env, { season, game_date } = {}){
  const seasonNum = Number(season || 2026);
  const dateYmd = String(game_date || "").slice(0,10);
  const out = { props_legit_minutes_fallback_v713:true, prepared:false, reason:null, proj_key:null, base_key:null, alias_key:null, source_key:null };
  try{
    if(!dateYmd || !env?.RTP_CACHE?.get || !env?.RTP_CACHE?.put) { out.reason = "missing_env_or_date"; return out; }
    const projKey = `nba:minutes:proj:v1:${dateYmd}:S${seasonNum}`;
    const baseKey = `nba:minutes:base:v1:${dateYmd}:S${seasonNum}`;
    out.proj_key = projKey;
    out.base_key = baseKey;

    // Projected minutes are always primary. If they exist for this historical date, do not override.
    const projPack = await _rtp712KvJson(env, projKey);
    if(projPack?.by_team){ out.prepared = true; out.reason = "exact_projected_minutes_present"; return out; }

    const basePack = await _rtp712KvJson(env, baseKey);
    if(basePack?.by_team){ out.prepared = true; out.reason = "exact_base_minutes_present"; return out; }

    const latest = await _rtp712FindLatestBaseMinutesPack(env, seasonNum);
    if(!latest?.pack?.by_team){ out.reason = "missing_latest_base_minutes"; return out; }

    // For archive historical generation only, create an exact-date base alias so the existing
    // props/script runtime reads base minutes before projections are generated. This is real
    // user-uploaded base minutes, not a synthetic default.
    const aliasPack = {
      ...latest.pack,
      date: dateYmd,
      kind: "base",
      source_type: "base",
      minutes_key: baseKey,
      alias_key: baseKey,
      alias_source_key: latest.key,
      archive_historical_base_alias_v713: true,
      props_legit_minutes_fallback_v713: true,
      props_historical_base_truth_tier_v724: true,
      minutes_truth_tier: "current_base_for_historical",
      minutes_date_true: false,
      calibration_weight: 0.35,
      lineups_locked: false,
      can_drive_lineup: false,
      can_drive_blowout: false,
      lineup_degraded: true
    };
    await env.RTP_CACHE.put(baseKey, JSON.stringify(aliasPack));
    out.prepared = true;
    out.reason = "created_exact_date_base_alias_from_latest";
    out.alias_key = baseKey;
    out.source_key = latest.key;
    return out;
  }catch(e){
    out.reason = `error:${String(e?.message || e)}`;
    return out;
  }
}

