  const reset = _rtp756Bool(item?.reset ?? body?.reset ?? body?.restart ?? body?.fresh, false);
  const explicitCursor = (typeof _rtp756HasExplicitPredCursor === "function") ? _rtp756HasExplicitPredCursor(item, body) : (item?.cursor !== undefined || body?.cursor !== undefined || body?.prop_cursor !== undefined);
  let cursor = explicitCursor
