  const includeSavedItems = _rtp756Bool(item?.include_saved_items ?? body?.include_saved_items, false);
  const props_preview = previewLimit > 0 ? _rtp653BuildPreviewRows(rows, previewLimit) : [];
  const players_with_edges_detail = includeDetail ? _rtp653PlayersWithEdges(_rtp653BuildPreviewRows(rows, Math.min(total, 50))) : [];
  const chunk = rows.slice(cursor, cursor + maxProps);
