    stored:saved?.stored || 0,
    count:saved?.count || 0,
    stored_keys:Array.isArray(saved?.stored_keys) ? saved.stored_keys.slice(0,25) : [],
    calibration_ready_count:saved?.calibration_ready_count || 0,
    projection_guard_rejected:saved?.projection_guard_rejected || 0,
    reject_reasons:saved?.reject_reasons || {},
