function _rtp665SplitCsvLine(line){
  const out = [];
  let cur = "", q = false;
  const s = String(line || "");
  for(let i=0;i<s.length;i++){
    const ch = s[i];
    if(ch === '"'){
      if(q && s[i+1] === '"'){ cur += '"'; i++; }
      else q = !q;
    }else if((ch === "," || ch === "\t") && !q){
      out.push(cur.trim());
      cur = "";
    }else{
      cur += ch;
    }
  }
  out.push(cur.trim());
  return out;
}

