const RTP_ROBUST_MINUTES_MAPPER_642 = true;
const RTP_ROBUST_MINUTES_MAPPER_NOTE = "Robust player/team minutes mapper with canonicalized name matching, punctuation-safe aliases, field fallbacks, and debug bridge diagnostics.";

function _rtpCanonicalPlayerName(name){
  return String(name || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[\'".\u2019\u2018\u201c\u201d,()\-]/g, "")
    .replace(/\b(jr|sr|ii|iii|iv|v)\b/g, "")
    .replace(/\s+/g, "")
    .trim();
}

function _rtpCanonicalTeam(team){
  return canonTeamAbbr(String(team || "").trim().toUpperCase());
}

function _rtpMinutesRowName(row){
  return String(
    row?.player_name ||
    row?.full_name ||
    row?.name ||
    row?.player ||
    row?.Player ||
    ""
  ).trim();
}

function _rtpMinutesRowTeam(row){
  return _rtpCanonicalTeam(
    row?.team_abbr ||
    row?.team ||
    row?.Team ||
    row?.team_name ||
    row?.abbreviation
  );
}

function _rtpBuildMinutesAliases(name){
  const raw = String(name || "").trim();
  const lower = raw.toLowerCase();
  const canonical = _rtpCanonicalPlayerName(raw);

  return Array.from(new Set([
    raw,
    lower,
    canonical,
    lower.replace(/\s+/g, "_"),
    lower.replace(/\s+/g, ""),
    lower.replace(/[\'".\u2019\u2018\u201c\u201d,()\-]/g, ""),
    canonical.replace(/_/g, "")
  ].filter(Boolean)));
}

function _rtpLookupMinutes(pack, teamAbbr, playerName, playerId){
  try {
    const direct = _rtp645MinutesFromPackById(pack, playerId);
    if (direct) return direct;
  } catch (_) {}

  try {
    const robust = _rtpLookupMinutesRobust(pack, teamAbbr, playerName, playerId);
    if (robust && robust.row) return robust.row;
  } catch (_) {}

  if(!pack || !pack.by_team) return null;

  const team = String(teamAbbr||"").toUpperCase();
  const bucket = pack.by_team[team];

  if(!bucket) return null;

  const raw = String(playerName||"").trim();
  const norm = _rtpNormalizeName(raw);
  const underscore = raw.toLowerCase().replace(/\s+/g,"_");

  if(playerId && bucket[String(playerId)]) return bucket[String(playerId)];
  if(bucket[norm]) return bucket[norm];
  if(bucket[raw]) return bucket[raw];
  if(bucket[underscore]) return bucket[underscore];

  for(const k in bucket){
    const r = bucket[k];
    const n = _rtpNormalizeName(
      r?.player_name ||
      r?.name ||
      r?.player ||
      ""
    );
    if(n && n === norm){
      return r;
    }
  }

  return null;
}
