function _rtp6391ApplyBucketSync(node, bucketModel, lane){
  try {
    if (!node || typeof node !== "object" || !bucketModel) return node;
    const ln = String(lane || node.lane || node.type || "").toLowerCase();
    const isTotal = ln === "total" || ln === "totals";
    const isSide = ln === "side" || ln === "spread";
    if (!isTotal && !isSide) return node;
    const p = isTotal ? "total" : "side";
    if (bucketModel[p + "_bucket"] != null) {
      node.bucket = bucketModel[p + "_bucket"];
      node.p_cash_bucket = bucketModel[p + "_bucket"];
    }
    if (bucketModel[p + "_label"] != null) node.bucket_label = bucketModel[p + "_label"];
    if (bucketModel[p + "_bucket_action"] != null) node.bucket_action = bucketModel[p + "_bucket_action"];
    if (bucketModel[p + "_is_play_bucket"] != null) node.is_play_bucket = !!bucketModel[p + "_is_play_bucket"];
    if (bucketModel[p + "_is_worst_bucket"] != null) node.is_worst_bucket = !!bucketModel[p + "_is_worst_bucket"];
    node.bucket_sync_v6391 = true;
  } catch (_) {}
  return node;
}
function _rtp6391SyncFinalDecision(data){
  try {
    if (!data || typeof data !== "object") return data;
    const bm = data.script_bucket_model || data.bucket_model || null;
    if (!bm) return data;
    if (data.final_decision) {
      _rtp6391ApplyBucketSync(data.final_decision.side, bm, "side");
      _rtp6391ApplyBucketSync(data.final_decision.total, bm, "total");
      if (data.final_decision.best) _rtp6391ApplyBucketSync(data.final_decision.best, bm, data.final_decision.best.type || data.final_decision.best.lane);
    }
    if (data.anchors) {
      _rtp6391ApplyBucketSync(data.anchors.side, bm, "side");
      _rtp6391ApplyBucketSync(data.anchors.total, bm, "total");
      if (data.anchors.best) _rtp6391ApplyBucketSync(data.anchors.best, bm, data.anchors.best.type || data.anchors.best.lane);
    }
    if (data.bet_card) {
      if (bm.side_bucket != null) data.bet_card.side_p_cash_bucket = bm.side_bucket;
      if (bm.side_label != null) data.bet_card.side_bucket_label = bm.side_label;
      if (bm.side_bucket_action != null) data.bet_card.side_bucket_action = bm.side_bucket_action;
      if (bm.total_bucket != null) data.bet_card.total_p_cash_bucket = bm.total_bucket;
      if (bm.total_label != null) data.bet_card.total_bucket_label = bm.total_label;
      if (bm.total_bucket_action != null) data.bet_card.total_bucket_action = bm.total_bucket_action;
      data.bet_card.bucket_sync_v6391 = true;
    }
    data.bucket_sync_v6391 = true;
  } catch (_) {}
  return data;
}
