function inferTotalPick(edgePts, marketTotal) {
  const e = Number(edgePts);
  const mt = Number(marketTotal);
  if (!isFinite(e) || !isFinite(mt)) return null;
  const side = e >= 0 ? "OVER" : "UNDER";
  return `${side} ${_fmtLineNum(mt)}`;
}

function inferSidePick(edgePts, home, away, marketSpreadHome) {
  const e = Number(edgePts);
  const ms = Number(marketSpreadHome);
  if (!isFinite(e) || !isFinite(ms) || !home || !away) return null;
  const pickTeam = (e >= 0) ? String(away) : String(home);
  const pickSpread = (pickTeam === String(home)) ? ms : (-ms);
  return _fmtSpread(pickTeam, pickSpread);
}
