function inferSeasonStartYearFromDateISO(dateISO) {
  // NBA season "start year" (e.g., 2025 for 2025-26). Rough rule:
  // Oct(10)-Dec -> same year; Jan-Sep -> previous year.
  try {
    const d = new Date(dateISO + "T00:00:00Z");
    if (Number.isNaN(d.getTime())) return null;
    const y = d.getUTCFullYear();
    const m = d.getUTCMonth() + 1;
    return (m >= 10) ? y : (y - 1);
  } catch (e) { return null; }
}

