function asInt(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === "string" && v.trim() === "") return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.trunc(n);
}
function asNum(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === "string" && v.trim() === "") return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return n;
}


function asFloat(v) {
  return asNum(v);
}

// Normalize market spread inputs into the *model convention* used in this worker:
//   spread_home_model = (home points - away points)
//   positive => home favored by that many points.
//
// Users/feeds often provide spreads in one of two conventions:
//  - Book convention: home -7.5 (favorite) / home +7.5 (underdog)
//  - Model convention: home +7.5 (favorite) / home -7.5 (underdog)
//
// This helper accepts a variety of field names and uses light heuristics
// (moneyline cross-check) to resolve ambiguity.
function normalizeMarketSpreadHome(input, ml_home, ml_away) {
  // Prefer explicit fields.
  const spread_home_book = asFloat(input?.spread_home ?? input?.home_spread);
  const spread_away_book = asFloat(input?.spread_away ?? input?.away_spread);
  const spread_home_model_direct = asFloat(input?.market_spread_home ?? input?.spread_home_model);

  let v = null;

  if (spread_home_book !== null) {
    // Book: home -7.5 => model +7.5
    v = -spread_home_book;
  } else if (spread_home_model_direct !== null) {
    // Already in model convention.
    v = spread_home_model_direct;
  } else if (spread_away_book !== null) {
    // Book: if away is +7.5, home favored => model +7.5. If away is -7.5 (away favored),
    // home is underdog => model -7.5.
    v = spread_away_book > 0 ? spread_away_book : spread_away_book;
  } else {
    // Fallback: ambiguous single spread fields usually are book convention.
    const s = asFloat(input?.market_spread ?? input?.spread ?? input?.line);
    if (s !== null) v = -s;
  }

  // Moneyline heuristic: if ML strongly indicates the opposite favorite, flip.
  const mlh = asFloat(ml_home);
  const mla = asFloat(ml_away);
  if (v !== null && mlh !== null && mla !== null) {
    const homeFav = (mlh < 0 && (mla > 0 || Math.abs(mlh) > Math.abs(mla)));
    const awayFav = (mla < 0 && (mlh > 0 || Math.abs(mla) > Math.abs(mlh)));
    if (homeFav && v < 0) v = Math.abs(v);
    if (awayFav && v > 0) v = -Math.abs(v);
  }

  return v;
}
