function getBdlAuthValue(env) {
  const k = String(env.BDL_API_KEY || "").trim();
  if (!k) return "";
  // BALLDONTLIE docs typically expect: Authorization: YOUR_API_KEY (no Bearer).
  // If the key is already prefixed (e.g. "Bearer ..."), preserve as-is.
  return /^bearer\s+/i.test(k) ? k : k;
}

// Build querystring from a small "qs" object that may include arrays.
// Your code uses: { "per_page": 100, "seasons[]": [season], cursor }
function buildQs(qs = {}) {
  const sp = new URLSearchParams();
  for (const [k, v] of Object.entries(qs || {})) {
    if (v === null || v === undefined) continue;
    if (Array.isArray(v)) {
      for (const item of v) sp.append(k, String(item));
    } else {
      sp.set(k, String(v));
    }
  }
  const s = sp.toString();
  return s ? `?${s}` : "";
}

// Generic BDL fetch w/ CF cache
async function fetchBDL(env, path, { ttl = 120, qs, base } = {}) {
  const auth = getBdlAuthValue(env);
  if (!auth) return null;

  const _base = base || BDL_CORE_BASE;
  const url = `${_base}${path}${buildQs(qs)}`;

  const doFetch = async (u) => {
    const init = { headers: { Authorization: auth } };
    const t = Number(ttl);
    if (Number.isFinite(t) && t > 0) init.cf = { cacheTtl: Math.floor(t) };
    return fetch(u, init);
  };

  let res = await doFetch(url);
  // Some older builds used /nba/v1. If we get a 404 from /v1, retry with the alternate base.
  if (!res.ok && res.status === 404 && _base === BDL_NBA_BASE && typeof BDL_NBA_BASE_ALT !== "undefined") {
    const url2 = `${BDL_NBA_BASE_ALT}${path}${buildQs(qs)}`;
    res = await doFetch(url2);
  }

  if (!res.ok) return null;
  return res.json().catch(() => null);
}

