function nbaSeasonToNbaDotCom(season) {
  // Accept 2025 => "2024-25", or "2024-25" passthrough
  const s = String(season || "").trim();
  if (/^\d{4}-\d{2}$/.test(s)) return s;
  const y = Number(s);
  if (!Number.isFinite(y) || y < 1990 || y > 2100) return "2024-25";
  const prev = y - 1;
  const yy = String(y).slice(-2);
  return `${prev}-${yy}`;
}

function nbaSeasonTypeToNbaDotCom(seasonType) {
  const st = String(seasonType || "regular").toLowerCase();
  if (st.includes("play")) return "Playoffs";
  if (st.includes("inseason") || st.includes("cup")) return "In Season Tournament";
  return "Regular Season";
}

function nbaSeasonTypeKey(seasonType) {
  const s = String(seasonType || "regular").toLowerCase();
  if (s.includes("play")) return "playoffs";
  if (s.includes("inseason") || s.includes("cup")) return "in_season_tournament";
  return "regular_season";
}

