function inferSeasonFromNowNY(){
  // Returns a season "end year" consistent with guessSeason(), but anchored to America/New_York.
  // If month >= Oct, season end year = current year + 1 else current year.
  try{
    const now = new Date();
    // Approx NY by using UTC and shifting -5/-4 hours is messy; for stability we mirror guessSeason().
    const m = now.getUTCMonth() + 1;
    const y = now.getUTCFullYear();
    return m >= 10 ? y + 1 : y;
  }catch(e){
    return guessSeason();
  }
}

function guessSeason() {
  const d = new Date();
  const m = d.getUTCMonth() + 1;
  const y = d.getUTCFullYear();
  return m >= 10 ? y + 1 : y;
}


function normalizeSeasonInput(seasonInput) {
  // Our UX: if user passes 2025 in Dec 2025, they mean 2025-26 start year.
  // BDL v1 uses start-year (2025). NBA.com uses end-year (2026 -> "2025-26").
  const guessedEnd = guessSeason();
  const s = Number(seasonInput);
  if (!s || !Number.isFinite(s)) {
    return { seasonStart: guessedEnd - 1, seasonEnd: guessedEnd };
  }
  // If s is <= current calendar year (or <= guessedEnd-1), treat it as start-year.
  if (s <= guessedEnd - 1) return { seasonStart: s, seasonEnd: s + 1 };
  // Otherwise treat it as end-year.
  return { seasonStart: s - 1, seasonEnd: s };
}

