async function fetchOdds(env, query = {}, { ttl = 120 } = {}) {
  const key = env.ODDS_API_KEY || env.THE_ODDS_API_KEY || env.ODDS_KEY || "";
  if (!key) return [];
  const url = new URL(`${ODDS_BASE}/sports/basketball_nba/odds`);
  url.searchParams.set("regions", query.regions || "us");
  url.searchParams.set("markets", query.markets || "spreads,totals");
  url.searchParams.set("oddsFormat", query.oddsFormat || "american");
  url.searchParams.set("dateFormat", query.dateFormat || "iso");
  url.searchParams.set("apiKey", key);
  const r = await fetch(url.toString(), { cf: { cacheTtl: ttl } });
  if (!r.ok) return [];
  return r.json().catch(() => []);
}

