// --- BDL TeamId maps (abbr <-> team_id) for lookups/backtests (built dynamically + cached)
let NBA_ABBR_TO_TEAM_ID = {};
let BDL_TEAM_ID_TO_ABBR = {};

async function ensureBdlTeamMaps(env) {
  try {
    // 
// Only skip when maps are actually populated
    if (
      NBA_ABBR_TO_TEAM_ID &&
      Object.keys(NBA_ABBR_TO_TEAM_ID).length > 0 &&
      BDL_TEAM_ID_TO_ABBR &&
      Object.keys(BDL_TEAM_ID_TO_ABBR).length > 0
    ) {
      return;
    }

    const cacheKey = "bdl_team_maps_v1";
    const kv = env?.RTP_CACHE;

    // 
// KV warm cache
    if (kv) {
      const cached = await kv.get(cacheKey);
      if (cached) {
        const js = JSON.parse(cached);
        if (js?.abbr_to_id && js?.id_to_abbr) {
          NBA_ABBR_TO_TEAM_ID = js.abbr_to_id;
          BDL_TEAM_ID_TO_ABBR = js.id_to_abbr;
          if (Object.keys(NBA_ABBR_TO_TEAM_ID).length && Object.keys(BDL_TEAM_ID_TO_ABBR).length) return;
        }
      }
    }

    const teams = await fetchBDLAll(env, "/teams", { per_page: 100 }, { ttl: 3600, maxPages: 3, base: BDL_CORE_BASE });
    const nameToAbbr = await _buildTeamNameToAbbr(env); // 
// was missing

    const abbr_to_id = {};
    const id_to_abbr = {};

    for (const t of (teams || [])) {
      const id = Number(t?.id);
      if (!Number.isFinite(id)) continue;

      // 
      // define teamName properly from BDL team object
      const teamName = String(t?.full_name || t?.name || "").trim();
      const teamAbbrRaw = String(t?.abbreviation || t?.abbr || "").trim();

      let abbr = "";

      // Prefer explicit abbreviation if present
      if (teamAbbrRaw && teamAbbrRaw.length === 3) abbr = teamAbbrRaw.toUpperCase();

      // Otherwise map from name
      if (!abbr && teamName) {
        const tn = teamName.toUpperCase();
        const key = teamName.toLowerCase().replace(/\s+/g, " ");

        abbr =
          (NBA_TEAM_NAME_TO_ABBR && NBA_TEAM_NAME_TO_ABBR[tn.toUpperCase()]) ||
          (TEAM_NAME_TO_ABBR && TEAM_NAME_TO_ABBR[tn]) ||
          nameToAbbr.get(key) ||
          "";
      }

      if (!abbr) continue;

      abbr_to_id[abbr] = id;
      id_to_abbr[String(id)] = abbr;
    }

    NBA_ABBR_TO_TEAM_ID = abbr_to_id;
    BDL_TEAM_ID_TO_ABBR = id_to_abbr;

    // 
// Save to KV
    if (kv) {
      await kv.put(
        cacheKey,
        JSON.stringify({
          asOf: new Date().toISOString(),
          abbr_to_id,
          id_to_abbr,
        }),
        { expirationTtl: 7 * 24 * 3600 }
      );
    }
  } catch (e) {
    console.log("ensureBdlTeamMaps_failed", e?.message || String(e));
    // Dont throw  let endpoints continue with empty maps
    NBA_ABBR_TO_TEAM_ID = NBA_ABBR_TO_TEAM_ID || {};
    BDL_TEAM_ID_TO_ABBR = BDL_TEAM_ID_TO_ABBR || {};
  }
}

