//////////////////////////////
// PrizePicks-style text parser
//////////////////////////////

function parsePropsFromText(raw) {
  if (!raw || !raw.trim()) return [];

  const rawLines = raw.split(/\r?\n/);
  const lines = rawLines
    .map((l) => {
      const firstCol = l.split(",")[0] ?? "";
      return firstCol.trim();
    })
    .filter(Boolean)
    .filter((l) => l.toLowerCase() !== "prop_raw");

  const items = [];

  const teamPosLine = /^([A-Z]{2,3})\s*-\s*([A-Z0-9\-]+)$/;
  const vsAtLine = /^(vs|@)\s+([A-Z]{2,3})\b/i;

  let i = 0;

  while (i < lines.length) {
    const L = lines[i];
    const tp = L.match(teamPosLine);

    if (tp && i + 4 < lines.length) {
      const team = tp[1].toUpperCase();
      const pos = tp[2].toUpperCase();
      const player = (lines[i + 1] || "").trim();

      const vsLine = lines[i + 2] || "";
      const vsm = vsLine.match(vsAtLine);
      const homeAway = vsm ? vsm[1] : "";
      const opp = vsm ? vsm[2].toUpperCase() : "";

      const lineStr = (lines[i + 3] || "").replace(/[^\d.]+/g, "");
      const lineVal = parseFloat(lineStr);

      const rawMarket = (lines[i + 4] || "").trim();
      let market = rawMarket.trim();
      const lower = rawMarket.toLowerCase();

      if (lower === "points") market = "pts";
      else if (lower === "rebounds") market = "reb";
      else if (lower === "assists") market = "ast";
      else if (lower === "pra") market = "pra";
      else if (
        lower === "pts+asts" ||
        lower === "pts+ast" ||
        lower === "pts+assists"
      )
        market = "pa";
      else if (
        lower === "pts+rebs" ||
        lower === "pts+reb" ||
        lower === "points+rebounds"
      )
        market = "pr";
      else if (
        lower === "rebs+asts" ||
        lower === "reb+asts" ||
        lower === "rebounds+assists"
      )
        market = "ra";

      items.push({
        prop_raw: [
          lines[i],
          lines[i + 1],
          lines[i + 2],
          lines[i + 3],
          lines[i + 4],
        ].join(" | "),
        team_abbr: team,
        position: pos,
        player_name: player,
        opp_abbr: opp,
        homeAway,
        line: Number.isFinite(lineVal) ? lineVal : null,
        market,
        lean: "",
      });

      i += 5;
      continue;
    }

    i += 1;
  }

  return items.filter(
    (p) =>
      p.player_name &&
      p.team_abbr &&
      p.opp_abbr &&
      typeof p.line === "number" &&
      p.market &&
      p.market.length > 0
  );
}

//////////////////////////////
// Player resolver (BDL)
//////////////////////////////

async function resolvePlayers(env, items) {
  const out = new Map();

  const uniq = Array.from(
    new Set(
      items
        .map((p) => String(p.player_name || "").trim())
        .filter(Boolean)
    )
  );

  const hints = new Map();
  for (const it of items) {
    const full = String(it.player_name || "").trim();
    if (!full || hints.has(full)) continue;
    hints.set(full, {
      team: _normTeam(it.team_abbr || ""),
      pos: _normPos(it.position || ""),
    });
  }

  // New BDL NBA API: prefer /players/active for current-player resolution
  async function searchActive(q) {
    const j = await fetchBDL(
      env,
      `/players/active?search=${encodeURIComponent(q)}&per_page=100`,
      { ttl: 86400, base: BDL_NBA_BASE }
    );
    const arr = Array.isArray(j?.data) ? j.data : (j?.data ? [j.data] : []);
    return arr;
  }

  function score(cand, full, hint) {
    const candName = `${cand.first_name} ${cand.last_name}`;
    const candNorm = _norm(_stripSuffix(candName));
    const wantNorm = _norm(_stripSuffix(full));
    let s = 0;

    if (candNorm === wantNorm) s += 5;
    else if (candNorm.startsWith(wantNorm)) s += 2;
    else {
      const ct = candNorm.split(/\s+/);
      const wt = wantNorm.split(/\s+/);
      const inter = wt.filter((t) => ct.includes(t));
      if (inter.length >= 2) s += 2;
    }

    if (hint?.team) {
      const t = String(cand.team?.abbreviation || "").toUpperCase();
      if (t && t === hint.team) s += 3;
    }
    if (hint?.pos) {
      const p = String(
        cand.position || cand.position_abbreviation || ""
      ).toUpperCase();
      if (p && p === hint.pos) s += 2;
    }
    return s;
  }

  function tokenCandidates(full) {
    const base = String(full || "").trim();
    const toks = base.split(/\s+/).filter(Boolean);
    const last = toks.length ? toks[toks.length - 1] : base;
    const first = toks.length ? toks[0] : base;

    // Prefer: full name -> last name -> first name (last resort)
    const cands = [];
    if (base) cands.push(base);
    if (last && last !== base) cands.push(last);
    if (first && first !== base && first !== last) cands.push(first);
    return Array.from(new Set(cands));
  }

  for (const full of uniq) {
    const hint = hints.get(full) || { team: "", pos: "" };

    let cands = [];
    for (const q of tokenCandidates(full)) {
      const got = await searchActive(q);
      if (got?.length) { cands = got; break; }
    }

    // Dedupe
    const seen = new Set();
    cands = (cands || []).filter((c) => {
      if (!c?.id || seen.has(c.id)) return false;
      seen.add(c.id);
      return true;
    });

    if (!cands.length) continue;

    let best = cands[0];
    let bestS = score(best, full, hint);

    for (const c of cands) {
      const sc = score(c, full, hint);
      if (sc > bestS) {
        best = c;
        bestS = sc;
      }
    }

    if (hint.team) {
      const sameTeam = cands.filter(
        (c) =>
          String(c.team?.abbreviation || "").toUpperCase() === hint.team
      );
      if (sameTeam.length) {
        let tb = sameTeam[0];
        let ts = score(tb, full, hint);
        for (const c of sameTeam) {
          const sc = score(c, full, hint);
          if (sc > ts) {
            tb = c;
            ts = sc;
          }
        }
        best = tb;
      }
    }

    out.set(full, {
      player_id: best.id,
      position: String(
        best.position || best.position_abbreviation || ""
      ).toUpperCase(),
      team_abbr: String(best.team?.abbreviation || "").toUpperCase(),
      team_id: best.team?.id || null,
    });
  }

  return out;
}

//////////////////////////////
// Player stat collectors

//////////////////////////////

function minutesToNumber(minStr) {
  if (!minStr) return "";
  if (typeof minStr === "number") return minStr;
  const [m, s] = String(minStr).split(":").map(Number);
  if (!Number.isFinite(m)) return "";
  return m + (Number.isFinite(s) ? s / 60 : 0);
}

// helper: aggregate full-season stats from /stats as a backfill
async function backfillSeasonFromStats(env, season, missingIds, seasonMap) {
  if (!missingIds || !missingIds.length) return;
  const missingSet = new Set(missingIds);
  const batchSize = 25;

  for (let i = 0; i < missingIds.length; i += batchSize) {
    const chunk = missingIds.slice(i, i + batchSize);
    const qs = new URLSearchParams();
    qs.append("seasons[]", String(season));
    for (const id of chunk) qs.append("player_ids[]", String(id));
    qs.set("per_page", "100");

    const j = await fetchBDL(env, `/stats?${qs.toString()}`, { ttl: 86400, base: BDL_NBA_BASE });
    const rows = j?.data || [];
    if (!rows.length) continue;

    const accMap = new Map();

    for (const row of rows) {
      const pid = row.player?.id || row.player_id;
      if (!pid || !missingSet.has(pid)) continue;

      let acc = accMap.get(pid);
      if (!acc) {
        acc = {
          games_played: 0,
          min: 0,
          pts: 0,
          reb: 0,
          ast: 0,
          stl: 0,
          blk: 0,
          fgm: 0,
          fga: 0,
          fg3m: 0,
          fg3a: 0,
          ftm: 0,
          fta: 0,
          oreb: 0,
          dreb: 0,
          turnover: 0,
          pf: 0,
        };
        accMap.set(pid, acc);
      }

      acc.games_played += 1;
      acc.min += minutesToNumber(row.min);
      acc.pts += Number(row.pts ?? 0);
      acc.reb += Number(row.reb ?? 0);
      acc.ast += Number(row.ast ?? 0);
      acc.stl += Number(row.stl ?? 0);
      acc.blk += Number(row.blk ?? 0);
      acc.fgm += Number(row.fgm ?? 0);
      acc.fga += Number(row.fga ?? 0);
      acc.fg3m += Number(row.fg3m ?? 0);
      acc.fg3a += Number(row.fg3a ?? 0);
      acc.ftm += Number(row.ftm ?? 0);
      acc.fta += Number(row.fta ?? 0);
      acc.oreb += Number(row.oreb ?? 0);
      acc.dreb += Number(row.dreb ?? 0);
      acc.turnover += Number(row.turnover ?? row.turnovers ?? 0);
      acc.pf += Number(row.pf ?? 0);
    }

    for (const [pid, acc] of accMap.entries()) {
      const g = acc.games_played || 1;
      const out = {
        player_id: pid,
        games_played: g,
        min: acc.min / g,
        pts: acc.pts / g,
        reb: acc.reb / g,
        ast: acc.ast / g,
        stl: acc.stl / g,
        blk: acc.blk / g,
        fgm: acc.fgm / g,
        fga: acc.fga / g,
        fg3m: acc.fg3m / g,
        fg3a: acc.fg3a / g,
        ftm: acc.ftm / g,
        fta: acc.fta / g,
        oreb: acc.oreb / g,
        dreb: acc.dreb / g,
        turnover: acc.turnover / g,
        pf: acc.pf / g,
      };

      if (out.fga) out.fg_pct = out.fgm / out.fga;
      if (out.fg3a) out.fg3_pct = out.fg3m / out.fg3a;
      if (out.fta) out.ft_pct = out.ftm / out.fta;

      seasonMap.set(pid, out);
    }
  }
}

async function collectPlayerBags(env, season, playerIds, dateISO) {
  const seasonMap = new Map();
  const l10Map = new Map();
  const advancedMap = new Map();

  if (!playerIds || !playerIds.length) {
    return { seasonMap, l10Map, advancedMap };
  }

  // BDL NBA season_averages expects the season START year (e.g., 2025 for 2025-26).
  // Prefer dateISO if provided; otherwise infer from "season" (your UI typically passes end-year like 2026).
  function seasonStartYearFromInputs(seasonEndYear, dateISO) {
    const y = Number(seasonEndYear);
    // If date provided, use that year; season start is that year if month >= Oct else year-1
    if (dateISO) {
      const m = String(dateISO).trim().match(/^(\d{4})-(\d{2})-/);
      if (m) {
        const yy = Number(m[1]);
        const mm = Number(m[2]);
        return (mm >= 10) ? yy : (yy - 1);
      }
    }
    // Fallback: assume seasonEndYear is end-year (e.g., 2026)  start-year = end-year - 1
    if (Number.isFinite(y) && y > 2000) return y - 1;
    return y;
  }

  const bdlSeason = seasonStartYearFromInputs(season, dateISO);


  // 1) season_averages (single player_id; endpoint rejects batched player_ids[] on some plans)
  {
    const maxPlayers = 220; // guardrail to avoid Worker timeouts on huge slates
    const ids = playerIds.slice(0, maxPlayers);
    const concurrency = 8;

    async function fetchOne(pid) {
      const qs = new URLSearchParams();
      qs.set("season", String(bdlSeason));
      qs.set("season_type", "regular");
      qs.set("type", "base");
      // IMPORTANT: this endpoint expects a single player_id integer (not repeated player_ids[])
      qs.set("player_id", String(pid));

      // Some BDL plans expose this under /season_averages/general; keep this path for compatibility.
      const j = await fetchBDL(
        env,
        `/season_averages/general?${qs.toString()}`,
        { ttl: 86400, base: BDL_NBA_BASE }
      );

      // Normalize response: some variants return {data:[...]} others {data:{...}}.
      const rows = Array.isArray(j?.data) ? j.data : (j?.data ? [j.data] : []);
      for (const row of rows) {
        const pid2 = row.player_id || row.player?.id || pid;
        const stats = row?.stats || row;
        if (!pid2 || !stats) continue;

        const out = {
          player_id: pid2,
          games_played: stats.gp ?? stats.games_played,
          min: stats.min,
          pts: stats.pts,
          reb: stats.reb,
          ast: stats.ast,
          stl: stats.stl,
          blk: stats.blk,
          fgm: stats.fgm,
          fga: stats.fga,
          fg3m: stats.fg3m ?? stats.fg3_made ?? stats.fg3m,
          fg3a: stats.fg3a ?? stats.fg3_attempted ?? stats.fg3a,
          ftm: stats.ftm,
          fta: stats.fta,
          oreb: stats.oreb,
          dreb: stats.dreb,
          turnover: stats.turnover ?? stats.tov,
          pf: stats.pf
        };

        // Derived rates
        if (out.fga) out.fg_pct = out.fgm / out.fga;
        if (out.fg3a) out.fg3_pct = out.fg3m / out.fg3a;
        if (out.fta) out.ft_pct = out.ftm / out.fta;

        seasonMap.set(pid2, out);
      }
    }

    // Concurrency pool
    for (let i = 0; i < ids.length; i += concurrency) {
      const slice = ids.slice(i, i + concurrency);
      await Promise.allSettled(slice.map(fetchOne));
    }
  }

// 2) last 10 games from /stats
  {
    for (const pid of playerIds) {
      const qs = new URLSearchParams();
      qs.append("player_ids[]", pid);
      qs.set("per_page", "10");
      qs.set("sort", "date:desc");

      const j = await fetchBDL(env, `/stats?${qs.toString()}`, { ttl: 600, base: BDL_NBA_BASE });

      const rows = j?.data || [];
      l10Map.set(pid, rows);
    }
  }

  // 3) advanced/usage/tracking season averages (BDL upgraded stats)
  // Prefer season_averages category+type combos; fall back to legacy /stats/advanced if needed.
  {
    const combos = [
      { category: "general", type: "advanced", ttl: 3600 },
      { category: "general", type: "usage", ttl: 3600 },
      { category: "general", type: "misc", ttl: 3600 },
      { category: "general", type: "scoring", ttl: 3600 },
      { category: "tracking", type: "passing", ttl: 3600 },
      { category: "tracking", type: "rebounding", ttl: 3600 },
      { category: "tracking", type: "drives", ttl: 3600 },
      { category: "tracking", type: "efficiency", ttl: 3600 },
    ];

    const batchSize = 75;

    function mergeAdv(pid, statsObj) {
      if (!pid || !statsObj) return;
      const prev = advancedMap.get(pid) || { player_id: pid, stats: {} };
      const s = prev.stats || prev;
      for (const [k, v] of Object.entries(statsObj)) {
        if (v === null || v === undefined) continue;
        if (typeof v === "object") continue;
        // Keep first non-empty value; don't overwrite existing.
        if (s[k] === undefined || s[k] === "") s[k] = v;
      }
      prev.stats = s;
      advancedMap.set(pid, prev);
    }

    for (const combo of combos) {
      for (let i = 0; i < playerIds.length; i += batchSize) {
        const chunk = playerIds.slice(i, i + batchSize);
        const qs = new URLSearchParams();
        qs.set("season", String(bdlSeason));
        qs.set("season_type", "regular");
        qs.set("type", combo.type);
        for (const id of chunk) qs.append("player_ids[]", id);

        const j = await fetchBDL(
          env,
          `/season_averages/${combo.category}?${qs.toString()}`,
          { ttl: combo.ttl, base: BDL_NBA_BASE }
        );

        const rows = j?.data || [];
        for (const row of rows) {
          const pid = row.player_id || row.player?.id;
          const stats = row?.stats || null;
          if (!pid || !stats) continue;
          mergeAdv(pid, stats);
        }
      }
    }

    // Fallback: legacy advanced endpoint (older BDL versions)
    const missing = playerIds.filter((pid) => !advancedMap.has(pid));
    if (missing.length) {
      for (let i = 0; i < missing.length; i += batchSize) {
        const chunk = missing.slice(i, i + batchSize);
        const qs = new URLSearchParams();
        qs.set("season", String(bdlSeason));
        for (const id of chunk) qs.append("player_ids[]", id);

        const j = await fetchBDL(env, `/stats/advanced?${qs.toString()}`, { ttl: 600, base: BDL_NBA_BASE });
        const rows = j?.data || [];
        for (const row of rows) {
          const pid = row.player_id || row.player?.id;
          if (!pid) continue;
          // row may be a flat stat bag already
          mergeAdv(pid, row?.stats || row);
        }
      }
    }
  }

  return { seasonMap, l10Map, advancedMap };
}

