async function collectTeamWells(env, season, teamAbbrs) {
  const teamSet = new Set(
    (teamAbbrs || [])
      .filter(Boolean)
      .map((t) => _normTeam(t))
  );
  if (!teamSet.size) {
    return new Map();
  }

  const fullMap = await buildTeamWellMap(env, season);
  const out = new Map();

  for (const abbr of teamSet) {
    const row = fullMap.get(abbr);
    if (row) out.set(abbr, row);
  }

  return out;
}

//////////////////////////////
// Probability / grading math
//////////////////////////////

function erf(x) {
  return Math.erf(x);
}

// 
// FIXED: sync (no await needed)
function computeSigmaForMarket(row) {
  const mkt = String(row.market || "").toLowerCase();

  const l10_pts = Number(row.l10_pts || 0);
  const l10_reb = Number(row.l10_reb || 0);
  const l10_ast = Number(row.l10_ast || 0);

  const varPts = Math.max(l10_pts, 4);
  const varReb = Math.max(l10_reb, 1.5);
  const varAst = Math.max(l10_ast, 1.5);

  if (mkt === "pts") return Math.sqrt(varPts);
  if (mkt === "reb") return Math.sqrt(varReb);
  if (mkt === "ast") return Math.sqrt(varAst);
  if (mkt === "pra") {
    const varPra = varPts + varReb + varAst;
    return Math.sqrt(varPra);
  }

  const base = Number(row.proj_stat || row.line || 0) || 5;
  return Math.sqrt(Math.max(base, 4));
}
// ---- ELITE PATCH v7.9.4: Player-log sigma + matchup-adjusted mean (guardrailed) ----

function _parseMinToFloat(minStr){
  const s = String(minStr||"").trim();
  if (!s) return null;
  if (s.includes(":")){
    const [mm, ss] = s.split(":");
    const m = Number(mm);
    const sec = Number(ss);
    if (!Number.isFinite(m)) return null;
    return m + (Number.isFinite(sec)? sec/60 : 0);
  }
  const v = Number(s);
  return Number.isFinite(v) ? v : null;
}

function _stddev(arr){
  const xs = arr.filter(x=>Number.isFinite(x));
  const n = xs.length;
  if (n < 2) return null;
  const mean = xs.reduce((a,b)=>a+b,0)/n;
  const v = xs.reduce((a,b)=>a + (b-mean)*(b-mean), 0)/(n-1);
  return Math.sqrt(v);
}

function _clamp(x, lo, hi){ return Math.max(lo, Math.min(hi, x)); }

function _marketToStatKey(mkt){
  const m = String(mkt||"").toLowerCase();
  if (m === "pts" || m === "points") return "pts";
  if (m === "reb" || m === "rebounds") return "reb";
  if (m === "ast" || m === "assists") return "ast";
  if (m === "pra" || m === "pts+reb+ast" || m === "points+rebounds+assists") return "pra";
  if (m === "pr" || m === "pts+reb") return "pr";
  if (m === "pa" || m === "pts+ast") return "pa";
  if (m === "ra" || m === "reb+ast") return "ra";
  if (m === "3pm" || m === "3pt" || m === "3s" || m === "threes") return "fg3m";
  return null;
}

async function _fetchPlayerStatsLogs(env, playerId, seasonStart, maxGames=25){
  const pid = Number(playerId);
  if (!Number.isFinite(pid) || pid <= 0) return null;
  const qs = {
    "player_ids[]": String(pid),
    "seasons[]": String(seasonStart),
    "per_page": "100",
    "postseason": "false",
  };
  const js = await fetchBDL(env, "/stats", { ttl: 3600, qs });
  const data = js?.data || [];
  if (!Array.isArray(data) || !data.length) return [];
  // Sort by game date desc if available
  data.sort((a,b)=>{
    const da = Date.parse(a?.game?.date || a?.game?.start_time || "");
    const db = Date.parse(b?.game?.date || b?.game?.start_time || "");
    return (Number.isFinite(db)?db:0) - (Number.isFinite(da)?da:0);
  });
  return data.slice(0, Math.max(1, maxGames));
}

function _calcSigmaFromLogsForMarket(logs, statKey){
  if (!Array.isArray(logs) || !logs.length) return { sigma:null, n:0, minutes_mean:null, minutes_sd:null };
  const mins = [];
  const vals = [];
  for (const g of logs){
    const pts = Number(g?.pts);
    const reb = Number(g?.reb);
    const ast = Number(g?.ast);
    const fg3m = Number(g?.fg3m);
    const min = _parseMinToFloat(g?.min);
    if (Number.isFinite(min)) mins.push(min);

    let v = null;
    if (statKey === "pts") v = pts;
    else if (statKey === "reb") v = reb;
    else if (statKey === "ast") v = ast;
    else if (statKey === "fg3m") v = fg3m;
    else if (statKey === "pra") v = (Number.isFinite(pts)?pts:0) + (Number.isFinite(reb)?reb:0) + (Number.isFinite(ast)?ast:0);
    else if (statKey === "pr") v = (Number.isFinite(pts)?pts:0) + (Number.isFinite(reb)?reb:0);
    else if (statKey === "pa") v = (Number.isFinite(pts)?pts:0) + (Number.isFinite(ast)?ast:0);
    else if (statKey === "ra") v = (Number.isFinite(reb)?reb:0) + (Number.isFinite(ast)?ast:0);

    if (Number.isFinite(v)) vals.push(v);
  }
  const sigma = _stddev(vals);
  const minutes_mean = mins.length ? (mins.reduce((a,b)=>a+b,0)/mins.length) : null;
  const minutes_sd = _stddev(mins);
  return { sigma, n: vals.filter(x=>Number.isFinite(x)).length, minutes_mean, minutes_sd };
}

function _minutesRiskTag(minutes_mean, minutes_sd){
  if (!Number.isFinite(minutes_mean) || !Number.isFinite(minutes_sd)) return "";
  // High risk: low minutes OR very volatile minutes
  if (minutes_mean < 22 || minutes_sd >= 7) return "high";
  if (minutes_mean < 28 || minutes_sd >= 5) return "med";
  return "";
}

function _matchupAdjPct(teamWell, oppWell){
  // Guardrailed small adjustment based on pace + opponent DRTG + rest
  if (!teamWell || !oppWell) return 0;
  const leaguePace = 99.0;
  const leagueDRTG = 115.0;

  const paceA = Number(teamWell.pace);
  const paceB = Number(oppWell.pace);
  const pace = (Number.isFinite(paceA)?paceA:leaguePace + Number.isFinite(paceB)?paceB:leaguePace)/2;
  const paceFactor = pace / leaguePace;

  const oppDRTG = Number(oppWell.drtg);
  const defAdj = Number.isFinite(oppDRTG) ? (oppDRTG - leagueDRTG)/10 : 0;

  const rA = Number(teamWell.rest_days);
  const rB = Number(oppWell.rest_days);
  const restAdj = (Number.isFinite(rA) && Number.isFinite(rB)) ? (rA - rB)/6 : 0;

  const raw = 0.04*(paceFactor-1) + 0.03*defAdj + 0.01*restAdj;
  return _clamp(raw, -0.08, 0.08);
}

// Main elite calculator per row
function _normName(s) {
  let t = String(s || "").toLowerCase();
  // Normalize unicode (e.g. Joki -> Jokic)
  try {
    if (t.normalize) t = t.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  } catch (e) {}
  t = t
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
  // Drop common suffixes to improve matching
  t = t.replace(/\b(jr|sr|ii|iii|iv|v)\b$/g, "").trim().replace(/\s+/g, " ");
  return t;
}


function _extractMinutesRowsFromSnap(snap) {
  const out = [];
  const d = snap && snap.data ? snap.data : snap;
  if (!d || typeof d !== "object") return out;

  try {
    const teams0 = (d && d.teams && typeof d.teams === "object") ? d.teams : {};
    if (typeof dropFillersFromTeamsMap === "function") {
      const df = dropFillersFromTeamsMap(teams0);
      d.teams = df.teams;
    }
  } catch {}

  if (d.by_player_id && typeof d.by_player_id === "object") {
    for (const [pid, row] of Object.entries(d.by_player_id)) {
      if (!row || typeof row !== "object") continue;
      out.push({ player_id: row.player_id ?? row.id ?? pid, ...row });
    }
  }

  if (d.by_team && typeof d.by_team === "object") {
    for (const [team, bucket] of Object.entries(d.by_team)) {
      if (Array.isArray(bucket)) {
        for (const p of bucket) if (p && typeof p === "object") out.push({ team, ...p });
      } else if (bucket && typeof bucket === "object") {
        for (const [key, p] of Object.entries(bucket)) {
          if (!p || typeof p !== "object") continue;
          const maybeId = /^\d+$/.test(String(key)) ? key : (p.player_id ?? p.id ?? p.bdl_player_id ?? null);
          out.push({ key, team, player_id: p.player_id ?? maybeId, ...p });
        }
      }
    }
  }

  const teams = d && d.teams;
  if (teams && typeof teams === "object" && !Array.isArray(teams)) {
    for (const [team, arr] of Object.entries(teams)) {
      if (!Array.isArray(arr)) continue;
      for (const p of arr) {
        if (!p || typeof p !== "object") continue;
        out.push({ team, ...p });
      }
    }
  }

  const lists = [];
  if (Array.isArray(d && d.players)) lists.push(d.players);
  if (Array.isArray(d && d.rows)) lists.push(d.rows);
  if (Array.isArray(d && d.items)) lists.push(d.items);

  for (const arr of lists) {
    for (const p of arr) {
      if (!p || typeof p !== "object") continue;
      out.push({ ...p, team: p.team || p.team_abbr || p.Team || p.teamAbbr || p.team_code || p.abbr || p.team_code_abbr || null });
    }
  }

  return out;
}

async function handleDebugCalRow(env, url) {
  const key = url.searchParams.get("key");
  if (!key) return jsonResponse({ ok:false, error:"missing_key" }, 400);
  const row = await env.RTP_CACHE.get(key, { type:"json" });
  return jsonResponse({ ok:true, data: row, meta:{ key } });
}

async function handleDebugPredKey(env, url) {
  const key = url.searchParams.get("key");
  if (!key) return jsonResponse({ ok:false, error:"missing_key" }, 400);
  const pred = await env.RTP_CACHE.get(key, { type:"json" });
  return jsonResponse({ ok:true, data: pred, meta:{ key } });
}


function _buildMinutesProjMapFromSnap(snap) {
  const map = new Map();
  const rows = _extractMinutesRowsFromSnap(snap);

  for (const p of rows) {
    const pid =
      p.player_id ?? p.playerId ?? p.id ?? p.bdl_player_id ?? p.bdlId ?? p.bdl_id ?? null;

    const name =
      p.player_name ?? p.name ?? p.player ?? p.full_name ?? p.Player ?? null;

    const minutes =
      p.minutes_proj ?? p.minutes ?? p.min ?? p.mins ?? p.Minutes ?? p.projected_minutes ?? p.projected_min ?? null;

    const team = canonTeamAbbr(p.team || p.team_abbr || p.Team || p.teamAbbr || "");
    const rec = { ...p, minutes, minutes_proj: p.minutes_proj ?? minutes, source: p.source || p.source_type || "proj_minutes_snapshot", team };

    if (pid != null && String(pid).trim()) map.set(String(pid), rec);
    if (name) {
      const aliases = (typeof _rtpBuildMinutesAliases === "function") ? _rtpBuildMinutesAliases(name) : [name];
      for (const a of aliases) {
        const nk = _normName(a);
        if (nk) {
          map.set("name:" + nk, rec);
          if (team) map.set("teamname:" + team + ":" + nk, rec);
        }
      }
    }
  }

  return map;
}

// ===== RTP v6.4.1 PROPS MINUTES BRIDGE HELPERS =====
async function _loadCanonicalMinutesSnap(env, { season, date, prefer = ["proj", "base"] } = {}) {
  const out = { key: null, snap: null, tried: [] };
  try {
    if (!env?.RTP_CACHE?.get || !season || !date) return out;
    const d = String(date || "").slice(0,10);
    const kinds = Array.isArray(prefer) && prefer.length ? prefer : ["proj", "base"];
    for (const kind of kinds) {
      const k = `nba:minutes:${kind}:v1:${d}:S${season}`;
      out.tried.push(k);
      const snap = await env.RTP_CACHE.get(k, { type: "json" }).catch(()=>null);
      if (snap) { out.key = k; out.snap = snap; return out; }
    }
  } catch (_) {}
  return out;
}
function _rtp641FindMinutesRow(minutesMap, { playerId, playerName, teamAbbr } = {}) {
  try {
    if (!minutesMap || typeof minutesMap.get !== "function") return null;
    const pid = String(playerId || "").trim();
    const team = canonTeamAbbr(teamAbbr || "");
    if (pid && minutesMap.has(pid)) {
      const hit = minutesMap.get(pid);
      const ht = canonTeamAbbr(hit?.team || hit?.team_abbr || "");
      if (!ht || !team || ht === team) return hit;
    }
    const names = Array.isArray(playerName) ? playerName : [playerName];
    for (const nm of names) {
      const n = _normName(nm || "");
      if (!n) continue;
      if (team && minutesMap.has("teamname:" + team + ":" + n)) return minutesMap.get("teamname:" + team + ":" + n);
      if (minutesMap.has("name:" + n)) {
        const hit = minutesMap.get("name:" + n);
        const ht = canonTeamAbbr(hit?.team || hit?.team_abbr || "");
        if (!ht || !team || ht === team) return hit;
      }
    }
  } catch (_) {}
  return null;
}
function _rtp641ApplyPlayerMinutesToAdjusted(adjusted, av, minutesRow) {
  const out = { found:false, minutes_proj:null, baseline_minutes:null, source:null, ratio:null, removed_generic_minutes_mult:null };
  try {
    if (!adjusted || !minutesRow) return out;
    const mp = Number(minutesRow.minutes ?? minutesRow.minutes_proj ?? minutesRow.min ?? minutesRow.mins);
    if (!Number.isFinite(mp) || mp <= 0) return out;
    out.found = true;
    out.minutes_proj = Number(mp.toFixed(2));
    out.source = minutesRow.source || minutesRow.source_type || "proj_minutes_snapshot";
    adjusted.projections = adjusted.projections || adjusted.proj || {};
    adjusted.proj = adjusted.proj || adjusted.projections;
    adjusted.multipliers = adjusted.multipliers || {};

    const generic = Number(adjusted.multipliers.minutes_mult);
    if (Number.isFinite(generic) && generic > 0 && Math.abs(generic - 1) > 1e-9) {
      for (const k of ["pts","reb","ast","pra","pr","pa","ra","threes","fg3m","ftm"]) {
        if (Number.isFinite(Number(adjusted.proj[k]))) adjusted.proj[k] = Number(adjusted.proj[k]) / generic;
      }
      out.removed_generic_minutes_mult = Number(generic.toFixed(6));
    }

    const bm = Number(av?.min ?? av?.minutes ?? av?.mp ?? av?.mpg ?? av?.minutes_per_game);
    if (Number.isFinite(bm) && bm > 0) {
      let ratio = mp / bm;
      ratio = Math.max(0.6, Math.min(1.4, ratio));
      out.baseline_minutes = Number(bm.toFixed(2));
      out.ratio = Number(ratio.toFixed(6));
      for (const k of ["pts","reb","ast","threes","fg3m","ftm"]) {
        if (Number.isFinite(Number(adjusted.proj[k]))) adjusted.proj[k] = Number(adjusted.proj[k]) * ratio;
      }
    }

    const pts = Number(adjusted.proj.pts), reb = Number(adjusted.proj.reb), ast = Number(adjusted.proj.ast);
    if (Number.isFinite(pts) && Number.isFinite(reb)) adjusted.proj.pr = pts + reb;
    if (Number.isFinite(pts) && Number.isFinite(ast)) adjusted.proj.pa = pts + ast;
    if (Number.isFinite(reb) && Number.isFinite(ast)) adjusted.proj.ra = reb + ast;
    if (Number.isFinite(pts) && Number.isFinite(reb) && Number.isFinite(ast)) adjusted.proj.pra = pts + reb + ast;
    adjusted.projections = adjusted.proj;

    adjusted.multipliers.minutes_mult = 1;
    adjusted.multipliers.minutes_mult_player = out.ratio || 1;
    adjusted.multipliers.minutes_mult_game = 1;
    adjusted.confidence = adjusted.confidence || {};
    adjusted.confidence.minutes = 0.9;
    const prevOverall = Number(adjusted.confidence.overall);
    adjusted.confidence.overall = Number.isFinite(prevOverall) ? Math.min(0.99, 0.80 * prevOverall + 0.20 * 0.9) : 0.9;
    adjusted.minutes_explain = {
      ...(adjusted.minutes_explain || {}),
      minutes_bridge_v641: true,
      snapshot_player_found: true,
      minutes_proj: out.minutes_proj,
      baseline_minutes: out.baseline_minutes,
      minutes_source: out.source,
      minutes_mult_player: out.ratio || 1,
      minutes_mult_game: 1,
      minutes_mult_total: 1,
      removed_generic_minutes_mult: out.removed_generic_minutes_mult,
      confidence_boosted: true,
      minutes_intel: minutesRow.minutes_intel || null,
      minutes_stability_score: minutesRow.minutes_intel?.minutes_stability_score ?? null,
      minutes_trend: minutesRow.minutes_intel?.minutes_trend ?? null,
      minutes_risk: minutesRow.minutes_intel?.minutes_risk ?? null,
      minutes_floor: minutesRow.minutes_intel?.minutes_floor ?? null,
      minutes_ceiling: minutesRow.minutes_intel?.minutes_ceiling ?? null,
      minutes_sd: minutesRow.minutes_intel?.minutes_sd ?? null,
      props_minutes_runtime_intel_v675: true
    };

    const stability = Number(minutesRow.minutes_intel?.minutes_stability_score);
    const risk = String(minutesRow.minutes_intel?.minutes_risk || "").toLowerCase();
    if (Number.isFinite(stability)) {
      adjusted.confidence.minutes_stability = stability;
      if (stability >= 0.88) adjusted.confidence.overall = Math.min(0.99, Number(adjusted.confidence.overall || 0.8) + 0.025);
      if (stability < 0.70 || risk === "high") adjusted.confidence.overall = Math.max(0.05, Number(adjusted.confidence.overall || 0.8) - 0.045);
    }
    adjusted.flags = Array.isArray(adjusted.flags) ? adjusted.flags : [];
    if (!adjusted.flags.includes("PLAYER_MINUTES_LOCKED")) adjusted.flags.push("PLAYER_MINUTES_LOCKED");
  } catch (e) { out.error = String(e?.message || e); }
  return out;
}
// ===== END RTP v6.4.1 PROPS MINUTES BRIDGE HELPERS =====


// Fetch a SINGLE player's season averages minutes from BDL (NBA).
// Some plans reject batched player_ids[]; this helper uses per-player requests.
async function _fetchSeasonAvgOneNBA(env, playerId, seasonYear){
  const pid = String(playerId || "").trim();
  if (!pid) return null;
  const y = Number(seasonYear);
  const season = Number.isFinite(y) ? y : null;
  if (!season) return null;

  // Canonical
  try {
    const r1 = await fetchBDL(env, "/season_averages", {
      base: BDL_NBA_BASE,
      ttl: 900,
      // BDL often expects player_ids[] rather than player_id
      qs: { season, "player_ids[]": pid }
    });
    const d1 = r1?.data;
    const row1 = Array.isArray(d1) ? d1[0] : (d1 && typeof d1 === "object" ? d1 : null);
    if (row1 && (row1.min != null || row1.minutes != null || row1.mp != null || row1.mpg != null)) return row1;
  } catch {}

  // Compatibility: some variants use player_id
  try {
    const r1b = await fetchBDL(env, "/season_averages", {
      base: BDL_NBA_BASE,
      ttl: 900,
      qs: { season, player_id: pid }
    });
    const d1b = r1b?.data;
    const row1b = Array.isArray(d1b) ? d1b[0] : (d1b && typeof d1b === "object" ? d1b : null);
    if (row1b && (row1b.min != null || row1b.minutes != null || row1b.mp != null || row1b.mpg != null)) return row1b;
  } catch {}

  // Compatibility: some variants use player_id
  try {
    const r1b = await fetchBDL(env, "/season_averages", {
      base: BDL_NBA_BASE,
      ttl: 900,
      qs: { season, player_id: pid }
    });
    const d1b = r1b?.data;
    const row1b = Array.isArray(d1b) ? d1b[0] : (d1b && typeof d1b === "object" ? d1b : null);
    if (row1b && (row1b.min != null || row1b.minutes != null || row1b.mp != null || row1b.mpg != null)) return row1b;
  } catch {}

  // Fallback variant
  try {
    const r2 = await fetchBDL(env, "/season_averages/general", {
      base: BDL_NBA_BASE,
      ttl: 900,
      qs: { season, season_type: "regular", type: "base", player_id: pid }
    });
    const d2 = r2?.data;
    const row2 = Array.isArray(d2) ? d2[0] : (d2 && typeof d2 === "object" ? d2 : null);
    if (row2 && (row2.min != null || row2.minutes != null || row2.mp != null || row2.mpg != null)) return row2;
  } catch {}

  return null;
}

async function _fetchRecentMinutesNBA(env, playerId, seasonStart, lastN = 10) {
  // Uses BDL /stats to compute recent actual minutes (no projections). Returns {ok, avg_min, games, mins[]} or {ok:false,error}
  try {
    const pid = Number(playerId);
    const ss = Number(seasonStart);
    if (!pid || !ss) return { ok: false, error: "bad_args" };

    const url = `/stats?seasons[]=${encodeURIComponent(ss)}&player_ids[]=${encodeURIComponent(pid)}&per_page=100`;
    const js = await bdlFetchJson(env, url);
    if (!js || !Array.isArray(js.data) || js.data.length === 0) return { ok: false, error: "no_data" };

    const toMin = (v) => {
      if (v == null) return null;
      if (typeof v === "number") return isFinite(v) ? v : null;
      const s = String(v).trim();
      if (!s) return null;
      if (s.includes(":")) {
        const [mm, ss2] = s.split(":");
        const m1 = Number(mm);
        const s1 = Number(ss2);
        if (!isFinite(m1) || !isFinite(s1)) return null;
        return m1 + (s1 / 60);
      }
      const n = Number(s);
      return isFinite(n) ? n : null;
    };

    const mins = [];
    for (const row of js.data) {
      const mv = toMin(row.min ?? row.minutes ?? row.mins);
      if (mv != null) mins.push(mv);
    }
    if (mins.length === 0) return { ok: false, error: "no_minutes" };

    const takeN = Math.max(1, Number(lastN) || 10);
    const take = mins.slice(0, takeN);
    const avg = take.reduce((a, b) => a + b, 0) / take.length;

    return { ok: true, avg_min: round2(avg), games: take.length, mins: take };
  } catch (e) {
    return { ok: false, error: String(e && e.message ? e.message : e) };
  }
}

async function elitePropCalcs(env, row, ctx){
  const seasonStart = ctx?.seasonStart;
  const statKey = _marketToStatKey(row.market || row.stat || row.market_type);
  const playerId = row.player_id || row.bdl_player_id || row.id;
  const priorSigma = computeSigmaForMarket(row);

  let sigma_used = priorSigma;
  let sigma_source = "heuristic";
  let n_logs_used = 0;

  let minutes_mean = "";
  let minutes_sd = "";
  let minutes_risk = "";
  let minutes_proj = "";
  let minutes_source = "";

  if (statKey && seasonStart && playerId){
    const cache = ctx.playerLogsCache || (ctx.playerLogsCache = new Map());
    const pid = String(playerId);
    let logs = cache.get(pid);
    if (!logs){
      logs = await _fetchPlayerStatsLogs(env, pid, seasonStart, 25);
      cache.set(pid, logs || []);
    }
    const { sigma, n, minutes_mean: mm, minutes_sd: ms } = _calcSigmaFromLogsForMarket(logs, statKey);
    if (Number.isFinite(mm)) minutes_mean = Number(mm.toFixed(2));
    if (Number.isFinite(ms)) minutes_sd = Number(ms.toFixed(2));
    minutes_risk = _minutesRiskTag(mm, ms);

    // If we have a per-date minutes projection snapshot, use it for props.
// IMPORTANT: No synthetic minutes. If minutes are missing -> leave null/blank.
// Accept minutes=0 as an explicit "out/DNP" signal.
try {
  const mMap = ctx?.minutesProjMap;
  const pName = row?.player_name || row?.player || row?.name || row?.playerName || row?.full_name || "";
  const teamRow = canonTeamAbbr(row?.team_abbr || row?.team || row?.Team || "");
  const mpById = mMap?.get(pid);
  const mpByName = (!mpById && pName) ? mMap?.get("name:" + _normName(pName)) : null;
  const mp = mpById || mpByName;

  if (mp && Number.isFinite(mp.minutes)) {
    // Guard: if snapshot has a team, require match to avoid wrong-name collisions
    const snapTeam = canonTeamAbbr(mp?.team || mp?.team_abbr || mp?.Team || "");
    if (snapTeam && teamRow && snapTeam !== teamRow) {
      // team mismatch -> ignore
    } else {
      minutes_proj = Number(Number(mp.minutes).toFixed(2));
      minutes_source = mp.source || mp.source_type || mp.sourceName || "minutes_snapshot";

      if (mp.minutes === 0) {
        // Explicit 0 minutes: treat as out/DNP
        minutes_mean = 0;
        minutes_risk = "out";
        proj_stat_used = 0;
      } else if (mp.minutes > 0) {
        // Scale projection by minutes ratio vs baseline minutes_mean from logs (if available)
        if (Number.isFinite(mm) && mm > 0 && Number.isFinite(proj_stat_used) && proj_stat_used) {
          let ratio = mp.minutes / mm;
          // guardrails so one bad minutes value can't blow up the prop
          ratio = Math.max(0.6, Math.min(1.4, ratio));
          proj_stat_used = proj_stat_used * ratio;
        }

        // Replace minutes_mean with projected minutes; keep sd from logs if present
        minutes_mean = Number(Number(mp.minutes).toFixed(2));
        if (!minutes_risk) minutes_risk = mp.risk || "";
      }
    }
  }
} catch {}

    if (Number.isFinite(sigma) && sigma > 0 && n >= 6){
      // Shrinkage toward priorSigma so small samples don't overreact
      const priorW = 10;
      const post = Math.sqrt((n*(sigma*sigma) + priorW*(priorSigma*priorSigma)) / (n + priorW));
      sigma_used = post;
      sigma_source = "gamelogs";
      n_logs_used = n;
    }
  }

  // Matchup-adjusted mean (proj_stat_used)
  const lineNum = Number(row.line ?? row.prop_line);
  const projStat = Number(row.proj_stat ?? row.proj_pts ?? 0);
  let elite_adj_pct = 0;
  let proj_stat_used = projStat;

  const teamAbbr = String(row.team_abbr || row.team || row.Team || "").toUpperCase().trim();
  const oppAbbr = String(row.opp_abbr || row.opponent_abbr || row.opponent || row.opp || "").toUpperCase().trim();
  if (teamAbbr && oppAbbr && ctx?.teamWellMap){
    const tw = ctx.teamWellMap.get(teamAbbr);
    const ow = ctx.teamWellMap.get(oppAbbr);
    elite_adj_pct = _matchupAdjPct(tw, ow);
    if (projStat){
      proj_stat_used = projStat * (1 + elite_adj_pct);
    }
  }

  return {
    lineNum,
    projStat,
    sigma_used,
    sigma_source,
    n_logs_used,
    minutes_mean,
    minutes_sd,
    minutes_risk,
    minutes_proj,
    minutes_source,
    proj_stat_used,
    elite_adj_pct: Number((elite_adj_pct||0).toFixed(4)),
  };
}

