function impliedProbFromAmerican(price) {
  const p = Number(price);
  if (!Number.isFinite(p) || p === 0) return null;
  if (p > 0) return 100 / (p + 100);
  return -p / (-p + 100);
}

function pickSideFromLean(row) {
  const lean = String(row.lean || "").toLowerCase();
  if (lean === "more" || lean === "over") return "over";
  if (lean === "less" || lean === "under") return "under";

  const pOver = Number((row.p_cal_over ?? row.model_prob_over ?? row.sim_hit_prob) || 0);
  const pUnder = Number((row.p_cal_under ?? row.model_prob_under ?? (pOver ? 1 - pOver : null)) || 0);
  return pOver >= pUnder ? "over" : "under";
}

function gradePropRow(row, opts = {}) {
  const side = pickSideFromLean(row);
  const pOver = Number((row.p_cal_over ?? row.model_prob_over ?? row.sim_hit_prob) || 0);
  const pUnder = Number((row.p_cal_under ?? row.model_prob_under ?? (pOver ? 1 - pOver : null)) || 0);
  const pModel = side === "over" ? pOver : pUnder;

  const implied = row.price_american
    ? impliedProbFromAmerican(row.price_american)
    : null;
  const targetProb = implied ?? Number(opts.targetProb || 0.525);

  const edge = pModel - targetProb;

  let grade = "";
  if (edge >= 0.07) grade = "A";
  else if (edge >= 0.05) grade = "B";
  else if (edge >= 0.03) grade = "C";
  else if (edge >= 0.01) grade = "D";

  row.side = side;
  row.prob = pModel || "";
  row.edge = Number.isFinite(edge) ? Number(edge.toFixed(4)) : "";
  row.grade = grade;

  return row;
}

//////////////////////////////
// Game stats + grading
//////////////////////////////

async function fetchGameStatsForDate(env, dateISO, playerIds) {
  if (!playerIds || !playerIds.length) return new Map();

  const statsMap = new Map();
  const batchSize = 75;

  for (let i = 0; i < playerIds.length; i += batchSize) {
    const chunk = playerIds.slice(i, i + batchSize);
    const qs = new URLSearchParams();
    qs.append("dates[]", dateISO);
    qs.set("per_page", "100");
    for (const pid of chunk) qs.append("player_ids[]", String(pid));

    const j = await fetchBDL(env, `/stats?${qs.toString()}`, { ttl: 120, base: BDL_NBA_BASE });
    const rows = j?.data || [];

    for (const row of rows) {
      const pid = row.player?.id || row.player_id;
      if (!pid) continue;
      statsMap.set(pid, row);
    }
  }

  return statsMap;
}

function actualFromStats(market, statRow) {
  if (!statRow) return null;

  const pts = Number(statRow.pts ?? 0);
  const reb = Number(statRow.reb ?? 0);
  const ast = Number(statRow.ast ?? 0);

  const m = String(market || "").toLowerCase();

  switch (m) {
    case "pts":
    case "points":
      return pts;
    case "reb":
    case "rebs":
    case "rebounds":
      return reb;
    case "ast":
    case "assists":
      return ast;
    case "pra":
      return pts + reb + ast;
    case "pr":
    case "pts+rebs":
    case "points+rebounds":
      return pts + reb;
    case "pa":
    case "pts+asts":
    case "points+assists":
      return pts + ast;
    case "ra":
    case "rebs+asts":
    case "rebounds+assists":
      return reb + ast;
    default:
      return pts;
  }
}

function normalizeSide(p) {
  const lean = String(p.lean || "").toLowerCase();
  const mkt = String(p.market || "").toLowerCase();
  const raw = String(p.prop_raw || "").toLowerCase();
  const s = lean || mkt || raw;

  if (s.includes("less") || s.includes("under")) return "under";
  if (s.includes("more") || s.includes("over")) return "over";
  return "";
}

async function gradePropsForDate(env, dateISO, items) {
  const resolved = await resolvePlayers(env, items);

  const pids = Array.from(
    new Set(
      items
        .map((i) => resolved.get(i.player_name)?.player_id)
        .filter(Boolean)
    )
  );

  const statsMap = await fetchGameStatsForDate(env, dateISO, pids);

  const graded = [];

  for (const p of items) {
    const resv = resolved.get(p.player_name) || {};
    const pid = resv.player_id || null;

    const market = (() => {
      const m = String(p.market || "").toLowerCase();
      if (["pts", "reb", "ast", "pra", "pr", "pa", "ra"].includes(m))
        return m;
      const raw = String(p.prop_raw || "").toLowerCase();
      if (raw.includes("pra")) return "pra";
      if (raw.includes("pts+asts") || raw.includes("points + assists"))
        return "pa";
      if (raw.includes("pts+rebs") || raw.includes("points + rebounds"))
        return "pr";
      if (raw.includes("rebs+asts") || raw.includes("rebounds + assists"))
        return "ra";
      if (raw.includes("rebounds")) return "reb";
      if (raw.includes("assists")) return "ast";
      if (raw.includes("points") || raw.includes("pts")) return "pts";
      return m || "pts";
    })();

    const lineNum = Number(p.line ?? p.prop_line);
    const side = normalizeSide(p);
    const statsRow = pid ? statsMap.get(pid) : null;
    const actual = statsRow ? actualFromStats(market, statsRow) : null;

    let result = "";
    let diff = "";

    if (Number.isFinite(lineNum) && Number.isFinite(actual)) {
      diff = Number((actual - lineNum).toFixed(2));
      if (Math.abs(actual - lineNum) < 0.01) {
        result = "push";
      } else if (side === "over") {
        result = actual > lineNum ? "win" : "loss";
      } else if (side === "under") {
        result = actual < lineNum ? "win" : "loss";
      }
    }

    graded.push({
      prop_raw: p.prop_raw || "",
      player_name: p.player_name || "",
      team_abbr: p.team_abbr || "",
      opp_abbr: p.opp_abbr || "",
      position: p.position || "",
      market,
      line: Number.isFinite(lineNum) ? lineNum : "",
      side,
      actual,
      diff,
      result,
      date: dateISO,
      player_id: pid || "",
    });
  }

  return graded;
}

