function stripHtml(text) {
  return String(text || "")
    .replace(/<[^>]*>/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

// Very lightweight HTML table parser: returns { header:[], rows:[{...}] }
async function fetchHtmlTableAsRows(env, url) {
  if (!url) return { header: [], rows: [] };

  const res = await fetch(url, { cf: { cacheTtl: 1800 } });
  if (!res.ok) {
    console.error("nbastuffer fetch failed", url, res.status);
    return { header: [], rows: [] };
  }

  const html = await res.text();

  const tableMatch = html.match(/<table[^>]*>[\s\S]*?<\/table>/i);
  if (!tableMatch) return { header: [], rows: [] };
  const tableHtml = tableMatch[0];

  const rowChunks = tableHtml
    .split(/<\/tr>/i)
    .filter((chunk) => /<t[hd][^>]*>/i.test(chunk));

  if (!rowChunks.length) return { header: [], rows: [] };

  let header = [];
  const rows = [];

  rowChunks.forEach((chunk, idx) => {
    const cells = [];
    const cellRegex = /<t[hd][^>]*>([\s\S]*?)<\/t[hd]>/gi;
    let m;
    while ((m = cellRegex.exec(chunk)) != null) {
      const txt = stripHtml(m[1]);
      if (txt) cells.push(txt);
    }
    if (!cells.length) return;

    if (idx === 0) {
      header = cells.map((h) =>
        h
          .toLowerCase()
          .replace(/[^a-z0-9]+/gi, "_")
          .replace(/^_+|_+$/g, "")
      );
    } else {
      const obj = {};
      header.forEach((h, i) => {
        obj[h] = cells[i] ?? "";
      });
      rows.push(obj);
    }
  });

  return { header, rows };
}

async function indexNbastufferByTeam(rows) {
  const map = new Map();
  const nameToAbbr = await _buildTeamNameToAbbr(env);

  for (const r of rows || []) {
    const rawTeam =
      r.teams ||
      r.team ||
      r.team_name ||
      r.team_abbr ||
      r.team_abbreviation ||
      r.teamname ||
      "";
    const teamName = String(rawTeam || "").trim();
    if (!teamName) continue;
    const tn = teamName.toUpperCase();
    const abbr =
      (NBA_TEAM_NAME_TO_ABBR && NBA_TEAM_NAME_TO_ABBR[tn.toUpperCase()]) ||
      (teamName.length === 3 ? tn : "");
    if (!abbr) continue;

    map.set(abbr, r);
  }

  return map;
}

// Pull schedule / travel / extra rest analysis into a Map (if we want later)
async function fetchRestScheduleMap(env) {
  const url = env.NBA_STUFFER_SCHED_REST_URL;
  if (!url) return new Map();

  const { rows } = await fetchHtmlTableAsRows(env, url);
  if (!rows.length) return new Map();

  return indexNbastufferByTeam(rows);
}

function toIntSafe(v) {
  if (v === null || v === undefined || v === "") return 0;
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}

// Uses env.NBA_STUFFER_REST_DAYS_CSV (Schedule Rest Days Analysis CSV)
async function fetchRestDaysMap(env) {
  const csvUrl = env.NBA_STUFFER_REST_DAYS_CSV;
  if (!csvUrl) return new Map();

  const res = await fetch(csvUrl, { cf: { cacheTtl: 3600 } });
  if (!res.ok) {
    console.warn("rest_days_csv fetch failed", csvUrl, res.status);
    return new Map();
  }

  const text = await res.text();
  const { rows } = parseCsv(text);

  const nameToAbbr = await _buildTeamNameToAbbr(env);

  const map = new Map();
  for (const row of rows) {
    const teamName = (row["TEAMS"] || row["Teams"] || "").trim();
    if (!teamName) continue;
    const tn = teamName.trim();
    const key = tn.toLowerCase().replace(/\s+/g, " ");
    const abbr =
      (NBA_TEAM_NAME_TO_ABBR && NBA_TEAM_NAME_TO_ABBR[tn.toUpperCase()]) ||
      nameToAbbr.get(key) ||
      nameToAbbr.get(tn.toLowerCase()) ||
      (tn.length === 3 ? tn.toUpperCase() : "");
    if (!abbr) continue;
    map.set(abbr, row);
  }
  return map;
}

function extractRestDaysFromRow(restRow) {
  if (!restRow) return "";

  const candidates = [
    "AVG REST DAYS",
    "AVG_REST_DAYS",
    "AVERAGE REST DAYS",
    "REST_DAYS",
    "REST DAYS",
    "AVG REST",
    "AVG_REST",
  ];

  for (const c of candidates) {
    if (restRow[c] != null && restRow[c] !== "") {
      const n = Number(restRow[c]);
      if (Number.isFinite(n)) return n;
    }
  }

  const totalGames = toIntSafe(
    restRow["TOTAL GAMES"] ||
      restRow["TOTALGAMES"] ||
      restRow["TOTAL_GAMES"]
  );
  return totalGames || "";
}

