async function buildTeamWell(env, seasonStart, seasonEnd, opts = {}) {
  const teamsRes = await fetchBDL(env, `/teams?per_page=100`, {
    ttl: 86400,
  });
  const teams = teamsRes?.data || [];

  const games = await fetchAllGamesForSeason(env, seasonStart);

  const teamAgg = new Map(); // team_id -> { games, ptsFor, ptsAgainst }

  function bump(team, scored, allowed) {
    if (!team || !team.id) return;
    const id = team.id;
    let acc = teamAgg.get(id);
    if (!acc) {
      acc = { games: 0, ptsFor: 0, ptsAgainst: 0 };
      teamAgg.set(id, acc);
    }
    acc.games += 1;
    acc.ptsFor += scored;
    acc.ptsAgainst += allowed;
  }

  for (const g of games) {
    const home = g.home_team;
    const away = g.visitor_team;

    // 
// Only count completed games with real scores
    const hsRaw = g.home_team_score;
    const asRaw = g.visitor_team_score;

    if (hsRaw == null || asRaw == null) continue;

    const hs = Number(hsRaw);
    const as = Number(asRaw);

    // NBA games will never be 0-0; treat that as "not played"
    if (!Number.isFinite(hs) || !Number.isFinite(as)) continue;
    if (hs === 0 && as === 0) continue;

    bump(home, hs, as);
    bump(away, as, hs);
  }

  // Odds are useful for market-aware features, but TeamWell MUST NOT fail if ODDS_API_KEY
  // is missing or the upstream is temporarily unavailable.
  let oddsMap = new Map();
  try {
    const oddsJson = await fetchOdds(
      env,
      { regions: "us", markets: "spreads,totals" },
      { ttl: 300 }
    );
    oddsMap = buildOddsTeamMap(oddsJson);
  } catch (e) {
    console.log("odds fetch failed (non-fatal)", e);
    oddsMap = new Map();
  }

  let fourFactors = new Map();
  try {
    fourFactors = await fetchNbaFourFactorsMap(env, seasonEnd);
  } catch (e) {
    console.log("four factors fetch failed", e);
  }

  let nbaAdvancedMap = new Map();
  try {
    nbaAdvancedMap = await fetchNbaTeamAdvancedMap(env, seasonEnd);
  } catch (e) {
    console.log("advanced fetch failed", e);
  }

  // These are produced by  and stored in KV as nba:legacy_nba_cache_removed:<stage>:<season>:regular_season
  // NBA.com cache keys use season like "2024-25" and season_type like "regular_season".
  // We compute both in a stable way here.
  const seasonNbaCom = toNbaSeasonString(seasonEnd);
  const stKey = nbaSeasonTypeKey('regular');

  // Shot location / profile rates (best-effort)
  let shotLocRates = null;
  let trThreeRate = null;
  let shotPasteRates = null;
  try {
    shotLocRates = await fetchNbaComTeamShotLocationRates(env, seasonEnd, "regular");
  } catch (e) { console.log("shotloc fetch failed", e); }
  try {
    trThreeRate = await fetchTeamRankingsThreePointRateMap(env);
  } catch (e) { console.log("teamrankings 3pt rate fetch failed", e); }
  try {
    shotPasteRates = await fetchPastedTeamShotRatesMap(env, seasonStart, seasonEnd, 'regular');
  } catch (e) { /* ignore */ }

  const stageItems = (payload) => {
    if (!payload) return [];
    // Some KV writes (older drafts / manual loads) store the array directly.
    if (Array.isArray(payload)) return payload;
    if (Array.isArray(payload?.data)) return payload.data;
    // Expected KV shape: { season, season_type, stage, ts, items:[...] }
    if (Array.isArray(payload.items)) return payload.items;
    // Some debug/raw shapes: { ok:true, data:{ preview:[...]} } or { data:{ items:[...] } }
    const d = payload.data || payload;
    if (d && Array.isArray(d.items)) return d.items;
    if (d && Array.isArray(d.preview)) return d.preview;
    if (d && d.data && Array.isArray(d.data.items)) return d.data.items;
    if (d && d.data && Array.isArray(d.data.preview)) return d.data.preview;
    return [];
  };

  const pickNum = (obj, keys) => {
    for (const k of keys) {
      if (obj && obj[k] != null && obj[k] !== '') {
        const n = Number(obj[k]);
        if (Number.isFinite(n)) return n;
      }
    }
    return '';
  };

  const tryStagePayload = async (stage) => {
    const candidates = [
      nbaKey(stage, seasonNbaCom, stKey),
      // fallback keys (older drafts)
      nbaKey(stage, seasonNbaCom, 'regular'),
      nbaKey(stage, seasonNbaCom, 'regularseason'),
      nbaKey(stage, seasonNbaCom, 'regular_season'),
    ];
    for (const k of candidates) {
      const p = await kvGetJson(env, k);
      if (p) return p;
    }
    return null;
  };

  let miscMap = new Map();
  try {
    const miscPayload = await tryStagePayload('misc');
    for (const it of stageItems(miscPayload)) {
      const abbr = String(it?.team_abbr || it?.TEAM_ABBREVIATION || '').toUpperCase();
      if (!abbr) continue;
      miscMap.set(abbr, it);
    }
    // Fallback: if we didn't get items (KV missing/out-of-sync), fetch live once and retry.
    if (miscMap.size === 0) {
      await nbaStageBuild('misc', seasonEnd, 'regular', env, 1, 86400);
      const miscPayload2 = await tryStagePayload('misc');
      for (const it of stageItems(miscPayload2)) {
        const abbr = String(it?.team_abbr || it?.TEAM_ABBREVIATION || '').toUpperCase();
        if (!abbr) continue;
        miscMap.set(abbr, it);
      }
    }
  } catch (e) {
    console.log('misc cache fetch failed', e);
  }

  let ptshotMap = new Map();
  try {
    const ptPayload = await tryStagePayload('ptshot');
    for (const it of stageItems(ptPayload)) {
      const abbr = String(it?.team_abbr || it?.TEAM_ABBREVIATION || '').toUpperCase();
      if (!abbr) continue;
      ptshotMap.set(abbr, it);
    }
    // Fallback: if we didn't get items (KV missing/out-of-sync), fetch live once and retry.
    if (ptshotMap.size === 0) {
      await nbaStageBuild('ptshot', seasonEnd, 'regular', env, 1, 86400);
      const ptPayload2 = await tryStagePayload('ptshot');
      for (const it of stageItems(ptPayload2)) {
        const abbr = String(it?.team_abbr || it?.TEAM_ABBREVIATION || '').toUpperCase();
        if (!abbr) continue;
        ptshotMap.set(abbr, it);
      }
    }
  } catch (e) {
    console.log('ptshot cache fetch failed', e);
  }

  const restDaysMap = await fetchRestDaysMap(env);
  const restSchedMap = await fetchRestScheduleMap(env);

  let stufferRestMap = new Map();
  try {
    stufferRestMap = await fetchStufferRestDaysMap(env, seasonEnd);
  } catch (e) {
    // optional
  }

  const rows = [];

  const nameToAbbr = await _buildTeamNameToAbbr(env);

  for (const t of teams) {
    const id = t.id;
    // Team name can come from BDL team objects; normalize safely
    const teamName = String(t?.full_name || t?.name || t?.team_name || '').trim();
    const tn = teamName.trim();
    const key = tn.toLowerCase().replace(/\s+/g, " ");
    const abbr =
      (NBA_TEAM_NAME_TO_ABBR && NBA_TEAM_NAME_TO_ABBR[tn.toUpperCase()]) ||
      nameToAbbr.get(key) ||
      nameToAbbr.get(tn.toLowerCase()) ||
      (tn.length === 3 ? tn.toUpperCase() : "");
    const conf = t.conference || "";

    if (!conf || (conf !== "East" && conf !== "West")) continue;

    const agg = teamAgg.get(id) || null;

    let ortg = "";
    let drtg = "";
    let net_rtg = "";
    let pace_team = "";

    if (agg && agg.games > 0) {
      const pf = agg.ptsFor / agg.games;
      const pa = agg.ptsAgainst / agg.games;
      const tot = pf + pa;

      ortg = Number(pf.toFixed(1));
      drtg = Number(pa.toFixed(1));
      net_rtg = Number((pf - pa).toFixed(1));
      pace_team = Number((tot / 2).toFixed(1));
    }

    const odds = oddsMap.get(abbr) || {};
    const ff = fourFactors.get(abbr) || {};
    const adv = nbaAdvancedMap.get(abbr) || {};

    const misc = miscMap.get(abbr) || {};
    const pt = ptshotMap.get(abbr) || {};

    // Prefer NBA.com Advanced ratings when available; fallback to BDL-derived approximations.
    if (Number.isFinite(adv.ortg)) ortg = adv.ortg;
    if (Number.isFinite(adv.drtg)) drtg = adv.drtg;
    if (Number.isFinite(adv.net_rtg)) net_rtg = adv.net_rtg;
    if (Number.isFinite(adv.pace_team)) pace_team = adv.pace_team;

    const restRow = restDaysMap.get(abbr) || {};
    const schedRow = restSchedMap.get(abbr) || {};

    const travelMiles =
      Number(
        schedRow.travel_miles ||
          schedRow.total_travel_miles ||
          schedRow.travel_distance ||
          0
      ) || 0;

    const restDaysVal = extractRestDaysFromRow(restRow);

    const shot = (shotLocRates && shotLocRates[abbr]) ? shotLocRates[abbr] : null;
    const shotPaste = (shotPasteRates && shotPasteRates[abbr]) ? shotPasteRates[abbr] : null;

    const _numOrNull = (v) => {
      const n = Number(v);
      return Number.isFinite(n) ? n : null;
    };

    const threeRateVal = (shotPaste && shotPaste.three_rate != null && isFinite(Number(shotPaste.three_rate)))
      ? Number(shotPaste.three_rate)
      : (shot && shot.three_rate != null && isFinite(Number(shot.three_rate)))
        ? Number(shot.three_rate)
        : (trThreeRate && trThreeRate[abbr] != null && isFinite(Number(trThreeRate[abbr])))
          ? Number(trThreeRate[abbr])
          : "";

    const rimRateVal = (shotPaste && shotPaste.rim_rate != null && isFinite(Number(shotPaste.rim_rate)))
      ? Number(shotPaste.rim_rate)
      : (shot && shot.rim_rate != null && isFinite(Number(shot.rim_rate)))
        ? Number(shot.rim_rate)
        : null;

    const midRateVal = (shotPaste && shotPaste.mid_rate != null && isFinite(Number(shotPaste.mid_rate)))
      ? Number(shotPaste.mid_rate)
      : (shot && shot.mid_rate != null && isFinite(Number(shot.mid_rate)))
        ? Number(shot.mid_rate)
        : null;

    const row = {
      team_id: id,
      team_abbr: abbr,

      team_name: t.full_name || t.name || abbr,
      conference: conf,
      division: t.division || "",

      ortg,
      drtg,
      net_rtg,
      pace_team,

      e_fg_pct: ff.e_fg_pct ?? "",
      three_rate: threeRateVal,
      rim_rate: rimRateVal,
      mid_rate: midRateVal,
      ft_rate: ff.ft_rate ?? "",
      off_reb_pct: ff.orb_pct ?? "",
      def_reb_pct: ff.dreb_pct ?? "",
      turnover_pct: ff.tov_pct_off ?? "",

      // NBA.com Misc (team context scoring)
      misc_pts_paint: pickNum(misc, ['PTS_PAINT','PTS_IN_PAINT','PTS_PNT','PTS_PAINT_PG']),
      misc_pts_off_tov: pickNum(misc, ['PTS_OFF_TOV','PTS_OFF_TO','PTS_OFF_TOV_PG']),
      misc_pts_2nd_chance: pickNum(misc, ['PTS_2ND_CHANCE','PTS_2ND_CHANCE_PG','PTS_2ND']),
      misc_pts_fb: pickNum(misc, ['PTS_FB','PTS_FASTBREAK','PTS_FB_PG']),

      // NOTE: AST/TO is not part of NBA.com 'Misc' team measure; pull from Advanced when available
      misc_ast_to: pickNum(adv, ['AST_TO','AST_TO_RATIO','AST/TO','AST_TO_R']),

      // NBA.com Player Tracking Team Defense (leaguedashptteamdefend)
      pt_def_freq: pickNum(pt, ['FREQ','FREQUENCY']),
      pt_def_fgm: pickNum(pt, ['D_FGM','DFGM']),
      pt_def_fga: pickNum(pt, ['D_FGA','DFGA']),
      pt_def_fg_pct: pickNum(pt, ['D_FG_PCT','DFG_PCT','DFG%']),
      pt_def_normal_fg_pct: pickNum(pt, ['NORMAL_FG_PCT','NORMALFGPCT']),
      pt_def_pct_plusminus: pickNum(pt, ['PCT_PLUSMINUS','PCT+/-','PCT_PLUS_MINUS']),

      home_spread: odds.spread ?? "",
      away_spread: odds.spread != null ? -odds.spread : "",
      implied_total: odds.total ?? "",

      rest_days: restDaysVal ?? "",
      travel_miles: travelMiles,
      form_offense_z: 0,
      form_defense_z: 0,
      form_pace_z: 0,
    };

    rows.push(row);
  }

  rows.sort((a, b) =>
    (a.team_name || "").localeCompare(b.team_name || "")
  );

  return rows;
}

async function buildTeamWellMap(env, seasonInput, opts = {}) {
  const { seasonStart, seasonEnd } = normalizeSeasonInput(seasonInput);
  const force = !!opts.force;
  let rows = force ? null : await kvGetJSON(env, `nba:teamwell:${seasonStart}:v3`);
  // If cached TeamWell exists but is missing newer NBA.com fields, auto-rebuild so slate edges populate.
  const _missingNewFields = (arr) => {
    if (!Array.isArray(arr) || !arr.length) return true;
    const r0 = arr[0] || {};
    const need = ['misc_pts_paint','misc_pts_off_tov','misc_pts_2nd_chance','misc_pts_fb','pt_def_fg_pct','pt_def_pct_plusminus','off_reb_pct','def_reb_pct'];
    for (const k of need) {
      if (!(k in r0)) return true;
      if (r0[k] === '' || r0[k] === null || r0[k] === undefined) return true;
    }
    return false;
  };
  if (rows && _missingNewFields(rows)) rows = null;

  if (!rows) {
    rows = await buildTeamWell(env, seasonStart, seasonEnd, {});
    await kvPutJSON(env, `nba:teamwell:${seasonStart}:v3`, rows, 6 * 3600);
  }

  const map = new Map();
  const nameToAbbr = await _buildTeamNameToAbbr(env);
  for (const r of rows) {
    const teamName = (pickAny(r, "team_name", "Team", "full_name", "FullName", "Name") || "").toString();
    const tn = teamName.trim();
    const key = tn.toLowerCase().replace(/\s+/g, " ");
    const abbr =
      (NBA_TEAM_NAME_TO_ABBR && NBA_TEAM_NAME_TO_ABBR[tn.toUpperCase()]) ||
      nameToAbbr.get(key) ||
      nameToAbbr.get(tn.toLowerCase()) ||
      (tn.length === 3 ? tn.toUpperCase() : "");
    if (!abbr) continue;
    map.set(abbr, r);
  }
  return map;
}

function mergeTeamWell(row, well) {
  if (!well) return;

  row.team_id =
    pickAny(well, "team_id", "TeamID", "id") ?? row.team_id ?? "";
  row.team_abbr =
    row.team_abbr ||
    pickAny(well, "team_abbr", "team", "Team", "Abbreviation") ||
    "";
  row.team_name =
    pickAny(
      well,
      "team_name",
      "TeamName",
      "full_name",
      "FullName",
      "Name"
    ) ?? row.team_name ?? "";
  row.conference =
    pickAny(well, "conference", "Conference") ??
    row.conference ??
    "";
  row.division =
    pickAny(well, "division", "Division") ?? row.division ?? "";

  const ortg = pickAny(
    well,
    "ortg",
    "offensive_rating",
    "OffensiveRating",
    "off_rating",
    "OffRating"
  );
  if (ortg !== undefined) row.ortg = ortg;

  const drtg = pickAny(
    well,
    "drtg",
    "defensive_rating",
    "DefensiveRating",
    "def_rating",
    "DefRating"
  );
  if (drtg !== undefined) row.drtg = drtg;

  const net = pickAny(well, "net_rtg", "net_rating", "NetRating");
  if (net !== undefined) row.net_rtg = net;

  const paceTeam = pickAny(
    well,
    "pace_team",
    "pace",
    "Pace",
    "possessions_per_game",
    "PossessionsPerGame"
  );
  if (paceTeam !== undefined) row.pace_team = paceTeam;

  const efg = pickAny(
    well,
    "e_fg_pct",
    "effective_field_goal_percentage",
    "EffectiveFieldGoalPercentage",
    "efg_pct",
    "EFG"
  );
  if (efg !== undefined) row.e_fg_pct = efg;

  const ftRate = pickAny(
    well,
    "ft_rate",
    "free_throw_rate",
    "FreeThrowRate",
    "ftr",
    "FTR"
  );
  if (ftRate !== undefined) row.ft_rate = ftRate;

  const offReb = pickAny(
    well,
    "off_reb_pct",
    "offensive_rebound_percentage",
    "OffensiveReboundPct",
    "OffRebPct",
    "orb_pct"
  );
  if (offReb !== undefined) row.off_reb_pct = offReb;

  const defReb = pickAny(
    well,
    "def_reb_pct",
    "defensive_rebound_percentage",
    "DefRebPct",
    "dreb_pct"
  );
  if (defReb !== undefined) row.def_reb_pct = defReb;

  const tovPct = pickAny(
    well,
    "turnover_pct",
    "turnover_percentage",
    "TurnoverPct",
    "tov_pct",
    "TOVPct",
    "tov_pct_off"
  );
  if (tovPct !== undefined) row.turnover_pct = tovPct;

  const homeSpread = pickAny(
    well,
    "home_spread",
    "HomeSpread",
    "home_spread_line"
  );
  if (homeSpread !== undefined) row.home_spread = homeSpread;

  const awaySpread = pickAny(
    well,
    "away_spread",
    "AwaySpread",
    "away_spread_line"
  );
  if (awaySpread !== undefined) row.away_spread = awaySpread;

  const total = pickAny(
    well,
    "implied_total",
    "ImpliedTotal",
    "game_total",
    "Total"
  );
  if (total !== undefined) row.implied_total = total;

  const rest = pickAny(well, "rest_days", "RestDays");
  if (rest !== undefined) row.rest_days = rest;

  const miles = pickAny(well, "travel_miles", "TravelMiles");
  if (miles !== undefined) row.travel_miles = miles;

  const formOff = pickAny(well, "form_offense_z", "FormOffenseZ");
  if (formOff !== undefined) row.form_offense_z = formOff;

  const formDef = pickAny(well, "form_defense_z", "FormDefenseZ");
  if (formDef !== undefined) row.form_defense_z = formDef;

  const formPace = pickAny(well, "form_pace_z", "FormPaceZ");
  if (formPace !== undefined) row.form_pace_z = formPace;
}

//////////////////////////////
// Game model / game lines
//////////////////////////////


// ===============================
// Elite TeamWell (BDL Team Season Averages)
// ===============================

function teamWellKey(season, seasonType) {
  const s = asInt(season);
  const st = (seasonType || "regular").toString().toLowerCase();
  return `nba:teamwell:${s}:${st}:bdl`;
}

async function fetchBDLTeamSeasonAverages(env, category, season, seasonType, type, opts = {}) {
  const qs = new URLSearchParams();
  qs.set("season", String(asInt(season)));
  qs.set("season_type", (seasonType || "regular").toString().toLowerCase());
  if (type) qs.set("type", type);
  qs.set("per_page", String(opts.per_page || 100));
  if (opts.team_ids && Array.isArray(opts.team_ids)) {
    for (const tid of opts.team_ids) qs.append("team_ids[]", String(tid));
  }
  // BDL path is already /nba/v1 inside fetchBDL
    return await fetchBDL(env, `/team_season_averages/${category}?${qs.toString()}`, { ttl: opts.ttl ?? 6 * 3600, base: BDL_NBA_BASE });
}

async function safeFetchBDLTeamSeasonAverages(env, category, season, seasonType, type, opts = {}) {
  try {
    const r = await fetchBDLTeamSeasonAverages(env, category, season, seasonType, type, opts);
    if (r && r.data) return r;
    return null;
  } catch (e) {
    return null;
  }
}

function flattenStats(obj, prefix) {
  const out = {};
  if (!obj || typeof obj !== "object") return out;
  for (const [k, v] of Object.entries(obj)) {
    const kk = prefix ? `${prefix}${k}` : k;
    out[kk] = v;
  }
  return out;
}

function deriveTeamCore(row) {
  // Normalize key metrics from the flattened BDL pulls.
  // buildTeamWellBDL flattens:
  //  - general/base     => base_*
  //  - general/advanced => adv_*
  //  - general/opponent => opp_*
  //  - general/defense  => def_*
  const d = {};
  const get = (...keys) => pickAny(row, ...keys);

  // Pace / ratings
  d.pace = asFloat(get("adv_pace", "pace"));
  d.ortg = asFloat(get("adv_off_rating", "adv_e_off_rating", "adv_offensive_rating", "off_rating", "offensive_rating", "ortg"));
  d.drtg = asFloat(get("adv_def_rating", "adv_e_def_rating", "adv_defensive_rating", "def_rating", "defensive_rating", "drtg"));
  d.net = asFloat(get("adv_net_rating", "adv_e_net_rating", "net_rating", "net"));

  // If net missing but we have ORTG/DRTG, compute it.
  if ((d.net === null || d.net === undefined) && d.ortg !== null && d.ortg !== undefined && d.drtg !== null && d.drtg !== undefined) {
    d.net = d.ortg - d.drtg;
  }

  // Four-factor-ish summaries (advanced)
  d.ts = asFloat(get("adv_true_shooting_percentage", "true_shooting_percentage", "ts"));
  d.efg = asFloat(get("adv_effective_field_goal_percentage", "effective_field_goal_percentage", "efg"));
  d.tov_ratio = asFloat(get("adv_turnover_ratio", "turnover_ratio", "tov_ratio"));
  d.ast_pct = asFloat(get("adv_assist_percentage", "assist_percentage", "ast_pct"));
  d.reb_pct = asFloat(get("adv_rebound_percentage", "rebound_percentage", "reb_pct"));
  d.oreb_pct = asFloat(get("adv_offensive_rebound_percentage", "offensive_rebound_percentage", "oreb_pct"));
  d.dreb_pct = asFloat(get("adv_defensive_rebound_percentage", "defensive_rebound_percentage", "dreb_pct"));

  // Basic shooting volume (base)
  d.fg3a = asFloat(get("base_fg3a", "fg3a"));
  d.fga = asFloat(get("base_fga", "fga"));
  if (d.fga && d.fga > 0 && d.fg3a !== null && d.fg3a !== undefined) d.threepar = d.fg3a / d.fga;

  d.fta = asFloat(get("base_fta", "fta"));
  if (d.fga && d.fga > 0 && d.fta !== null && d.fta !== undefined) d.ftr = d.fta / d.fga;

  return d;
}

function computeMatchupEdges(home, away) {
  // Elite matchup feature pack (built from TeamWell rows produced by buildTeamWell())
  const n = (v) => {
    if (v === '' || v === null || v === undefined) return null;
    const x = Number(v);
    return Number.isFinite(x) ? x : null;
  };
  const h = home || {};
  const a = away || {};

  const edges = {};

  // Core strength
  const h_net = n(h.net_rtg);
  const a_net = n(a.net_rtg);
  const h_ortg = n(h.ortg);
  const a_ortg = n(a.ortg);
  const h_drtg = n(h.drtg);
  const a_drtg = n(a.drtg);
  const h_pace = n(h.pace_team);
  const a_pace = n(a.pace_team);

  edges.net_rtg_edge = (h_net != null && a_net != null) ? (h_net - a_net) : null;
  edges.ortg_vs_drtg_edge = (h_ortg != null && a_drtg != null) ? (h_ortg - a_drtg) : null;
  edges.drtg_vs_ortg_edge = (h_drtg != null && a_ortg != null) ? (a_ortg - h_drtg) : null;
  edges.pace_edge = (h_pace != null && a_pace != null) ? (h_pace - a_pace) : null;

  // Four Factors
  const h_efg = n(h.e_fg_pct);
  const a_efg = n(a.e_fg_pct);
  const h_ftr = n(h.ft_rate);
  const a_ftr = n(a.ft_rate);
  const h_tov = n(h.turnover_pct);
  const a_tov = n(a.turnover_pct);
  const h_orb = n(h.off_reb_pct);
  const a_drb = n(a.def_reb_pct);
  const a_orb = n(a.off_reb_pct);
  const h_drb = n(h.def_reb_pct);

  edges.efg_edge = (h_efg != null && a_efg != null) ? (h_efg - a_efg) : null;
  // Advantage home if away turns it over more
  edges.tov_edge = (a_tov != null && h_tov != null) ? (a_tov - h_tov) : null;
  edges.ft_rate_edge = (h_ftr != null && a_ftr != null) ? (h_ftr - a_ftr) : null;
  // Advantage home if home OREB% beats away DREB% (and vice versa)
  edges.reb_edge = (h_orb != null && a_drb != null) ? (h_orb - a_drb) : null;
  edges.reb_edge_away = (a_orb != null && h_drb != null) ? (a_orb - h_drb) : null;

  // Misc profile (team points breakdown)
  const h_paint = n(h.misc_pts_paint);
  const a_paint = n(a.misc_pts_paint);
  const h_fb = n(h.misc_pts_fb);
  const a_fb = n(a.misc_pts_fb);
  const h_offtov = n(h.misc_pts_off_tov);
  const a_offtov = n(a.misc_pts_off_tov);
  const h_second = n(h.misc_pts_2nd_chance);
  const a_second = n(a.misc_pts_2nd_chance);

  edges.paint_edge = (h_paint != null && a_paint != null) ? (h_paint - a_paint) : null;
  edges.fb_edge = (h_fb != null && a_fb != null) ? (h_fb - a_fb) : null;
  edges.off_tov_pts_edge = (h_offtov != null && a_offtov != null) ? (h_offtov - a_offtov) : null;
  edges.second_chance_edge = (h_second != null && a_second != null) ? (h_second - a_second) : null;

  // Shot defense (ptshot / leaguedashptteamdefend)
  const h_pt_dfg = n(h.pt_def_fg_pct);
  const a_pt_dfg = n(a.pt_def_fg_pct);
  const h_pt_pm = n(h.pt_def_pct_plusminus);
  const a_pt_pm = n(a.pt_def_pct_plusminus);

  // Advantage home if away allows a higher D_FG% than home allows
  edges.pt_def_fg_pct_edge = (a_pt_dfg != null && h_pt_dfg != null) ? (a_pt_dfg - h_pt_dfg) : null;
  edges.pt_def_plusminus_edge = (h_pt_pm != null && a_pt_pm != null) ? (h_pt_pm - a_pt_pm) : null;


  return edges;
}

async function buildTeamWellBDL(env, season, seasonType, opts = {}) {
  const cacheKey = teamWellKey(season, seasonType);
  if (!opts.force) {
    const cached = await kvGetJSON(env, cacheKey);
    if (cached) return { cacheKey, rows: cached, cached: true };
  }

  const ttl = opts.ttl ?? 6 * 3600;

  // Pull a focused "elite bundle" of categories/types (can expand later).
  const pulls = [
    ["general", "base"],
    ["general", "advanced"],
    ["general", "opponent"],
    ["general", "defense"],
    ["shooting", "by_zone_base"],
    ["shooting", "by_zone_opponent"],
    ["shooting", "5ft_range_base"],
    ["shooting", "5ft_range_opponent"],
    ["playtype", "transition"],
    ["playtype", "isolation"],
    ["playtype", "spotup"],
    ["playtype", "prballhandler"],
    ["playtype", "prrollman"],
    ["playtype", "postup"],
    ["tracking", "possessions"],
    ["tracking", "passing"],
    ["tracking", "drives"],
    ["tracking", "rebounding"],
    ["tracking", "efficiency"],
    ["shotdashboard", "overall"],
    ["shotdashboard", "catch_and_shoot"],
    ["shotdashboard", "pullups"],
    ["hustle", null]
  ];

  // Fetch in sequence (safe + simple). We can parallelize later if needed.
  const bundle = {};
  for (const [cat, typ] of pulls) {
    const key = `${cat}:${typ || "na"}`;
    const res = await safeFetchBDLTeamSeasonAverages(env, cat, season, seasonType, typ, { ttl, per_page: 100 });
    bundle[key] = res?.data || [];
  }

  // Merge per team_id
  const byTeam = new Map();
  const ensure = (teamObj) => {
    const tid = asInt(teamObj?.id);
    if (!tid) return null;
    if (!byTeam.has(tid)) {
      byTeam.set(tid, {
        team_id: tid,
        team_abbr: (teamObj?.abbreviation || "").toString(),
        team_name: (teamObj?.full_name || teamObj?.name || "").toString(),
        conference: (teamObj?.conference || "").toString(),
        division: (teamObj?.division || "").toString(),
        season: asInt(season),
        season_type: (seasonType || "regular").toString().toLowerCase(),
        // raw namespaces:
        raw: {},
        // derived:
        core: {}
      });
    }
    return byTeam.get(tid);
  };

  for (const [bkey, arr] of Object.entries(bundle)) {
    for (const item of (arr || [])) {
      const teamObj = item?.team;
      const row = ensure(teamObj);
      if (!row) continue;
      const stats = item?.stats || {};
      // Store raw under namespace keys like general_base.*
      const [cat, typ] = bkey.split(":");
      const ns = typ && typ !== "na" ? `${cat}_${typ}.` : `${cat}.`;
      row.raw = row.raw || {};
      Object.assign(row.raw, flattenStats(stats, ns));
      // Also add some convenience shallow keys for common categories
      if (cat === "general" && typ === "base") Object.assign(row, flattenStats(stats, "base_"));
      if (cat === "general" && typ === "advanced") Object.assign(row, flattenStats(stats, "adv_"));
      if (cat === "general" && typ === "opponent") Object.assign(row, flattenStats(stats, "opp_"));
      if (cat === "general" && typ === "defense") Object.assign(row, flattenStats(stats, "def_"));
    }
  }

  const rows = Array.from(byTeam.values()).map((r) => {
    r.core = deriveTeamCore(r);
    return r;
  });

  await kvPutJSON(env, cacheKey, rows, ttl);
  return { cacheKey, rows, cached: false };
}

async function handleTeamsBuild(env, url) {
  // NOTE: /teams/build is the canonical TeamWell builder used by /teams/export.csv and game scripts.
  // It builds the NBA TeamWell v2 table (nba:teamwell:<seasonStart>:v3).
  const season = asInt(url.searchParams.get("season") || 2026);
  const seasonType = (url.searchParams.get("season_type") || "regular").toString().toLowerCase();
  const force = (url.searchParams.get("force") || "").toString() === "1";
  const strict = (url.searchParams.get("strict") || "") === "1";
  const ttl = asInt(url.searchParams.get("ttl") || 6 * 3600);

  const { seasonStart, seasonEnd } = normalizeSeasonInput(season);
  const cacheKey = `nba:teamwell:${seasonStart}:v3`;

  let rows = force ? null : await kvGetJSON(env, cacheKey);
  const cached = !!rows;
  if (!rows) {
    rows = await buildTeamWell(env, seasonStart, seasonEnd, {});
    await kvPutJSON(env, cacheKey, rows, ttl);
  }

  const n = Array.isArray(rows) ? rows.length : 0;
  let three = 0, rim = 0, mid = 0;
  for (const r of (rows || [])) {
    if (r?.three_rate != null && r.three_rate !== '' && isFinite(Number(r.three_rate))) three++;
    if (r?.rim_rate != null && r.rim_rate !== '' && isFinite(Number(r.rim_rate))) rim++;
    if (r?.mid_rate != null && r.mid_rate !== '' && isFinite(Number(r.mid_rate))) mid++;
  }

  return ok(
    env,
    {
      season,
      season_type: seasonType,
      cache_key: cacheKey,
      cached,
      teams_built: n,
      shot_rates_filled: {
        three_rate: three,
        rim_rate: rim,
        mid_rate: mid,
      }
    },
    { build: "teamwell-v3", season, seasonType, cached }
  );
}


    // ===============================
    // Shot profile ingestion (PBPStats-like table paste)
    // ===============================

    function _seasonFolderPBP(seasonStart, seasonEnd) {
      // 2526, 2425, etc.
      const a = String(seasonStart).slice(-2);
      const b = String(seasonEnd).slice(-2);
      return `${a}${b}`;
    }

    function _parseNumToken(tok) {
      if (tok == null) return null;
      const s = String(tok).trim();
      if (!s) return null;
      const cleaned = s.replace(/,/g, '').replace(/%/g, '');
      const n = Number(cleaned);
      return Number.isFinite(n) ? n : null;
    }

    function parseShotQueryTable(raw) {
      // PBPStats "shot-query-summary" table paste is messy in the wild.
      // Users often paste:
      //  - a full TSV row (all columns on one line), OR
      //  - a header list where each column name is on its own line,
      //    followed by the data block (team + many numeric tokens).
      //
      // This parser is *stream-based*:
      // 1) Find team tokens (ATL/BOS/...) anywhere
      // 2) Collect the next numeric tokens (counts + percentages) until next team token
      // 3) Use fixed indices (same as your pasted schema)

      const text = String(raw || '').replace(/\r/g, '');
      const lines = text.split('\n');

      const rows = {};
      const errors = [];
      const warnings = [];
      const TEAM_RE = /^[A-Z]{3}$/;
      const VALID_ABBRS = new Set(Object.values(NBA_TEAM_NAME_TO_ABBR || {}));
      // Filter header tokens like FGA, FGM, etc. Only accept real NBA team abbreviations.


      // Flatten into tokens, but keep order.
      const toks = [];
      for (let li = 0; li < lines.length; li++) {
        const line = String(lines[li] || '').trim();
        if (!line) continue;
        const low = line.toLowerCase();
        if (low.startsWith('sort table by')) continue;
        if (low === 'name' || low === 'fga' || low === 'efg%') continue;
        // Split by any whitespace; preserve raw tokens.
        const parts = line.split(/\s+/g).filter(Boolean);
        for (const p of parts) toks.push(p);
      }

      // Walk token stream: TEAM -> [nums...] -> next TEAM
      for (let i = 0; i < toks.length; i++) {
        const t0 = String(toks[i] || '').toUpperCase();
        if (!TEAM_RE.test(t0)) continue;

        const team = t0;
        if (VALID_ABBRS && VALID_ABBRS.size && !VALID_ABBRS.has(team)) { continue; }
        const nums = [];
        let j = i + 1;
        for (; j < toks.length; j++) {
          const t = String(toks[j] || '').toUpperCase();
          if (TEAM_RE.test(t)) break;
          const n = _parseNumToken(toks[j]);
          if (n != null) nums.push(n);
        }

        // Advance outer loop
        i = j - 1;

        if (nums.length < 20) {
          warnings.push({ team, line: null, msg: 'row_too_short', got: nums.length });
          continue;
        }

        const get = (k) => (k >= 0 && k < nums.length) ? nums[k] : null;
        // Index mapping (0-based within vals):
        // 0 FGA
        // 6 FG3M, 7 FG3A
        // 13 Rim FGM, 14 Rim FGA
        // 16 SMR FGM, 17 SMR FGA
        // 19 LMR FGM, 20 LMR FGA
        // 22 C3 FGM, 23 C3 FGA
        // 25 AB3 FGM, 26 AB3 FGA
        const fga = get(0);
        const fg3a = get(7);
        const rimFga = get(14);
        const smrFga = get(17);
        const lmrFga = get(20);
        const c3Fga = get(23);
        const ab3Fga = get(26);

        if (!fga || fga <= 0) {
          warnings.push({ team, line: i + 1, msg: 'bad_fga', fga });
          continue;
        }

        const three_rate = (fg3a != null) ? (fg3a / fga) : null;
        const rim_rate = (rimFga != null) ? (rimFga / fga) : null;
        const mid_rate = (smrFga != null || lmrFga != null) ? (((smrFga || 0) + (lmrFga || 0)) / fga) : null;
        const c3_rate = (c3Fga != null) ? (c3Fga / fga) : null;
        const ab3_rate = (ab3Fga != null) ? (ab3Fga / fga) : null;

        const strict01 = (name, x) => {
          if (x == null) return null;
          const n = Number(x);
          if (!Number.isFinite(n)) { warnings.push({ team, field: name, msg: 'non_numeric_rate', value: x }); return null; }
          if (n < 0 || n > 1) { warnings.push({ team, field: name, msg: 'rate_out_of_range', value: n }); return null; }
          return n;
        };

        rows[team] = {
          team,
          fga,
          fg3a,
          rim_fga: rimFga,
          smr_fga: smrFga,
          lmr_fga: lmrFga,
          c3_fga: c3Fga,
          ab3_fga: ab3Fga,
          three_rate: strict01("three_rate", three_rate),
          rim_rate: strict01("rim_rate", rim_rate),
          mid_rate: strict01("mid_rate", mid_rate),
          c3_rate: strict01("c3_rate", c3_rate),
          ab3_rate: strict01("ab3_rate", ab3_rate),
          src: 'paste'
        };
      }

      const teamsParsed = Object.keys(rows).length;
      if (teamsParsed < 10) {
        errors.push({ msg: 'too_few_teams_parsed', teamsParsed });
      }

      return { rows, teamsParsed, errors, warnings };
    }

    async function handleShotProfileUpload(req, env, url) {
      const season = asInt(url.searchParams.get('season') || 2026);
      const seasonType = (url.searchParams.get('season_type') || 'regular').toString().toLowerCase();
      const raw = await req.text();
      const { seasonStart, seasonEnd } = normalizeSeasonInput(season);
      const folder = _seasonFolderPBP(seasonStart, seasonEnd);
      const cacheKey = `nba:shots:team:paste:v1:${folder}:${seasonType}`;

      const parsed = parseShotQueryTable(raw);
      if (parsed.errors && parsed.errors.length) {
        return fail(env, 'shot_upload_parse_failed', { cacheKey, ...parsed }, 400);
      }

      // Write to KV
      await kvPutJSON(env, cacheKey, parsed.rows, 30 * 24 * 3600);
      await kvPutJSON(env, `${cacheKey}:meta`, {
        ts: new Date().toISOString(),
        teamsParsed: parsed.teamsParsed,
        warnings: parsed.warnings || []
      }, 30 * 24 * 3600);

      return ok(env, {
        season,
        season_type: seasonType,
        cache_key: cacheKey,
        teams_parsed: parsed.teamsParsed,
        warnings: parsed.warnings || []
      }, { build: 'shot-profile-upload' });
    }

