    if(Date.now() - started > Math.max(500, budgetMs - 500)) break;
    const date = datesAll[dateIndex];
    currentDate = date;
    const dateKeysRaw = await _rtp688KvGet(env, _rtp688ArchiveDateIndexKey(season, date));
    const boardKeys = (Array.isArray(dateKeysRaw) ? dateKeysRaw : []).filter(k => String(k).includes(":props_board:"));
