async function _kvListAll(env, prefix, limit=5000){
  const out = [];
  if (!env?.RTP_CACHE || typeof env.RTP_CACHE.list !== "function") return out;
  let cursor = undefined;
  // Cloudflare KV list max is 1000; we page defensively
  for (let guard = 0; guard < 50; guard++){
    const resp = await env.RTP_CACHE.list({ prefix, cursor, limit: Math.min(1000, limit) });
    const keys = resp?.keys || [];
    for (const k of keys) out.push(k?.name);
    cursor = resp?.cursor;
    if (!cursor) break;
  }
  return out;
}

function _featVectorV2(row){
  const f = row?.features || {};
  // Feature order is fixed (do NOT change without bumping v)
  // IMPORTANT: We scale features for numerical stability (prevents SGD blow-ups / NaN weights).
  // This is NOT a clamp and does not invent stats; it's just optimization normalization.
  const scale = (v, denom) => (v == null ? null : (v / denom));
  const spread = scale(_numOrNull(row?.model?.spread_home), 10);   // ~[-2, +2]
  const total  = scale(_numOrNull(row?.model?.total), 250);        // ~[0.7, 1.1]
  const mismatch = scale(_numOrNull(f?.mismatch_score), 20);       // ~[0, 1]
  const blowout  = _numOrNull(f?.blowout_risk);                    // [0,1]
  const pace     = scale(_numOrNull(f?.pace), 100);                // ~[0.85, 1.10]
  const foul     = _numOrNull(f?.foul_env_score);                  // [0,1]
  const netDiff  = scale(_numOrNull(f?.net_diff), 15);             // ~[-1, 1]
  const efgDiff  = scale(_numOrNull(f?.efg_diff), 0.10);           // ~[-1, 1]
  const tovDiff  = scale(_numOrNull(f?.tov_diff), 0.10);           // ~[-1, 1]
  const rebDiff  = scale(_numOrNull(f?.reb_diff), 0.10);           // ~[-1, 1]
  const ftDiff   = scale(_numOrNull(f?.ft_rate_diff), 0.10);       // ~[-1, 1]
  const pSide    = _numOrNull(f?.p_side);                          // [0,1]

  return [
    1, // bias
    spread,
    total,
    mismatch,
    blowout,
    pace,
    foul,
    netDiff,
    efgDiff,
    tovDiff,
    rebDiff,
    ftDiff,
    pSide
  ];
}

function _dot(w, x){
  let s = 0;
  for (let i=0;i<w.length;i++){
    const xi = x[i];
    if (xi == null) continue;
    s += w[i] * xi;
  }
  return s;
}

function _sgdFit(rows, yKey, opts={}){
  const lr = Number(opts.lr ?? 0.01);
  const epochs = Number(opts.epochs ?? 250);
  const lambda = Number(opts.lambda ?? 1e-3); // L2
  const p = Number(opts.p ?? 13); // number of features
  const w = new Array(p).fill(0);

  const usable = [];
  for (const r of rows){
    const x = _featVectorV2(r);
    // require at least bias present
    if (x[0] !== 1) continue;
    const y = _numOrNull(r?.errors?.[yKey]);
    if (y == null) continue;
    if (!Number.isFinite(y)) continue;
    usable.push({ x, y });
  }
  if (!usable.length) return { w, used:0, rmse:null, diverged:false };

  // SGD (ridge / L2)
  for (let ep=0; ep<epochs; ep++){
    for (const it of usable){
      const pred = _dot(w, it.x);
      const err = (pred - it.y);

      // If we ever go non-finite, bail immediately (fail-loud).
      if (!Number.isFinite(err)) {
        return { w: new Array(p).fill(null), used: usable.length, rmse:null, diverged:true };
      }

      for (let j=0; j<p; j++){
        const xj = it.x[j];
        if (xj == null) continue;
        // xj should already be scaled; still guard to avoid Infinity / NaN.
        if (!Number.isFinite(xj)) continue;

        const grad = err * xj + lambda * w[j];
        const step = lr * grad;
        const next = w[j] - step;

        if (!Number.isFinite(next)) {
          return { w: new Array(p).fill(null), used: usable.length, rmse:null, diverged:true };
        }
        w[j] = next;
      }
    }
  }

  // RMSE
  let se = 0;
  for (const it of usable){
    const pred = _dot(w, it.x);
    const e = pred - it.y;
    if (!Number.isFinite(e)) return { w: new Array(p).fill(null), used: usable.length, rmse:null, diverged:true };
    se += e*e;
  }
  const rmse = Math.sqrt(se / usable.length);
  if (!Number.isFinite(rmse)) return { w: new Array(p).fill(null), used: usable.length, rmse:null, diverged:true };


return { w, used: usable.length, rmse, diverged:false };
}

async function handleBacktestCalibrateV2(env, req, url){
  // GET /backtest/calibrate/v2?season=2026&limit=5000&epochs=250&lr=0.01&lambda=0.001
  const season = Number(url.searchParams.get("season") || 0);
  if (!season) return json({ ok:false, data:null, meta:{}, error:"backtest:v2:missing_season" }, 400);

  const limit = asInt(url.searchParams.get("limit") || "5000");
  const epochs = asInt(url.searchParams.get("epochs") || "250");
  const lr = Number(url.searchParams.get("lr") || "0.001");
  const lambda = Number(url.searchParams.get("lambda") || "0.001");

  // list all v2 rows; filter by season in key
  const prefix = "nba:cal:rows:v2:";
  const keys = await _kvListAll(env, prefix, limit);

  const rows = [];
  // Read at most `limit` rows
  for (let i=0; i<keys.length && rows.length<limit; i++){
    const k = keys[i];
    if (!k || !k.includes(`:S${season}:`)) continue;
    const r = await kvGetJSON(env, k);
    if (r) rows.push(r);
  }

  const feats = ["bias","spread","total","mismatch","blowout","pace","foul","net_diff","efg_diff","tov_diff","reb_diff","ft_rate_diff","p_side"];

  const fitSpread = _sgdFit(rows, "spread_err", { epochs, lr, lambda, p: 13 });
  const fitTotal  = _sgdFit(rows, "total_err",  { epochs, lr, lambda, p: 13 });

  const diverged = !!fitSpread?.diverged || !!fitTotal?.diverged;
  if (diverged){
    const debug = {
      season,
      v: "v2",
      ts: new Date().toISOString(),
      scanned: keys.length,
      rows: rows.length,
      used_spread: fitSpread.used,
      used_total: fitTotal.used,
      lambda, lr, epochs
    };
    return json({ ok:false, data:debug, meta:{ build_id: BUILD_ID }, error:"backtest:v2:diverged_nonfinite_weights" }, 500);
  }

  const payload = {
    season,
    v: "v2",
    ts: new Date().toISOString(),
    scanned: keys.length,
    rows: rows.length,
    used_spread: fitSpread.used,
    used_total: fitTotal.used,
    lambda, lr, epochs,
    features: feats,
    w_spread: fitSpread.w,
    w_total: fitTotal.w,
    rmse_spread: fitSpread.rmse,
    rmse_total: fitTotal.rmse
  };

  const wkey = _calWeightsV2Key(season);
  const stored = await kvPutJSON(env, wkey, payload);

  return json({ ok:true, data:{ ...payload, stored: !!stored }, meta:{ key: wkey, build_id: BUILD_ID }, error:null });
}


function _extractRawModelFromPred(pred){
  const sh = _numOrNull(
    pred?.spread_model ??
    pred?.spread_model_raw ??
    pred?.spread ??
    pred?.model?.spread_home ??
    pred?.pure?.spread_home ??
    pred?.pure?.spread
  );
  const tt = _numOrNull(
    pred?.total_model ??
    pred?.total_model_raw ??
    pred?.total ??
    pred?.model?.total ??
    pred?.pure?.total
  );
  return { spread_home: sh, total: tt };
}
function _sideFromSpreadVsMarket(modelSpread, marketSpreadHome){
  const ms = _numOrNull(modelSpread);
  const mk = _numOrNull(marketSpreadHome);
  if (ms == null || mk == null) return null;
  if (Math.abs(ms - mk) < 1e-9) return null;
  // lower/more negative spread_home = stronger home; higher = away value
  return (ms < mk) ? "home" : "away";
}
function _gradeSpreadSide(lineHome, marginHome, side){
  const ln = _numOrNull(lineHome);
  const mg = _numOrNull(marginHome);
  if (ln == null || mg == null || !side) return null;
  const homeCoverDelta = mg + ln;
  if (Math.abs(homeCoverDelta) < 1e-9) return "push";
  const homeCovered = homeCoverDelta > 0;
  if (side === "home") return homeCovered ? "win" : "loss";
  if (side === "away") return homeCovered ? "loss" : "win";
  return null;
}
function _gradeTotalDirection(modelTotal, marketTotal, actualTotal){
  const mt = _numOrNull(modelTotal);
  const mk = _numOrNull(marketTotal);
  const at = _numOrNull(actualTotal);
  if (mt == null || mk == null || at == null) return { direction:null, result:null };
  if (Math.abs(mt - mk) < 1e-9) return { direction:null, result:null };
  const dir = (mt > mk) ? "over" : "under";
  const marketDelta = at - mk;
  if (Math.abs(marketDelta) < 1e-9) return { direction: dir, result:"push" };
  const overHit = marketDelta > 0;
  return { direction: dir, result: (dir === "over" ? (overHit ? "win" : "loss") : (overHit ? "loss" : "win")) };
}
function _bumpWLP(bucket, result){
  if (!bucket || !result) return;
  if (result === "win") bucket.wins++;
  else if (result === "loss") bucket.losses++;
  else if (result === "push") bucket.pushes++;
}
function _finalizeWLP(bucket){
  if (!bucket) return bucket;
  bucket.picks = bucket.wins + bucket.losses + bucket.pushes;
  const decisions = bucket.wins + bucket.losses;
  bucket.hit_rate = decisions > 0 ? (bucket.wins / decisions) : null;
  return bucket;
}
// [cleaned] removed legacy lines 13897-13924

function _bucketKey(v){
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return n.toFixed(2);
}
function _makeBucketAgg(){
  return { wins:0, losses:0, pushes:0, picks:0, hit_rate:null, avg_conf:null, avg_edge:null, avg_p_cash:null };
}
function _addBucketAgg(map, bucket, result, conf, edge, p){
  const k = _bucketKey(bucket);
  if (!k || !result) return;
  if (!map[k]) map[k] = { wins:0, losses:0, pushes:0, conf_sum:0, conf_n:0, edge_sum:0, edge_n:0, p_sum:0, p_n:0 };
  const row = map[k];
  if (result === 'win') row.wins++;
  else if (result === 'loss') row.losses++;
  else if (result === 'push') row.pushes++;
  const c = Number(conf); if (Number.isFinite(c)) { row.conf_sum += c; row.conf_n++; }
  const e = Number(edge); if (Number.isFinite(e)) { row.edge_sum += e; row.edge_n++; }
  const pp = Number(p); if (Number.isFinite(pp)) { row.p_sum += pp; row.p_n++; }
}
function _finalizeBucketMap(map){
  return Object.keys(map).sort((a,b)=>Number(a)-Number(b)).map((k)=>{
    const r = map[k];
    const picks = (r.wins||0)+(r.losses||0)+(r.pushes||0);
    return {
      bucket: Number(k), wins:r.wins||0, losses:r.losses||0, pushes:r.pushes||0, picks,
      hit_rate: picks ? (r.wins||0)/picks : null,
      avg_conf: r.conf_n ? r.conf_sum/r.conf_n : null,
      avg_edge: r.edge_n ? r.edge_sum/r.edge_n : null,
      avg_p_cash: r.p_n ? r.p_sum/r.p_n : null
    };
  });
}
function _rtpBestPlayBuckets(exactBuckets, minPicks=5){
  return (exactBuckets||[]).filter(b => (b.picks||0) >= minPicks).sort((a,b)=> ((b.hit_rate??-1)-(a.hit_rate??-1)) || ((b.picks||0)-(a.picks||0))).slice(0,8).map(b=>b.bucket);
}
function _rtpWorstPlayBuckets(exactBuckets, minPicks=5){
  return (exactBuckets||[]).filter(b => (b.picks||0) >= minPicks).sort((a,b)=> ((a.hit_rate??2)-(b.hit_rate??2)) || ((b.picks||0)-(a.picks||0))).slice(0,8).map(b=>b.bucket);
}


function _calibrationRejectReason(r){
  if (!r) return "missing_row";
  if (!r.final_best_type) return "missing_final_best_type";
  const res = String(r.final_best_result || "").toLowerCase();
  if (!(res === "win" || res === "loss" || res === "push")) return "missing_final_best_result";
  const marketTotal = Number(r.market?.total ?? r.market_total);
  if (!Number.isFinite(marketTotal)) return "missing_market_total";
  const marketSpreadHome = Number(r.market?.spread_home ?? r.market_spread_home);
  if (!Number.isFinite(marketSpreadHome)) return "missing_market_spread_home";
  if (marketSpreadHome === 0) return "zero_market_spread_home";
  const bucket = Number(r.final_best_p_cash_bucket ?? r.final_best_bucket ?? r.final_best_p_cash);
  if (!Number.isFinite(bucket)) return "missing_final_best_bucket";
  if (bucket === 0) return "zero_final_best_bucket";
  return null;
}
function isValidCalibrationRow(r){
  return _calibrationRejectReason(r) === null;
}
function _calibrationBucketValue(r){
  const rawP = Number(r?.final_best_p_cash);
  const rawB = Number(r?.final_best_p_cash_bucket ?? r?.final_best_bucket);
  const safe = (typeof _rtpSafeDecisionBucket === "function") ? _rtpSafeDecisionBucket(rawB, rawP) : null;
  if (Number.isFinite(safe)) return Number(safe.toFixed(2));
  const bucket = Number.isFinite(rawB) ? rawB : rawP;
  return Number.isFinite(bucket) ? Number(Math.min(0.89, bucket).toFixed(2)) : null;
}

async function handleBacktestPerformanceReport(env, req, url){
  const season = Number(url.searchParams.get("season") || 0);
  const limit = Math.min(10000, Math.max(1, asInt(url.searchParams.get("limit") || "500")));
  const pageSize = Math.min(250, Math.max(25, asInt(url.searchParams.get("page_size") || "250")));
  const budgetMs = Math.min(10000, Math.max(1000, asInt(url.searchParams.get("budget_ms") || "5000")));
  const cursorIn = (url.searchParams.get("cursor") || "").trim() || undefined;
  if (!season) return json({ ok:false, data:null, meta:{ path:"/backtest/performance/report", build_id: BUILD_ID }, error:"performance:missing_season" }, 400);

  const START = Date.now();
  const prefix = "nba:cal:rows:v2:";
  let cursor = cursorIn;
  let keys_seen = 0;
  let keys_matching_season = 0;
  let list_complete = false;
  let timed_out = false;

  const spreads = {
    model_raw: { wins:0, losses:0, pushes:0 },
    engine_final: { wins:0, losses:0, pushes:0 },
    final_decision: { wins:0, losses:0, pushes:0 },
    market_favorite: { wins:0, losses:0, pushes:0 },
    disagreement_raw_vs_market: { games:0, model_wins:0, market_wins:0, pushes:0 },
    disagreement_final_vs_market: { games:0, model_wins:0, market_wins:0, pushes:0 }
  };
  const totals = {
    model_raw: { wins:0, losses:0, pushes:0 },
    engine_final: { wins:0, losses:0, pushes:0 },
    final_decision: { wins:0, losses:0, pushes:0 },
    market_distribution: { overs:0, unders:0, pushes:0 },
    note: "Closing totals are a number, not a directional market pick. Market side W/L is not applicable for totals."
  };

  const spread_model_buckets = {};
  const spread_engine_buckets = {};
  const spread_final_buckets = {};
  const total_model_buckets = {};
  const total_engine_buckets = {};
  const total_final_buckets = {};

  const worst_spread = [];
  const worst_total = [];
  let rows_scanned = 0;
  let valid_rows = 0;
  let rejected_rows = 0;
  let games_graded = 0;
  const rejected_reasons = {};

  const _pushWorst = (arr, key, row, valueField) => {
    const val = _numOrNull(row?.errors?.[valueField] ?? row?.[valueField]);
    if (val == null) return;
    const label = valueField === "spread_err" ? "spread_err" : "total_err";
    arr.push({ key, game_date:row?.game_date, home:row?.home, away:row?.away, [label]: val, abs_err: Math.abs(val) });
  };

  while (true){
    if ((Date.now() - START) > budgetMs) { timed_out = true; break; }
    const listRes = await env.RTP_CACHE.list({ prefix, cursor, limit: pageSize });
    keys_seen += (listRes?.keys || []).length;
    cursor = listRes?.cursor || null;
    list_complete = !!listRes?.list_complete;

    for (const meta of (listRes?.keys || [])){
      if (rows_scanned >= limit) break;
      if ((Date.now() - START) > budgetMs) { timed_out = true; break; }
      const k = meta?.name;
      if (!k) continue;
      if (!k.includes(`:S${season}:`)) continue;
      keys_matching_season++;

      const row = await kvGetJSON(env, k);
      if (!row) continue;
      rows_scanned++;

      const rejectReason = _calibrationRejectReason(row);
      if (rejectReason) {
        rejected_rows++;
        rejected_reasons[rejectReason] = (rejected_reasons[rejectReason] || 0) + 1;
        _pushWorst(worst_spread, k, row, "spread_err");
        _pushWorst(worst_total, k, row, "total_err");
        continue;
      }
      valid_rows++;

      const game_date = row?.game_date;
      const home = normalizeTeamAbbr(row?.home);
      const away = normalizeTeamAbbr(row?.away);
      const final = row?.final || {};
      const market = row?.market || {};
      const marginHome = _numOrNull(final?.margin_home);
      const totalPts = _numOrNull(final?.total);
      const marketSpreadHome = _numOrNull(market?.spread_home ?? row?.market_spread_home);
      const marketTotal = _numOrNull(market?.total ?? row?.market_total);
      const rowBucket = _calibrationBucketValue(row);

      const pred_key = _btPredKey(game_date, season, home, away);
      const pred = await kvGetJSON(env, pred_key);
      if (!pred) {
        _pushWorst(worst_spread, k, row, "spread_err");
        _pushWorst(worst_total, k, row, "total_err");
        continue;
      }

      const raw = _extractRawModelFromPred(pred);
      const fin = _extractModelFromPred(pred);
      const modelDecision = pred?.model_decision || null;

      if (marginHome != null && marketSpreadHome != null){
        games_graded++;

        const rawSide = _sideFromSpreadVsMarket(raw?.spread_home, marketSpreadHome);
        const rawRes = _gradeSpreadSide(marketSpreadHome, marginHome, rawSide);
        _bumpWLP(spreads.model_raw, rawRes);
        _addBucketAgg(spread_model_buckets, modelDecision?.side?.p_cash_bucket ?? modelDecision?.side?.p_cash, rawRes, modelDecision?.side?.conf, modelDecision?.side?.edge_pts, modelDecision?.side?.p_cash);

        const engineSide = _sideFromSpreadVsMarket(fin?.spread_home, marketSpreadHome);
        const engineRes = _gradeSpreadSide(marketSpreadHome, marginHome, engineSide);
        _bumpWLP(spreads.engine_final, engineRes);
        _addBucketAgg(spread_engine_buckets, pred?.anchors?.side?.p_cash_bucket ?? pred?.anchors?.side?.p_cash, engineRes, pred?.anchors?.side?.conf, pred?.anchors?.side?.edge_pts, pred?.anchors?.side?.p_cash);

        const finalPick = row?.final_best_type === 'side' ? row?.final_best_pick : null;
        const finalRes = row?.final_best_type === 'side' ? row?.final_best_result : null;
        if (finalPick && finalRes && rowBucket != null) {
          _bumpWLP(spreads.final_decision, finalRes);
          _addBucketAgg(spread_final_buckets, rowBucket, finalRes, row?.final_best_conf, row?.final_best_edge, row?.final_best_p_cash);
        }

        const marketFavSide = (marketSpreadHome < 0) ? "home" : (marketSpreadHome > 0 ? "away" : null);
        const marketFavRes = _gradeSpreadSide(marketSpreadHome, marginHome, marketFavSide);
        _bumpWLP(spreads.market_favorite, marketFavRes);

        if (rawSide && marketFavSide && rawSide !== marketFavSide){
          spreads.disagreement_raw_vs_market.games++;
          if (rawRes === "push" || marketFavRes === "push") spreads.disagreement_raw_vs_market.pushes++;
          else if (rawRes === "win") spreads.disagreement_raw_vs_market.model_wins++;
          else if (marketFavRes === "win") spreads.disagreement_raw_vs_market.market_wins++;
        }
        if (finalPick && marketFavSide){
          const fp = String(finalPick).toUpperCase();
          const finalSide = fp.includes(home) ? 'home' : (fp.includes(away) ? 'away' : ((marketSpreadHome < 0) ? 'home' : 'away'));
          if (finalSide !== marketFavSide){
            spreads.disagreement_final_vs_market.games++;
            if (finalRes === "push" || marketFavRes === "push") spreads.disagreement_final_vs_market.pushes++;
            else if (finalRes === "win") spreads.disagreement_final_vs_market.model_wins++;
            else if (marketFavRes === "win") spreads.disagreement_final_vs_market.market_wins++;
          }
        }
      }

      if (totalPts != null && marketTotal != null){
        const rawTot = _gradeTotalDirection(raw?.total, marketTotal, totalPts);
        _bumpWLP(totals.model_raw, rawTot.result);
        _addBucketAgg(total_model_buckets, modelDecision?.total?.p_cash_bucket ?? modelDecision?.total?.p_cash, rawTot.result, modelDecision?.total?.conf, modelDecision?.total?.edge_pts, modelDecision?.total?.p_cash);

        const finTot = _gradeTotalDirection(fin?.total, marketTotal, totalPts);
        _bumpWLP(totals.engine_final, finTot.result);
        _addBucketAgg(total_engine_buckets, pred?.anchors?.total?.p_cash_bucket ?? pred?.anchors?.total?.p_cash, finTot.result, pred?.anchors?.total?.conf, pred?.anchors?.total?.edge_pts, pred?.anchors?.total?.p_cash);

        if (row?.final_best_type === 'total' && row?.final_best_result && rowBucket != null) {
          _bumpWLP(totals.final_decision, row.final_best_result);
          _addBucketAgg(total_final_buckets, rowBucket, row.final_best_result, row?.final_best_conf, row?.final_best_edge, row?.final_best_p_cash);
        }

        const marketDelta = totalPts - marketTotal;
        if (Math.abs(marketDelta) < 1e-9) totals.market_distribution.pushes++;
        else if (marketDelta > 0) totals.market_distribution.overs++;
        else totals.market_distribution.unders++;
      }

      _pushWorst(worst_spread, k, row, "spread_err");
      _pushWorst(worst_total, k, row, "total_err");
    }

    if (rows_scanned >= limit) break;
    if (timed_out) break;
    if (list_complete || !cursor) break;
  }

  worst_spread.sort((a,b)=>b.abs_err-a.abs_err);
  worst_total.sort((a,b)=>b.abs_err-a.abs_err);

  _finalizeWLP(spreads.model_raw);
  _finalizeWLP(spreads.engine_final);
  _finalizeWLP(spreads.final_decision);
  _finalizeWLP(spreads.market_favorite);
  _finalizeWLP(totals.model_raw);
  _finalizeWLP(totals.engine_final);
  _finalizeWLP(totals.final_decision);

  const spread_model_exact_buckets = _finalizeBucketMap(spread_model_buckets);
  const spread_engine_exact_buckets = _finalizeBucketMap(spread_engine_buckets);
  const spread_final_exact_buckets = _finalizeBucketMap(spread_final_buckets);
  const total_model_exact_buckets = _finalizeBucketMap(total_model_buckets);
  const total_engine_exact_buckets = _finalizeBucketMap(total_engine_buckets);
  const total_final_exact_buckets = _finalizeBucketMap(total_final_buckets);

  const trust = {
    spreads: {
      raw_model_hit_rate: spreads.model_raw.hit_rate,
      calibrated_engine_hit_rate: spreads.engine_final.hit_rate,
      final_decision_hit_rate: spreads.final_decision.hit_rate,
      market_favorite_hit_rate: spreads.market_favorite.hit_rate
    },
    totals: {
      raw_model_hit_rate: totals.model_raw.hit_rate,
      calibrated_engine_hit_rate: totals.engine_final.hit_rate,
      final_decision_hit_rate: totals.final_decision.hit_rate
    },
    strongest_lane: ((spreads.final_decision.hit_rate ?? spreads.engine_final.hit_rate ?? -1) > (totals.final_decision.hit_rate ?? totals.engine_final.hit_rate ?? -1) ? "spreads" : (((totals.final_decision.hit_rate ?? totals.engine_final.hit_rate ?? -1) > (spreads.final_decision.hit_rate ?? spreads.engine_final.hit_rate ?? -1)) ? "totals" : "tied"))
  };

  return json({
    ok:true,
    data:{
      season,
      cursor: cursorIn || null,
      next_cursor: cursor || null,
      list_complete: !!list_complete,
      timed_out,
      budget_ms: budgetMs,
      page_size: pageSize,
      page_count: rows_scanned,
      keys_seen,
      keys_matching_season,
      rows_scanned,
      valid_rows,
      rejected_rows,
      rejected_reasons,
      games_graded,
      spreads,
      totals,
      trust,
      spread_model_exact_buckets,
      spread_engine_exact_buckets,
      spread_final_exact_buckets,
      total_model_exact_buckets,
      total_engine_exact_buckets,
      total_final_exact_buckets,
      best_spread_model_buckets: _rtpBestPlayBuckets(spread_model_exact_buckets),
      best_spread_engine_buckets: _rtpBestPlayBuckets(spread_engine_exact_buckets),
      best_spread_final_buckets: _rtpBestPlayBuckets(spread_final_exact_buckets),
      best_total_model_buckets: _rtpBestPlayBuckets(total_model_exact_buckets),
      best_total_engine_buckets: _rtpBestPlayBuckets(total_engine_exact_buckets),
      best_total_final_buckets: _rtpBestPlayBuckets(total_final_exact_buckets),
      worst_spread_model_buckets: _rtpWorstPlayBuckets(spread_model_exact_buckets),
      worst_spread_engine_buckets: _rtpWorstPlayBuckets(spread_engine_exact_buckets),
      worst_spread_final_buckets: _rtpWorstPlayBuckets(spread_final_exact_buckets),
      worst_total_model_buckets: _rtpWorstPlayBuckets(total_model_exact_buckets),
      worst_total_engine_buckets: _rtpWorstPlayBuckets(total_engine_exact_buckets),
      worst_total_final_buckets: _rtpWorstPlayBuckets(total_final_exact_buckets),
      worst_spread_errors: worst_spread.slice(0, 15),
      worst_total_errors: worst_total.slice(0, 15)
    },
    meta:{ path:"/backtest/performance/report", build_id: BUILD_ID },
    error:null
  });
}

async function handleBacktestRowsV2(env, req, url){
  const season = Number(url.searchParams.get("season") || 0);
  const limit = Math.min(5000, Math.max(1, asInt(url.searchParams.get("limit") || "50")));
  const cursorIn = (url.searchParams.get("cursor") || "").trim() || undefined;
  const prefix = "nba:cal:rows:v2:";

  let cursor = cursorIn;
  let keys_seen = 0;
  let list_complete = false;
  const out = [];
  let valid_count = 0;
  let rejected_count = 0;

  while (true){
    const listRes = await env.RTP_CACHE.list({ prefix, cursor, limit: 250 });
    keys_seen += (listRes?.keys || []).length;
    cursor = listRes?.cursor || null;
    list_complete = !!listRes?.list_complete;

    for (const meta of (listRes?.keys || [])){
      const k = meta?.name;
      if (!k) continue;
      if (season && !k.includes(`:S${season}:`)) continue;
      const r = await kvGetJSON(env, k);
      if (r) {
        const bucketVal = _calibrationBucketValue(r) ?? 0;
        const isValid = isValidCalibrationRow(r);
        const rejectedReason = isValid ? null : _calibrationRejectReason(r);
        if (isValid) valid_count++; else rejected_count++;
        out.push({
          key:k, game_date:r.game_date, home:r.home, away:r.away,
          spread_err:r?.errors?.spread_err, total_err:r?.errors?.total_err,
          final_best_type:r?.final_best_type ?? null,
          final_best_pick:r?.final_best_pick ?? null,
          final_best_source:r?.final_best_source ?? null,
          final_best_label:r?.final_best_label ?? null,
          final_best_bucket:r?.final_best_bucket ?? null,
          final_best_p_cash_bucket: bucketVal,
          final_best_edge:r?.final_best_edge ?? null,
          final_best_conf:r?.final_best_conf ?? null,
          final_best_p_cash:r?.final_best_p_cash ?? null,
          final_best_units:r?.final_best_units ?? null,
          final_best_grade:r?.final_best_grade ?? null,
          final_best_result:r?.final_best_result ?? null,
          final_best_engine_flag:r?.final_best_engine_flag ?? null,
          final_best_engine_hates:r?.final_best_engine_hates ?? false,
          final_best_selector_score:r?.final_best_selector_score ?? null,
          final_best_bucket_rank:r?.final_best_bucket_rank ?? null,
          final_best_is_play_bucket:r?.final_best_is_play_bucket ?? false,
          final_best_is_worst_bucket:r?.final_best_is_worst_bucket ?? false,
          market_total:r?.market?.total ?? r?.market_total ?? null,
          market_spread_home:r?.market?.spread_home ?? r?.market_spread_home ?? null,
          is_valid_calibration_row: isValid,
          rejected_reason: rejectedReason
        });
      }
      if (out.length >= limit) break;
    }

    if (out.length >= limit) break;
    if (list_complete || !cursor) break;
  }

  return json({ ok:true, data:{ season: season||null, cursor: cursorIn || null, next_cursor: cursor || null, list_complete: !!list_complete, keys_seen, count: out.length, valid_count, rejected_count, items: out }, meta:{ build_id: BUILD_ID }, error:null });
}

/** ===== End Learning v2 ===== **/


async function handleBacktestCalibrationBuild(env, req, url){
  const season = Number(url.searchParams.get("season") || "0") || null;
  if (!season) return fail(env, "calibration_build:missing_season", { path:"/backtest/calibration/build" }, 400);

  const prefix = "nba:cal:rows:v1:";
  const maxRows = Math.min(5000, Math.max(50, Number(url.searchParams.get("max") || "2000")));
  const lambda = Math.max(0, Number(url.searchParams.get("lambda") || "3")); // mild shrinkage default
  const capSpread = Math.max(0, Number(url.searchParams.get("cap_spread") || "1.5"));
  const capTotal  = Math.max(0, Number(url.searchParams.get("cap_total") || "2.0"));

  const rows = [];
  let cursor = undefined;
  let scanned = 0;

  while (true){
    const listRes = await env.RTP_CACHE.list({ prefix, cursor, limit: 1000 });
    cursor = listRes.cursor;
    for (const k of (listRes.keys || [])){
      scanned++;
      if (!k?.name) continue;
      if (!k.name.includes(`:S${season}:`)) continue;
      const row = await kvGetJSON(env, k.name);
      if (row) rows.push(row);
      if (rows.length >= maxRows) break;
    }
    if (rows.length >= maxRows) break;
    if (!listRes.list_complete && cursor) continue;
    break;
  }

  // Build training set by reading associated pred+res (more reliable feature extraction)
  const Xs = [];
  const ys = [];
  const Xt = [];
  const yt = [];

  const feature_names = ["bias","spread","total","mismatch","blowout","pace","foul","p_side"];

  let used = 0;
  let skipped = 0;

  for (const r of rows){
    try{
      const game_date = r?.game?.game_date || r?.game_date;
      const home = canonTeamAbbr(r?.game?.home || r?.home);
      const away = canonTeamAbbr(r?.game?.away || r?.away);
      const s = Number(r?.game?.season || r?.season || season) || season;

      if (!game_date || !home || !away) { skipped++; continue; }

      const pred_key = r?.keys?.pred_key || _btPredKey(game_date, s, home, away);
      const res_key  = r?.keys?.res_key  || _btResKey(game_date, s, home, away);

      const pred = await kvGetJSON(env, pred_key);
      const res  = await kvGetJSON(env, res_key);

      const home_score = Number(res?.home_score ?? res?.final?.home_score);
      const away_score = Number(res?.away_score ?? res?.final?.away_score);
      if (!isFinite(home_score) || !isFinite(away_score)) { skipped++; continue; }

      const actual_margin_home = home_score - away_score;
      const actual_total = home_score + away_score;

      // baseline prediction (use final if present)
      const pred_spread = Number(
        pred?.spread_final ?? pred?.spread_model ?? pred?.spread_home ?? pred?.pure?.spread_home ?? pred?.pure?.spread ?? pred?.model?.spread_home
      );
      const pred_total = Number(
        pred?.total_final ?? pred?.total_model ?? pred?.total ?? pred?.pure?.total ?? pred?.model?.total
      );
      if (!isFinite(pred_spread) || !isFinite(pred_total)) { skipped++; continue; }

      // pregm features
      const mismatch = Number(pred?.diagnostics?.mismatch_score ?? pred?.mismatch_score);
      const blowout  = Number(pred?.blowout_risk ?? pred?.anchors?.gates?.side?.blowout_risk);
      const pace     = Number(pred?.pace ?? pred?.pace_game ?? pred?.pace_est ?? pred?.pace_plays ?? pred?.pace_tier_val);
      const foul     = Number(pred?.foul_env_score ?? pred?.foul_score);
      const p_side   = Number(pred?.anchors?.side?.p_cash ?? pred?.p_cash_side ?? pred?.p_cash);

      const x = [
        1,
        isFinite(pred_spread) ? pred_spread : 0,
        isFinite(pred_total) ? pred_total : 0,
        isFinite(mismatch) ? mismatch : 0,
        isFinite(blowout) ? blowout : 0,
        isFinite(pace) ? pace : 0,
        isFinite(foul) ? foul : 0,
        isFinite(p_side) ? p_side : 0,
      ];

      // target residuals: actual - predicted
      const y_spread = actual_margin_home - pred_spread;
      const y_total  = actual_total - pred_total;

      if (isFinite(y_spread)){
        Xs.push(x);
        ys.push(y_spread);
      }
      if (isFinite(y_total)){
        Xt.push(x);
        yt.push(y_total);
      }
      used++;
    } catch(e){
      skipped++;
    }
  }

  const w_spread = fitRidge(Xs, ys, lambda);
  const w_total  = fitRidge(Xt, yt, lambda);

  // training metrics (in-sample) for quick sanity
  function rmse(X, y, w){
    if (!w || !X.length) return null;
    let s=0;
    for (let i=0;i<X.length;i++){
      const e = (y[i] - dot(w, X[i]));
      s += e*e;
    }
    return Math.sqrt(s / X.length);
  }

  const report = {
    season,
    build_id: BUILD_ID,
    ts: new Date().toISOString(),
    scanned,
    rows: rows.length,
    used,
    skipped,
    lambda,
    caps: { spread: capSpread, total: capTotal },
    features: feature_names,
    w_spread,
    w_total,
    rmse_spread: rmse(Xs, ys, w_spread),
    rmse_total: rmse(Xt, yt, w_total),
  };

  const key = _calWeightsKey(season);
  await kvPutJSON(env, key, report);

  return ok(env, report, { key, build_id: BUILD_ID });
}

/** ===== End Fix17 ===== **/
async function handleBacktestCalibrate(env, req, url) {
  const q = url.searchParams;
  const date = q.get("date");
  const start = q.get("start");
  const end = q.get("end");
  const limit = Math.min(1000, Math.max(10, Number(q.get("limit") || 500)));
  const targetBE = Number(q.get("target_be") || 0.524);
  const minBucket = Number(q.get("min_bucket") || 0.55);

  // date-scoped by default. Range supported via start/end (inclusive).
  if (!date && !(start && end)) {
    return jsonResponse({ ok:false, data:null, meta:{ path:"/backtest/calibrate", build_id: BUILD_ID }, error:"backtest:missing_date" }, 400);
  }

  const kv = getKV(env);
  if (!kv || !kv.list) {
    return jsonResponse({ ok:false, data:null, meta:{ path:"/backtest/calibrate", build_id: BUILD_ID }, error:"backtest:kv_missing_list" }, 500);
  }

  const dates = [];
  if (date) {
    dates.push(date);
  } else {
    // inclusive list of ISO dates from start..end (cap to 370 days to protect KV.list)
    const s0 = String(start||"").slice(0,10);
    const e0 = String(end||"").slice(0,10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s0) || !/^\d{4}-\d{2}-\d{2}$/.test(e0)) {
      return jsonResponse({ ok:false, data:null, meta:{ path:"/backtest/calibrate", build_id: BUILD_ID }, error:"backtest:bad_date_range" }, 400);
    }
    let cur = s0;
    let guard = 0;
    while (true) {
      dates.push(cur);
      if (cur === e0) break;
      cur = _addDaysISO(cur, 1);
      guard++;
      if (guard > 370) break;
    }
  }

  // list prediction keys for the selected date(s)
  let keys = [];
  for (const d of dates) {
    const prefix = `nba:bt:v1:pred:${d}:`;
    let cursor = undefined;
    while (true) {
      const res = await kv.list({ prefix, cursor, limit: 100 });
      keys = keys.concat((res?.keys || []).map(k => k.name));
      cursor = res?.cursor;
      if (res?.list_complete || keys.length >= limit) break;
    }
    if (keys.length >= limit) break;
  }
  keys = keys.slice(0, limit);

  const rows = [];
  const debugRaw = (q.get("debug") || q.get("dbg") || "");
  const debug = String(debugRaw).toLowerCase() === "1" || String(debugRaw).toLowerCase() === "true";
  let preds_scanned = 0;
  let joins_found = 0;
  let rows_expected = 0;
  const missing_rows = [];
  const missingCap = 250;

  const mode = (q.get("mode") || "best").toLowerCase(); // best | all

  for (const k of keys) {
    preds_scanned++;
    const pred = await kvGetJson(env, k);
    if (!pred) continue;
    const season = pred?.season;
    const home = pred?.home;
    const away = pred?.away;
    if (!season || !home || !away) continue;

    const rawKDate = String(k||"").split(":")[4] || date || start || "";
    const kDate = rtpCleanDate(rawKDate);
    const { obj: resObj, key: resKey } = await rtpGetResultForJoin(env, rawKDate, season, home, away);
    if (!resObj) {
      if (missing_rows.length < missingCap) missing_rows.push({ game_date: kDate, season, home: normalizeTeamAbbr(home), away: normalizeTeamAbbr(away), which: "join", reason: "result_missing", res_key: resKey });
      continue;
    }
    joins_found++;
    rows_expected += (mode === "all") ? 2 : 1;

    // results: support multiple shapes (older/newer storage)
    const hs = (resObj?.home_score ?? resObj?.homeScore ?? resObj?.score?.home ?? resObj?.score_home ?? resObj?.home ?? resObj?.h ?? null);
    const as_ = (resObj?.away_score ?? resObj?.awayScore ?? resObj?.score?.away ?? resObj?.score_away ?? resObj?.away ?? resObj?.a ?? null);
    const ft = (resObj?.final_total ?? resObj?.finalTotal ?? ((hs!=null && as_!=null) ? (Number(hs)+Number(as_)) : null));
    const mt = (pred?.market?.total ?? pred?.market_total ?? pred?.marketTotal ?? null);
    const ms = (pred?.market?.spread_home ?? pred?.market_spread_home ?? pred?.marketSpreadHome ?? null);

    // skip obvious decoy / invalid market rows (prevents OVER 0 noise)
    const _tPickRaw = String(pred?.anchors?.total?.pick || "").trim().toUpperCase();
    if ((mt!=null && Number(mt) <= 0) && (ms!=null && Number(ms) === 0) && (_tPickRaw === "OVER 0" || _tPickRaw === "UNDER 0")) {
      // treat as non-real / invalid market row; don't count against calibration coverage
      continue;
    }

    function pushRow(p, out, tag, units, meta) {
      // Grade even when p_cash is null. p may be null; such rows won't enter buckets but will count toward totals/profit.
      if (!out) return;
      const u = (units != null && isFinite(Number(units)) && Number(units) > 0) ? Number(units) : 1;
      const pv = (p != null && isFinite(Number(p))) ? Number(p) : null;
      rows.push({ p: pv, out, u, tag, meta: meta || null });
    }

    if (mode === "all") {
      // TOTAL
      let tPick = String(pred?.anchors?.total?.pick || "");
      const tP = pred?.anchors?.total?.p_cash;
      const tU = Number(pred?.anchors?.total?.units || 0) || 0;
      let tOut = null;
      if (ft != null && mt != null) {
        if (!tPick) tPick = inferTotalPick(pred?.anchors?.total?.edge_pts, mt) || "";
        const tPickU = String(tPick || "").trim().toUpperCase();
        if (tPickU.startsWith("OVER")) tOut = (ft>mt) ? "W" : (ft<mt) ? "L" : "PUSH";
        else if (tPickU.startsWith("UNDER")) tOut = (ft<mt) ? "W" : (ft>mt) ? "L" : "PUSH";
      }
      if (!tOut && missing_rows.length < missingCap) {
        missing_rows.push({ game_date: kDate, season, home: normalizeTeamAbbr(home), away: normalizeTeamAbbr(away), which: "total", reason: (ft==null||mt==null)?"missing_total_or_score":"unable_to_grade" });
      }
      pushRow(tP, tOut, "total", tU, { game_date:kDate, season, home:normalizeTeamAbbr(home), away:normalizeTeamAbbr(away) });

      // SIDE
      let sPick = String(pred?.anchors?.side?.pick || "").trim();
      const sP = pred?.anchors?.side?.p_cash;
      const sU = Number(pred?.anchors?.side?.units || 0) || 0;
      let sOut = null;
      if (hs!=null && as_!=null && ms!=null && sPick) {
        const pickTeam = sPick.split(/\s+/)[0];
        const margin = hs - as_;
        const sp = Number(ms);
        if (pickTeam === home) { const adj = margin + sp; sOut = (adj>0)?"W":(adj<0)?"L":"PUSH"; }
        else if (pickTeam === away) { const adj = (-margin) - sp; sOut = (adj>0)?"W":(adj<0)?"L":"PUSH"; }
      }
      // If no pick string (PASS), infer a model-side pick from edge sign so calibration can still grade it.
      if (!sPick && hs!=null && as_!=null && ms!=null) {
        sPick = inferSidePick(pred?.anchors?.side?.edge_pts, home, away, ms) || "";
        const pickTeam = sPick.split(/\s+/)[0];
        const margin = hs - as_;
        const sp = Number(ms);
        if (pickTeam === home) { const adj = margin + sp; sOut = (adj>0)?"W":(adj<0)?"L":"PUSH"; }
        else if (pickTeam === away) { const adj = (-margin) - sp; sOut = (adj>0)?"W":(adj<0)?"L":"PUSH"; }
      }
      if (!sOut && missing_rows.length < missingCap) {
        missing_rows.push({ game_date: kDate, season, home: normalizeTeamAbbr(home), away: normalizeTeamAbbr(away), which: "side", reason: (hs==null||as_==null||ms==null)?"missing_spread_or_score":"unable_to_grade" });
      }
      pushRow(sP, sOut, "side", sU, { game_date:kDate, season, home:normalizeTeamAbbr(home), away:normalizeTeamAbbr(away) });
    } else {
      // BEST
      const best = pred?.anchors?.best || null;
      const bestType = best?.type || null;
      const p = (bestType === "total") ? pred?.anchors?.total?.p_cash : pred?.anchors?.side?.p_cash;
      const u = Number(best?.units || 0) || 0;

      let out = null;
      if (bestType === "total") {
        let pick = String(pred?.anchors?.total?.pick || "");
        if (ft != null && mt != null) {
          if (!pick) pick = inferTotalPick(pred?.anchors?.total?.edge_pts, mt) || "";
          const pickU = String(pick||"").trim().toUpperCase();
          if (pickU.startsWith("OVER")) out = (ft>mt) ? "W" : (ft<mt) ? "L" : "PUSH";
          else if (pickU.startsWith("UNDER")) out = (ft<mt) ? "W" : (ft>mt) ? "L" : "PUSH";
        }
      } else if (bestType === "side") {
        let pick = String(pred?.anchors?.side?.pick || "").trim();
        if (!pick && ms!=null) pick = inferSidePick(pred?.anchors?.side?.edge_pts, home, away, ms) || "";
        const pickTeam = pick.split(/\s+/)[0];
        if (hs!=null && as_!=null && ms!=null && pickTeam) {
          const margin = hs - as_;
          const sp = Number(ms);
          if (pickTeam === home) { const adj = margin + sp; out = (adj>0)?"W":(adj<0)?"L":"PUSH"; }
          else if (pickTeam === away) { const adj = (-margin) - sp; out = (adj>0)?"W":(adj<0)?"L":"PUSH"; }
        }
      }

      if (!out && missing_rows.length < missingCap) {
        missing_rows.push({ game_date: kDate, season, home: normalizeTeamAbbr(home), away: normalizeTeamAbbr(away), which: "best", reason: "unable_to_grade" });
      }
      pushRow(p, out, "best", u, { game_date:kDate, season, home:normalizeTeamAbbr(home), away:normalizeTeamAbbr(away), best_type: bestType });
    }
  }

  // bucket stats
  const stats = {};
  const unbucketed = { n:0, w:0, l:0, push:0, profit:0 };
  for (const r of rows) {
    if (r.p == null || !isFinite(Number(r.p))) {
      unbucketed.n++;
      if (r.out === "W") { unbucketed.w++; unbucketed.profit += r.u; }
      else if (r.out === "L") { unbucketed.l++; unbucketed.profit -= r.u; }
      else if (r.out === "PUSH") unbucketed.push++;
      continue;
    }
    const b = Math.floor(r.p*100)/100;
    if (b < minBucket) continue;
    if (!stats[b]) stats[b] = { n:0, w:0, l:0, push:0, profit:0 };
    stats[b].n++;
    if (r.out === "W") { stats[b].w++; stats[b].profit += r.u; }
    else if (r.out === "L") { stats[b].l++; stats[b].profit -= r.u; }
    else if (r.out === "PUSH") stats[b].push++;
  }

  const buckets = Object.keys(stats).map(Number).sort((a,b)=>a-b);
  const outBuckets = buckets.map(b => {
    const s = stats[b];
    const wr = (s.w + s.l) ? (s.w/(s.w+s.l)) : null;
    return { bucket:b, ...s, win_rate: wr };
  });

  const minN = 8;
  function recommendFloor(targetWr) {
    for (const b of outBuckets) {
      if ((b.w + b.l) >= minN && b.win_rate != null && b.win_rate >= targetWr) return b.bucket;
    }
    return null;
  }

  return jsonResponse({
    ok:true,
    data:{
      sample: { rows: rows.length, rows_expected, preds_scanned, joins_found, mode },
      target_break_even: targetBE,
      recommendations: {
        lean_p_cash_floor: recommendFloor(targetBE),
        play_p_cash_floor: recommendFloor(Math.max(targetBE, 0.55)),
        anchor_p_cash_floor: recommendFloor(Math.max(targetBE, 0.57))
      },
      unbucketed,
      missing_rows: missing_rows.length ? missing_rows : [] ,
      buckets: outBuckets
    },
    meta:{ build_id: BUILD_ID, path:"/backtest/calibrate", date: date || null, start: start || null, end: end || null },
    error:null
  });
}


// GET /backtest/calibrate/all?mode=all|best&min_bucket=0.55&limit=2000&budget_ms=20000&cursor=&reset=true
// Budget-safe anchors calibration across ALL logged predictions.
// v6.3.87: internal cursor + KV-backed cumulative run state so full calibration can finish over multiple calls without 504.
async function handleBacktestCalibrateAll(env, req, url) {
  const q = url.searchParams;
  const seasonParam = Number(q.get("season") || 2026);
  const totalLimit = Math.min(25000, Math.max(10, Number(q.get("limit") || 5000)));
  const pageLimit = Math.min(1000, Math.max(10, Number(q.get("page_limit") || q.get("max_cold") || 100)));
  const budgetMs = Math.min(25000, Math.max(1500, Number(q.get("budget_ms") || 18000)));
  const started = Date.now();
  const softStop = () => (Date.now() - started) >= Math.max(500, budgetMs - 750);

  const targetBE = Number(q.get("target_be") || 0.524);
  const minBucket = Number(q.get("min_bucket") || 0.55);
  const mode = (q.get("mode") || "best").toLowerCase();
  const debug = String(q.get("debug") || "").toLowerCase() === "1";
  const reset = ["1","true","yes"].includes(String(q.get("reset") || "").toLowerCase());
  const resumeCursor = q.get("cursor") || q.get("next_cursor") || null;
  const runId = String(q.get("run_id") || `S${seasonParam}:${mode}:mb${minBucket}:be${targetBE}:limit${totalLimit}`)
    .replace(/[^A-Za-z0-9_.:-]/g, "_");
  const stateKey = `nba:cal:anchors:run:v6387:${runId}`;

  const kv = getKV(env);
  if (!kv || !kv.list) {
    return jsonResponse({ ok:false, data:null, meta:{ path:"/backtest/calibrate/all", build_id: BUILD_ID }, error:"backtest:kv_missing_list" }, 500);
  }

  function freshState() {
    return {
      schema: "anchors_calibrate_all_state_v6387",
      run_id: runId,
      season: seasonParam,
      mode,
      target_be: targetBE,
      min_bucket: minBucket,
      limit: totalLimit,
      cursor: null,
      done: false,
      preds_scanned: 0,
      joins_found: 0,
      rows_expected: 0,
      rows: 0,
      unbucketed: { n:0, w:0, l:0, push:0, profit:0 },
      stats: {},
      missing_rows: [],
      missing_cap: debug ? 500 : 50,
      started_at: nowIso(),
      updated_at: nowIso()
    };
  }

  let state = null;
  if (!reset && kv.get) {
    try { state = await kv.get(stateKey, { type: "json" }); } catch (_) { state = null; }
  }
  if (!state || typeof state !== "object" || reset) state = freshState();
  if (resumeCursor) state.cursor = resumeCursor;

  const addMissing = (row) => {
    const cap = Number(state.missing_cap || 50);
    if (state.missing_rows.length < cap) state.missing_rows.push(row);
  };

  function bucketAdd(p, out, units) {
    if (!out) return;
    const u = (units != null && isFinite(Number(units)) && Number(units) > 0) ? Number(units) : 1;
    const pv = (p != null && isFinite(Number(p))) ? Number(p) : null;
    state.rows++;
    if (pv == null) {
      const ub = state.unbucketed;
      ub.n++;
      if (out === "W") { ub.w++; ub.profit += u; }
      else if (out === "L") { ub.l++; ub.profit -= u; }
      else if (out === "PUSH") ub.push++;
      return;
    }
    const b = Math.floor(pv * 100) / 100;
    if (b < minBucket) return;
    const bk = String(b);
    if (!state.stats[bk]) state.stats[bk] = { n:0, w:0, l:0, push:0, profit:0 };
    const st = state.stats[bk];
    st.n++;
    if (out === "W") { st.w++; st.profit += u; }
    else if (out === "L") { st.l++; st.profit -= u; }
    else if (out === "PUSH") st.push++;
  }

  const gradeTotal = (pick, ft, mt, edge) => {
    if (ft == null || mt == null) return null;
    let p = String(pick || "").trim().toUpperCase();
    if (!p) p = inferTotalPick(edge, mt) || "";
    if (p.startsWith("OVER") || p === "O" || p.startsWith("O ")) return (ft > mt) ? "W" : (ft < mt) ? "L" : "PUSH";
    if (p.startsWith("UNDER") || p === "U" || p.startsWith("U ")) return (ft < mt) ? "W" : (ft > mt) ? "L" : "PUSH";
    return null;
  };

  const gradeSide = (pick, hs, as_, ms, home, away, edge) => {
    if (hs == null || as_ == null || ms == null) return null;
    let sPick = String(pick || "").trim();
    if (!sPick) sPick = inferSidePick(edge, home, away, ms) || "";
    const pickTeam = normalizeTeamAbbr(String(sPick).split(/\s+/)[0]);
    const H = normalizeTeamAbbr(home);
    const A = normalizeTeamAbbr(away);
    const margin = Number(hs) - Number(as_);
    const sp = Number(ms);
    if (pickTeam === H) { const adj = margin + sp; return (adj > 0) ? "W" : (adj < 0) ? "L" : "PUSH"; }
    if (pickTeam === A) { const adj = (-margin) - sp; return (adj > 0) ? "W" : (adj < 0) ? "L" : "PUSH"; }
    return null;
  };

  let pages_scanned_this_call = 0;
  let keys_scanned_this_call = 0;
  let lastListComplete = false;

  while (!softStop() && !state.done && state.preds_scanned < totalLimit) {
    const listLimit = Math.min(pageLimit, Math.max(1, totalLimit - state.preds_scanned));
    const listed = await kv.list({ prefix: "nba:bt:v1:pred:", cursor: state.cursor || undefined, limit: listLimit });
    pages_scanned_this_call++;
    const keys = (listed?.keys || []).map(k => k.name).filter(Boolean);
    state.cursor = listed?.cursor || null;
    lastListComplete = !!listed?.list_complete;

    if (!keys.length) {
      state.done = true;
      break;
    }

    for (const k of keys) {
      if (softStop() || state.preds_scanned >= totalLimit) break;
      keys_scanned_this_call++;
      state.preds_scanned++;

      const pred = await kvGetJson(env, k);
      if (!pred) continue;
      const season = Number(pred?.season || seasonParam);
      if (seasonParam && season && season !== seasonParam) continue;
      const home = normalizeTeamAbbr(pred?.home);
      const away = normalizeTeamAbbr(pred?.away);
      if (!season || !home || !away || home === away) continue;

      const rawKDate = String(k || "").split(":")[4] || pred?.game_date || pred?.date || null;
      const kDate = rtpCleanDate(rawKDate);
      if (!kDate) continue;

      const { obj: resObj, key: resKey } = await rtpGetResultForJoin(env, rawKDate, season, home, away);
      if (!resObj) {
        addMissing({ game_date: kDate, season, home, away, which: "join", reason: "result_missing", res_key: resKey });
        continue;
      }
      state.joins_found++;
      state.rows_expected += (mode === "all") ? 2 : 1;

      const hs = Number(resObj?.home_score ?? resObj?.homeScore ?? resObj?.score?.home ?? resObj?.score_home ?? resObj?.home ?? resObj?.h ?? NaN);
      const as_ = Number(resObj?.away_score ?? resObj?.awayScore ?? resObj?.score?.away ?? resObj?.score_away ?? resObj?.away ?? resObj?.a ?? NaN);
      const hsOk = Number.isFinite(hs) ? hs : null;
      const asOk = Number.isFinite(as_) ? as_ : null;
      const ft = (resObj?.final_total ?? resObj?.finalTotal ?? ((hsOk != null && asOk != null) ? (hsOk + asOk) : null));
      const mt = (pred?.market?.total ?? pred?.market_total ?? pred?.marketTotal ?? null);
      const ms = (pred?.market?.spread_home ?? pred?.market_spread_home ?? pred?.marketSpreadHome ?? null);

      const tPickRaw = String(pred?.anchors?.total?.pick || "").trim().toUpperCase();
      if ((mt != null && Number(mt) <= 0) && (ms != null && Number(ms) === 0) && (tPickRaw === "OVER 0" || tPickRaw === "UNDER 0")) continue;

      if (mode === "all") {
        const tOut = gradeTotal(pred?.anchors?.total?.pick, ft, mt, pred?.anchors?.total?.edge_pts);
        if (!tOut) addMissing({ game_date:kDate, season, home, away, which:"total", reason:(ft==null||mt==null)?"missing_total_or_score":"unable_to_grade" });
        bucketAdd(pred?.anchors?.total?.p_cash, tOut, Number(pred?.anchors?.total?.units || 0) || 0);

        const sOut = gradeSide(pred?.anchors?.side?.pick, hsOk, asOk, ms, home, away, pred?.anchors?.side?.edge_pts);
        if (!sOut) addMissing({ game_date:kDate, season, home, away, which:"side", reason:(hsOk==null||asOk==null||ms==null)?"missing_spread_or_score":"unable_to_grade" });
        bucketAdd(pred?.anchors?.side?.p_cash, sOut, Number(pred?.anchors?.side?.units || 0) || 0);
      } else {
        const best = pred?.anchors?.best || {};
        let bestType = String(best?.type || "").toLowerCase();
        let pick = String(best?.pick || "").trim();
        if (!bestType || (bestType !== "side" && bestType !== "total")) {
          if (pick.toUpperCase().startsWith("OVER") || pick.toUpperCase().startsWith("UNDER") || pick.toUpperCase().startsWith("O") || pick.toUpperCase().startsWith("U")) bestType = "total";
          else bestType = "side";
        }
        if (!pick) pick = bestType === "total" ? String(pred?.anchors?.total?.pick || "") : String(pred?.anchors?.side?.pick || "");
        const p = bestType === "total" ? (pred?.anchors?.total?.p_cash ?? best?.p_cash ?? null) : (pred?.anchors?.side?.p_cash ?? best?.p_cash ?? null);
        const u = Number(best?.units || 0) || 0;
        const out = bestType === "total"
          ? gradeTotal(pick, ft, mt, pred?.anchors?.total?.edge_pts)
          : gradeSide(pick, hsOk, asOk, ms, home, away, pred?.anchors?.side?.edge_pts);
        if (!out) addMissing({ game_date:kDate, season, home, away, which:"best", reason:"unable_to_grade", debug: debug ? { bestType, pick, mt, ms, hs:hsOk, as:asOk, ft } : undefined });
        bucketAdd(p, out, u);
      }
    }

    if (listed?.list_complete || state.preds_scanned >= totalLimit) {
      state.done = true;
      break;
    }
  }

  state.updated_at = nowIso();
  if (kv.put) {
    try { await kv.put(stateKey, JSON.stringify(state), { expirationTtl: 86400 * 3 }); } catch (_) {}
  }

  const outBuckets = Object.keys(state.stats || {}).map(Number).sort((a,b)=>a-b).map(b => {
    const st = state.stats[String(b)] || {};
    const w = Number(st.w || 0), l = Number(st.l || 0);
    return { bucket:b, ...st, win_rate: (w + l) ? (w / (w + l)) : null };
  });

  const minN = 8;
  function recommendFloor(targetWr) {
    for (const b of outBuckets) {
      if ((Number(b.w || 0) + Number(b.l || 0)) >= minN && b.win_rate != null && b.win_rate >= targetWr) return b.bucket;
    }
    return null;
  }

  return jsonResponse({
    ok:true,
    data:{
      sample: { rows: state.rows, rows_expected: state.rows_expected, preds_scanned: state.preds_scanned, joins_found: state.joins_found, mode },
      progress: {
        done: !!state.done,
        next_cursor: state.done ? null : state.cursor,
        run_id: runId,
        state_key: stateKey,
        scanned_this_call: keys_scanned_this_call,
        pages_this_call: pages_scanned_this_call,
        budget_ms: budgetMs,
        elapsed_ms: Date.now() - started,
        list_complete: lastListComplete
      },
      target_break_even: targetBE,
      recommendations: {
        lean_p_cash_floor: recommendFloor(targetBE),
        play_p_cash_floor: recommendFloor(Math.max(targetBE, 0.55)),
        anchor_p_cash_floor: recommendFloor(Math.max(targetBE, 0.57))
      },
      unbucketed: state.unbucketed,
      missing_rows: state.missing_rows || [],
      buckets: outBuckets
    },
    meta:{ build_id: BUILD_ID, path:"/backtest/calibrate/all", cursor: state.done ? null : state.cursor, run_id: runId },
    error:null
  });
}


async function handleBacktestReport(env, url) {
  if (!env?.RTP_CACHE?.list) {
    return jsonResponse({ ok:false, data:null, meta:{ path:"/backtest/report" }, error:"backtest:kv_missing_list" }, 500);
  }
  const single = url.searchParams.get("date") || null;
  const start = url.searchParams.get("start") || single || null;
  const end = url.searchParams.get("end") || single || null;
  const limit = Math.max(1, Math.min(500, Number(url.searchParams.get("limit") || 200)));

  // Prefix search (v1): if start provided, use that exact date; otherwise default today.
  const datePrefix = start || nyDateISO();
  const prefix = `nba:bt:v1:pred:${datePrefix}:`;

  const listed = await env.RTP_CACHE.list({ prefix, limit });
  const keys = (listed?.keys || []).map(k => k.name);
  const items = [];
  for (const k of keys) {
    const obj = await kvGetJson(env, k);
    if (obj) items.push(obj);
  }

  // Aggregate basic stats (v2 w/ results + calibration)
  let n = 0;
  let nLean = 0, nPlay = 0, nAnchor = 0, nPass = 0;
  let avgP = 0, avgEdge = 0, nP = 0, nE = 0;
  let blowoutBlocked = 0;

  // v2 results aggregation
  let nWithResults = 0, nWins = 0, nLosses = 0, nPush = 0;
  let sumProfit = 0;
  const calib = {}; // bucket -> {n,w,l,push,avg_p}

  for (const it of items) {
    const a = it?.anchors;
    if (!a) continue;
    n++;

    const best = a?.best || null;
    const act = best?.action || "PASS";
    if (act === "LEAN") nLean++;
    else if (act === "PLAY") nPlay++;
    else if (act === "ANCHOR") nAnchor++;
    else nPass++;

    const bestType = best?.type || null;
    const bestUnits = Number(best?.units || 0) || 0;

    const p = (bestType === "total") ? a?.total?.p_cash : a?.side?.p_cash;
    const edge = (bestType === "total") ? a?.total?.edge_pts : a?.side?.edge_pts;

    if (p != null && isFinite(p)) { avgP += p; nP++; }
    if (edge != null && isFinite(edge)) { avgEdge += Math.abs(edge); nE++; }

    const blocked = (bestType === "total") ? a?.total?.blocked_lean : a?.side?.blocked_lean;
    if (blocked) blowoutBlocked++;

    // Join results from KV (if present)
    const game_date = it?.game_date || it?.date || null;
    const season = it?.season ?? null;
    const home = it?.home ?? null;
    const away = it?.away ?? null;

    let resObj = null;
    if (game_date && season && home && away) {
      const resKey = rtpBtResKey(game_date, season, home, away);
      resObj = await kvGetJson(env, resKey);
    }

    let bestOutcome = null;
    let bestProfitUnits = null;

    // Grade both markets whenever a result exists (regardless of best units)
    let totalOutcome = null, sideOutcome = null;
    let totalProfit = null, sideProfit = null;

    if (resObj) {
      nWithResults++;

      const hs = resObj?.score?.home;
      const as_ = resObj?.score?.away;
      const final_total = resObj?.final_total;

      const market_total = it?.market?.total ?? null;
      const market_spread_home = it?.market?.spread_home ?? null;

      // Total outcome (supports OVER/UNDER)
      const totalPick = a?.total?.pick || null;
      if (final_total != null && market_total != null && totalPick) {
        const s = String(totalPick).trim().toUpperCase();
        const isOver = s.startsWith("OVER");
        const isUnder = s.startsWith("UNDER");
        if (isOver) {
          if (final_total > market_total) totalOutcome = "W";
          else if (final_total < market_total) totalOutcome = "L";
          else totalOutcome = "PUSH";
        } else if (isUnder) {
          if (final_total < market_total) totalOutcome = "W";
          else if (final_total > market_total) totalOutcome = "L";
          else totalOutcome = "PUSH";
        }
        const u = Number(a?.total?.units || 0) || 0;
        if (totalOutcome === "W") totalProfit = u;
        else if (totalOutcome === "L") totalProfit = -u;
        else if (totalOutcome === "PUSH") totalProfit = 0;
      }

      // Side outcome (best-effort using pick team token)
      const sidePick = a?.side?.pick || null;
      if (hs != null && as_ != null && market_spread_home != null && sidePick) {
        const margin = hs - as_;
        const sp = Number(market_spread_home);
        const pickStr = String(sidePick).trim();
        const pickTeam = pickStr.split(" ")[0];

        if (pickTeam === home) {
          const adj = margin + sp;
          if (adj > 0) sideOutcome = "W";
          else if (adj < 0) sideOutcome = "L";
          else sideOutcome = "PUSH";
        } else if (pickTeam === away) {
          const adj = (-margin) - sp;
          if (adj > 0) sideOutcome = "W";
          else if (adj < 0) sideOutcome = "L";
          else sideOutcome = "PUSH";
        }
        const u = Number(a?.side?.units || 0) || 0;
        if (sideOutcome === "W") sideProfit = u;
        else if (sideOutcome === "L") sideProfit = -u;
        else if (sideOutcome === "PUSH") sideProfit = 0;
      }

      // Best bet outcome (for summary ROI/hit rate we keep using best.units>0)
      if (bestType === "total") bestOutcome = totalOutcome;
      else if (bestType === "side") bestOutcome = sideOutcome;

      if (bestUnits > 0 && bestOutcome) {
        if (bestOutcome === "W") { nWins++; bestProfitUnits = bestUnits; sumProfit += bestUnits; }
        else if (bestOutcome === "L") { nLosses++; bestProfitUnits = -bestUnits; sumProfit -= bestUnits; }
        else if (bestOutcome === "PUSH") { nPush++; bestProfitUnits = 0; }
      }

      // Calibration bucket on p_cash (best bet only, only when bestOutcome exists)
      if (p != null && isFinite(p) && bestOutcome) {
        const b = Math.max(0, Math.min(9, Math.floor(p*10)));
        if (!calib[b]) calib[b] = { n:0, w:0, l:0, push:0, avg_p:0 };
        calib[b].n += 1;
        calib[b].avg_p += p;
        if (bestOutcome === "W") calib[b].w += 1;
        else if (bestOutcome === "L") calib[b].l += 1;
        else if (bestOutcome === "PUSH") calib[b].push += 1;
      }

      // Attach full grading
      it.eval = {
        has_result: true,
        score: resObj?.score ?? null,
        final_total: resObj?.final_total ?? null,
        total: {
          action: a?.total?.action ?? null,
          pick: a?.total?.pick ?? null,
          units: Number(a?.total?.units || 0) || 0,
          outcome: totalOutcome,
          profit_units: totalProfit
        },
        side: {
          action: a?.side?.action ?? null,
          pick: a?.side?.pick ?? null,
          units: Number(a?.side?.units || 0) || 0,
          outcome: sideOutcome,
          profit_units: sideProfit
        },
        best: {
          type: bestType,
          action: act,
          units: bestUnits,
          outcome: bestOutcome,
          profit_units: bestProfitUnits
        }
      };
    } else {
      it.eval = { has_result: false };
    }
  }

  const data = {
    schema: "bt_report_v2",
    datePrefix,
    prefix,
    counts: { total: n, pass: nPass, lean: nLean, play: nPlay, anchor: nAnchor, blocked: blowoutBlocked },
    results: { with_results: nWithResults, wins: nWins, losses: nLosses, push: nPush, hit_rate: (nWins + nLosses) ? (nWins / (nWins + nLosses)) : null, profit_units: sumProfit },
    calibration: Object.keys(calib).sort((a,b)=>Number(a)-Number(b)).map(k => { const b = calib[k]; return { bucket: Number(k)/10, n: b.n, win: b.w, loss: b.l, push: b.push, avg_p: b.n ? (b.avg_p/b.n) : null, actual_win_rate: (b.w + b.l) ? (b.w/(b.w+b.l)) : null }; }),
    averages: { p_cash: (nP ? avgP/nP : null), edge_abs: (nE ? avgEdge/nE : null) },
    items: items.slice(0, limit)
  };

  return jsonResponse({ ok:true, data, meta:{ build_id: BUILD_ID }, error:null });
}

// ===========================================================


// GET /games/model?season=2025&season_type=regular&home=BOS&away=NYK&market_total=226.5&market_spread=-3.5
// Returns a lightweight game model + calibrated script used by props and UI.
async function handleGameModel(env, url) {
  const q = url.searchParams;
  const playerNameParam = (q.get("player_name") || q.get("pname") || q.get("player") || "").trim();
  let resolvedPlayerName = playerNameParam;
  const season = asInt(q.get("season") || guessSeason());
  const seasonType = (q.get("season_type") || "regular").toString().toLowerCase();
  const home = _normTeam(q.get("home") || "");
  const away = _normTeam(q.get("away") || "");
  if (!home || !away) return fail(env, "missing_teams", { home, away }, 400);

  // Market inputs: allow both book convention (home -X when favored) and model convention.
  // Market total: treat missing/0 as null so we never calibrate to "0"
const _mt_raw = (q.get("market_total") != null ? q.get("market_total") : q.get("total"));
const _mt_parsed = (_mt_raw != null && String(_mt_raw).trim() !== "") ? asFloat(_mt_raw) : null;
const market_total = (Number.isFinite(Number(_mt_parsed)) && Number(_mt_parsed) > 0) ? Number(_mt_parsed) : null;
  // Market spread: only consider it "present" if a spread param was actually provided.
const _spreadProvided = (
  (q.get("spread_home")!=null && String(q.get("spread_home")).trim()!=="") ||
  (q.get("home_spread")!=null && String(q.get("home_spread")).trim()!=="") ||
  (q.get("spread_away")!=null && String(q.get("spread_away")).trim()!=="") ||
  (q.get("away_spread")!=null && String(q.get("away_spread")).trim()!=="") ||
  (q.get("market_spread_home")!=null && String(q.get("market_spread_home")).trim()!=="") ||
  (q.get("market_spread")!=null && String(q.get("market_spread")).trim()!=="") ||
  (q.get("spread")!=null && String(q.get("spread")).trim()!=="")
);
const _market_spread_home_val = normalizeMarketSpreadHome(
  {
    spread_home: q.get("spread_home") || q.get("home_spread"),
    spread_away: q.get("spread_away") || q.get("away_spread"),
    market_spread_home: q.get("market_spread_home"),
    market_spread: q.get("market_spread") || q.get("spread"),
    spread: q.get("spread"),
  },
  q.get("ml_home"),
  q.get("ml_away")
);
const market_spread_home = _spreadProvided && Number.isFinite(Number(_market_spread_home_val)) ? Number(_market_spread_home_val) : null;

  const forceTeamWell = (q.get('force_teamwell') || q.get('forceTeamWell') || '') === '1';
  const teamMap = await buildTeamWellMap(env, season, { force: forceTeamWell });
  const homeRow = teamMap.get(home);
  const awayRow = teamMap.get(away);
  if (!homeRow || !awayRow) return fail(env, "missing_team_rows", { home, away }, 404);

  const rowsAll = Array.from(teamMap.values());
  const avg = (arr, fallback) => {
    const xs = (arr || []).map((x) => Number(x)).filter((x) => Number.isFinite(x));
    if (!xs.length) return fallback;
    return xs.reduce((a, b) => a + b, 0) / xs.length;
  };
  const lg_ortg = avg(rowsAll.map((r) => r.ortg), 114);
  const lg_drtg = avg(rowsAll.map((r) => r.drtg), 114);
  const lg_pace = avg(rowsAll.map((r) => r.pace_team), 99);

  const n = (v, fb) => {
    const x = Number(v);
    return Number.isFinite(x) ? x : fb;
  };

  const pace = (n(homeRow.pace_team, lg_pace) + n(awayRow.pace_team, lg_pace)) / 2;
  const ortg_h = n(homeRow.ortg, lg_ortg);
  const drtg_h = n(homeRow.drtg, lg_drtg);
  const ortg_a = n(awayRow.ortg, lg_ortg);
  const drtg_a = n(awayRow.drtg, lg_drtg);

  // Baseline matchup efficiencies
  const exp_ortg_home = (ortg_h + (lg_ortg - (lg_drtg - drtg_a))) / 2;
  const exp_ortg_away = (ortg_a + (lg_ortg - (lg_drtg - drtg_h))) / 2;

  // Edges and conservative margin adjustment (same policy as /matchup/sim)
  const edges = computeMatchupEdges(homeRow, awayRow);
  const HCA = asFloat(q.get("hca")) ?? 2.0;

  const w = {
    net: 0.75,
    efg: 40.0,
    tov: 22.0,
    reb: 18.0,
    ftr: 20.0,
    pt_def: 28.0,
    pt_pm: 10.0,
    misc_paint: 0.05,
    misc_fb: 0.04,
    misc_offtov: 0.04,
    misc_second: 0.04,
  };
  const safe = (x) => (x === null || x === undefined ? 0 : Number(x));
  const margin_adj =
    w.net * safe(edges.net_rtg_edge) +
    w.efg * safe(edges.efg_edge) +
    w.tov * safe(edges.tov_edge) +
    w.reb * safe(edges.reb_edge) +
    w.ftr * safe(edges.ft_rate_edge) +
    w.pt_def * safe(edges.pt_def_fg_pct_edge) +
    w.pt_pm * safe(edges.pt_def_plusminus_edge) +
    w.misc_paint * safe(edges.paint_edge) +
    w.misc_fb * safe(edges.fb_edge) +
    w.misc_offtov * safe(edges.off_tov_pts_edge) +
    w.misc_second * safe(edges.second_chance_edge);

  // Mean points
  const home_pts = (pace * exp_ortg_home) / 100 + HCA / 2;
  const away_pts = (pace * exp_ortg_away) / 100 - HCA / 2;
  const total = home_pts + away_pts;
  const spread = -((home_pts - away_pts) + margin_adj); // home spread (negative => home favored)

  const model = {
    pace,
    home_pts,
    away_pts,
    total,
    spread,
  };

  const market = {
    total: Number.isFinite(Number(market_total)) ? Number(market_total) : null,
    spread_home: Number.isFinite(Number(market_spread_home)) ? Number(market_spread_home) : null,
    spread: Number.isFinite(Number(market_spread_home)) ? Number(market_spread_home) : null,
  };

  const strict = asInt(q.get("strict") || "0") === 1;

const dateParam = q.get('date') || q.get('game_date') || null;
const inferredISO = dateParam ? null : (await inferMatchupISODate(env, { seasonEnd: season, home, away }));

// If strict=1: do NOT fall back to "today" (prevents wrong KV snapshot reads)
if (strict && !dateParam && !inferredISO) {
  return fail(env, "missing_date_strict", { hint: "Pass ?date=YYYY-MM-DD (or game_date) when strict=1" }, 400);
}

const dateUsedISO = dateParam || inferredISO || todayISOInTZ(NY_TZ);

  const date_source = dateParam ? 'query' : (inferredISO ? 'inferred' : 'today');

  const includeRest = (q.get('include_rest') ?? '1') === '1';
  const includeTravel = (q.get('include_travel') ?? '1') === '1';
  const debugRest = (q.get('debug_rest') || '') === '1';
  let rest = null;
let rest_debug_obj = null;
if (debugRest) {
  rest_debug_obj = {
    ok: false,
    step: "init",
    date_used: dateUsedISO,
    date_source,
    season_end: season,
    season_start_year: (new Date(dateUsedISO + "T00:00:00Z").getUTCMonth() <= 5 ? season - 1 : season),
    home,
    away,
    include_rest: includeRest,
    include_travel: includeTravel,
    cache_key: null,
    cache_hit: null,
    error: "",
    stack_head: ""
  };
}
if (includeRest || includeTravel) {
  try {
    if (rest_debug_obj) rest_debug_obj.step = "buildRestTravelForGame";
    rest = await buildRestTravelForGame(env, season, dateUsedISO, home, away);
    if (rest_debug_obj) {
      rest_debug_obj.ok = true;
      rest_debug_obj.step = "ok";
      rest_debug_obj.cache_key = rest?.cache_key || null;
      rest_debug_obj.cache_hit = rest?.cached ?? null;
      rest_debug_obj.home_rest_days = rest?.home?.rest_days ?? null;
      rest_debug_obj.away_rest_days = rest?.away?.rest_days ?? null;
      rest_debug_obj.home_last_game = rest?.home?.last_game_date ?? null;
      rest_debug_obj.away_last_game = rest?.away?.last_game_date ?? null;
      rest_debug_obj.travel_miles = rest?.travel_miles ?? null;
    }
  } catch (e) {
    rest = null;
    if (rest_debug_obj) {
      rest_debug_obj.ok = false;
      rest_debug_obj.step = "error";
      rest_debug_obj.error = String(e && e.message ? e.message : e);
      rest_debug_obj.stack_head = String(e && e.stack ? e.stack : "").split("\n").slice(0, 3).join(" | ");
    }
  }
}

  if (rest && includeRest) {
    try {
      const nbRestTable = await getNbastufferRestAedTable(env, { force: false });
      const headers = nbRestTable?.headers || [];
      const rows = nbRestTable?.rows || [];
      const teamIdx = headers.findIndex((h) => String(h).trim().toUpperCase() === "TEAM NAME");
      if (teamIdx >= 0) {
        const wantH = _nbastufferTeamKey(nbastufferTeamLabel(homeRow?.team_name));
        const wantA = _nbastufferTeamKey(nbastufferTeamLabel(awayRow?.team_name));
        for (const r of rows) {
          const k = _nbastufferTeamKey(r?.[teamIdx]);
          if (k && k === wantH) rest.home_rest_aed = pickRestAedFromNbastufferRow(headers, r, rest.home_rest_days);
          if (k && k === wantA) rest.away_rest_aed = pickRestAedFromNbastufferRow(headers, r, rest.away_rest_days);
          if (rest.home_rest_aed != null && rest.away_rest_aed != null) break;
        }
      }
    } catch {}
  }

  const includeRefs = (q.get('include_refs') ?? '1') === '1';
  const debugRefs = (q.get('debug_refs') || '') === '1';

  let refs = null;
  let refsDebug = null;
  try {
    const forceRefs = (q.get('force_refs') || '') === '1' || (q.get('force') || q.get('rebuild') || '') === '1';
    const dateParam = dateUsedISO || null;
    if (includeRefs) {
      refs = await buildRefsContext(env, { seasonEnd: season, home, away, force: forceRefs, date: dateParam, debug: (typeof debugRefs !== 'undefined' ? debugRefs : false) });
      refsDebug = refs && refs._debug ? refs._debug : null;
    }
  } catch (e) {
    if ((typeof debugRefs !== 'undefined' ? debugRefs : false)) refsDebug = { error: String(e && (e.message || e)) };
    refs = null;
  }


  // Elite Environment Pack (optional): if built for the date, attach it.
  // This is additive and never required.
  let envPack = null;
  try {
    if (env.RTP_CACHE) {
            const _envSeasonStart = ((new Date(dateUsedISO + "T00:00:00Z").getUTCMonth() <= 5) ? (season - 1) : season);
      envPack = await getEnvForTeams(env, _envSeasonStart, seasonType, dateUsedISO, home, away);
    }
  } catch {
    envPack = null;
  }


// Injuries (Fresh Start):
// Hard lock to RTP_CACHE ONLY. No bundle overlay. No live API fallback in /script.
let injuryCtx = null;
let injuryLockMeta = null;
try {
  const injDateISO = String(dateUsedISO || game_date || "").slice(0,10);
  const injKey = `nba:injuries:team_score:v1:${injDateISO}:S${season}`;
  const raw = await env.RTP_CACHE.get(injKey);
  injuryLockMeta = { key: injKey, date: injDateISO, has_pack: !!raw };
  if (raw) {
    const pack = JSON.parse(raw);
    if (pack && pack.by_team) {
      const home_score = pack.by_team[home]?.score ?? 0;
      const away_score = pack.by_team[away]?.score ?? 0;
      injuryCtx = { home_score, away_score, source: "kv_team_score", key: injKey, date: injDateISO };
      injuryLockMeta.home_score = home_score;
      injuryLockMeta.away_score = away_score;
    }
  }
} catch (err) {
  injuryCtx = null;
}

// Lineups (BDL daily lock): read only the date-locked lineup pack for the same slate date.
let lineupCtx = null;
let lineupLockMeta = null;
try {
  const lineupDateISO = String(dateUsedISO || game_date || '').slice(0,10);
  const lineupKey = _bdlLineupsKey(season, lineupDateISO);
  const pack = await env?.RTP_CACHE?.get(lineupKey, { type:'json' }).catch(()=>null);
  lineupLockMeta = { key: lineupKey, date: lineupDateISO, has_pack: !!pack };
  if (pack && pack.by_team) {
    const homePack = pack.by_team[home] || null;
    const awayPack = pack.by_team[away] || null;
    lineupCtx = { source: 'bdl_lineups', key: lineupKey, date: lineupDateISO, home: homePack, away: awayPack };
    lineupLockMeta.home_count = homePack?.count ?? 0;
    lineupLockMeta.away_count = awayPack?.count ?? 0;
  }
} catch (err) {
  lineupCtx = null;
}

// Minutes context (optional): prefer proj minutes map; fallback to base minutes map.
// Hard lock RTP_CACHE only. No synthetic defaults: if missing or one team missing -> null.
let minutesCtx = null;
let minutesDiag = null;
try {
  const dateISO = String(dateUsedISO || game_date || "").slice(0,10);
  const seasonNum = Number(season);
  const projKey = `nba:minutes:proj:v1:${dateISO}:S${seasonNum}`;
  const baseKey = `nba:minutes:base:v1:${dateISO}:S${seasonNum}`;

  let chosenKey = null;
  let pack = null;

  // prefer proj
  let raw = await env.RTP_CACHE.get(projKey);
  if (raw) { chosenKey = projKey; pack = (typeof raw === "string") ? JSON.parse(raw) : raw; }
  if (!pack || !pack.by_team) {
    raw = await env.RTP_CACHE.get(baseKey);
    if (raw) { chosenKey = baseKey; pack = (typeof raw === "string") ? JSON.parse(raw) : raw; }
  }

  if (pack && pack.by_team) {
    const byTeam = pack.by_team;
    const homeKey = canonTeamAbbr(home);
    const awayKey = canonTeamAbbr(away);
    const hMap = byTeam[homeKey] || byTeam[home] || null;
    const aMap = byTeam[awayKey] || byTeam[away] || null;

    const hSum = _minutesSummaryFromTeamMap(hMap);
    const aSum = _minutesSummaryFromTeamMap(aMap);
    const kind = pack.kind || (chosenKey === projKey ? "proj" : "base");

    if (hSum && aSum && hMap && aMap) {
      minutesCtx = {
        key: chosenKey,
        kind,
        source: chosenKey === projKey ? "proj" : "base",
        home: hSum,
        away: aSum
      };
    }

    // lightweight diag (no synthetic; just flags)
    minutesDiag = {
      key: chosenKey,
      kind,
      has_home: !!hMap,
      has_away: !!aMap,
      home_rotation: hSum ? hSum.rotation : null,
      away_rotation: aSum ? aSum.rotation : null
    };

    // Fallback lineup proxy from real projected minutes if BDL lineup pack is unavailable.
    // v7.1.8: base minutes may scale player props and backfills, but cannot become lineup-locked truth.
    if ((!lineupCtx || !(lineupCtx.home || lineupCtx.away)) && kind === "proj" && hMap && aMap && hSum && aSum && hSum.rotation >= 8 && aSum.rotation >= 8) {
      const homeProxy = _minutesLineupProxyFromTeamMap(home, hMap, `minutes_${kind}`);
      const awayProxy = _minutesLineupProxyFromTeamMap(away, aMap, `minutes_${kind}`);
      if (homeProxy && awayProxy) {
        lineupCtx = {
          source: `minutes_${kind}_proxy`,
          key: chosenKey,
          date: dateISO,
          proxy_from_minutes: true,
          lineups_locked: true,
          minutes_source_trust_v718: { tier:"projected", factor:1, lineups_locked:true, can_drive_lineup:true, can_drive_blowout:true },
          home: homeProxy,
          away: awayProxy
        };
        lineupLockMeta = Object.assign({}, lineupLockMeta || {}, {
          key: chosenKey,
          date: dateISO,
          has_pack: true,
          proxy_from_minutes: true,
          source: `minutes_${kind}`,
          home_count: homeProxy.count,
          away_count: awayProxy.count
        });
      }
    } else if ((!lineupCtx || !(lineupCtx.home || lineupCtx.away)) && kind !== "proj" && hMap && aMap) {
      lineupLockMeta = Object.assign({}, lineupLockMeta || {}, {
        key: chosenKey,
        date: dateISO,
        has_pack: true,
        proxy_from_minutes: false,
        source: `minutes_${kind}`,
        lineups_locked: false,
        degraded_reason: "base_minutes_not_lineup_truth_v718"
      });
    }
  }
} catch (e) {
  minutesCtx = null;
}

const script = computeGameScript({
    season,
    home: homeRow,
    away: awayRow,
    model,
    market,
    rest,
    refs,
    injuries: injuryCtx || null,
    minutes: minutesCtx || null,
    opts: { minutes_ctx: minutesCtx || null, lineups_ctx: lineupCtx || null },
  });

  script.notes = script.notes || {};
  const hasLineupCtx = !!(lineupCtx && (lineupCtx.home || lineupCtx.away));
  const lineupTrust718 = hasLineupCtx && typeof _rtp718ContextTrustFromSources === "function" ? _rtp718ContextTrustFromSources(lineupCtx.minutes_source_trust_v718 || lineupCtx.source || lineupCtx.source_map || {}) : null;
  script.notes.injuries_locked = !!injuryCtx;
  script.notes.minutes_included = !!minutesCtx;
  script.notes.lineups_locked = !!(hasLineupCtx && lineupTrust718?.lineups_locked);
  script.notes.lineups_included = hasLineupCtx;
  script.notes.lineup_source = hasLineupCtx ? String(lineupCtx.source || '') : null;
  script.notes.lineup_trust_tier_v718 = lineupTrust718?.tier || null;
  script.notes.lineup_degraded_v718 = hasLineupCtx ? !lineupTrust718?.can_drive_lineup : false;
  script.notes.minutes_source = minutesCtx ? String(minutesCtx.source || minutesCtx.kind || '') : null;
  script.notes.teamwell_date_locked = String(dateUsedISO || game_date || '').slice(0,10) || null;
  script.injury_lock = injuryLockMeta || null;
  script.lineup_lock = lineupLockMeta || null;
  script.lineup_context = lineupCtx || null;
  script.minutes_context = minutesCtx || null;
  script.minutes_diag = minutesDiag || null;

  if (debugRest) {
    script.rest_debug = rest_debug_obj || { ok:false, step:'missing' };
    script.notes = script.notes || {};
    script.notes.rest_debug = true;
  }


  return ok(
    env,
    {
      season,
      season_type: seasonType,
      home_team: home,
      away_team: away,
      model,
      market,
      edges,
      script,
      env: envPack,
    },
    { build_id: BUILD_ID }
  );
}


