// ---- Script  baseline projection transform (starter pack + FTM)
function applyScriptToBaseline(baseline, script) {
  const pace_mult = Number(script?.multipliers?.pace_mult ?? 1);
  const foul_mult = Number(script?.multipliers?.foul_mult ?? 1);
  const blow = Number(script?.blowout_risk ?? 0);
  const foulScore = Number(script?.foul_env_score ?? 0.5);
  const spreadEdge = Number(script?.spread_edge_final ?? script?.spread_edge_vs_market ?? 0);

  // Minutes/rotation stability: haircut when blowout is high or spread edge is huge
  const blowHair = clamp01((blow - 0.20) / 0.35);        // 0..1 when blowout in [0.20,0.55]
  const spreadHair = clamp01(Math.abs(spreadEdge) / 6.0); // 0..1 when edge big
  const minutes_mult = 1 - (0.08 * blowHair) - (0.04 * spreadHair);

  // Usage tilt: small, only from foul env + pace (kept conservative until we add player usage model)
  const usage_mult = 1 + (foulScore - 0.5) * 0.02; // +/-1%
  const baseFlags = [];
  if (blow > 0.25) baseFlags.push("BLOWOUT_RISK");
  if ((script?.foul_tag || "") === "whistle-heavy") baseFlags.push("WHISTLE_HEAVY");
  if ((script?.pace_tier || "") === "fast") baseFlags.push("PACE_FAST");
  if ((script?.pace_tier || "") === "slow") baseFlags.push("PACE_SLOW");

  // Stat multipliers
  const pts_mult = pace_mult * minutes_mult * usage_mult * (1 + (foulScore - 0.5) * 0.03);
  const reb_mult = pace_mult * minutes_mult * (1 + (Math.abs(spreadEdge) > 3 ? 0.01 : 0));
  const ast_mult = pace_mult * minutes_mult * usage_mult;
  const threes_mult = pace_mult * minutes_mult * (1 + (foulScore - 0.5) * 0.02);
  const ftm_mult = minutes_mult * foul_mult * (1 + (foulScore - 0.5) * 0.06);

  const pts = baseline.pts * pts_mult;
  const reb = baseline.reb * reb_mult;
  const ast = baseline.ast * ast_mult;
  const fg3m = baseline.fg3m * threes_mult;
  const ftm = baseline.ftm * ftm_mult;
  const pra = pts + reb + ast;

  // Confidence is about stability, not "edge"
  const conf = {
    minutes: 1 - (0.45 * blowHair + 0.15 * spreadHair),
    env: 1 - Math.abs(foulScore - 0.5) * 0.15,
  };
  const totalConf = clamp01(0.55 * conf.minutes + 0.45 * conf.env);

  return {
    projections: {
      pts, reb, ast, pra, threes: fg3m, ftm
    },
    multipliers: {
      pace_mult, foul_mult, minutes_mult, usage_mult,
      pts_mult, reb_mult, ast_mult, threes_mult, ftm_mult
    },
    confidence: {
      overall: totalConf,
      minutes: clamp01(conf.minutes),
      env: clamp01(conf.env),
    },
    flags: baseFlags,
  };
}

function _rtp717Num(v){
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function _rtp717PositiveStatSignal(row){
  try{
    if(!row || typeof row !== "object") return false;
    const vals = [
      row.pts ?? row.points ?? row.pts_per_game,
      row.reb ?? row.rebounds ?? row.reb_per_game,
      row.ast ?? row.assists ?? row.ast_per_game,
      row.fg3m ?? row.three_pt_made ?? row.threes_made ?? row.fg3m_per_game,
      row.ftm ?? row.free_throws_made ?? row.ftm_per_game
    ].map(_rtp717Num).filter((v)=>v != null);
    // Important: all-zero rows from /season_averages are not valid player baselines.
    // They usually mean empty/new-season data and must fall through to recent/prior real stats.
    return vals.some((v)=>v > 0);
  }catch(_){ return false; }
}
function _rtp717ParseMinutes(v){
  if(v == null) return null;
  if(typeof v === "number") return Number.isFinite(v) ? v : null;
  const s = String(v).trim();
  if(!s) return null;
  if(/^\d+:[0-5]?\d$/.test(s)){
    const [m,sec] = s.split(":").map(Number);
    return m + (sec/60);
  }
  const n = Number(s.replace(/[^0-9.\-]/g,""));
  return Number.isFinite(n) ? n : null;
}
function _rtp717StatFromRow(r, keys){
  for(const k of keys){
    const n = _rtp717Num(r?.[k]);
    if(n != null) return n;
  }
  return 0;
}

async function fetchBDLSeasonAveragesOne(env, playerId, seasonStart, seasonEnd) {
  // BallDontLie season_averages behavior has historically varied across versions.
  // Some datasets key by the season END year (e.g., 2026 for 2025-26), others by start year (2025).
  // So we try seasonEnd first, then seasonStart, but v7.1.7 rejects all-zero stat rows.
  const trySeasons = Array.from(new Set([seasonEnd, seasonStart].filter((v) => Number.isFinite(Number(v))).map(Number)));

  for (const s of trySeasons) {
    const data = await fetchBDL(env, "/season_averages", {
      ttl: 120,
      qs: { season: s, "player_ids[]": playerId }
    });
    const row = data?.data?.[0] || data?.[0] || null;
    if (!row) continue;

    if (_rtp717PositiveStatSignal(row)) {
      row._rtp717_baseline_valid = true;
      row._rtp717_baseline_source = "bdl_season_averages_positive";
      return row;
    }
    // All-zero rows are not synthetic baselines. Fall through to recent/prior real stats.
  }

  return null;
}

async function fetchBDLRecentAveragesOne(env, playerId, seasonStart, lastN = 10) {
  // Fallback when /season_averages is empty/all-zero. Pull raw game stats and compute last-N mean.
  const data = await fetchBDL(env, "/stats", {
    ttl: 120,
    qs: { "seasons[]": seasonStart, "player_ids[]": playerId, per_page: 100 }
  });
  const rows0 = data?.data || data || [];
  if (!Array.isArray(rows0) || rows0.length === 0) return null;

  // Only keep rows with real stat signal or real minutes. DNP/empty rows must not become all-zero baselines.
  const rows = rows0.filter((r)=>{
    const min = _rtp717ParseMinutes(r?.min ?? r?.minutes ?? r?.mp);
    const pts = _rtp717StatFromRow(r, ["pts","points"]);
    const reb = _rtp717StatFromRow(r, ["reb","rebounds"]);
    const ast = _rtp717StatFromRow(r, ["ast","assists"]);
    return (Number.isFinite(min) && min > 0) || (pts + reb + ast) > 0;
  });
  if (!rows.length) return null;

  rows.sort((a, b) => {
    const da = (a?.game?.date || a?.game?.start_time || "").toString();
    const db = (b?.game?.date || b?.game?.start_time || "").toString();
    return da < db ? -1 : da > db ? 1 : 0;
  });

  const take = rows.slice(Math.max(0, rows.length - lastN));
  const n = take.length || 1;

  const sum = { pts:0, reb:0, ast:0, fg3m:0, ftm:0, min:0 };
  for (const r of take) {
    sum.pts  += _rtp717StatFromRow(r, ["pts","points"]);
    sum.reb  += _rtp717StatFromRow(r, ["reb","rebounds"]);
    sum.ast  += _rtp717StatFromRow(r, ["ast","assists"]);
    sum.fg3m += _rtp717StatFromRow(r, ["fg3m","three_pt_made","threes_made"]);
    sum.ftm  += _rtp717StatFromRow(r, ["ftm","free_throws_made"]);
    sum.min  += _rtp717ParseMinutes(r?.min ?? r?.minutes ?? r?.mp) || 0;
  }

  if ((sum.pts + sum.reb + sum.ast + sum.fg3m + sum.ftm) <= 0) return null;

  const last = take[take.length - 1] || {};
  let teamAbbr = (last?.team?.abbreviation || last?.team?.abbr || "").toString().toUpperCase() || null;

  return {
    _source: "recent_stats_v717_positive",
    _team_abbr: teamAbbr,
    min: sum.min / n,
    minutes: sum.min / n,
    pts: sum.pts / n,
    reb: sum.reb / n,
    ast: sum.ast / n,
    fg3m: sum.fg3m / n,
    ftm: sum.ftm / n,
    _rtp717_baseline_valid: true,
    _rtp717_baseline_source: "bdl_recent_positive"
  };
}

async function _fetchRecentRatesNBA(env, playerId, seasonStart, lastN = 10) {
  // v7.1.7: Real recent per-minute rates. This helper was referenced but missing, so
  // minutes-based baseline rebuilds silently never happened. No synthetic fills.
  const seasons = Array.from(new Set([Number(seasonStart), Number(seasonStart)-1].filter((v)=>Number.isFinite(v) && v > 0)));
  let bestRows = [];
  let usedSeason = null;
  for (const ss of seasons) {
    const data = await fetchBDL(env, "/stats", {
      ttl: 120,
      qs: { "seasons[]": ss, "player_ids[]": playerId, per_page: 100 }
    });
    const rows0 = data?.data || data || [];
    if (!Array.isArray(rows0) || rows0.length === 0) continue;
    const rows = rows0.filter((r)=>{
      const min = _rtp717ParseMinutes(r?.min ?? r?.minutes ?? r?.mp);
      const pts = _rtp717StatFromRow(r, ["pts","points"]);
      const reb = _rtp717StatFromRow(r, ["reb","rebounds"]);
      const ast = _rtp717StatFromRow(r, ["ast","assists"]);
      return Number.isFinite(min) && min > 0 && (pts + reb + ast) >= 0;
    });
    if (rows.length) { bestRows = rows; usedSeason = ss; break; }
  }
  if (!bestRows.length) return { ok:false, error:"no_recent_stats_rows" };

  bestRows.sort((a, b) => {
    const da = (a?.game?.date || a?.game?.start_time || "").toString();
    const db = (b?.game?.date || b?.game?.start_time || "").toString();
    return da < db ? -1 : da > db ? 1 : 0;
  });
  const take = bestRows.slice(Math.max(0, bestRows.length - lastN));
  const sum = { min:0, pts:0, reb:0, ast:0, fg3m:0, ftm:0 };
  const mins = [];
  for(const r of take){
    const min = _rtp717ParseMinutes(r?.min ?? r?.minutes ?? r?.mp) || 0;
    if(min <= 0) continue;
    mins.push(min);
    sum.min += min;
    sum.pts += _rtp717StatFromRow(r, ["pts","points"]);
    sum.reb += _rtp717StatFromRow(r, ["reb","rebounds"]);
    sum.ast += _rtp717StatFromRow(r, ["ast","assists"]);
    sum.fg3m += _rtp717StatFromRow(r, ["fg3m","three_pt_made","threes_made"]);
    sum.ftm += _rtp717StatFromRow(r, ["ftm","free_throws_made"]);
  }
  if(sum.min <= 0) return { ok:false, error:"no_recent_minutes" };
  if((sum.pts + sum.reb + sum.ast + sum.fg3m + sum.ftm) <= 0) return { ok:false, error:"all_zero_recent_rates" };

  return {
    ok:true,
    data:{
      source:"bdl_recent_rates_v717",
      season:usedSeason,
      games:mins.length,
      mins,
      sum_min:sum.min,
      rates_per_min:{
        pts: sum.pts / sum.min,
        reb: sum.reb / sum.min,
        ast: sum.ast / sum.min,
        fg3m: sum.fg3m / sum.min,
        ftm: sum.ftm / sum.min
      },
      totals:sum
    }
  };
}


async function fetchBDLPlayerInjuryOne(env, playerId, { ttl = 300 } = {}) {
  // BallDontLie NBA injuries endpoint (live): /player_injuries
  // Returns current injury designations for active players.
  if (!playerId) return null;
  const data = await fetchBDL(env, "/player_injuries", {
    ttl,
    qs: { "player_ids[]": playerId, per_page: 50 }
  });
  const rows = data?.data || data || [];
  const r = Array.isArray(rows) ? rows[0] : null;
  if (!r) return null;

  // Normalize fields (BDL has evolved; keep flexible)
  const statusRaw = (r.status || r.game_status || r.availability || "").toString().toLowerCase();
  const desc = (r.description || r.details || r.injury || "").toString();
  const date = r.date || r.updated_at || r.reported_at || null;

  // Map to our tags
  let tag = "unknown";
  if (/(out|inactive)/.test(statusRaw)) tag = "out";
  else if (/(doubtful)/.test(statusRaw)) tag = "doubtful";
  else if (/(questionable)/.test(statusRaw)) tag = "questionable";
  else if (/(probable)/.test(statusRaw)) tag = "probable";
  else if (/(available|active)/.test(statusRaw)) tag = "available";

  return {
    raw: r,
    tag,
    status: statusRaw || null,
    description: desc || null,
    date: date || null,
  };
}

async function fetchBDLBestBaseline(env, playerId, seasonStart, seasonEnd, { lastN = 10 } = {}) {
  // Best-effort baseline pipeline:
  // 1) season_averages (seasonEnd -> seasonStart)
  // 2) last-N averages from /stats for seasonStart
  // 3) prior season_averages (seasonEnd-1 -> seasonStart-1)
  // 4) last-N averages from /stats for seasonStart-1
  const ss = Number(seasonStart);
  const se = Number(seasonEnd);

  const rowsTry = [
    { kind: "season_averages", ss, se },
    { kind: "recent", ss, se: null },
    { kind: "season_averages_prev", ss: ss - 1, se: se - 1 },
    { kind: "recent_prev", ss: ss - 1, se: null },
  ].filter((x) => Number.isFinite(x.ss) && x.ss > 0);

  for (const t of rowsTry) {
    if (t.kind === "season_averages" || t.kind === "season_averages_prev") {
      const row = await fetchBDLSeasonAveragesOne(env, playerId, t.ss, t.se);
      if (row) return { row, source: t.kind, season: t.se ?? t.ss };
    } else {
      const row = await fetchBDLRecentAveragesOne(env, playerId, t.ss, lastN);
      if (row) return { row, source: t.kind, season: t.ss };
    }
  }
  return null;
}


async function fetchBDLPlayerOne(env, playerId) {
  const data = await fetchBDL(env, `/players/${playerId}`, { ttl: 3600 });
  // BDL returns {data:{...}} for v1 endpoints
  return data?.data || data || null;
}


function clamp01(x) {
  const n = Number(x);
  if (!Number.isFinite(n)) return 0;
  if (n < 0) return 0;
  if (n > 1) return 1;
  return n;
}


