//////////////////////////////
// Game lines (OddsAPI) - fail-soft
//////////////////////////////
// GET /game-lines?regions=us&markets=spreads,totals&date=YYYY-MM-DD
// Returns a normalized snapshot of spreads/totals (if ODDS_API_KEY is present).
// This endpoint must NEVER hard-fail the UI; if OddsAPI is unavailable,
// we return ok:true with an empty items array and meta flags.
async function handleGameLines(_req, env, url) {
  const q = url.searchParams;
  const playerNameParam = (q.get("player_name") || q.get("pname") || q.get("player") || "").trim();
  let resolvedPlayerName = playerNameParam;
  const date = String(q.get("date") || "").trim();
  const regions = String(q.get("regions") || "us").trim();
  const markets = String(q.get("markets") || "spreads,totals").trim();
  const oddsFormat = String(q.get("oddsFormat") || "american").trim();
  const dateFormat = String(q.get("dateFormat") || "iso").trim();
  const ttl = asInt(q.get("ttl") || "120") || 120;

  const hasKey = !!(env.ODDS_API_KEY || "").trim();
  let raw = [];
  let upstream = { ok: false, status: 0, err: "missing_odds_api_key" };

  try {
    raw = await fetchOdds(env, { regions, markets, oddsFormat, dateFormat }, { ttl });
    upstream = { ok: Array.isArray(raw), status: 200, err: "" };
  } catch (e) {
    upstream = { ok: false, status: 0, err: String(e?.message || e) };
    raw = [];
  }

  const items = (raw || []).map((ev) => {
    const homeName = String(ev?.home_team || "");
    const awayName = String(ev?.away_team || "");
    const home = _normTeam(homeName);
    const away = _normTeam(awayName);
    const commence_time = ev?.commence_time || ev?.commenceTime || null;

    // Pull first bookmaker for spreads/totals (good enough for UI snapshot)
    const book = (ev?.bookmakers || [])[0] || null;
    const mkts = book?.markets || [];
    const spreads = mkts.find((m) => (m?.key || "") === "spreads") || null;
    const totals = mkts.find((m) => (m?.key || "") === "totals") || null;

    const spreadOutcomes = spreads?.outcomes || [];
    const totalOutcomes = totals?.outcomes || [];

    const pickSpread = (teamName) => {
      const o = spreadOutcomes.find((x) => String(x?.name || "").toLowerCase() === String(teamName || "").toLowerCase());
      return o ? { point: asFloat(o.point), price: asFloat(o.price) } : null;
    };
    const pickTotal = (label) => {
      const o = totalOutcomes.find((x) => String(x?.name || "").toLowerCase() === label);
      return o ? { point: asFloat(o.point), price: asFloat(o.price) } : null;
    };

    const spHome = pickSpread(homeName);
    const spAway = pickSpread(awayName);
    const totOver = pickTotal("over");
    const totUnder = pickTotal("under");

    return {
      event_id: ev?.id || null,
      date: (commence_time || "").slice(0, 10) || null,
      commence_time,
      home,
      away,
      vendor: book?.key || book?.title || null,
      spread_home: spHome?.point ?? null,
      spread_away: spAway?.point ?? null,
      total: totOver?.point ?? totUnder?.point ?? null,
      price_spread_home: spHome?.price ?? null,
      price_spread_away: spAway?.price ?? null,
      price_over: totOver?.price ?? null,
      price_under: totUnder?.price ?? null,
      raw_home: homeName || null,
      raw_away: awayName || null,
    };
  }).filter((x) => x && x.home && x.away);

  // Optional cache snapshot
  const cacheKey = `nba:game_lines:${date || todayISO()}`;
  try {
    if (env?.RTP_CACHE) {
      await kvPutJSON(env, cacheKey, { asOf: new Date().toISOString(), items }, 60 * 5);
    }
  } catch {}

  return ok(
    env,
    {
      date: date || todayISO(),
      games: items.length,
      items,
      has_odds_key: hasKey,
    },
    {
      build_id: BUILD_ID,
      upstream,
      cache_key: cacheKey,
    }
  );
}

