async function handleUpload(req, env) {
  const ct = req.headers.get("content-type") || "";
  let text = "";
  let body = null;

  if (/json/i.test(ct)) {
    body = await req.json().catch(() => null);
  } else {
    text = await req.text().catch(() => "");
  }

  let items = [];
  let source = "text";

  if (body && typeof body === "object") {
    const inputType = String(
      body.input_type || (Array.isArray(body.items) ? "items" : "text")
    ).toLowerCase();

    if (inputType === "text") {
      source = "text";
      const t = String(body.text || text || "");
      items = parsePropsFromText(normalizeText(t));
    } else if (inputType === "items" && Array.isArray(body.items)) {
      source = "items";
      items = body.items;
    } else {
      return fail(
        env,
        "unsupported_input",
        {
          hint:
            'use { input_type:"text", text:"..." } or { input_type:"items", items:[...] }',
        },
        400
      );
    }
  } else {
    const t = String(text || "");
    items = parsePropsFromText(normalizeText(t));
  }

  const sport = "nba";
  // Resolve BDL player_id for each item (real or null; never synthetic)
  try {
    const idMap = await resolvePlayers(env, items || []);
    for (const it of items || []) {
      const full = String(it?.player_name || "").trim();
      if (!full) { it.player_id = null; continue; }
      const hit = idMap.get(full);
      it.player_id = hit?.player_id != null ? hit.player_id : null;
    }
    await storePropIdMapFromItems(env, sport, items || []);
  } catch (e) {
    // Non-fatal: keep player_id null if resolution fails
    for (const it of items || []) {
      if (it && it.player_id == null) it.player_id = null;
    }
  }

  const key = `props:${sport}:${todayISO()}`;
  const bundle = {
    meta: { sport, ingested_at: new Date().toISOString(), source },
    items,
  };
  await propsPutJSON(env, key, bundle);
  await env.RTP_PROPS.put(`props:${sport}:latest`, key);

// Build a lightweight id->name/team mapping so UI (ID-only) can still resolve names for minutes matching.
// This avoids extra upstream calls during upload; we store what we already have.
try {
  for (const it of items || []) {
    const pid = it && (it.player_id ?? it.playerId ?? it.id);
    const pname = it && (it.player_name ?? it.playerName ?? it.name);
    const tabbr = it && (it.team_abbr ?? it.team ?? it.teamAbbr);
    if (!pid || !pname) continue;
    const mapKey = `props:${sport}:idmap:${pid}`;
    const payload = { player_id: pid, player_name: String(pname), team_abbr: tabbr ? String(tabbr) : null, ts: new Date().toISOString() };
    await env.RTP_PROPS.put(mapKey, JSON.stringify(payload), { expirationTtl: 60 * 60 * 24 * 14 }); // 14d
  }
} catch (e) {
  // non-fatal
}


// POST /props/upload.csv  (CSV/TSV containing 5-line slate rows, or a single column "prop_raw")
// - If the sheet is literally the 5-line slate exported as one-column rows (TeamPos, Player, vs/opponent, line, market),
//   we re-group every 5 rows into a proper prop block and reuse parsePropsFromText().
// - If the sheet already has a prop_raw column, we use it directly.
async function handlePropsUploadCSV(req, env) {
  const raw = await req.text().catch(() => "");
  if (!raw || !raw.trim()) return fail(env, "empty_body", {}, 400);

  // Accept CSV or TSV
  const parsed = parseSimpleCSV(raw);
  const header = parsed?.header || [];
  const rows = parsed?.rows || [];

  if (!rows.length) {
    return fail(env, "no_rows", { header }, 400);
  }

  // Helper: pull first column text
  const firstCol = rows.map((r) => (r && r[0] != null ? String(r[0]) : "")).filter((s) => String(s).trim().length > 0);

  // Case A: prop_raw column exists
  const hLower = header.map((h) => String(h || "").trim().toLowerCase());
  const propRawIdx = hLower.indexOf("prop_raw");
  let items = [];
  let source = "csv";

  if (propRawIdx >= 0) {
    const blocks = [];
    for (const r of rows) {
      const v = r && r[propRawIdx] != null ? String(r[propRawIdx]) : "";
      if (!v.trim()) continue;
      blocks.push(v.trim());
    }
    // Each row is already a full prop block
    items = blocks.map((prop_raw) => ({ prop_raw }));
    // If prop_raw contains 5-line blocks, parse them for full schema
    const joined = blocks.join("\n\n");
    const parsedItems = parsePropsFromText(normalizeText(joined));
    if (parsedItems?.length) items = parsedItems;
  } else {
    // Case B: one-column "5-line slate" (like your NBA PROPS.csv)
    // If header is actually a team line, treat it as the first row too.
    const headerLooksLikeData = header.length === 1 && String(header[0] || "").trim().length > 0 && /[A-Z]{2,3}\s*[-]\s*/.test(String(header[0] || ""));
    const lines = [];
    if (headerLooksLikeData) lines.push(String(header[0]).trim());
    for (const v of firstCol) lines.push(String(v).trim());

    // Group into 5-line props whenever possible
    const grouped = [];
    for (let i = 0; i + 4 < lines.length; ) {
      const teamLine = lines[i] || "";
      const playerLine = lines[i + 1] || "";
      const oppLine = lines[i + 2] || "";
      const lineLine = lines[i + 3] || "";
      const marketLine = lines[i + 4] || "";

      // Must look like a prop header row to start a group
      const isTeam = /[A-Z]{2,3}\s*[-]\s*/.test(teamLine);
      const isNumericLine = /^[0-9]+(\.[0-9]+)?$/.test(lineLine.trim());
      const isMarket = marketLine.length > 0;

      if (isTeam && playerLine && oppLine && isNumericLine && isMarket) {
        grouped.push([teamLine, playerLine, oppLine, lineLine, marketLine].join("\n"));
        i += 5;
        continue;
      }

      // Fallback: advance one line and keep scanning
      i += 1;
    }

    const slateText = grouped.join("\n\n");
    items = parsePropsFromText(normalizeText(slateText));
    source = "slate_csv";
  }

  const sport = "nba";
  const key = `props:${sport}:${todayISO()}`;
  const bundle = { meta: { sport, ingested_at: new Date().toISOString(), source }, items };
  await propsPutJSON(env, key, bundle);
  await env.RTP_PROPS.put(`props:${sport}:latest`, key);

  return ok(env, { count: items.length }, { stored: key, source, header });
}


  return ok(env, { count: items.length }, { stored: key });
}


function _normPlayerKey(name) {
  // Normalizes player names for fuzzy matching + KV keys.
  // Examples:
  //  - "Michael Porter" -> "michael porter"
  //  - "Michael Porter Jr." -> "michael porter"
  //  - "E.J. Liddell" -> "e j liddell"
  //  - "Day'Ron Sharpe" -> "day ron sharpe"
  const s = normText(name || "");
  // remove common suffixes and their variations
  const noSuffix = s
    .replace(/\b(jr|jr\.|sr|sr\.|ii|iii|iv|v)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return noSuffix.toLowerCase();
}
async function bdlFetchJson(env, path, { qs = null, method = "GET" } = {}) {
  // v4.3.6.6: robust URL building
  // - If `path` is already an absolute URL, do NOT prefix a base.
  // - Otherwise, prefix with BDL_NBA_BASE when provided; fall back to /v1 base per docs.
  const base = (typeof BDL_NBA_BASE !== "undefined" && BDL_NBA_BASE)
    ? BDL_NBA_BASE
    : "https://api.balldontlie.io/v1";

  const rawPath = String(path || "");
  const u = /^https?:\/\//i.test(rawPath)
    ? new URL(rawPath)
    : new URL(String(base).replace(/\/+$/,"") + "/" + rawPath.replace(/^\/+/,""));

  if (qs && typeof qs === "object") {
    for (const [k, v] of Object.entries(qs)) {
      if (v === undefined || v === null || v === "") continue;
      // support repeated params via array
      if (Array.isArray(v)) {
        for (const vv of v) {
          if (vv === undefined || vv === null || vv === "") continue;
          u.searchParams.append(k, String(vv));
        }
      } else {
        u.searchParams.set(k, String(v));
      }
    }
  }

  const auth = getBdlAuthValue(env);
  const headers = {
    "accept": "application/json,text/plain;q=0.9,*/*;q=0.8",
    "user-agent": "Mozilla/5.0 (compatible; RTP-NBA-Lab/1.0; +https://rtp-nba.pages.dev)",
  };
  if (auth) headers["authorization"] = auth;

  try {
    const res = await fetch(u.toString(), { method, headers });
    const text = await res.text();
    let json = null;
    try { json = JSON.parse(text); } catch (e) {}
    return {
      ok: res.ok,
      status: res.status,
      url: u.toString(),
      json,
      text_head: text ? String(text).slice(0, 180) : ""
    };
  } catch (e) {
    return { ok: false, status: 0, url: u.toString(), json: null, text_head: String(e || "").slice(0, 180) };
  }
}

async function _resolvePlayerId(env, teamAbbr, playerName, dbg = null) {
  const team = (teamAbbr || "").toUpperCase().trim();
  const keyName = _normPlayerKey(playerName);
  if (!team || !keyName) return null;

  const mapKey = `nba:pidmap:${team}:${keyName}`;
  const cached = await kvGetJson(env, mapKey);
  if (dbg) dbg.push({ step: "map_cache", key: mapKey, hit: !!cached });
  if (cached && typeof cached === "object" && cached.player_id) return cached.player_id;
  if (typeof cached === "number") return cached;
  // Use BDL search to resolve
  const r = await bdlFetchJson(env, "/players", { qs: { search: playerName, per_page: 50 } });
  if (dbg) dbg.push({ step: "bdl_search", ok: r.ok, status: r.status, url: r.url, text_head: r.text_head });
  const items = Array.isArray(r?.json?.data) ? r.json.data : (Array.isArray(r?.json) ? r.json : (Array.isArray(r?.json?.data?.data) ? r.json.data.data : []));
  if (!items.length) {
  const raw = String(playerName || "").trim();
  const variants = [];
  const rawNoSuffix = raw.replace(/\b(JR\.?|SR\.?|II|III|IV|V)\b/ig, " ").replace(/\s+/g, " ").trim();
  if (rawNoSuffix && rawNoSuffix.toLowerCase() !== raw.toLowerCase()) variants.push(rawNoSuffix);
  try {
    const parts = normText(rawNoSuffix || raw).split(" ").filter(Boolean);
    if (parts.length >= 2) {
      // last-name search is often more reliable
      variants.push(parts[parts.length - 1]);
      // first+last (already) but without middle token
      variants.push(parts[0] + " " + parts[parts.length - 1]);
    }
  } catch {}
  for (const v of variants) {
    const r2 = await bdlFetchJson(env, "/players", { qs: { search: v, per_page: 50 } });
    if (dbg) dbg.push({ step: "bdl_search_retry", q: v, ok: r2.ok, status: r2.status, url: r2.url, text_head: r2.text_head });
    const it2 = Array.isArray(r2?.json?.data) ? r2.json.data : (Array.isArray(r2?.json) ? r2.json : (Array.isArray(r2?.json?.data?.data) ? r2.json.data.data : []));
    if (it2 && it2.length) { items.push(...it2); break; }
  }
  if (!items.length) return null;
}


  const targetNorm = keyName;
  const scored = items.map((p) => {
    const full = p.full_name || `${p.first_name || ""} ${p.last_name || ""}`.trim();
    const fullNorm = _normPlayerKey(full);
    const teamKey = (p.team_abbr || p.team?.abbreviation || p.team?.abbr || "").toUpperCase().trim();
    let score = 0;
    if (teamKey === team) score += 50;
    if (fullNorm === targetNorm) score += 40;
    if (fullNorm.includes(targetNorm) || targetNorm.includes(fullNorm)) score += 10;
    // extra fuzzy: same last name + first initial
    try {
      const tn = String(targetNorm || "").split(" ").filter(Boolean);
      const fn = String(fullNorm || "").split(" ").filter(Boolean);
      if (tn.length >= 2 && fn.length >= 2) {
        if (fn[fn.length - 1] === tn[tn.length - 1]) score += 8;
        if ((fn[0] || "")[0] && (tn[0] || "")[0] && fn[0][0] === tn[0][0]) score += 5;
        if (fn.slice(0,2).join(" ") === tn.slice(0,2).join(" ")) score += 6;
      }
    } catch {}

    return { p, score, teamKey, full, fullNorm };
  }).sort((a,b)=>b.score-a.score);

  const best = scored[0];
  if (!best || !best.p || !best.p.id || best.score < 10) return null;

  // Cache mapping
  await kvPutJson(env, mapKey, { player_id: best.p.id, team: team, player: best.full, ts: new Date().toISOString() }, 60 * 60 * 24 * 365);
  return best.p.id;
}

// [cleaned] removed legacy lines 17277-19344

async function handleList(_req, env, url) {
  const sport = (url.searchParams.get("sport") || "nba").toLowerCase();
  const ptr = await env.RTP_PROPS.get(`props:${sport}:latest`);
  if (!ptr) return ok(env, [], { sport, key: null });
  const raw = await env.RTP_PROPS.get(ptr);
  if (!raw) return ok(env, [], { sport, key: ptr });
  const parsed = JSON.parse(raw);
  return ok(env, parsed.items || [], {
    ...(parsed.meta || {}),
    key: ptr,
  });
}

//////////////////////////////
// Props  enriched CSV
//////////////////////////////

function parseSimpleCSV(text) {
  const trimmed = text.trim();
  if (!trimmed) return { header: [], rows: [] };
  const lines = trimmed.split(/\r?\n/);
  const header = lines[0].split(",");
  const rows = lines.slice(1).map((line) => {
    const cols = line.split(",");
    const obj = {};
    header.forEach((h, idx) => {
      obj[h] = cols[idx] ?? "";
    });
    return obj;
  });
  return { header, rows };
}

async function handleExportCSV(_req, env, url) {
  const sport = (url.searchParams.get("sport") || "nba").toLowerCase();
  if (sport !== "nba") {
    return fail(env, "only_nba_supported", { sport }, 400);
  }

  // Export modes:
  //  - fast (default): O(1) export of the stored props blob (no live enrichment)
  //  - full: runs live enrichment (resolve players + player bags + team-well)
  const exportMode = String(url.searchParams.get("mode") || "fast").toLowerCase();

  const season = Number(url.searchParams.get("season")) || guessSeason();

  const ptr = await env.RTP_PROPS.get(`props:${sport}:latest`);
  const baseHeader = [
    ...PROP_FIELDS,
    ...FEATURE_FIELDS,
    ...ADVANCED_FIELDS,
    ...TEAM_WELL_FIELDS,
    ...GRADE_FIELDS,
  ];

  if (!ptr) {
    const header = Array.from(new Set(baseHeader));
    const csvEmpty = toCSV(header, []);

    // UI/iOS failsafe: allow JSON envelope carrying the CSV
    if ((url.searchParams.get('format') || '').toLowerCase() === 'json') {
      return ok(env, { filename: 'rtp_nba_enriched_empty.csv', csv: csvEmpty }, { season, mode: 'empty' });
    }

    return new Response(csvEmpty, {
      status: 200,
      headers: {
        ...cors({}),
        "content-type": "text/csv; charset=utf-8",
        "content-disposition":
          'attachment; filename="rtp_nba_enriched_empty.csv"',
        "x-rtp-schema": DEFAULTS.SCHEMA_TAG,
        "cache-control": "no-store",
      },
    });
  }

  const raw = await env.RTP_PROPS.get(ptr);
  if (!raw) {
    return fail(env, "missing_props_blob", { ptr }, 404);
  }

  let items = [];

  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      items = parsed;
    } else {
      if (Array.isArray(parsed.items)) items = parsed.items;
      else if (Array.isArray(parsed.data)) items = parsed.data;
      else items = [];
    }
  } catch (e) {
    return fail(env, "bad_props_json", { ptr, msg: e.message }, 500);
  }

  if (!items.length) {
    const header = Array.from(new Set(baseHeader));
    const csvEmpty = toCSV(header, []);

    // UI/iOS failsafe: allow JSON envelope carrying the CSV
    if ((url.searchParams.get('format') || '').toLowerCase() === 'json') {
      return ok(env, { filename: 'rtp_nba_enriched_empty.csv', csv: csvEmpty }, { season, mode: 'empty' });
    }

    return new Response(csvEmpty, {
      status: 200,
      headers: {
        ...cors({}),
        "content-type": "text/csv; charset=utf-8",
        "content-disposition":
          'attachment; filename="rtp_nba_enriched_empty.csv"',
        "x-rtp-schema": DEFAULTS.SCHEMA_TAG,
        "cache-control": "no-store",
      },
    });
  }

  // FAST MODE: avoid all upstream calls and heavy joins.
  // This prevents timeouts (504) when exporting from the UI.
  if (exportMode !== "full") {
    const headerSet = new Set(baseHeader);
    for (const it of items) {
      if (it && typeof it === "object" && !Array.isArray(it)) {
        for (const k of Object.keys(it)) headerSet.add(k);
      }
    }
    const header = Array.from(headerSet);
    const csv = toCSV(header, items);

    // UI/iOS failsafe: allow JSON envelope carrying the CSV
    if ((url.searchParams.get('format') || '').toLowerCase() === 'json') {
      return ok(env, { filename: 'rtp_nba_props_fast.csv', csv }, { season, mode: 'fast' });
    }

    return new Response(csv, {
      status: 200,
      headers: {
        ...cors({}),
        "content-type": "text/csv; charset=utf-8",
        "content-disposition": 'attachment; filename="rtp_nba_props_fast.csv"',
        "x-rtp-schema": DEFAULTS.SCHEMA_TAG,
        "cache-control": "no-store",
        "x-rtp-export-mode": "fast",
      },
    });
  }

  const resolved = await resolvePlayers(env, items);

  const pids = Array.from(
    new Set(
      items
        .map((i) => resolved.get(i.player_name)?.player_id)
        .filter(Boolean)
    )
  );

  const teamAbbrs = Array.from(
    new Set(
      items
        .map((i) => {
          const r = resolved.get(i.player_name) || {};
          return (r.team_abbr || i.team_abbr || "").toUpperCase();
        })
        .filter(Boolean)
    )
  );

  const { seasonMap, l10Map, advancedMap } =
    await collectPlayerBags(env, season, pids, (url.searchParams.get('date') || '').trim() || null);

  const teamWellMap = await collectTeamWells(env, season, teamAbbrs);

  const rows = [];

  for (const p of items) {
    const resv = resolved.get(p.player_name) || {};
    const pid = resv.player_id || null;

    const row = buildRowShell(p, resv);

    const sa = pid ? seasonMap.get(pid) || null : null;
    const l10 = pid ? l10Map.get(pid) || [] : [];
    const adv = pid ? advancedMap.get(pid) || null : null;

    mergeSeason(row, sa);
    mergeL10(row, l10);
    mergeAdvanced(row, adv);

    const tAbbr = (
      row.team_abbr ||
      resv.team_abbr ||
      p.team_abbr ||
      ""
    ).toUpperCase();
    const well = teamWellMap.get(tAbbr);
    mergeTeamWell(row, well);

    const lineNum = Number(
      p.line ?? p.Line ?? p.prop_line
    );
    const market = String(p.market || "").toLowerCase();

    let proj = null;
    if (
      Number.isFinite(lineNum) &&
      (sa || (Array.isArray(l10) && l10.length))
    ) {
      proj = buildProjectionForMarket({
        market,
        line: lineNum,
        seasonRow: sa,
        l10Games: l10,
      });
    }

    row.proj_stat = proj?.proj_stat ?? "";
    row.proj_pts = proj?.proj_pts ?? "";
    row.proj_reb = proj?.proj_reb ?? "";
    row.proj_ast = proj?.proj_ast ?? "";
    row.sim_hit_prob = proj?.sim_hit_prob ?? "";
    row.model_prob_over = proj?.model_prob_over ?? "";
    row.model_prob_under = proj?.model_prob_under ?? "";

    gradePropRow(row);
    rows.push(row);
  }

  const header = Array.from(
    new Set([
      ...baseHeader,
      ...rows.flatMap((r) => Object.keys(r)),
    ])
  );

  const csv = toCSV(header, rows);
  const fname = `rtp_nba_enriched_props_${todayISO()}_${Date.now()}.csv`;

  try {
    await r2PutCSV(env, fname, csv);
  } catch (e) {
    console.error("R2 save failed", e);
  }

  return new Response(csv, {
    status: 200,
    headers: {
      ...cors({}),
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="${fname}"`,
      "x-rtp-schema": DEFAULTS.SCHEMA_TAG,
      "cache-control": "no-store",
    },
  });
}

function buildProjectionForMarket({ market, line, seasonRow, l10Games }) {
  const seaPts = Number(seasonRow?.pts_pg ?? seasonRow?.pts ?? 0);
  const seaReb = Number(seasonRow?.reb_pg ?? seasonRow?.reb ?? 0);
  const seaAst = Number(seasonRow?.ast_pg ?? seasonRow?.ast ?? 0);

  let l10Pts = 0, l10Reb = 0, l10Ast = 0;
  if (Array.isArray(l10Games) && l10Games.length) {
    for (const g of l10Games) {
      l10Pts += Number(g.pts ?? 0);
      l10Reb += Number(g.reb ?? 0);
      l10Ast += Number(g.ast ?? 0);
    }
    const n = l10Games.length;
    l10Pts /= n; l10Reb /= n; l10Ast /= n;
  } else {
    l10Pts = Number(l10Games?.pts_pg ?? l10Games?.pts ?? 0);
    l10Reb = Number(l10Games?.reb_pg ?? l10Games?.reb ?? 0);
    l10Ast = Number(l10Games?.ast_pg ?? l10Games?.ast ?? 0);
  }

  const blend = (sea, l10) => {
    if (!sea && !l10) return 0;
    if (!l10) return sea;
    if (!sea) return l10;
    return 0.7 * sea + 0.3 * l10;
  };

  const projPts = blend(seaPts, l10Pts);
  const projReb = blend(seaReb, l10Reb);
  const projAst = blend(seaAst, l10Ast);

  let proj = 0;
  const m = String(market || "").toLowerCase();

  switch (m) {
    case "pts":
    case "points":
      proj = projPts;
      break;
    case "reb":
    case "rebs":
    case "rebounds":
      proj = projReb;
      break;
    case "ast":
    case "assists":
      proj = projAst;
      break;
    case "pra":
      proj = projPts + projReb + projAst;
      break;
    case "pts+rebs":
    case "points+rebounds":
      proj = projPts + projReb;
      break;
    case "pts+asts":
    case "points+assists":
      proj = projPts + projAst;
      break;
    case "rebs+asts":
    case "rebounds+assists":
      proj = projReb + projAst;
      break;
    default:
      proj = projPts;
      break;
  }

  const vals = [];
  if (Array.isArray(l10Games) && l10Games.length) {
    for (const g of l10Games) {
      let v = 0;
      const pts = Number(g.pts ?? 0);
      const reb = Number(g.reb ?? 0);
      const ast = Number(g.ast ?? 0);
      switch (m) {
        case "pts":
        case "points":
          v = pts; break;
        case "reb":
        case "rebs":
        case "rebounds":
          v = reb; break;
        case "ast":
        case "assists":
          v = ast; break;
        case "pra":
          v = pts + reb + ast; break;
        case "pts+rebs":
        case "points+rebounds":
          v = pts + reb; break;
        case "pts+asts":
        case "points+assists":
          v = pts + ast; break;
        case "rebs+asts":
        case "rebounds+assists":
          v = reb + ast; break;
        default:
          v = pts; break;
      }
      vals.push(v);
    }
  }

  let sigma = 4;
  if (vals.length > 1) {
    const mVal = vals.reduce((a, b) => a + b, 0) / vals.length;
    const varSum = vals.reduce((a, v) => {
      const d = v - mVal;
      return a + d * d;
    }, 0);
    sigma = Math.sqrt(varSum / vals.length) || sigma;
  }

  let hitProb = "";
  let modelProbOver = "";
  let modelProbUnder = "";

  if (typeof line === "number" && Number.isFinite(line) && sigma > 0) {
    const z = (line - proj) / sigma;
    const cdf = 0.5 * (1 + erf(z / Math.SQRT2));
    const probOver = 1 - cdf;
    const probUnder = cdf;

    hitProb = Number(probOver.toFixed(4));
    modelProbOver = hitProb;
    modelProbUnder = Number(probUnder.toFixed(4));
  }

  return {
    proj_stat: proj ? Number(proj.toFixed(2)) : "",
    proj_pts: projPts ? Number(projPts.toFixed(2)) : "",
    proj_reb: projReb ? Number(projReb.toFixed(2)) : "",
    proj_ast: projAst ? Number(projAst.toFixed(2)) : "",
    sim_hit_prob: hitProb,
    model_prob_over: modelProbOver,
    model_prob_under: modelProbUnder,
  };
}

//////////////////////////////
// /props/sim  (CSV  re-run sim)
//////////////////////////////

async function handlePropsSim(req, env, url) {
  const sport = (url.searchParams.get("sport") || "nba").toLowerCase();
  if (sport !== "nba") {
    return fail(env, "only_nba_supported", { sport }, 400);
  }

  const body = await req.text();
  let { header, rows } = parseSimpleCSV(body);

  // If user uploaded a 1-column "5-line slate" CSV (each row is a line: team-pos, player, vs/opponent, line, market),
  // convert it into the normal props schema before enrichment.
  const hLower0 = (header || []).map((h) => String(h || "").trim().toLowerCase());
  const hasPropRaw0 = hLower0.includes("prop_raw");
  const looksLikeSlate0 =
    !hasPropRaw0 &&
    (header || []).length >= 1 &&
    /[A-Z]{2,3}\s*[-]\s*/.test(String(header[0] || "").trim());
  if (looksLikeSlate0) {
    const h0 = String(header[0] || "").trim();
    const lines = [h0];
    for (const r of rows || []) {
      const v = r && r[h0] != null ? String(r[h0]) : "";
      if (v.trim()) lines.push(v.trim());
    }
    const grouped = [];
    for (let i = 0; i + 4 < lines.length; ) {
      const teamLine = lines[i] || "";
      const playerLine = lines[i + 1] || "";
      const oppLine = lines[i + 2] || "";
      const lineLine = lines[i + 3] || "";
      const marketLine = lines[i + 4] || "";

      const isTeam = /[A-Z]{2,3}\s*[-]\s*/.test(teamLine);
      const isNumericLine = /^[0-9]+(\.[0-9]+)?$/.test(String(lineLine).trim());
      if (isTeam && playerLine && oppLine && isNumericLine && marketLine) {
        grouped.push([teamLine, playerLine, oppLine, lineLine, marketLine].join("\n"));
        i += 5;
        continue;
      }
      i += 1;
    }
    const slateText = grouped.join("\n\n");
    const parsedItems = parsePropsFromText(normalizeText(slateText));
    rows = (parsedItems || []).map((it) => ({
      prop_raw: it.prop_raw || "",
      player_name: it.player_name || "",
      team_abbr: it.team_abbr || "",
      opp_abbr: it.opp_abbr || "",
      market: it.market || "",
      line: it.line != null ? it.line : "",
      lean: it.lean || "",
      game_date: it.game_date || todayISO(),
    }));
    header = PROP_FIELDS.slice();
  }


  // Ensure player_id exists and is resolved (real or null)
  if (!header.includes("player_id")) header = ["player_id", ...header];
  try {
    const toResolve = (rows || []).map((r) => ({
      player_name: r.player_name || "",
      team_abbr: r.team_abbr || "",
      position: r.position || r.pos || "",
    }));
    const idMap = await resolvePlayers(env, toResolve);
    for (const r of rows || []) {
      const full = String(r.player_name || "").trim();
      const hit = idMap.get(full);
      r.player_id = hit?.player_id != null ? hit.player_id : null;
    }
    await storePropIdMapFromItems(env, sport, (rows || []).map((r)=>({player_id:r.player_id, player_name:r.player_name, team_abbr:r.team_abbr})));
  } catch (e) {
    for (const r of rows || []) {
      if (r.player_id == null) r.player_id = null;
    }
  }

  if (!rows.length) {
    const csv = toCSV(header, []);
    return new Response(csv, {
      status: 200,
      headers: {
        ...cors({}),
        "content-type": "text/csv; charset=utf-8",
        "content-disposition":
          'attachment; filename="rtp_nba_sim_empty.csv"',
        "cache-control": "no-store",
      },
    });
  }

  const out = [];
  const seasonInput = url.searchParams.get("season") || "";
  const { seasonStart } = normalizeSeasonInput(seasonInput);
  // Build TeamWell map once for matchup-aware adjustments
  let teamWellMap = null;
  try { teamWellMap = await buildTeamWellMap(env, seasonInput || String(seasonStart)); } catch(e) { teamWellMap = null; }

  const eliteExtraCols = ["sigma_used","sigma_source","n_logs_used","proj_stat_used","elite_adj_pct","minutes_mean","minutes_sd","minutes_risk","minutes_proj","minutes_source","p_cal_over","p_cal_under"];
  for (const c of eliteExtraCols) { if (!header.includes(c)) header.push(c); }

  const ctx = { seasonStart, teamWellMap, playerLogsCache: new Map() };

  // Optional environment pack to drive props (pace/total/blowout).
  const envDateISO = (url.searchParams.get("date") || url.searchParams.get("slate_date") || todayISOInTZ(NY_TZ)).slice(0, 10);
  const envSeason = asInt(url.searchParams.get("env_season") || url.searchParams.get("season") || String(seasonStart)) || seasonStart;
  const envSeasonType = (url.searchParams.get("env_season_type") || url.searchParams.get("season_type") || "regular").toLowerCase();
  let envPack = null;
  try {
    if (env.RTP_CACHE) envPack = await getEnvPackFromKV(env, envSeason, envSeasonType, envDateISO);
  } catch { envPack = null; }

  
// Minutes snapshot to drive props using canonical proj/base minutes.
// Priority:
// 1) nba:minutes:proj:v1:YYYY-MM-DD:Sseason
// 2) nba:minutes:base:v1:YYYY-MM-DD:Sseason
// If missing -> minutes=null (no synthetic fills).
let minutesSnap = null;
try {
  const loadedMinutes = await _loadCanonicalMinutesSnap(env, { season: envSeason, date: envDateISO, prefer: ["proj", "base"] });
  minutesSnap = loadedMinutes.snap || null;
} catch { minutesSnap = null; }

// Optional props calibration model (maps p_raw -> p_cal by market bucket)
let calModel = null;
try {
  if (env.RTP_CACHE) calModel = await kvGetJson(env, KV_CAL_PROPS_MODEL_KEY);
} catch { calModel = null; }

ctx.minutesProjMap = _buildMinutesProjMapFromSnap(minutesSnap);

  const envCols = ["env_date","env_poss_proj","env_total_proj","env_team_pts_proj","env_blowout_risk","env_adj_factor"];
  for (const c of envCols) { if (!header.includes(c)) header.push(c); }


  for (const r of rows) {
    const elite = await elitePropCalcs(env, r, ctx);

    // Environment adjustment (if available): scale counting stats by possessions.
    // This is intentionally conservative and only nudges projections.
    let env_game = null;
    let env_team_pts_proj = null;
    let env_poss_proj = null;
    let env_total_proj = null;
    let env_blowout_risk = null;
    let env_adj_factor = null;

    try {
      const ta = _normTeam(r?.team_abbr || r?.team || "");
      const oa = _normTeam(r?.opp_abbr || r?.opponent || r?.opp || "");
      if (envPack?.games?.length && ta && oa) {
        for (const g of envPack.games) {
          const h = _normTeam(g?.home);
          const a = _normTeam(g?.away);
          if ((h === ta && a === oa) || (h === oa && a === ta)) { env_game = g; break; }
        }
      }
      if (env_game) {
        env_poss_proj = asFloat(env_game.poss_proj);
        env_total_proj = asFloat(env_game.total_proj);
        env_blowout_risk = asFloat(env_game.blowout_risk);
        // team points depends on home/away orientation
        const h = _normTeam(env_game.home);
        env_team_pts_proj = (ta && h === ta) ? asFloat(env_game.home_pts_proj) : asFloat(env_game.away_pts_proj);
        const lgPoss = 99;
        if (env_poss_proj != null && Number.isFinite(env_poss_proj)) {
          env_adj_factor = Number((env_poss_proj / lgPoss).toFixed(4));
          if (Number.isFinite(elite.proj_stat_used) && elite.proj_stat_used) {
            elite.proj_stat_used = elite.proj_stat_used * env_adj_factor;
          }
        }
      }
    } catch {}

    let simHitProb = "";
    let modelProbOver = "";
    let modelProbUnder = "";

    if (Number.isFinite(elite.lineNum) && elite.proj_stat_used) {
      const sigma = Number(elite.sigma_used);
      if (sigma > 0) {
        const z = (elite.lineNum - elite.proj_stat_used) / sigma;
        const cdf = 0.5 * (1 + erf(z / Math.SQRT2));
        const probOver = 1 - cdf;
        const probUnder = cdf;

        simHitProb = Number(probOver.toFixed(4));
        modelProbOver = simHitProb;
        modelProbUnder = Number(probUnder.toFixed(4));
      }
    }

    // Apply calibration to model probabilities (optional)
    const marketName = (r.market || r.Market || r.prop_market || r.market_name || r.marketKey || "").toString();
    const pCalOver = calModel ? _applyCalPropsModel(modelProbOver, marketName, calModel) : null;
    const pCalUnder = calModel ? _applyCalPropsModel(modelProbUnder, marketName, calModel) : null;

    const row = {
      ...r,
      env_date: envDateISO,
      env_poss_proj: env_poss_proj ?? "",
      env_total_proj: env_total_proj ?? "",
      env_team_pts_proj: env_team_pts_proj ?? "",
      env_blowout_risk: env_blowout_risk ?? "",
      env_adj_factor: env_adj_factor ?? "",
      // elite diagnostics
      sigma_used: elite.sigma_used ? Number(Number(elite.sigma_used).toFixed(4)) : "",
      sigma_source: elite.sigma_source || "",
      n_logs_used: elite.n_logs_used || "",
      proj_stat_used: elite.proj_stat_used ? Number(Number(elite.proj_stat_used).toFixed(4)) : "",
      elite_adj_pct: elite.elite_adj_pct ?? "",
      minutes_mean: elite.minutes_mean ?? "",
      minutes_sd: elite.minutes_sd ?? "",
      minutes_risk: elite.minutes_risk ?? "",
      // existing outputs
      minutes_proj: elite.minutes_proj ?? "",
      minutes_source: elite.minutes_source ?? "",
      // existing outputs
      sim_hit_prob: simHitProb,
      model_prob_over: modelProbOver,
      model_prob_under: modelProbUnder,
      p_cal_over: (pCalOver==null? "" : Number(Number(pCalOver).toFixed(4))),
      p_cal_under: (pCalUnder==null? "" : Number(Number(pCalUnder).toFixed(4))),
    };

    gradePropRow(row);
    out.push(row);
  }

  const csv = toCSV(header, out);
  return new Response(csv, {
    status: 200,
    headers: {
      ...cors({}),
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": 'attachment; filename="rtp_nba_sim.csv"',
      "cache-control": "no-store",
    },
  });
}

//////////////////////////////
// /props/eval  (graded CSV  JSON summary)
//////////////////////////////

async function handlePropsEval(req, env, url) {
  const sport = (url.searchParams.get("sport") || "nba").toLowerCase();
  if (sport !== "nba") {
    return fail(env, "only_nba_supported", { sport }, 400);
  }

  const body = await req.text();
  let { header, rows } = parseSimpleCSV(body);

  if (!rows.length) {
    return ok(
      env,
      {
        picks: 0,
        wins: 0,
        losses: 0,
        pushes: 0,
        winrate: 0,
        markets: {},
        teams: {},
      },
      { header }
    );
  }

  const sideKey = header.includes("side")
    ? "side"
    : header.includes("lean")
    ? "lean"
    : null;
  const resultKey = header.includes("result") ? "result" : null;
  const marketKey = header.includes("market") ? "market" : null;
  const teamKey = header.includes("team_abbr") ? "team_abbr" : null;

  if (!sideKey || !resultKey) {
    return fail(
      env,
      "missing_side_or_result_column",
      {
        required: ["side or lean", "result"],
        header,
      },
      400
    );
  }

  let picks = 0;
  let wins = 0;
  let losses = 0;
  let pushes = 0;

  const byMarket = new Map();
  const byTeam = new Map();

  function bump(map, key, res) {
    if (!key) return;
    const k = String(key).toLowerCase();
    if (!k) return;
    let bucket = map.get(k);
    if (!bucket) {
      bucket = { picks: 0, wins: 0, losses: 0, pushes: 0 };
      map.set(k, bucket);
    }
    bucket.picks++;
    if (res === "win") bucket.wins++;
    else if (res === "loss") bucket.losses++;
    else if (res === "push") bucket.pushes++;
  }

  for (const r of rows) {
    const resRaw = String(r[resultKey] || "").toLowerCase();
    if (!resRaw) continue;

    const res =
      resRaw === "w"
        ? "win"
        : resRaw === "l"
        ? "loss"
        : resRaw;

    if (!["win", "loss", "push"].includes(res)) continue;

    picks++;
    if (res === "win") wins++;
    else if (res === "loss") losses++;
    else if (res === "push") pushes++;

    if (marketKey) bump(byMarket, r[marketKey], res);
    if (teamKey) bump(byTeam, r[teamKey], res);
  }

  const graded = wins + losses + pushes;
  const winrate = graded ? wins / graded : 0;

  const markets = {};
  for (const [m, v] of byMarket.entries()) {
    const g = v.wins + v.losses + v.pushes;
    markets[m] = {
      ...v,
      graded: g,
      winrate: g ? v.wins / g : 0,
    };
  }

  const teams = {};
  for (const [t, v] of byTeam.entries()) {
    const g = v.wins + v.losses + v.pushes;
    teams[t] = {
      ...v,
      graded: g,
      winrate: g ? v.wins / g : 0,
    };
  }

  return ok(
    env,
    {
      picks,
      graded,
      wins,
      losses,
      pushes,
      winrate,
      markets,
      teams,
    },
    { header }
  );
}

//////////////////////////////
// /props/grade  (latest props vs BDL box scores)
//////////////////////////////


// POST /props/grade.elite
// Body: {
//   season: 2026, home:"BOS", away:"NYK", market_total:224.5, market_spread:-3.5,
//   items:[{player_id:73, team_abbr:"NYK", lines:{pts:28.5, reb:3.5, ast:6.5, pra:38.5, threes:2.5, ftm:4.5}, odds_american:{pts_over:-110, pts_under:-110}}]
// }
//
// Returns JSON rows per market: projection, line, prob_over/prob_under, recommended_side, edge vs implied (if odds provided) and grades.
async function handlePropsGradeElite(req, env, url) {
  let body = null;
  try { body = await req.json(); } catch (e) {}

  const season = Number(body?.season || body?.seasonEnd || 0) || 0;
  const home = _normTeam(body?.home || "");
  const away = _normTeam(body?.away || "");
  const items = Array.isArray(body?.items) ? body.items : [];

  if (!season || !home || !away || !items.length) {
    return json({ ok:false, data:null, meta:{ season, home, away, items: items.length }, error:"missing_required:season,home,away,items[]" }, 400);
  }

  // Build a URL-like object for handleGameModel reuse (so we get calibrated script)
  const tmp = new URL(url.toString());
  tmp.searchParams.set("season", String(season));
  tmp.searchParams.set("home", home);
  tmp.searchParams.set("away", away);
  if (body?.market_total != null) tmp.searchParams.set("market_total", String(body.market_total));
  if (body?.market_spread != null) tmp.searchParams.set("market_spread", String(body.market_spread));

  const modelRes = await handleGameModel(env, tmp);
  const modelJson = await modelRes.json();
  if (!modelJson?.ok) return json(modelJson, 500);

  const seasonStart = Number(modelJson?.data?.seasonStart || (season - 1)) || (season - 1);
  const seasonEnd = Number(modelJson?.data?.seasonEnd || season) || season;
  const script = modelJson?.data?.script || null;
  const expectedTeams = [home, away];

  const outRows = [];

  for (const it of items) {
    const pid = Number(it?.player_id || it?.pid || 0) || 0;
    if (!pid) continue;

    let teamAbbr = _normTeam(it?.team_abbr || it?.team || "");
    // Canonical player + team
    let pmeta = null;
    try {
      pmeta = await fetchBDLPlayerOne(env, pid);
      const ta = _normTeam(pmeta?.team?.abbreviation || "");
      if (!teamAbbr && ta) teamAbbr = ta;
    } catch (e) {}

    const injury = await fetchBDLPlayerInjuryOne(env, pid, { ttl: 300 });

    // Baseline: best available (season avg -> recent -> prior season avg -> prior recent)
    const best = await fetchBDLBestBaseline(env, pid, seasonStart, seasonEnd, { lastN: 10 });
    const av = best?.row || null;

    // Build baseline
    const baseline = av ? {
      pts: Number(av.pts ?? av.points ?? 0),
      reb: Number(av.reb ?? av.rebounds ?? 0),
      ast: Number(av.ast ?? av.assists ?? 0),
      fg3m: Number(av.fg3m ?? av.three_pt_made ?? av.threes_made ?? 0),
      ftm: Number(av.ftm ?? av.free_throws_made ?? 0),
    } : null;
    if (baseline) baseline.pr = baseline.pts + baseline.reb;
  baseline.pa = baseline.pts + baseline.ast;
  baseline.ra = baseline.reb + baseline.ast;
  baseline.pr = baseline.pts + baseline.reb;
  baseline.pa = baseline.pts + baseline.ast;
  baseline.ra = baseline.reb + baseline.ast;
  baseline.pra = baseline.pts + baseline.reb + baseline.ast;

    // Apply script if we have baseline
    let adjusted = baseline ? applyScriptToBaseline(baseline, script) : null;

    // Injury adjustment (same policy as /props/script)
    if (adjusted && injury?.tag) {
      adjusted.flags = adjusted.flags || [];
      const t = injury.tag;
      if (t === "out" || t === "inactive") {
        adjusted.flags.push("INJURY_OUT");
        adjusted.confidence = adjusted.confidence || {};
        adjusted.confidence.overall = Math.min(0.15, adjusted.confidence.overall ?? 0.15);
        adjusted.projections = { pts: 0, reb: 0, ast: 0, pra: 0, threes: 0, ftm: 0 };
      } else if (t === "doubtful") {
        adjusted.flags.push("INJURY_DOUBTFUL");
        for (const k of ["pts","reb","ast","pra","threes","ftm"]) adjusted.projections[k] *= 0.35;
        adjusted.confidence.overall = Math.min(0.35, adjusted.confidence.overall ?? 0.35);
      } else if (t === "questionable") {
        adjusted.flags.push("INJURY_Q");
        for (const k of ["pts","reb","ast","pra","threes","ftm"]) adjusted.projections[k] *= 0.85;
        adjusted.confidence.overall = Math.min(0.70, adjusted.confidence.overall ?? 0.70);
      } else if (t === "probable") {
        adjusted.flags.push("INJURY_PROB");
        for (const k of ["pts","reb","ast","pra","threes","ftm"]) adjusted.projections[k] *= 0.95;
      }
    }

    // Team mismatch info (never hard-fail here; we just flag)
    const tm = !!(teamAbbr && expectedTeams.indexOf(teamAbbr) === -1);

    const lines = it?.lines || {};
    const odds = it?.odds_american || it?.odds || {};

    const markets = [
      ["pts","PTS","line_pts","pts"],
      ["reb","REB","line_reb","reb"],
      ["ast","AST","line_ast","ast"],
      ["pr","PR","line_pr","pr"],
      ["pa","PA","line_pa","pa"],
      ["ra","RA","line_ra","ra"],
      ["pra","PRA","line_pra","pra"],
      ["threes","3PM","line_3pm","threes"],
      ["ftm","FTM","line_ftm","ftm"],
    ];

    for (const [key, label, legacyKey, oddsKey] of markets) {
      const line =
        Number(lines?.[key] ?? it?.[legacyKey] ?? it?.[`line_${key}`] ?? NaN);
      if (!Number.isFinite(line)) continue;

      const proj = Number(adjusted?.projections?.[key] ?? baseline?.[key] ?? 0);

      // Sigma heuristic (elite-stable, no extra endpoints):
      // - scale with projection, but keep floors.
      const baseFloor = (key === "pts" || key === "pra") ? 4.5 : (key === "threes" ? 0.9 : 1.8);
      const scale = (key === "pts") ? 0.22 : (key === "pra" ? 0.20 : (key === "threes" ? 0.35 : 0.30));
      const sigma = Math.max(baseFloor, Math.abs(proj) * scale);

      const z = (line - proj) / sigma;
      // CDF of standard normal using erf
      const cdf = 0.5 * (1 + erf(z / Math.SQRT2));
      const pUnder = cdf;
      const pOver = 1 - cdf;

      const pSide = pOver >= pUnder ? "over" : "under";
      const pModel = pSide === "over" ? pOver : pUnder;

      // implied prob from odds (if provided)
      const priceOver = odds?.[`${oddsKey}_over`] ?? odds?.[`${key}_over`] ?? odds?.over ?? null;
      const priceUnder = odds?.[`${oddsKey}_under`] ?? odds?.[`${key}_under`] ?? odds?.under ?? null;

      const impliedOver = priceOver != null ? impliedProbFromAmerican(priceOver) : null;
      const impliedUnder = priceUnder != null ? impliedProbFromAmerican(priceUnder) : null;

      const implied = pSide === "over" ? impliedOver : impliedUnder;
      const targetProb = implied ?? 0.525;
      const edge = pModel - targetProb;

      // simple grade bands
      let grade = "";
      if (edge >= 0.07) grade = "A";
      else if (edge >= 0.05) grade = "B";
      else if (edge >= 0.03) grade = "C";
      else if (edge >= 0.01) grade = "D";

      const flags = [];
      if (tm) flags.push("TEAM_MISMATCH");
      if (adjusted?.flags?.length) flags.push(...adjusted.flags);

      outRows.push({
        player_id: pid,
        player_name: (pmeta?.first_name && pmeta?.last_name) ? `${pmeta.first_name} ${pmeta.last_name}` : (it?.player_name || ""),
        team_abbr: teamAbbr || null,
        market: label,
        line,
        proj: Number.isFinite(proj) ? Number(proj.toFixed(3)) : proj,
        sigma: Number(sigma.toFixed(3)),
        p_over: Number(pOver.toFixed(4)),
        p_under: Number(pUnder.toFixed(4)),
        side: pSide,
        prob: Number(pModel.toFixed(4)),
        implied: implied != null ? Number(implied.toFixed(4)) : null,
        edge: Number(edge.toFixed(4)),
        grade,
        confidence: Number((adjusted?.confidence?.overall ?? 0.6).toFixed(3)),
        flags,
        injury: injury?.status || null,
        baseline_meta: best ? { source: best.source, season: best.season } : null,
      });
    }
  }

  // Sort best edges first
  outRows.sort((a,b) => (b.edge ?? 0) - (a.edge ?? 0));

  return ok(env, {
    season,
    seasonStart,
    seasonEnd,
    home,
    away,
    script,
    count: outRows.length,
    rows: outRows,
  }, { generatedAt: new Date().toISOString() });
}

async function handlePropsGrade(_req, env, url) {
  const sport = (url.searchParams.get("sport") || "nba").toLowerCase();
  if (sport !== "nba") {
    return fail(env, "only_nba_supported", { sport }, 400);
  }

  const dateISO = url.searchParams.get("date") || todayISO();

  const ptr = await env.RTP_PROPS.get(`props:${sport}:latest`);
  const header = [
    "prop_raw",
    "player_name",
    "team_abbr",
    "opp_abbr",
    "position",
    "market",
    "line",
    "side",
    "actual",
    "diff",
    "result",
    "date",
    "player_id",
  ];

  if (!ptr) {
    const csv = toCSV(header, []);
    return new Response(csv, {
      status: 200,
      headers: {
        ...cors({}),
        "content-type": "text/csv; charset=utf-8",
        "content-disposition":
          'attachment; filename="rtp_nba_grades_empty.csv"',
        "cache-control": "no-store",
      },
    });
  }

  const raw = await env.RTP_PROPS.get(ptr);
  if (!raw) {
    return fail(env, "missing_props_blob", { ptr }, 404);
  }

  let items = [];
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) items = parsed;
    else if (Array.isArray(parsed.items)) items = parsed.items;
    else if (Array.isArray(parsed.data)) items = parsed.data;
  } catch (e) {
    return fail(env, "bad_props_json", { ptr, msg: e.message }, 500);
  }

  if (!items.length) {
    const csv = toCSV(header, []);
    return new Response(csv, {
      status: 200,
      headers: {
        ...cors({}),
        "content-type": "text/csv; charset=utf-8",
        "content-disposition":
          'attachment; filename="rtp_nba_grades_empty.csv"',
        "cache-control": "no-store",
      },
    });
  }

  const graded = await gradePropsForDate(env, dateISO, items);

  const csv = toCSV(header, graded);
  const fname = `nba_grades_${dateISO}_${Date.now()}.csv`;

  try {
    await r2PutCSV(env, fname, csv);
  } catch (e) {
    console.error("grade R2 save failed", e);
  }

  return new Response(csv, {
    status: 200,
    headers: {
      ...cors({}),
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="${fname}"`,
      "cache-control": "no-store",
    },
  });
}

//////////////////////////////
// /teams/export.csv and alias
//////////////////////////////

// 
// FIXED: use cached rows rather than recomputing every call
async function handleTeamsExportCSV(_req, env, url) {
  const season = Number(url.searchParams.get("season") || guessSeason());
  const force =
    String(url.searchParams.get("force") || "") === "1";

  // Ensure seasonStart/seasonEnd are defined for cache keys + builder.
  const { seasonStart, seasonEnd } = normalizeSeasonInput(season);

  let rows = force ? null : await kvGetJSON(env, `nba:teamwell:${seasonStart}:v3`);

  if (!rows) {
    rows = await buildTeamWell(env, seasonStart, seasonEnd, {});
    await kvPutJSON(env, `nba:teamwell:${seasonStart}:v3`, rows, 6 * 3600);
  }

  const csv = toCSV(TEAM_FIELDS, rows);
  const fname = `nba_teams_${season}.csv`;

  // UI/iOS failsafe: allow JSON envelope carrying the CSV (copy/save manually)
  if ((url.searchParams.get('format') || '').toLowerCase() === 'json') {
    return ok(env, { filename: fname, csv }, { season, season_type: url.searchParams.get('season_type') || 'regular', source: 'kv' });
  }

  return new Response(csv, {
    status: 200,
    headers: {
      ...cors({}),
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="${fname}"`,
    },
  });
}

//////////////////////////////
// BDL proxy
//////////////////////////////

async function handleBDLProxy(req, env, url) {
  const idx = path.indexOf("/bdl/nba/v1");
  const suffix = path.slice(idx + "/bdl/nba/v1".length) || "";
  const qs = url.search || "";
  const r = await fetch(`${BDL_BASE}${suffix}${qs}`, {
    headers: { Authorization: `Bearer ${env.BDL_API_KEY}` },
  });

  const wantsEnvelope =
    new URL(req.url).searchParams.get("envelope") === "1";
  const ct = r.headers.get("content-type") || "";

  if (wantsEnvelope && /^application\/json/i.test(ct)) {
    const payload = await r.json().catch(() => null);
    if (!payload)
      return fail(env, "bad_gateway", { route: suffix }, 502);
    return ok(
      env,
      payload.data ?? payload,
      { route: suffix, source: "bdl", ts: new Date().toISOString() },
      r.status
    );
  }

  const h = new Headers(r.headers);
  for (const [k, v] of Object.entries(cors({}))) h.set(k, v);
  return new Response(r.body, { status: r.status, headers: h });
}

// ===============================
// Elite Environment Pack (Spreads/Totals  drives Props)
// ===============================

function envKeyDate(seasonStart, seasonType, dateISO) {
  return `nba:env:${seasonStart}:${seasonType}:date:${dateISO}`;
}

function envKeyGame(seasonStart, seasonType, gameId) {
  return `nba:env:${seasonStart}:${seasonType}:game:${gameId}`;
}

function clamp01(x) {
  const n = Number(x);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(1, n));
}

function _abbrFromTeamObj(t) {
  const ab = String(t?.abbreviation || t?.abbr || "").trim().toUpperCase();
  return ab.length === 3 ? ab : _normTeam(ab);
}

function _nameFromTeamObj(t) {
  return String(t?.full_name || t?.name || t?.display_name || "").trim();
}

// Conservative odds parser for BDL v2 odds objects.
// We don't assume schema stability; we try a few common shapes and otherwise return null.
function pickMarketFromBdlOddsItems(items, homeName, awayName) {
  const h = normText(homeName);
  const a = normText(awayName);
  if (!h || !a) return null;
  const same = (x, y) => !!x && !!y && (x === y || x.includes(y) || y.includes(x));

  for (const it of items || []) {
    const hn = normText(it?.home_team || it?.homeTeam || it?.home || "");
    const an = normText(it?.away_team || it?.awayTeam || it?.away || "");
    if (!same(hn, h) || !same(an, a)) continue;

    // Common: { bookmakers:[{ markets:[{ key:'spreads'|'totals', outcomes:[...] }]}] }
    const bms = Array.isArray(it?.bookmakers) ? it.bookmakers : [];
    let spreads = [];
    let totals = [];
    for (const bm of bms) {
      const markets = Array.isArray(bm?.markets) ? bm.markets : [];
      for (const m of markets) {
        const key = String(m?.key || m?.market || "").toLowerCase();
        const outs = Array.isArray(m?.outcomes) ? m.outcomes : [];
        if (key.includes("spread")) spreads.push({ bm: bm?.key || bm?.title || "", outcomes: outs });
        if (key.includes("total")) totals.push({ bm: bm?.key || bm?.title || "", outcomes: outs });
      }
    }

    const out = { source: "bdl_v2", spread_home_book: null, total: null, raw: it };
    // spreads: find home outcome point
    for (const s of spreads) {
      for (const o of s.outcomes || []) {
        const nm = normText(o?.name || o?.team || "");
        const pt = asFloat(o?.point ?? o?.line ?? o?.handicap);
        if (pt == null) continue;
        if (same(nm, h)) { out.spread_home_book = pt; break; }
      }
      if (out.spread_home_book != null) break;
    }
    // totals: find points (sometimes outcome 'Over'/'Under')
    for (const t of totals) {
      for (const o of t.outcomes || []) {
        const nm = normText(o?.name || "");
        const pt = asFloat(o?.point ?? o?.line);
        if (pt == null) continue;
        if (nm.includes("over") || nm.includes("under") || nm === "total") { out.total = pt; break; }
      }
      if (out.total != null) break;
    }

    // If we didn't parse anything, don't pretend.
    if (out.spread_home_book == null && out.total == null) return { source: "bdl_v2", raw: it };
    return out;
  }
  return null;
}

async function getEnvPackFromKV(env, seasonStart, seasonType, dateISO) {
  const key = envKeyDate(seasonStart, seasonType, dateISO);
  try {
    const raw = await env.RTP_CACHE?.get(key);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

async function getEnvForTeams(env, seasonStart, seasonType, dateISO, homeAbbr, awayAbbr) {
  const pack = await getEnvPackFromKV(env, seasonStart, seasonType, dateISO);
  if (!pack?.games?.length) return null;
  const h = _normTeam(homeAbbr);
  const a = _normTeam(awayAbbr);
  for (const g of pack.games) {
    if (_normTeam(g?.home) === h && _normTeam(g?.away) === a) return g;
  }
  return null;
}

async function buildEnvPackForDate(env, { seasonStart, seasonType, dateISO, force = false } = {}) {
  const key = envKeyDate(seasonStart, seasonType, dateISO);
  if (!force) {
    const hit = await env.RTP_CACHE?.get(key);
    if (hit) {
      try { return { cached: true, pack: JSON.parse(hit) }; } catch {}
    }
  }

  // TeamWell is the foundation.
  const teamMap = await buildTeamWellMap(env, String(seasonStart));
  const rowsAll = Array.from(teamMap.values());
  const avg = (arr, fb) => {
    const xs = (arr || []).map((x) => Number(x)).filter((x) => Number.isFinite(x));
    if (!xs.length) return fb;
    return xs.reduce((a, b) => a + b, 0) / xs.length;
  };
  const lg_ortg = avg(rowsAll.map((r) => r.ortg), 114);
  const lg_drtg = avg(rowsAll.map((r) => r.drtg), 114);
  const lg_pace = avg(rowsAll.map((r) => r.pace_team), 99);
  const n = (v, fb) => {
    const x = Number(v);
    return Number.isFinite(x) ? x : fb;
  };

  // Games for the slate date
  const games = await fetchBDLAll2(env, "/games", { "dates[]": [dateISO], per_page: 100 }, { ttl: 30, maxPages: 5, base: BDL_NBA_BASE });

  // Market odds (optional)
  let oddsItems = [];
  try {
    oddsItems = await fetchBDLAll2(env, "/odds", { "dates[]": [dateISO], per_page: 100 }, { ttl: 30, maxPages: 10, base: BDL_NBA_V2_BASE });
  } catch { oddsItems = []; }

  const outGames = [];
  for (const g of games || []) {
    const gid = asInt(g?.id);
    const homeAbbr = _abbrFromTeamObj(g?.home_team || g?.homeTeam || g?.home);
    const awayAbbr = _abbrFromTeamObj(g?.visitor_team || g?.away_team || g?.awayTeam || g?.away);
    if (!homeAbbr || !awayAbbr) continue;
    const homeRow = teamMap.get(homeAbbr);
    const awayRow = teamMap.get(awayAbbr);

    const pace = (n(homeRow?.pace_team, lg_pace) + n(awayRow?.pace_team, lg_pace)) / 2;
    const ortg_h = n(homeRow?.ortg, lg_ortg);
    const drtg_h = n(homeRow?.drtg, lg_drtg);
    const ortg_a = n(awayRow?.ortg, lg_ortg);
    const drtg_a = n(awayRow?.drtg, lg_drtg);

    // Same baseline expectation as /games/model (no extra edges here; we keep it stable)
    const exp_ortg_home = (ortg_h + (lg_ortg - (lg_drtg - drtg_a))) / 2;
    const exp_ortg_away = (ortg_a + (lg_ortg - (lg_drtg - drtg_h))) / 2;

    const home_pts = (pace * exp_ortg_home) / 100;
    const away_pts = (pace * exp_ortg_away) / 100;
    const total_proj = home_pts + away_pts;
    const spread_home_model = (home_pts - away_pts); // model convention (+ = home favored)

    const homeName = _nameFromTeamObj(g?.home_team || g?.homeTeam || g?.home);
    const awayName = _nameFromTeamObj(g?.visitor_team || g?.away_team || g?.awayTeam || g?.away);
    const market = pickMarketFromBdlOddsItems(oddsItems, homeName, awayName);

    // Blowout risk: conservative mapping from projected margin (0..1)
    const blowout_risk = clamp01(Math.abs(spread_home_model) / 18);

    outGames.push({
      game_id: gid ?? null,
      date: dateISO,
      home: homeAbbr,
      away: awayAbbr,
      poss_proj: Number(pace.toFixed(2)),
      home_pts_proj: Number(home_pts.toFixed(2)),
      away_pts_proj: Number(away_pts.toFixed(2)),
      total_proj: Number(total_proj.toFixed(2)),
      spread_home_model: Number(spread_home_model.toFixed(2)),
      spread_home_book: (market?.spread_home_book != null ? Number(market.spread_home_book) : null),
      market_total: (market?.total != null ? Number(market.total) : null),
      blowout_risk: Number(blowout_risk.toFixed(4)),
      market: market ? { source: market.source || "bdl_v2", spread_home_book: market.spread_home_book ?? null, total: market.total ?? null } : null,
    });

    // Store per-game too (handy for lookups)
    if (gid != null && env.RTP_CACHE) {
      try {
        await env.RTP_CACHE.put(envKeyGame(seasonStart, seasonType, gid), JSON.stringify(outGames[outGames.length - 1]), { expirationTtl: 6 * 3600 });
      } catch (e2) { bdl_fallback_error = String(e2?.message || e2); }
    }
  }

  const pack = {
    ok: true,
    season: seasonStart,
    season_type: seasonType,
    date: dateISO,
    ts: new Date().toISOString(),
    count: outGames.length,
    games: outGames,
  };

  try {
    await env.RTP_CACHE?.put(key, JSON.stringify(pack), { expirationTtl: 6 * 3600 });
  } catch {}

  return { cached: false, pack };
}

async function handleEnvBuild(env, url) {
  const q = url.searchParams;
  const playerNameParam = (q.get("player_name") || q.get("pname") || q.get("player") || "").trim();
  let resolvedPlayerName = playerNameParam;
  const dateISO = (q.get("date") || q.get("slate_date") || todayISOInTZ(NY_TZ)).slice(0, 10);
  // IMPORTANT: you told me 202526 = season 2025; we honor that here.
  const seasonStart = asInt(q.get("season") || q.get("season_start") || q.get("seasonStart") || "2025") || 2025;
  const seasonType = (q.get("season_type") || "regular").toLowerCase();
  const force = (q.get("force") || q.get("rebuild") || "") === "1";

  if (!env.RTP_CACHE) {
    return fail(env, "missing_kv:RTP_CACHE", { need: "RTP_CACHE binding" }, 500);
  }

  try {
    const built = await buildEnvPackForDate(env, { seasonStart, seasonType, dateISO, force });
    return ok(env, built.pack, { cached: built.cached, key: envKeyDate(seasonStart, seasonType, dateISO) });
  } catch (e) {
    return fail(env, "env_build_failed", { error: String(e?.message || e) }, 500);
  }
}

async function handleEnvGet(env, url) {
  const q = url.searchParams;
  const playerNameParam = (q.get("player_name") || q.get("pname") || q.get("player") || "").trim();
  let resolvedPlayerName = playerNameParam;
  const dateISO = (q.get("date") || q.get("slate_date") || todayISOInTZ(NY_TZ)).slice(0, 10);
  const seasonStart = asInt(q.get("season") || q.get("season_start") || q.get("seasonStart") || "2025") || 2025;
  const seasonType = (q.get("season_type") || "regular").toLowerCase();
  const buildIfMissing = (q.get("build") || "") === "1";

  if (!env.RTP_CACHE) return fail(env, "missing_kv:RTP_CACHE", { need: "RTP_CACHE binding" }, 500);
  let pack = await getEnvPackFromKV(env, seasonStart, seasonType, dateISO);
  if (!pack && buildIfMissing) {
    const built = await buildEnvPackForDate(env, { seasonStart, seasonType, dateISO, force: false });
    pack = built.pack;
  }
  if (!pack) return ok(env, { ok: false, season: seasonStart, season_type: seasonType, date: dateISO, count: 0, games: [] }, { cache: "miss" });
  return ok(env, pack, { cache: "hit", key: envKeyDate(seasonStart, seasonType, dateISO) });
}


