    const key = _rtpBdlPropsOddsKeyV6397({ game_date: d, season, game_id: gid });
    let pack = await kvGetJSON(env, key).catch(()=>null);
    if (pack && pack.board) return pack;
    try {
      const oddsKey = _rtp654BoardKey(season, d, h, a);
      const oddsPack = await kvGetJSON(env, oddsKey).catch(()=>null);
      if (oddsPack && (oddsPack.by_player || oddsPack.props_archive_board_shape_adapter_v710) && oddsPack.board) return oddsPack;
    } catch (_) {}
    // If not already stored, fetch/store through the existing BDL odds handler. This avoids duplicate odds code.
    if (typeof handlePropsBdlOddsGetV6397 === "function") {
      const u = new URL("https://props.local/props/odds/bdl");
      u.searchParams.set("game_id", gid);
      if (d) { u.searchParams.set("date", d); u.searchParams.set("game_date", d); }
      if (season) u.searchParams.set("season", String(season));
      if (h) u.searchParams.set("home", h);
      if (a) u.searchParams.set("away", a);
      const res = await handlePropsBdlOddsGetV6397(env, u);
      const j = await res.json().catch(()=>null);
      if (j?.ok && j?.data?.board) return j.data;
    }
