async function handleBacktestsList(env) {
  if (!env.R2) return fail(env, "no_r2");
  const list = await env.R2.list({ prefix: "nba_", limit: 1000 });
  const files = (list?.objects || [])
    .filter((o) => o.key.endsWith(".csv"))
    .map((o) => ({
      key: o.key,
      size: o.size,
      uploaded: o.uploaded,
    }));
  return ok(env, { count: files.length, files }, { ts: todayISO() });
}

async function handleBacktestsGet(env, key) {
  if (!env.R2) return fail(env, "no_r2");
  const obj = await env.R2.get(key);
  if (!obj) return fail(env, "not_found", { key }, 404);
  return new Response(obj.body, {
    status: 200,
    headers: {
      ...cors({}),
      "content-type":
        obj.httpMetadata?.contentType ||
        "text/csv; charset=utf-8",
      "content-disposition":
        obj.httpMetadata?.contentDisposition ||
        `attachment; filename="${key}"`,
    },
  });
}

async function handleBacktestRun(_req, env, url) {
  if (!env.R2) return fail(env, "no_r2");

  const key = url.searchParams.get("key");
  if (!key) return fail(env, "missing_key", {}, 400);

  const obj = await env.R2.get(key);
  if (!obj)
    return fail(env, "missing_r2_object", { key }, 404);

  const csvText = await obj.text();
  const [head, ...lines] = csvText.split(/\r?\n/);
  if (!head) return ok(env, { rows_count: 0 });
  const headers = head.split(",");
  const rows = lines
    .filter(Boolean)
    .map((line) => {
      const cols = line.split(",");
      const r = {};
      headers.forEach((h, i) => (r[h] = cols[i]));
      return r;
    });

  return ok(env, { rows_count: rows.length });
}

