async function handleDebugBDL(env) {
  const auth = String(env.BDL_API_KEY || "").trim();

  // Basic auth presence check (don't expose key)
  const keyMeta = {
    hasKey: !!auth,
    keyLen: auth.length,
    looksBearer: /^bearer\s+/i.test(auth),
  };

  // Try a small upstream call
  let teamsOk = false;
  let teamsCount = 0;
  let status = 0;
  let err = "";

  try {
    const res = await fetch(`${BDL_BASE}/teams?per_page=5`, {
      headers: auth ? { Authorization: auth } : {},
    });
    status = res.status;
    teamsOk = res.ok;

    const j = await res.json().catch(() => null);
    teamsCount = Array.isArray(j?.data) ? j.data.length : 0;
  } catch (e) {
    err = e?.message || String(e);
  }

  return ok(env, {
    keyMeta,
    upstream: { teamsOk, status, teamsCount, err },
  });
}


/**
 * LOOKUP: /lookup/games
 * - Helps you find game_id without knowing IDs.
 */
async function handleLookupGames(req, env, url) {
  // Lightweight, reliable game lookup:
  // pull ONLY the requested date from BDL (no full-season paging),
  // and return normalized home/away abbreviations.
  const season = asInt(url.searchParams.get("season")) || guessSeason();
  const seasonStart = seasonStartFromSeason(season);

  const date = (url.searchParams.get("date") || todayISO()).trim();
  const perPage = asInt(url.searchParams.get("per_page")) || 50;

  try {
    const qs = { "per_page": perPage, "dates[]": [date], "seasons[]": [seasonStart] };
    const res = await fetchBDL(env, "/games", { ttl: 30, qs });

    const games = Array.isArray(res?.data) ? res.data : [];
    const sample = games.slice(0, perPage).map(g => {
      const home = (g?.home_team?.abbreviation || g?.home_team?.abbr || "").toUpperCase();
      const away = (g?.visitor_team?.abbreviation || g?.visitor_team?.abbr || "").toUpperCase();
      return {
        id: g?.id ?? null,
        date: (g?.date || "").slice(0, 10) || date,
        status: g?.status ?? null,
        period: g?.period ?? null,
        postseason: !!g?.postseason,
        home,
        away,
        home_team: g?.home_team?.full_name || g?.home_team?.name || null,
        away_team: g?.visitor_team?.full_name || g?.visitor_team?.name || null,
        home_score: g?.home_team_score ?? null,
        away_score: g?.visitor_team_score ?? null,
      };
    });

    return ok(env, { season, seasonStart, date, count: games.length, sample }, { per_page: perPage, next_cursor: res?.meta?.next_cursor || null });
  } catch (e) {
    return fail(env, "lookup_games_failed:" + (e?.message || String(e)));
  }
}

async function handleLookupGame(req, env, url) {
  await ensureBdlTeamMaps(env);
  try {
    const qp = url.searchParams;
    const season = asInt(qp.get("season")) || inferSeasonFromNowNY();
    const date = (qp.get("date") || "").trim();
    const home = (qp.get("home") || "").trim().toUpperCase();
    const away = (qp.get("away") || "").trim().toUpperCase();
    if (!home || !away) return jsonResp({ ok:false, data:null, meta:{home,away}, error:"missing_home_away" }, 400);

    const q = new URLSearchParams();
    q.set("per_page", "100");
    q.set("seasons[]", String(seasonStartFromSeason(season)));
    if (date) q.set("dates[]", date);
    const ids=[];
    if (NBA_ABBR_TO_TEAM_ID[home]) ids.push(NBA_ABBR_TO_TEAM_ID[home]);
    if (NBA_ABBR_TO_TEAM_ID[away]) ids.push(NBA_ABBR_TO_TEAM_ID[away]);
    for (const id of [...new Set(ids)]) q.append("team_ids[]", String(id));

    const js = await fetchBDL(env, "/games", q);
    const rows = Array.isArray(js?.data) ? js.data : [];
    const exact = rows.find(g => (g.home_team?.abbreviation||"").toUpperCase()===home && (g.visitor_team?.abbreviation||"").toUpperCase()===away)
               || rows.find(g => (g.home_team?.abbreviation||"").toUpperCase()===away && (g.visitor_team?.abbreviation||"").toUpperCase()===home);
    const g = exact || rows[0] || null;
    if (!g) return jsonResp({ ok:false, data:null, meta:{season,home,away,date}, error:"not_found" }, 404);

    const item = {
      id: g.id,
      date: g.date,
      season: g.season,
      home: (g.home_team?.abbreviation || "").toUpperCase(),
      away: (g.visitor_team?.abbreviation || "").toUpperCase(),
      hs: g.home_team_score,
      as: g.visitor_team_score,
      status: g.status || "",
    };
    return jsonResp({ ok:true, data:item, meta:{season,home,away,date:date||null}, error:null });
  } catch (e) {
    return jsonResp({ ok:false, data:null, meta:{}, error: e?.message || String(e) }, 500);
  }
}

/**
 * BACKTEST: /backtest/game
 * Resolve a game (by game_id OR by date+home+away), run the current game-script model,
 * then compare vs actual final score (if available) to evaluate calibration.
 *
 * Query:
 *   season=2026
 *   game_id=18446820     (optional)
 *   date=2025-10-21      (optional, used for lookup)
 *   home=LAL&away=GSW    (required if no game_id)
 *   market_total=224.5   (optional)
 *   market_spread=-3.5   (optional, market spread for HOME team; negative = home favored)
 */
async function handleBacktestGame(req, env, url) {
  try {
    const qp = url.searchParams;

    const season = asInt(qp.get("season")) || inferSeasonFromNowNY();
    const market_total = asNum(qp.get("market_total"));
    const market_spread = asNum(qp.get("market_spread"));

    let game_id = asInt(qp.get("game_id"));
    const date = (qp.get("date") || "").trim();
    const home = (qp.get("home") || "").trim().toUpperCase();
    const away = (qp.get("away") || "").trim().toUpperCase();

    if (!game_id && (!home || !away)) {
      return jsonResp({ ok:false, data:null, meta:{ season, game_id: game_id||null, date, home, away }, error:"missing_game_id_or_home_away" }, 400);
    }

    // ---- Resolve game (lookup) if needed
    let game = null;

    if (game_id) {
      // BDL supports /games/{id}
      game = await fetchBDL(env, `/games/${game_id}`, new URLSearchParams());
    }

    if (!game) {
      // Use the same lookup strategy as /lookup/game
      const q = new URLSearchParams();
      q.set("per_page", "100");
      q.set("seasons[]", String(seasonStartFromSeason(season)));
      if (date) q.set("dates[]", date);
      if (NBA_ABBR_TO_TEAM_ID[home]) q.append("team_ids[]", String(NBA_ABBR_TO_TEAM_ID[home]));
      if (NBA_ABBR_TO_TEAM_ID[away]) q.append("team_ids[]", String(NBA_ABBR_TO_TEAM_ID[away]));

      const js = await fetchBDL(env, "/games", q);
      const rows = Array.isArray(js?.data) ? js.data : [];

      const pick = rows.find(g =>
        (g.home_team?.abbreviation || "").toUpperCase() === home &&
        (g.visitor_team?.abbreviation || "").toUpperCase() === away
      ) || rows.find(g =>
        (g.home_team?.abbreviation || "").toUpperCase() === away &&
        (g.visitor_team?.abbreviation || "").toUpperCase() === home
      ) || null;

      if (!pick) {
        return jsonResp({ ok:false, data:null, meta:{ season, date: date||null, home, away }, error:"game_not_found" }, 404);
      }

      game = pick;
      game_id = asInt(game?.id) || game_id;
    }

    // ---- Actuals (if final/available)
    const actual_home = (game?.home_team?.abbreviation || "").toUpperCase();
    const actual_away = (game?.visitor_team?.abbreviation || "").toUpperCase();
    const hs = asNum(game?.home_team_score);
    const as_ = asNum(game?.visitor_team_score);
    const has_final_scores = Number.isFinite(hs) && Number.isFinite(as_);

    const actual_total = has_final_scores ? (hs + as_) : null;
    const actual_margin_home = has_final_scores ? (hs - as_) : null;

    // ---- Run model (script)
    const modelUrl = new URL("https://internal/games/model");
    modelUrl.searchParams.set("season", String(season));
    modelUrl.searchParams.set("home", actual_home || home);
    modelUrl.searchParams.set("away", actual_away || away);
    if (Number.isFinite(market_total)) modelUrl.searchParams.set("market_total", String(market_total));
    if (Number.isFinite(market_spread)) modelUrl.searchParams.set("market_spread", String(market_spread));

    const modelRes = await handleGameModel(env, modelUrl);
    const modelJ = await modelRes.json().catch(() => null);
    if (!modelJ?.ok) {
      return jsonResp({ ok:false, data:null, meta:{ season, home: actual_home||home, away: actual_away||away, game_id }, error: modelJ?.error || "model_failed" }, 500);
    }

    const script = modelJ?.data?.script || null;
    const total_final = asNum(script?.total_final ?? script?.total_model);
    const spread_final = asNum(script?.spread_final ?? script?.spread_model);

    const total_error = (has_final_scores && Number.isFinite(total_final)) ? (total_final - actual_total) : null;
    const spread_error = (has_final_scores && Number.isFinite(spread_final)) ? (spread_final - actual_margin_home) : null;

    const picked_winner = Number.isFinite(spread_final) ? (spread_final >= 0 ? (actual_home||home) : (actual_away||away)) : null;
    const actual_winner = has_final_scores ? ((actual_margin_home >= 0) ? (actual_home||home) : (actual_away||away)) : null;
    const winner_correct = (picked_winner && actual_winner) ? (picked_winner === actual_winner) : null;

    return jsonResp({
      ok: true,
      data: {
        season,
        game_id: game_id || null,
        game: {
          id: game_id || null,
          date: game?.date || null,
          status: game?.status || null,
          home: actual_home || home,
          away: actual_away || away,
          hs: has_final_scores ? hs : null,
          as: has_final_scores ? as_ : null,
        },
        market: {
          total: Number.isFinite(market_total) ? market_total : null,
          spread_home: Number.isFinite(market_spread) ? market_spread : null,
        },
        model: {
          total_final: Number.isFinite(total_final) ? total_final : null,
          spread_final: Number.isFinite(spread_final) ? spread_final : null,
          script,
        },
        eval: {
          actual_total,
          actual_margin_home,
          total_error,
          spread_error,
          picked_winner,
          actual_winner,
          winner_correct,
        },
      },
      meta: { ts: new Date().toISOString() },
      error: null,
    });
  } catch (e) {
    return jsonResp({ ok:false, data:null, meta:{}, error: e?.message || String(e) }, 500);
  }
}


async function fetchBDLAll(env, path, qs = {}, { ttl = 60, maxPages = 10 } = {}) {
  // Cursor-based pagination helper for BallDontLie
  let cursor = null;
  let out = [];
  for (let i = 0; i < maxPages; i++) {
    const q = { ...(qs || {}) };
    if (cursor) q.cursor = cursor;
    const js = await fetchBDL(env, path, { ttl, qs: q });
    const rows = Array.isArray(js?.data) ? js.data : [];
    out.push(...rows);
    cursor = js?.meta?.next_cursor;
    if (!cursor || rows.length === 0) break;
  }
  return out;
}

function withQ(qp) {
  // Convert URLSearchParams -> plain object, preserving repeated keys with [] into arrays
  const out = {};
  if (!qp) return out;
  for (const [k, v] of qp.entries()) {
    if (k.endsWith("[]")) {
      if (!out[k]) out[k] = [];
      out[k].push(v);
    } else if (out[k] === undefined) {
      out[k] = v;
    } else if (Array.isArray(out[k])) {
      out[k].push(v);
    } else {
      out[k] = [out[k], v];
    }
  }
  return out;
}

async function fetchBDLAll2(env, path, qs = {}, { ttl = 60, maxPages = 10, base } = {}) {
  // Cursor-based pagination helper for BallDontLie (supports NBA v1/v2 bases)
  let cursor = null;
  let out = [];
  for (let i = 0; i < maxPages; i++) {
    const q = { ...(qs || {}) };
    if (cursor) q.cursor = cursor;
    const js = await fetchBDL(env, path, { ttl, qs: q, base });
    const rows = Array.isArray(js?.data) ? js.data : [];
    out.push(...rows);
    cursor = js?.meta?.next_cursor;
    if (!cursor || rows.length === 0) break;
  }
  return out;
}


function pickStatNum(obj, keys) {
  for (const k of keys) {
    const v = obj?.[k];
    const n = Number(v);
    if (Number.isFinite(n)) return n;
  }
  return null;
}

function marketToActualValue(market, statRow) {
  // Map our markets to BDL stats fields (best-effort)
  const m = String(market || "").toUpperCase();
  const pts = pickStatNum(statRow, ["pts", "points", "PTS"]);
  const reb = pickStatNum(statRow, ["reb", "rebounds", "REB"]);
  const ast = pickStatNum(statRow, ["ast", "assists", "AST"]);
  const fg3m = pickStatNum(statRow, ["fg3m", "fg3m", "three_pt_made", "three_point_field_goals_made", "fg3m"]);
  const ftm = pickStatNum(statRow, ["ftm", "free_throws_made", "ftm"]);
  const pra = (Number.isFinite(pts) && Number.isFinite(reb) && Number.isFinite(ast)) ? (pts + reb + ast) : null;

  if (m === "PTS") return pts;
  if (m === "REB") return reb;
  if (m === "AST") return ast;
  if (m === "3PM" || m === "FG3M" || m === "THREES") return fg3m;
  if (m === "FTM") return ftm;
  if (m === "PRA") return pra;
  return null;
}

async function resolveGameForBacktest(env, { season, game_id, date, home, away }) {
  await ensureBdlTeamMaps(env);
  let gid = asInt(game_id);
  let game = null;

  if (gid) {
    const js = await fetchBDL(env, `/games/${gid}`, { ttl: 30 });
    game = js?.data || js || null;
    return { game_id: gid, game };
  }

  if (!home || !away) return { game_id: null, game: null };

  const q = new URLSearchParams();
  q.set("seasons[]", String(season));
  if (date) q.set("dates[]", date);
  q.set("per_page", "100");
  if (NBA_ABBR_TO_TEAM_ID[home]) q.append("team_ids[]", String(NBA_ABBR_TO_TEAM_ID[home]));
  if (NBA_ABBR_TO_TEAM_ID[away]) q.append("team_ids[]", String(NBA_ABBR_TO_TEAM_ID[away]));

  const js = await fetchBDL(env, "/games", q);
  const rows = Array.isArray(js?.data) ? js.data : [];
  const pick =
    rows.find(g =>
      (g.home_team?.abbreviation || "").toUpperCase() === home &&
      (g.visitor_team?.abbreviation || "").toUpperCase() === away
    ) ||
    rows.find(g =>
      (g.home_team?.abbreviation || "").toUpperCase() === away &&
      (g.visitor_team?.abbreviation || "").toUpperCase() === home
    ) ||
    null;

  if (!pick) return { game_id: null, game: null };
  gid = asInt(pick?.id) || null;
  return { game_id: gid, game: pick };
}

async function handleBacktestProps(req, env, url) {
  await ensureBdlTeamMaps(env);
  try {
    const qp = url.searchParams;
    let body = null;
    if (req.method === "POST") {
      try { body = await req.json(); } catch (e) {}
    }

    const season = asInt((body?.season ?? qp.get("season"))) || inferSeasonFromNowNY();
    const market_total = asNum(body?.market_total ?? qp.get("market_total"));
    const market_spread = asNum(body?.market_spread ?? qp.get("market_spread"));

    const date = (body?.date ?? qp.get("date") ?? "").trim();
    const home = _normTeam(body?.home ?? qp.get("home") ?? "");
    const away = _normTeam(body?.away ?? qp.get("away") ?? "");
    const game_id = asInt(body?.game_id ?? qp.get("game_id"));

    const items = Array.isArray(body?.items) ? body.items : [];

    if ((!game_id && (!home || !away)) || (!game_id && !date)) {
      return jsonResp(env, { ok:false, data:null, meta:{ season, date:date||null, home, away }, error:"missing_required: (game_id) OR (date,home,away)" }, 400);
    }
    if (!items.length) {
      return jsonResp(env, { ok:false, data:null, meta:{ season, date:date||null, home, away }, error:"missing_items" }, 400);
    }

    // resolve game id
    const resolved = await resolveGameForBacktest(env, { season, game_id, date, home, away });
    const gid = resolved.game_id;
    const game = resolved.game;

    if (!gid) {
      return jsonResp(env, { ok:false, data:null, meta:{ season, date:date||null, home, away }, error:"game_not_found" }, 404);
    }

    // Pull boxscore stats for that game (all players)
    const statsRows = await fetchBDLAll(env, "/stats", {
      "per_page": 100,
      "game_ids[]": [gid],
    }, { ttl: 30, maxPages: 5 });

    // Map player_id -> stat row
    const byPid = new Map();
    for (const r of statsRows) {
      const pid = asInt(r?.player?.id ?? r?.player_id ?? r?.playerId ?? r?.id);
      if (!pid) continue;
      byPid.set(pid, r);
    }

    // Run grading using existing /props/grade.elite handler
    const gradeReq = new Request(url.toString().replace("/backtest/props", "/props/grade.elite"), {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ season, home, away, market_total, market_spread, items }),
    });
    const gradeRes = await handlePropsGradeElite(gradeReq, env, new URL(gradeReq.url));
    const gradeJ = await gradeRes.json().catch(() => null);
    if (!gradeJ?.ok) {
      return jsonResp(env, { ok:false, data:null, meta:{ season, home, away, game_id: gid }, error: gradeJ?.error || "grade_failed" }, 500);
    }

    const script = gradeJ?.data?.script || null;
    const rows = Array.isArray(gradeJ?.data?.rows) ? gradeJ.data.rows : [];

    // Evaluate rows
    let evalRows = [];
    for (const r of rows) {
      const pid = asInt(r.player_id);
      const stat = byPid.get(pid) || null;
      const actual = stat ? marketToActualValue(r.market, stat) : null;
      const line = asNum(r.line);
      const side = String(r.side || "").toLowerCase();
      const p_over = asNum(r.p_over);
      const p_under = asNum(r.p_under);
      const chosen_prob = asNum(r.prob);

      let outcome = null; // "win"|"loss"|"push"|null
      let brier = null;

      if (Number.isFinite(actual) && Number.isFinite(line)) {
        const overHit = actual > line;
        const underHit = actual < line;
        const push = actual === line;

        if (push) outcome = "push";
        else if (side === "over") outcome = overHit ? "win" : "loss";
        else if (side === "under") outcome = underHit ? "win" : "loss";
        else outcome = null;

        // Brier on OVER event (1 if over, 0 if not over)
        if (Number.isFinite(p_over)) {
          const y = overHit ? 1 : 0;
          brier = (y - p_over) * (y - p_over);
        } else if (Number.isFinite(chosen_prob)) {
          const y = (side === "over") ? (overHit ? 1 : 0) : (underHit ? 1 : 0);
          brier = (y - chosen_prob) * (y - chosen_prob);
        }
      }

      evalRows.push({
        ...r,
        actual,
        outcome,
        brier,
      });
    }

    // Summary by grade
    const bucket = {};
    const add = (g, o, b) => {
      const k = g || "UNGRaded";
      if (!bucket[k]) bucket[k] = { n:0, wins:0, losses:0, pushes:0, brier_sum:0, brier_n:0 };
      const bb = bucket[k];
      bb.n += 1;
      if (o === "win") bb.wins += 1;
      else if (o === "loss") bb.losses += 1;
      else if (o === "push") bb.pushes += 1;
      if (Number.isFinite(b)) { bb.brier_sum += b; bb.brier_n += 1; }
    };

    for (const r of evalRows) add(r.grade, r.outcome, r.brier);

    const grades = Object.entries(bucket).map(([grade, v]) => ({
      grade,
      n: v.n,
      win_rate: (v.wins + v.losses) ? (v.wins / (v.wins + v.losses)) : null,
      wins: v.wins,
      losses: v.losses,
      pushes: v.pushes,
      avg_brier: v.brier_n ? (v.brier_sum / v.brier_n) : null,
    })).sort((a,b)=> (String(a.grade).localeCompare(String(b.grade))));

    // game meta
    const actual_home = (game?.home_team?.abbreviation || home || "").toUpperCase();
    const actual_away = (game?.visitor_team?.abbreviation || away || "").toUpperCase();
    const hs = asNum(game?.home_team_score);
    const as_ = asNum(game?.visitor_team_score);

    return jsonResp(env, {
      ok: true,
      data: {
        season,
        game_id: gid,
        game: {
          id: gid,
          date: game?.date || date || null,
          status: game?.status || null,
          home: actual_home,
          away: actual_away,
          hs: Number.isFinite(hs) ? hs : null,
          as: Number.isFinite(as_) ? as_ : null,
        },
        script,
        count: evalRows.length,
        rows: evalRows,
        summary: {
          by_grade: grades,
        },
      },
      meta: { generatedAt: todayISO() },
      error: null
    }, 200);

  } catch (e) {
    return jsonResp(env, { ok:false, data:null, meta:{}, error: String(e?.message || e) }, 500);
  }
}

async function handleDebugBDLPlayers(env, url) {
  const q = url.searchParams;
  const playerNameParam = (q.get("player_name") || q.get("pname") || q.get("player") || "").trim();
  let resolvedPlayerName = playerNameParam;
  const search = (url.searchParams.get("search") || url.searchParams.get("q") || "").trim();
  const perPage = Math.min(100, Math.max(1, Number(url.searchParams.get("per_page") || 25) || 25));
  if (!search) {
    return json({ ok: false, data: null, meta: { search }, error: "missing_search" }, 400);
  }
  const data = await fetchBDL(env, "/players", { ttl: 300, qs: { search, per_page: perPage } });
  const items = (data?.data || []).map((p) => ({
    id: p.id,
    full_name: `${p.first_name || ""} ${p.last_name || ""}`.trim(),
    first_name: p.first_name || "",
    last_name: p.last_name || "",
    position: p.position || "",
    team_abbr: p.team?.abbreviation || null,
    team_name: p.team?.full_name || null,
    team_id: p.team?.id || null,
  }));
  return ok(env, { search, count: items.length, items });
}


async function handleDebugBDLInjuries(env, url) {
  const q = url.searchParams;
  const playerNameParam = (q.get("player_name") || q.get("pname") || q.get("player") || "").trim();
  let resolvedPlayerName = playerNameParam;
  const playerId = Number(url.searchParams.get("player_id") || url.searchParams.get("id") || 0) || 0;
  const teamId = Number(url.searchParams.get("team_id") || 0) || 0;
  const perPage = Math.min(100, Math.max(1, Number(url.searchParams.get("per_page") || 25) || 25));

  const qs = { per_page: perPage };
  if (playerId) qs["player_ids[]"] = playerId;
  if (teamId) qs["team_ids[]"] = teamId;

  if (!playerId && !teamId) {
    return json({ ok: false, data: null, meta: { playerId, teamId }, error: "missing_player_or_team" }, 400);
  }

  const data = await fetchBDL(env, "/player_injuries", { ttl: 120, qs });
  const rows = data?.data || data || [];
  const items = (Array.isArray(rows) ? rows : []).map((r) => ({
    player_id: r.player?.id ?? r.player_id ?? null,
    full_name: r.player ? `${r.player.first_name || ""} ${r.player.last_name || ""}`.trim() : null,
    team_abbr: r.player?.team?.abbreviation ?? r.team?.abbreviation ?? null,
    status: r.status ?? r.game_status ?? r.availability ?? null,
    description: r.description ?? r.details ?? r.injury ?? null,
    date: r.date ?? r.updated_at ?? r.reported_at ?? null,
  }));
  return ok(env, { count: items.length, items });
}


async function handleDebugNbaTeamStats(env, url) {
  const measureRaw = String(url.searchParams.get("measure") || "Advanced");
  // Support both "FourFactors" and "Four Factors"
  const measure = measureRaw === "FourFactors" ? "Four Factors" : measureRaw;

  const seasonInput = url.searchParams.get("season");
  const { seasonEnd } = normalizeSeasonInput(seasonInput);
  const seasonStr = toNbaSeasonString(seasonEnd);

  const params = _leagueDashTeamStatsParams(seasonStr, measure);

  const refererPath =
    measure === "Four Factors"
      ? "/stats/teams/four-factors"
      : "/stats/teams/advanced";

  const dbg = await fetchNbaStats("leaguedashteamstats", params, {
    ttl: 60,
    refererPath,
    debug: true,
  });

  // dbg.ok may be false with status/bodyPreview
  if (!dbg || !dbg.__debug) {
    return jsonResp(env, { ok: true, data: { season: seasonStr, measure, note: "no_debug_payload" }, meta: {}, error: null });
  }

  const out = {
    season: seasonStr,
    measure,
    requestUrl: dbg.url,
    status: dbg.status,
    contentType: dbg.contentType,
    okUpstream: !!dbg.ok,
    bodyPreview: dbg.bodyPreview,
  };

  // If JSON is present, summarize headers
  const json = dbg.json;
  const rs = (json && (json.resultSets || json.ResultSets || []))[0] || (json && json.resultSet) || null;
  if (rs) {
    const headers = rs.headers || rs.Headers || [];
    const rows = rs.rowSet || rs.rows || [];
    out.headersCount = Array.isArray(headers) ? headers.length : 0;
    out.sampleHeaders = Array.isArray(headers) ? headers.slice(0, 12) : [];
    out.sampleRow0 = Array.isArray(rows) && rows[0] ? rows[0].slice(0, 12) : null;
  }

  return jsonResp(env, { ok: true, data: out, meta: {}, error: null });
}

async function handleDebugGames(env, url) {
  const season = Number(url.searchParams.get("season")) || guessSeason();

  // Pull a small page of games to see if BDL is responding
  const qs = new URLSearchParams();
  // Wide window to avoid date edge cases
  qs.set("per_page", "5");
  const se = resolveSeasonStartEnd(season);
  const seasonStart = se.seasonStart;
  const seasonEnd = se.seasonEnd;
  qs.set("seasons[]", String(seasonStart));

  let j = await fetchBDL(env, `/games?${qs.toString()}`, { ttl: 0 });
  let data = (j && Array.isArray(j.data)) ? j.data : [];
  if (!data.length && seasonEnd && seasonEnd !== seasonStart) {
    qs.set("seasons[]", String(seasonEnd));
    j = await fetchBDL(env, `/games?${qs.toString()}`, { ttl: 0 });
    data = (j && Array.isArray(j.data)) ? j.data : [];
  }

  return ok(env, {
    season,
    sampleCount: data.length,
    sample: data.map((g) => ({
      id: g.id,
      date: g.date,
      home: g.home_team?.abbreviation,
      away: g.visitor_team?.abbreviation,
      hs: g.home_team_score,
      as: g.visitor_team_score,
    })),
    meta: j?.meta || {},
  });
}

async function handleDebugTeamWell(env, url) {
  const season = Number(url.searchParams.get("season")) || guessSeason();
  const { seasonStart, seasonEnd } = normalizeSeasonInput(season);
  const force =
    String(url.searchParams.get("force") || "").toLowerCase() === "1";

  let rows = null;
  let source = "kv";

  if (!force) {
    rows = await kvGetJSON(env, `nba:teamwell:${seasonStart}:v3`);
  }

  if (!rows) {
    source = "rebuild";
    rows = await buildTeamWell(env, seasonStart, seasonEnd, {});
    // Dont overwrite cache unless you want it
    // await kvPutJSON(env, `nba:teamwell:${seasonStart}:v3`, rows, 6 * 3600);
  }

  const sample = (rows || []).slice(0, 5);

  // Show only a focused subset so its readable
  const compact = sample.map((r) => ({
    team_abbr: r.team_abbr,
    team_name: r.team_name,
    conference: r.conference,
    division: r.division,

    ortg: r.ortg,
    drtg: r.drtg,
    net_rtg: r.net_rtg,
    pace_team: r.pace_team,

    e_fg_pct: r.e_fg_pct,
    ft_rate: r.ft_rate,
    turnover_pct: r.turnover_pct,
    off_reb_pct: r.off_reb_pct,
    def_reb_pct: r.def_reb_pct,

    misc_pts_paint: r.misc_pts_paint,
    misc_pts_fb: r.misc_pts_fb,
    misc_pts_off_tov: r.misc_pts_off_tov,
    misc_pts_2nd_chance: r.misc_pts_2nd_chance,

    pt_def_fg_pct: r.pt_def_fg_pct,
    pt_def_pct_plusminus: r.pt_def_pct_plusminus,

    home_spread: r.home_spread,
    away_spread: r.away_spread,
    implied_total: r.implied_total,

    rest_days: r.rest_days,
    travel_miles: r.travel_miles,
  }));

  return ok(env, {
    season,
    source,
    count: Array.isArray(rows) ? rows.length : 0,
    sample: compact,
  });
}


//////////////////////////////
// NBA Stuffer  scrape helpers (stable + defensive)
//////////////////////////////

function _stripTags(s) {
  return String(s || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<\/?[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, " ")
    .trim();
}

function _parseHtmlTableFirst(html) {
  const h = String(html || "");
  const tableMatch = h.match(/<table[\s\S]*?<\/table>/i);
  if (!tableMatch) return { headers: [], rows: [] };

  const table = tableMatch[0];

  // headers
  let headers = [];
  const thead = table.match(/<thead[\s\S]*?<\/thead>/i);
  const headHtml = thead ? thead[0] : table;
  const ths = [...headHtml.matchAll(/<th[^>]*>([\s\S]*?)<\/th>/gi)].map(m => _stripTags(m[1]));
  if (ths.length) headers = ths;

  // rows
  const rows = [];
  const trs = [...table.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)].map(m => m[1]);
  for (const tr of trs) {
    const tds = [...tr.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map(m => _stripTags(m[1]));
    if (!tds.length) continue;
    rows.push(tds);
  }

  return { headers, rows };
}

async function _fetchHtml(env, url, { ttl = 6 * 3600, cacheKey = "", headers = null } = {}) {
  const key = cacheKey ? `HTML:${cacheKey}` : `HTML:${url}`;
  const cached = await kvGetJson(env, key);
  if (cached && cached.html && cached.ts && (Date.now() - cached.ts) < ttl * 1000) return cached;

  const ua =
    (env && env.SCRAPE_UA) ||
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36";

  const hdrs = {
    "user-agent": ua,
    "accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "accept-language": "en-US,en;q=0.9",
    "cache-control": "no-cache",
    "pragma": "no-cache",
    ...(headers || {})
  };

  const resp = await fetch(url, { headers: hdrs });
  const html = await resp.text().catch(() => "");
  const out = {
    ts: Date.now(),
    status: resp.status,
    content_type: resp.headers.get("content-type") || "",
    url,
    html
  };
  await kvPutJson(env, key, out);
  return out;
}

function _normTeamFromCell(s) {
  const txt = String(s || "").trim();
  if (!txt) return "";

  const up = txt.toUpperCase();

  // If already an abbreviation
  if (up.length === 3 && NBA_ABBR_TO_TEAM_ID[up]) return up;

  // Match by full team name
  const byName = NBA_TEAM_NAME_TO_ABBR[up];
  if (byName) return byName;

  // Common prefixes / variants
  const up2 = up
    .replace(/\./g, "")
    .replace(/\s+/g, " ")
    .replace(/^LOS ANGELES /, "LA ")
    .replace(/^GOLDEN STATE /, "GOLDEN STATE ");

  const byName2 = NBA_TEAM_NAME_TO_ABBR[up2];
  if (byName2) return byName2;

  // Fallback: first token if it is a 3-letter abbr
  const token = txt.split(/\s+/)[0].toUpperCase();
  if (token.length === 3 && NBA_ABBR_TO_TEAM_ID[token]) return token;

  return "";
}

async function fetchStufferRestDaysMap(env, seasonEnd) {
  const seasonStr = toNbaSeasonString(seasonEnd); // "2025-26"
  // Stuffer uses "2025-2026" style
  const year0 = Number(String(seasonStr).slice(0, 4));
  const stufferSeason = `${year0}-${year0 + 1}`;
  const url = `https://www.nbastuffer.com/${stufferSeason}-nba-rest-days-stats/`;
  const html = await _fetchHtml(env, url, { ttl: 6 * 3600, cacheKey: `stuffer:rest:${stufferSeason}` });

  const { headers, rows } = _parseHtmlTableFirst(html?.html || "");

  const nameToAbbr = await _buildTeamNameToAbbr(env);

  // flexible column finding
  const h = headers.map(x => x.toLowerCase());
  const idxTeam = h.findIndex(x => x.includes("team"));
  const idxRest = h.findIndex(x => x.includes("rest") && x.includes("days"));
  const idxB2B  = h.findIndex(x => x.includes("b2b") || x.includes("back-to-back"));
  const idx3in4 = h.findIndex(x => x.includes("3") && x.includes("4"));
  const idx4in6 = h.findIndex(x => x.includes("4") && x.includes("6"));

  const map = new Map();
  for (const r of rows) {
    const teamCell = r[idxTeam >= 0 ? idxTeam : 0];
    const teamName = String(teamCell || "").trim();
    if (!teamName) continue;
    const tn = teamName.toUpperCase();
    const key = tn.toLowerCase().replace(/\s+/g, " ");
    const abbr =
      (NBA_TEAM_NAME_TO_ABBR[tn.toUpperCase()]) ||
      nameToAbbr.get(key) ||
      (tn.length === 3 ? tn : "");
    if (!abbr) continue;

    const restDays = idxRest >= 0 ? safeNum(r[idxRest]) : "";
    map.set(abbr, {
      rest_days: restDays,
      b2b: idxB2B >= 0 ? safeNum(r[idxB2B]) : "",
      three_in_four: idx3in4 >= 0 ? safeNum(r[idx3in4]) : "",
      four_in_six: idx4in6 >= 0 ? safeNum(r[idx4in6]) : "",
      _src: url,
    });
  }
  return map;
}

async function fetchStufferRefStats(env, seasonEnd) {
  const seasonStr = toNbaSeasonString(seasonEnd);
  const year0 = Number(String(seasonStr).slice(0, 4));
  const stufferSeason = `${year0}-${year0 + 1}`;
  const url = `https://www.nbastuffer.com/${stufferSeason}-nba-referee-stats/`;
  const html = await _fetchHtml(env, url, { ttl: 12 * 3600, cacheKey: `stuffer:refs:${stufferSeason}` });

  const { headers, rows } = _parseHtmlTableFirst(html?.html || "");

  const nameToAbbr = await _buildTeamNameToAbbr(env);
  // Return raw table but normalized keys where possible
  const out = [];
  const keys = headers.length ? headers : [];
  for (const r of rows) {
    const obj = {};
    for (let i = 0; i < r.length; i++) obj[keys[i] || `c${i}`] = r[i];
    out.push(obj);
  }
  return { url, count: out.length, rows: out.slice(0, 400), headers };
}


// --- NBA Official referee assignments (official.nba.com) ---
const OFFICIAL_CITY_TO_ABBR = {
  "ATLANTA": "ATL",
  "BOSTON": "BOS",
  "BROOKLYN": "BKN",
  "CHARLOTTE": "CHA",
  "CHICAGO": "CHI",
  "CLEVELAND": "CLE",
  "DALLAS": "DAL",
  "DENVER": "DEN",
  "DETROIT": "DET",
  "GOLDEN STATE": "GSW",
  "HOUSTON": "HOU",
  "INDIANA": "IND",
  "LA CLIPPERS": "LAC",
  "LOS ANGELES CLIPPERS": "LAC",
  "LA LAKERS": "LAL",
  "LOS ANGELES LAKERS": "LAL",
  "MEMPHIS": "MEM",
  "MIAMI": "MIA",
  "MILWAUKEE": "MIL",
  "MINNESOTA": "MIN",
  "NEW ORLEANS": "NOP",
  "NEW YORK": "NYK",
  "OKLAHOMA CITY": "OKC",
  "ORLANDO": "ORL",
  "PHILADELPHIA": "PHI",
  "PHOENIX": "PHX",
  "PORTLAND": "POR",
  "SACRAMENTO": "SAC",
  "SAN ANTONIO": "SAS",
  "TORONTO": "TOR",
  "UTAH": "UTA",
  "WASHINGTON": "WAS",
};

function _normOfficialCity(s) {
  const t = String(s || "")
    .replace(/\u00A0/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const up = t.toUpperCase()
    .replace(/^L\.A\.\s*/i, "LA ")
    .replace(/^L\.A\s*/i, "LA ")
    .replace(/^LOS ANGELES\s+/i, "LOS ANGELES ")
    .replace(/^GOLDEN\s+STATE/i, "GOLDEN STATE")
    .replace(/^O\.K\.C\.\s*/i, "OKLAHOMA CITY ")
    .replace(/\./g, "")
    .replace(/\s+/g, " ")
    .trim();
  // normalize "LA LAKERS" / "LA CLIPPERS"
  if (up.startsWith("LA ") && up.includes("LAKERS")) return "LA LAKERS";
  if (up.startsWith("LA ") && up.includes("CLIPPERS")) return "LA CLIPPERS";
  return up;
}

function _parseOfficialAssignmentsText(text) {
  // Expect block like:
  // Phoenix @ Philadelphia Scott Foster (#48) Ashley ... (#13) Jonathan ... (#17)
  const out = [];
  const body = String(text || "").replace(/\u00A0/g, " ");

  // isolate NBA section (before G League)
  const nbaStart = body.indexOf("NBA Referee Assignments");
  if (nbaStart < 0) return { dateText: "", games: out };
  const gLeagueStart = body.indexOf("G League Referee Assignments", nbaStart);
  const nbaBlock = body.slice(nbaStart, gLeagueStart > 0 ? gLeagueStart : undefined);

  // date line (e.g., "January 21, 2026")
  const dateMatch = nbaBlock.match(/\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},\s+\d{4}\b/);
  const dateText = dateMatch ? dateMatch[0] : "";

  // capture game lines (the page tends to have one game per line)
  const lines = nbaBlock.split(/\r?\n/).map((x) => x.trim()).filter(Boolean);

  // regex for one line (alternate optional)
  const re = /^(.+?)\s+@\s+(.+?)\s+([A-Za-z.'\-\s]+?)\s*\(#\d+\)\s+([A-Za-z.'\-\s]+?)\s*\(#\d+\)\s+([A-Za-z.'\-\s]+?)\s*\(#\d+\)(?:\s+([A-Za-z.'\-\s]+?)\s*\(#\d+\))?\s*$/;

  for (const ln of lines) {
    if (!ln.includes("@") || !ln.includes("(#")) continue;
    // remove extra link markers etc (the open() view is already mostly plain)
    const clean = ln.replace(/\s+/g, " ").trim();
    const m = clean.match(re);
    if (!m) continue;
    const awayCity = m[1].trim();
    const homeCity = m[2].trim();
    const crewChief = m[3].trim();
    const referee = m[4].trim();
    const umpire = m[5].trim();
    const alternate = (m[6] || "").trim();

    const awayAbbr = OFFICIAL_CITY_TO_ABBR[_normOfficialCity(awayCity)] || null;
    const homeAbbr = OFFICIAL_CITY_TO_ABBR[_normOfficialCity(homeCity)] || null;

    out.push({
      away_city: awayCity,
      home_city: homeCity,
      away: awayAbbr,
      home: homeAbbr,
      officials: [
        { role: "crew_chief", name: crewChief },
        { role: "referee", name: referee },
        { role: "umpire", name: umpire },
      ].concat(alternate ? [{ role: "alternate", name: alternate }] : []),
      raw_line: clean,
    });
  }

  return { dateText, games: out };
}

function _monthNameToNum(m) {
  const mm = {
    january: 1, february: 2, march: 3, april: 4, may: 5, june: 6,
    july: 7, august: 8, september: 9, october: 10, november: 11, december: 12
  };
  return mm[String(m || "").toLowerCase()] || null;
}

function _dateTextToISO(dateText) {
  // "January 21, 2026" -> "2026-01-21"
  const m = String(dateText || "").match(/^(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2}),\s+(\d{4})$/);
  if (!m) return null;
  const mo = _monthNameToNum(m[1]);
  const day = Number(m[2]);
  const yr = Number(m[3]);
  if (!mo || !day || !yr) return null;
  const mm = String(mo).padStart(2, "0");
  const dd = String(day).padStart(2, "0");
  return `${yr}-${mm}-${dd}`;
}

async function fetchOfficialRefAssignments(env, { force = false, date = null, debug = false, dump = false } = {}) {
  const srcUrl = "https://official.nba.com/referee-assignments/";
  const altUrl = "https://official.nba.com/"; // fallback: Today's Officials block sometimes easier to parse
  const isoDate = date || todayISOInTZ(NY_TZ);
  const cacheKey = `nba:official:refs_assignments:${isoDate}`;

  // Serve cache if present
  if (!force && env?.RTP_CACHE) {
    try {
      const hit = await env.RTP_CACHE.get(cacheKey, "json");
      if (hit && hit.date && Array.isArray(hit.games)) return { ...hit, cached: true };
    } catch {}
  }

  // Fetch HTML with browser-ish headers (NBA Official sometimes blocks bare fetch)
  const html = await _fetchHtml(env, srcUrl, {
    ttl: 60 * 30,
    cacheKey,
    headers: {
      "accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
      "accept-language": "en-US,en;q=0.9",
      "cache-control": "no-cache",
      "pragma": "no-cache",
      "referer": "https://official.nba.com/",
      "upgrade-insecure-requests": "1",
      "user-agent": "Mozilla/5.0 (compatible; RTP-NBA-Lab/1.0; +https://rtp-nba.pages.dev)"
    }
  });

  // Primary parse
  let parsed = parseNbaOfficialAssignmentsHtml(html?.html || "", { debug });

  // Fallback: sometimes the /referee-assignments page is JS-rendered or blocked for Workers.
  // Try parsing the homepage "Today's Officials" section if we didn't find any tables.
  if (!parsed?.games?.length) {
    try {
      const alt = await _fetchHtml(env, altUrl, {
        ttl: 60 * 30,
        cacheKey: `${cacheKey}:alt`,
        headers: {
          "accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
          "accept-language": "en-US,en;q=0.9",
          "cache-control": "no-cache",
          "pragma": "no-cache",
          "referer": "https://official.nba.com/",
          "upgrade-insecure-requests": "1",
          "user-agent": "Mozilla/5.0 (compatible; RTP-NBA-Lab/1.0; +https://rtp-nba.pages.dev)"
        }
      });
      const altParsed = parseNbaOfficialTodaysOfficialsHtml(alt?.html || "", { debug });
      if (altParsed?.games?.length) parsed = altParsed;
      // If debug requested and primary had 0 tables, attach fallback debug too.
      if (debug && parsed && parsed.debug) {
        parsed.debug.fallback_used = !!altParsed?.games?.length;
      }
    } catch {}
  }

  // Attach fetch-level debug for troubleshooting when tables_found is 0
  if (debug) {
    parsed = parsed || { games: [], debug: {} };
    parsed.debug = parsed.debug || {};
    parsed.debug.fetch = {
      src_status: html?.status ?? null,
      src_content_type: html?.content_type ?? null,
      src_len: (html?.html ? String(html.html).length : 0),
      src_has_table_tag: (html?.html ? /<table\b/i.test(String(html.html)) : false),
      src_body_head: (html?.html ? String(html.html).slice(0, 900) : "")
    };
  }
  const games = parsed.games;
  const byKey = {};
  for (const g of games) {
    if (g && g.key) byKey[g.key] = g;
  }

  const out = {
    date: isoDate,
    source_url: srcUrl,
    games,
    byKey,
    cached: false,
    ...(debug ? { debug: parsed.debug } : {})
  };

  if (env?.RTP_CACHE) {
    try { await env.RTP_CACHE.put(cacheKey, JSON.stringify(out), { expirationTtl: 60 * 30 }); } catch {}
  }

  return out;
}

function parseNbaOfficialAssignmentsHtml(html, { debug = false, dump = false } = {}) {
  const result = { games: [], debug: null };

  const src = String(html || "");
  const tables = [];
  const reTable = /<table\b[\s\S]*?<\/table>/gi;
  let tm;
  while ((tm = reTable.exec(src)) !== null) tables.push(tm[0]);

  // Helper: extract headers from a table (thead preferred; otherwise first row th)
  function _extractHeaders(tableHtml) {
    const headers = [];
    const thead = tableHtml.match(/<thead\b[\s\S]*?<\/thead>/i)?.[0] || "";
    const scope = thead || tableHtml;
    const reTh = /<th\b[^>]*>([\s\S]*?)<\/th>/gi;
    let m;
    while ((m = reTh.exec(scope)) !== null) {
      const t = _stripHtml(m[1]);
      if (t) headers.push(t);
    }
    // If nothing found in thead, try first <tr> with <th>
    if (!headers.length) {
      const tr = tableHtml.match(/<tr\b[^>]*>[\s\S]*?<\/tr>/i)?.[0] || "";
      let m2;
      while ((m2 = reTh.exec(tr)) !== null) {
        const t = _stripHtml(m2[1]);
        if (t) headers.push(t);
      }
    }
    return headers;
  }

  // Helper: extract rows (tbody preferred)
  function _extractRows(tableHtml) {
    const tbody = tableHtml.match(/<tbody\b[\s\S]*?<\/tbody>/i)?.[0] || tableHtml;
    const rows = [];
    const reTr = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
    let m;
    while ((m = reTr.exec(tbody)) !== null) rows.push(m[1]);
    return rows;
  }

  // Helper: extract cells (<td> or <th>, allowing attrs)
  function _extractCells(trInnerHtml) {
    const cells = [];
    const reCell = /<(td|th)\b[^>]*>([\s\S]*?)<\/\1>/gi;
    let m;
    while ((m = reCell.exec(trInnerHtml)) !== null) {
      const t = _stripHtml(m[2]);
      cells.push(t);
    }
    return cells;
  }

  // Choose the assignments table by header match
  let chosen = -1;
  let chosenHeaders = [];
  for (let i = 0; i < tables.length; i++) {
    const h = _extractHeaders(tables[i]);
    const hl = h.map((x) => String(x || "").toLowerCase());
    const ok =
      hl.includes("game") &&
      (hl.some((x) => x.includes("crew")) || hl.includes("crew chief")) &&
      hl.includes("referee") &&
      hl.includes("umpire");
    if (ok) {
      chosen = i;
      chosenHeaders = h;
      break;
    }
  }

  // Stage A: parse HTML table rows
  const games = [];
  const byKey = {};
  const sample_rows = [];
  let stage = "html_table";
  let rowsParsed = 0;

  if (chosen >= 0) {
    const rows = _extractRows(tables[chosen]);
    for (const r of rows) {
      const cells = _extractCells(r).map((x) => String(x || "").trim());
      if (!cells.length) continue;

      // Skip header-like rows
      if (cells[0] && cells[0].toLowerCase() === "game") continue;
      // Require at least 4 columns: Game, Crew Chief, Referee, Umpire
      if (cells.length < 4) continue;

      const gameStr = cells[0];
      const crewChief = cells[1] || "";
      const referee = cells[2] || "";
      const umpire = cells[3] || "";
      const alternate = cells[4] || "";

      // Must look like a matchup
      const parsedGame = _parseGameMatchup(gameStr);
      if (!parsedGame?.home || !parsedGame?.away) continue;

      const officials = [];
      if (crewChief) officials.push({ role: "crew_chief", name: _normRefName(crewChief) });
      if (referee) officials.push({ role: "referee", name: _normRefName(referee) });
      if (umpire) officials.push({ role: "umpire", name: _normRefName(umpire) });
      if (alternate) officials.push({ role: "alternate", name: _normRefName(alternate) });

      const k = `${parsedGame.away}@${parsedGame.home}`;
      const obj = { game: gameStr, away: parsedGame.away, home: parsedGame.home, key: k, officials };
      games.push(obj);
      byKey[k] = obj;
      rowsParsed++;
      if (sample_rows.length < 3) sample_rows.push(obj);
    }
  }

  // Stage B: embedded JSON extractor (script blobs)
  function _extractEmbeddedAssignmentsJson(srcHtml) {
    const hits = [];
    const reScript = /<script\b[^>]*>([\s\S]*?)<\/script>/gi;
    let sm;
    while ((sm = reScript.exec(srcHtml)) !== null) {
      const blob = sm[1] || "";
      if (!blob) continue;
      // Only consider blobs that mention column names
      if (!/Referee/i.test(blob) && !/Umpire/i.test(blob) && !/Crew/i.test(blob)) continue;

      // Try: find a JSON array of row objects containing "Game"
      // Pattern: [ { "Game": "...", "Crew Chief": "...", ... }, ... ]
      const reArr = /\[[\s\S]*?\]/g;
      const candidates = [];
      let am;
      while ((am = reArr.exec(blob)) !== null) {
        const chunk = am[0];
        if (chunk.length < 200) continue;
        if (!/"Game"/i.test(chunk) && !/\bGame\b/i.test(chunk)) continue;
        if (!/Crew\s*Chief/i.test(chunk)) continue;
        candidates.push(chunk);
        if (candidates.length >= 3) break;
      }

      for (const c of candidates) {
        // Some blobs use escaped quotes; unescape lightly if needed
        let txt = c.trim();
        // Guard: prevent enormous parse
        if (txt.length > 300000) continue;
        try {
          const parsed = JSON.parse(txt);
          if (Array.isArray(parsed)) {
            for (const row of parsed) {
              if (!row || typeof row !== "object") continue;
              const game = row.Game || row.game || row.MATCHUP || row.matchup;
              const cc = row["Crew Chief"] || row.crew_chief || row.CrewChief || "";
              const rf = row.Referee || row.referee || "";
              const um = row.Umpire || row.umpire || "";
              const al = row.Alternate || row.alternate || "";
              if (!game || !cc || !rf || !um) continue;
              hits.push({ game: String(game), crewChief: String(cc), referee: String(rf), umpire: String(um), alternate: String(al || "") });
            }
          }
        } catch (e2) { bdl_fallback_error = String(e2?.message || e2); }
      }
    }
    return hits;
  }

  if (!games.length) {
    const hits = _extractEmbeddedAssignmentsJson(src);
    if (hits.length) {
      stage = "embedded_json";
      for (const h of hits) {
        const parsedGame = _parseGameMatchup(h.game);
        if (!parsedGame?.home || !parsedGame?.away) continue;
        const officials = [];
        if (h.crewChief) officials.push({ role: "crew_chief", name: _normRefName(h.crewChief) });
        if (h.referee) officials.push({ role: "referee", name: _normRefName(h.referee) });
        if (h.umpire) officials.push({ role: "umpire", name: _normRefName(h.umpire) });
        if (h.alternate) officials.push({ role: "alternate", name: _normRefName(h.alternate) });

        const k = `${parsedGame.away}@${parsedGame.home}`;
        const obj = { game: h.game, away: parsedGame.away, home: parsedGame.home, key: k, officials };
        if (!byKey[k]) {
          games.push(obj);
          byKey[k] = obj;
        }
        if (sample_rows.length < 3) sample_rows.push(obj);
      }
    }
  }

  // Stage C: plain-text fallback (strip HTML and parse by line adjacency)
  function _stripAllToText(srcHtml) {
    return String(srcHtml || "")
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<br\s*\/?\s*>/gi, "\n")
      .replace(/<\/p>/gi, "\n")
      .replace(/<\/tr>/gi, "\n")
      .replace(/<\/td>/gi, "\t")
      .replace(/<\/th>/gi, "\t")
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/\u00a0/g, " ")
      .replace(/\r/g, "")
      .replace(/\n{3,}/g, "\n\n")
      .replace(/[\t ]{2,}/g, " ")
      .trim();
  }

  function _textFallbackParse(srcHtml) {
    const text = _stripAllToText(srcHtml);
    const lines = text.split(/\n/).map((x) => x.trim()).filter(Boolean);

    const out = [];
    for (let i = 0; i < lines.length; i++) {
      const ln = lines[i];
      // Matchup line typically contains "@" or " at "
      const isMatchup = /\b@\b/.test(ln) || /\bat\b/i.test(ln);
      if (!isMatchup) continue;

      const parsedGame = _parseGameMatchup(ln);
      if (!parsedGame?.home || !parsedGame?.away) continue;

      // Collect next few lines as officials (skip role labels)
      const officialsRaw = [];
      let j = i + 1;
      while (j < lines.length && officialsRaw.length < 4) {
        const v = lines[j];
        if (/crew\s*chief|referee|umpire|alternate/i.test(v) && v.split(" ").length <= 3) { j++; continue; }
        // stop if next matchup starts
        if ((/\b@\b/.test(v) || /\bat\b/i.test(v)) && _parseGameMatchup(v)?.home) break;
        // heuristic: a name has a space and letters
        if (/[A-Za-z]/.test(v) && v.split(" ").length >= 2) officialsRaw.push(v);
        j++;
      }

      if (officialsRaw.length < 3) {
        // Some renders put officials on the SAME line as the matchup (table-like text).
        // Try to extract 3-4 full names from the matchup line itself after the separator.
        const nameRe = /\b([A-Z][a-z]+\s+[A-Z][a-z]+)\b/g;
        const names = [];
        let nm;
        while ((nm = nameRe.exec(ln)) !== null) {
          const name = (nm[1] || "").trim();
          // Avoid capturing city/team tokens; keep plausible person names.
          if (name && !/\b(Team|Referee|Assignments|League)\b/i.test(name)) names.push(name);
          if (names.length >= 4) break;
        }
        // If we got 3+ names, use them as officials.
        if (names.length >= 3) officialsRaw.push(...names.slice(0, 4));
      }

      if (officialsRaw.length >= 3) {
        const officials = [];
        if (officialsRaw[0]) officials.push({ role: "crew_chief", name: _normRefName(officialsRaw[0]) });
        if (officialsRaw[1]) officials.push({ role: "referee", name: _normRefName(officialsRaw[1]) });
        if (officialsRaw[2]) officials.push({ role: "umpire", name: _normRefName(officialsRaw[2]) });
        if (officialsRaw[3]) officials.push({ role: "alternate", name: _normRefName(officialsRaw[3]) });

        const k = `${parsedGame.away}@${parsedGame.home}`;
        const obj = { game: ln, away: parsedGame.away, home: parsedGame.home, key: k, officials };
        if (!byKey[k]) {
          out.push(obj);
          byKey[k] = obj;
        }
      }
    }
    return out;
  }

  if (!games.length) {
    const fb = _textFallbackParse(src);
    if (fb.length) {
      stage = "text_fallback";
      for (const g of fb) {
        games.push(g);
        if (sample_rows.length < 3) sample_rows.push(g);
      }
    }
  }

  // Optional debug dump (helps identify real markup / embedded data)
  const dbg = debug ? {
    tables_found: tables.length,
    chosen_table_index: chosen,
    headers: chosenHeaders || [],
    sample_rows,
    stage,
    rowsParsed,
  } : null;

  if (debug && dump) {
    const dumpObj = {};

    // Snippet around the chosen table and header text
    const pivot = chosen >= 0 ? tables[chosen] : "";
    const pivotHead = pivot ? pivot.slice(0, 2500) : "";
    dumpObj.chosen_table_head = pivotHead;

    // Snippet around first occurrence of "Crew Chief" in HTML
    const idx = src.toLowerCase().indexOf("crew chief");
    if (idx >= 0) dumpObj.crew_chief_context = src.slice(Math.max(0, idx - 800), Math.min(src.length, idx + 1600));

    // Script snippet candidates
    const scripts = [];
    const reScript = /<script\b[^>]*>([\s\S]*?)<\/script>/gi;
    let sm;
    while ((sm = reScript.exec(src)) !== null) {
      const blob = sm[1] || "";
      if (!blob) continue;
      if (/Crew\s*Chief/i.test(blob) || /Referee/i.test(blob) || /Umpire/i.test(blob)) {
        scripts.push(blob.slice(0, 2000));
        if (scripts.length >= 3) break;
      }
    }
    dumpObj.script_heads = scripts;

    dbg.dump = dumpObj;
  }

  result.games = games;
  result.debug = dbg;
  return result;
}


function _stripHtml(s) {
  let x = String(s || "");
  // replace breaks with space
  x = x.replace(/<br\s*\/?>/gi, " ");
  // strip tags
  x = x.replace(/<[^>]+>/g, " ");
  // decode common entities
  x = x.replace(/&nbsp;/gi, " ");
  x = x.replace(/&amp;/gi, "&").replace(/&lt;/gi, "<").replace(/&gt;/gi, ">");
  x = x.replace(/&#39;/g, "'").replace(/&quot;/g, '"');
  // normalize whitespace
  x = x.replace(/\s+/g, " ").trim();
  return x;
}

function _parseGameMatchup(gameStr) {
  const raw = String(gameStr || "").replace(/\s+/g, " ").trim();
  if (!raw) return { away: null, home: null };

  // Common separators: "@" or " at "
  let parts = null;
  if (raw.includes("@")) parts = raw.split("@");
  else if (raw.toLowerCase().includes(" at ")) parts = raw.split(/ at /i);
  else if (raw.toLowerCase().includes(" vs ")) parts = raw.split(/ vs /i);

  if (!parts || parts.length < 2) return { away: null, home: null };

  const awayName = parts[0].trim();
  const homeName = parts[1].trim();

  const away = _teamAbbrFromLooseName(awayName);
  const home = _teamAbbrFromLooseName(homeName);

  return { away, home };
}

function _teamAbbrFromLooseName(name) {
  const s = String(name || "").trim();
  if (!s) return null;

  const cleaned = s
    .replace(/\./g, "")
    .replace(/[\u2013\u2014\-]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();

  // Direct match against known team full names
  try {
    const map = (typeof NBA_TEAM_NAME_TO_ABBR === "object" && NBA_TEAM_NAME_TO_ABBR) ? NBA_TEAM_NAME_TO_ABBR : {};
    for (const [k, v] of Object.entries(map)) {
      if (String(k).toLowerCase() === cleaned) return v;
    }
    // Loose contains match (city only)
    for (const [k, v] of Object.entries(map)) {
      const kk = String(k).toLowerCase();
      if (cleaned === kk) return v;
      // match by city token(s)
      if (kk.includes(cleaned) || cleaned.includes(kk)) return v;
    }
  } catch {}

  // If the string already looks like an abbr
  const up = s.toUpperCase().replace(/[^A-Z]/g, "");
  if (up.length === 3) return up;

  return null;
}

function _normRefName(s) {
  return String(s || "")
    .replace(/\u00A0/g, " ")
    .replace(/\s+/g, " ")
    // keep letters, spaces, common punctuation in names
    .replace(/[^A-Za-z\s\-\.'"]/g, "")
    .trim()
    .toLowerCase();
}

function _buildRefStatsIndex(refRows) {
  const byName = {};
  const all = [];
  for (const r of (refRows || [])) {
    const name = r?.["Referee"] || r?.["Name"] || r?.["Official"] || r?.["REFEREE"] || r?.["referee"] || "";
    const n = _normRefName(name);
    if (!n) continue;

    const totalPts = safeNum(r?.["TOTAL POINTS PER GAME"] ?? r?.["TOTAL PTS PER GAME"] ?? r?.["TOTAL PTS"] ?? r?.["TOTAL POINTS"] ?? r?.["PTS"] ?? "");
    const calledFouls = safeNum(r?.["CALLED FOULS PER GAME"] ?? r?.["CALLED FOULS"] ?? r?.["FOULS PER GAME"] ?? "");
    const foulDiff = safeNum(r?.["FOUL DIFFERENTIAL"] ?? r?.["FOUL DIFF"] ?? "");
    const homeWinPct = safeNum(r?.["HOME WIN%"] ?? r?.["HOME WIN %"] ?? "");
    const homePtsDiff = safeNum(r?.["HOME TEAM POINTS DIFFERENTIAL"] ?? r?.["HOME PTS DIFF"] ?? "");

    const obj = { name, total_pts_pg: totalPts, called_fouls_pg: calledFouls, foul_diff: foulDiff, home_win_pct: homeWinPct, home_pts_diff: homePtsDiff, _raw: r };
    byName[n] = obj;
    all.push(obj);
  }

  const avg = (arr, key) => {
    const xs = (arr || []).map((x) => Number(x?.[key])).filter((x) => Number.isFinite(x));
    if (!xs.length) return null;
    return xs.reduce((a, b) => a + b, 0) / xs.length;
  };

  const league = {
    avg_total_pts_pg: avg(all, "total_pts_pg"),
    avg_called_fouls_pg: avg(all, "called_fouls_pg"),
    avg_foul_diff: avg(all, "foul_diff"),
    avg_home_win_pct: avg(all, "home_win_pct"),
    avg_home_pts_diff: avg(all, "home_pts_diff"),
  };

  return { byName, league };
}

function _crewAverages(statsByName, officials) {
  const picks = [];
  for (const o of (officials || [])) {
    const n = _normRefName(o?.name);
    const s = n ? statsByName?.[n] : null;
    if (s) picks.push(s);
  }
  const avg = (key) => {
    const xs = picks.map((x) => Number(x?.[key])).filter((x) => Number.isFinite(x));
    if (!xs.length) return null;
    return xs.reduce((a, b) => a + b, 0) / xs.length;
  };
  return {
    refs_found: picks.length,
    crew_total_pts_pg: avg("total_pts_pg"),
    crew_called_fouls_pg: avg("called_fouls_pg"),
    crew_foul_diff: avg("foul_diff"),
    crew_home_win_pct: avg("home_win_pct"),
    crew_home_pts_diff: avg("home_pts_diff"),
  };
}

async function inferMatchupISODate(env, { seasonEnd, home, away } = {}) {
  try {
    await ensureBdlTeamMaps(env);
    const h = String(home || "").toUpperCase();
    const a = String(away || "").toUpperCase();
    if (!h || !a) return null;

    const today = todayISOInTZ(NY_TZ);
    const seasonStart = seasonStartFromSeason(asInt(seasonEnd) || inferSeasonFromNowNY());

    const q = new URLSearchParams();
    q.set("per_page", "100");
    q.set("seasons[]", String(seasonStart));
    // Narrow by team ids if available
    if (NBA_ABBR_TO_TEAM_ID[h]) q.append("team_ids[]", String(NBA_ABBR_TO_TEAM_ID[h]));
    if (NBA_ABBR_TO_TEAM_ID[a]) q.append("team_ids[]", String(NBA_ABBR_TO_TEAM_ID[a]));

    const js = await fetchBDL(env, "/games", q);
    const rows = Array.isArray(js?.data) ? js.data : [];

    const candidates = rows.filter(g => {
      const homeAb = (g?.home_team?.abbreviation || g?.home_team?.abbr || "").toUpperCase();
      const awayAb = (g?.visitor_team?.abbreviation || g?.visitor_team?.abbr || "").toUpperCase();
      return (homeAb === h && awayAb === a) || (homeAb === a && awayAb === h);
    }).map(g => {
      const d = (g?.date || "").slice(0,10);
      return { d, g };
    }).filter(x => x.d && /^\d{4}-\d{2}-\d{2}$/.test(x.d));

    if (!candidates.length) return null;

    // Choose closest to "today". We *slightly* prefer future over past only when the distance is equal.
    // This keeps minutes/ref date aligned when calling /script the day after a game.
    const toDayNum = (s) => {
      const [Y,M,D] = s.split("-").map(n=>parseInt(n,10));
      return Math.floor(Date.UTC(Y,M-1,D)/86400000);
    };
    const tN = toDayNum(today);

    candidates.sort((x,y) => {
      const xN = toDayNum(x.d), yN = toDayNum(y.d);
      const xAbs = Math.abs(xN - tN);
      const yAbs = Math.abs(yN - tN);
      if (xAbs !== yAbs) return xAbs - yAbs;
      // tie-break: prefer future (including today)
      const xIsFuture = xN >= tN ? 0 : 1;
      const yIsFuture = yN >= tN ? 0 : 1;
      return xIsFuture - yIsFuture;
    });

    // If best is far away (>14d), don't trust it.
    const best = candidates[0].d;
    const bestN = toDayNum(best);
    if (Math.abs(bestN - tN) > 14) return today;

    return best;
  } catch {
    return null;
  }
}

async function buildRefsContext(env, { seasonEnd, home, away, force = false, date = null, debug = false } = {}) {
  // Ref assignments are date-keyed on NBA Official. If date isn't provided,
  // infer the likely matchup date from BDL schedule so /script works without UI changes.
  const inferred = date ? null : (await inferMatchupISODate(env, { seasonEnd, home, away }));
  const isoDate = date || inferred || todayISOInTZ(NY_TZ);
  const date_source = date ? 'query' : (inferred ? 'inferred' : 'today');
  const dbg = debug ? { isoDate, date_source, key1: `${away}@${home}`, key2: `${home}@${away}` } : null;

  // Pull assignments for the inferred date + stuffer ref stats; then compute crew means
  const assign = await fetchOfficialRefAssignments(env, { force, date: isoDate, debug });
  if (dbg) { dbg.assign_cached = !!assign?.cached; dbg.tables_found = assign?.debug?.tables_found ?? null; dbg.stage = assign?.debug?.stage ?? null; }

  const key1 = `${away}@${home}`; // canonical
  const key2 = `${home}@${away}`; // fallback (if upstream keyed differently)
  let row = (assign?.byKey?.[key1]) || (assign?.byKey?.[key2]) || null;

  // Fallback: search games[] if byKey not populated or key mismatch
  if (!row && Array.isArray(assign?.games)) {
    row = assign.games.find(g => (g?.away===away && g?.home===home) || (g?.away===home && g?.home===away)) || null;
  }

  const matchup_key = row?.key || (row?.away && row?.home ? `${row.away}@${row.home}` : key1);
  if (!row || !Array.isArray(row.officials) || !row.officials.length) {
    if (dbg) {
      dbg.matchup_key = matchup_key;
      dbg.row_found = !!row;
      dbg.officials_len = row?.officials?.length ?? 0;
      return { date: assign?.date || isoDate, matchup_key, source_url: assign?.source_url, officials: (row?.officials || []), refs_found: 0, _debug: dbg };
    }
    return null;
  }

  const stuffer = await fetchStufferRefStats(env, seasonEnd);
  const idx = _buildRefStatsIndex(stuffer?.rows || []);
  const crew = _crewAverages(idx.byName, row.officials);

  return {
    date: assign?.date || isoDate,
    matchup_key,
    source_url: assign?.source_url,
    officials: row.officials,
    refs_found: crew.refs_found,
    crew_total_pts_pg: crew.crew_total_pts_pg,
    crew_called_fouls_pg: crew.crew_called_fouls_pg,
    crew_foul_diff: crew.crew_foul_diff,
    crew_home_win_pct: crew.crew_home_win_pct,
    crew_home_pts_diff: crew.crew_home_pts_diff,
    league_avg_total_pts_pg: idx.league.avg_total_pts_pg,
    league_avg_called_fouls_pg: idx.league.avg_called_fouls_pg,
    league_avg_foul_diff: idx.league.avg_foul_diff,
    league_avg_home_win_pct: idx.league.avg_home_win_pct,
    league_avg_home_pts_diff: idx.league.avg_home_pts_diff,
    ...(debug ? { _debug: dbg } : {}),
  };

  if (dbg) {
    dbg.matchup_key = out.matchup_key;
    dbg.refs_found = out.refs_found;
  }
  return out;
}


//////////////////////////////
// BDL Minutes Pipeline (ELITE)
// Rule: REAL minutes or null. NO defaults. NO synthetic.
//////////////////////////////

const KV_MINUTES_BDL_PREFIX = "nba:minutes:bdl:"; // nba:minutes:bdl:YYYY-MM-DD
const KV_MINUTES_BDL_META_PREFIX = "nba:minutes:bdl:meta:"; // nba:minutes:bdl:meta:YYYY-MM-DD

function _kvKeyBdlMinutes(date){ return `${KV_MINUTES_BDL_PREFIX}${date}`; }
function _kvKeyBdlMinutesMeta(date){ return `${KV_MINUTES_BDL_META_PREFIX}${date}`; }

function _asISODate(d){
  const s = String(d||"").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  return s;
}

function _inferSeasonStartYearFromDate(date){
  // NBA season year is the start year (e.g., 2025 for 2025-26). If month>=10 => same year else year-1.
  const s = _asISODate(date);
  if (!s) return null;
  const [y,mo] = s.split("-").map(x=>Number(x));
  if (!Number.isFinite(y) || !Number.isFinite(mo)) return null;
  return (mo >= 10 ? y : (y-1));
}

function _gameMarginFromStat(st){
  const g = st?.game || {};
  const hs = Number(g.home_team_score);
  const vs = Number(g.visitor_team_score);
  if (Number.isFinite(hs) && Number.isFinite(vs)) return hs - vs;
  // fallback if API uses different keys
  const h2 = Number(g.home_score);
  const v2 = Number(g.visitor_score);
  if (Number.isFinite(h2) && Number.isFinite(v2)) return h2 - v2;
  const m = Number(g.margin);
  return Number.isFinite(m) ? m : null;
}

function _statGameTs(st){
  const g = st?.game || {};
  const d = g.date || g.start_time || g.startTime || "";
  const t = Date.parse(d);
  return Number.isFinite(t) ? t : 0;
}

function _recencyWeights(n){
  const base = [1.00,0.90,0.80,0.70,0.60,0.55,0.50,0.45,0.40,0.35];
  const out = [];
  for (let i=0;i<n;i++) out.push(base[i] ?? Math.max(0.20, 0.35 - 0.03*(i-9)));
  return out;
}

function _wavg(vals){
  const xs = (vals||[]).filter(v=>Number.isFinite(v?.x) && Number.isFinite(v?.w) && v.w>0);
  if (!xs.length) return null;
  const sw = xs.reduce((a,b)=>a+b.w,0);
  if (!Number.isFinite(sw) || sw<=0) return null;
  return xs.reduce((a,b)=>a + b.x*b.w,0)/sw;
}

function _bucketMinutes(logs, { bucket="comp", maxGames=10 } = {}){
  // logs sorted desc
  const out = [];
  for (const st of (logs||[])){
    const min = _parseMinToFloat(st?.min);
    if (!Number.isFinite(min) || min <= 0) continue;
    const margin = _gameMarginFromStat(st);
    if (!Number.isFinite(margin)) continue;
    const am = Math.abs(margin);

    if (bucket === "comp"){
      if (am > 12) continue;
    } else if (bucket === "blow"){
      if (am < 18) continue;
    } else {
      continue;
    }
    out.push(min);
    if (out.length >= maxGames) break;
  }
  if (out.length < 3) return { minutes:null, n: out.length };
  const ws = _recencyWeights(out.length);
  const wvals = out.map((x,i)=>({x, w: ws[i]||1}));
  return { minutes: _wavg(wvals), n: out.length };
}

function _bucketMinutesRole(logs, { bucket="comp", role="starter", maxGames=10 } = {}){
  const out = [];
  for (const st of (logs||[])){
    const started = st?.start_position ? true : (typeof st?.started === "boolean" ? st.started : null);
    if (role === "starter" && started !== true) continue;
    if (role === "bench" && started !== false) continue;

    const min = _parseMinToFloat(st?.min);
    if (!Number.isFinite(min) || min <= 0) continue;

    const margin = _gameMarginFromStat(st);
    if (!Number.isFinite(margin)) continue;
    const am = Math.abs(margin);

    if (bucket === "comp"){
      if (am > 12) continue;
    } else if (bucket === "blow"){
      if (am < 18) continue;
    } else continue;

    out.push(min);
    if (out.length >= maxGames) break;
  }
  if (out.length < 3) return { minutes:null, n: out.length };
  const ws = _recencyWeights(out.length);
  const wvals = out.map((x,i)=>({x, w: ws[i]||1}));
  return { minutes: _wavg(wvals), n: out.length };
}

function _detectRoleFromLogs(logs){
  // Use last 3 games where we can determine started
  const flags = [];
  for (const st of (logs||[])){
    let started = null;
    if (st?.start_position) started = true;
    else if (typeof st?.started === "boolean") started = st.started;
    if (started === null) continue;
    flags.push(started);
    if (flags.length >= 3) break;
  }
  if (flags.length < 2) return "unclear";
  const s = flags.reduce((a,b)=>a + (b?1:0),0);
  if (s >= 2) return "starter";
  if (s === 0) return "bench";
  return "unclear";
}

function _trendFromComp(logs){
  // logs sorted desc; use competitive bucket minutes
  const compMins = [];
  for (const st of (logs||[])){
    const min = _parseMinToFloat(st?.min);
    if (!Number.isFinite(min) || min <= 0) continue;
    const margin = _gameMarginFromStat(st);
    if (!Number.isFinite(margin)) continue;
    if (Math.abs(margin) > 12) continue;
    compMins.push(min);
    if (compMins.length >= 6) break;
  }
  if (compMins.length < 4) return { trend:"unknown", recent3:null, prev3:null };
  const recent3 = (compMins.slice(0,3).reduce((a,b)=>a+b,0))/3;
  const prev3 = (compMins.slice(3,6).reduce((a,b)=>a+b,0))/Math.min(3, compMins.length-3);
  const d = recent3 - prev3;
  let trend = "flat";
  if (d >= 4) trend = "up";
  else if (d <= -4) trend = "down";
  return { trend, recent3, prev3 };
}

function _confidenceTag(compGames, role, usedRoleBucket){
  if (!Number.isFinite(compGames)) return null;
  if (compGames >= 8 && role !== "unclear" && usedRoleBucket) return "high";
  if (compGames >= 5) return "med";
  if (compGames >= 3) return "low";
  return null;
}

async function _fetchTeamActivePlayersBDL(env, teamId){
  const js = await fetchBDL(env, "/players/active", { ttl: 3600, qs: { "team_ids[]": String(teamId), "per_page": "100" }});
  const arr = js?.data || [];
  return Array.isArray(arr) ? arr : [];
}

async function _fetchTeamStatsBDLPaged(env, teamId, seasonStart, maxPages=4){
  const all = [];
  let cursor = null;
  for (let i=0;i<maxPages;i++){
    const qs = {
      "team_ids[]": String(teamId),
      "seasons[]": String(seasonStart),
      "per_page": "100",
      "postseason": "false",
    };
    if (cursor) qs.cursor = String(cursor);
    const js = await fetchBDL(env, "/stats", { ttl: 1800, qs });
    const data = js?.data || [];
    if (Array.isArray(data) && data.length) all.push(...data);
    cursor = js?.meta?.next_cursor || js?.meta?.nextCursor || null;
    if (!cursor) break;
  }
  // sort desc by game date
  all.sort((a,b)=>_statGameTs(b)-_statGameTs(a));
  return all;
}

async function _fetchRecentTeamGamesBDL(env, teamId, seasonStart, wantGames=10){
  const out = [];
  let cursor = null;
  for (let i=0;i<6;i++){
    const qs = {
      "team_ids[]": String(teamId),
      "seasons[]": String(seasonStart),
      "per_page": "100",
      "postseason": "false"
    };
    if (cursor) qs.cursor = String(cursor);
    const js = await fetchBDL(env, "/games", { ttl: 300, qs });
    const data = js?.data || [];
    if (Array.isArray(data) && data.length) out.push(...data);
    cursor = js?.meta?.next_cursor || js?.meta?.nextCursor || null;
    if (!cursor) break;
    if (out.length >= wantGames) break;
  }
  out.sort((a,b)=> (Date.parse(b?.date||"")||0) - (Date.parse(a?.date||"")||0));
  return out.slice(0, wantGames);
}

async function _fetchStatsForGameIdsBDL(env, gameIds, maxPages=8){
  const ids = (gameIds||[]).map(x=>String(x)).filter(Boolean);
  if (!ids.length) return [];
  const all = [];
  let cursor = null;
  for (let i=0;i<maxPages;i++){
    const qs = { "per_page":"100", "postseason":"false" };
    // Encode as indexed params to avoid duplicate-key object limitations
    for (let k=0;k<ids.length;k++) qs[`game_ids[${k}]`] = ids[k];
    if (cursor) qs.cursor = String(cursor);
    const js = await fetchBDL(env, "/stats", { ttl: 300, qs });
    const data = js?.data || [];
    if (Array.isArray(data) && data.length) all.push(...data);
    cursor = js?.meta?.next_cursor || js?.meta?.nextCursor || null;
    if (!cursor) break;
  }
  all.sort((a,b)=>_statGameTs(b)-_statGameTs(a));
  return all;
}


function _groupStatsByPlayer(stats){
  const m = new Map();
  for (const st of (stats||[])){
    const pid = Number(st?.player?.id || st?.player_id || st?.playerId);
    if (!Number.isFinite(pid) || pid<=0) continue;
    const arr = m.get(pid) || [];
    arr.push(st);
    m.set(pid, arr);
  }
  // Ensure each player's logs sorted desc
  for (const [pid, arr] of m.entries()){
    arr.sort((a,b)=>_statGameTs(b)-_statGameTs(a));
  }
  return m;
}

function _inferPlayerMinutesBDL(player, logs){
  const pid = Number(player?.id || player?.player_id || player?.playerId);
  const name = String(player?.first_name ? `${player.first_name} ${player.last_name||""}` : (player?.name || player?.full_name || "")).trim() || null;

  const role = _detectRoleFromLogs(logs);
  const trendObj = _trendFromComp(logs);

  // competitive
  let usedRoleBucket = false;
  let comp = { minutes:null, n:0 };
  if (role === "starter"){
    const rs = _bucketMinutesRole(logs, { bucket:"comp", role:"starter", maxGames:10 });
    if (Number.isFinite(rs.minutes)) { comp = rs; usedRoleBucket = true; }
    else comp = _bucketMinutes(logs, { bucket:"comp", maxGames:10 });
  } else if (role === "bench"){
    const rb = _bucketMinutesRole(logs, { bucket:"comp", role:"bench", maxGames:10 });
    if (Number.isFinite(rb.minutes)) { comp = rb; usedRoleBucket = true; }
    else comp = _bucketMinutes(logs, { bucket:"comp", maxGames:10 });
  } else { // unclear
    comp = _bucketMinutes(logs, { bucket:"comp", maxGames:10 });
    // stricter minimum for unclear
    if (comp.n < 4) comp = { minutes:null, n: comp.n };
  }

  // blowout
  const blow = _bucketMinutes(logs, { bucket:"blow", maxGames:10 });

  

  return {
    player_id: Number.isFinite(pid)?pid:null,
    player_name: name,
    minutes_comp: Number.isFinite(comp.minutes) ? round4(comp.minutes) : null,
    minutes_blow: Number.isFinite(blow.minutes) ? round4(blow.minutes) : null,
    blowout_delta: (Number.isFinite(comp.minutes) && Number.isFinite(blow.minutes)) ? round4(comp.minutes - blow.minutes) : null,
    role,
    confidence,
    evidence: {
      comp_games: comp.n || 0,
      blow_games: blow.n || 0,
      trend: trendObj.trend,
      recent3_comp: Number.isFinite(trendObj.recent3) ? round4(trendObj.recent3) : null,
      prev3_comp: Number.isFinite(trendObj.prev3) ? round4(trendObj.prev3) : null,
      used_role_bucket: usedRoleBucket,
    },
    source: "bdl_inferred",
  };
}

async function buildMinutesBDLSnapshot(env, { date, teams=null, maxPages=4, wantGames=10 } = {}){
  const d = _asISODate(date);
  if (!d) return { ok:false, error:"bad_date", data:null, meta:{ build_id: BUILD_ID } };

  const seasonStart = _inferSeasonStartYearFromDate(d);
  if (!seasonStart) return { ok:false, error:"bad_season", data:null, meta:{ build_id: BUILD_ID } };

  // Fetch teams map once
  const teamsJs = await fetchBDL(env, "/teams", { ttl: 86400, qs: { per_page: "100" }});
  const teamsArr = teamsJs?.data || [];
  const idToAbbr = new Map();
  const abbrToId = new Map();
  for (const t of (teamsArr||[])){
    const id = Number(t?.id);
    const ab = String(t?.abbreviation||"").toUpperCase();
    if (Number.isFinite(id) && ab) { idToAbbr.set(id, ab); abbrToId.set(ab, id); }
  }

  // Determine slate teams if not provided
  let teamAbbrs = [];
  if (Array.isArray(teams) && teams.length){
    teamAbbrs = teams.map(x=>String(x||"").toUpperCase()).filter(Boolean);
  } else {
    const gamesJs = await fetchBDL(env, "/games", { ttl: 300, qs: { "dates[]": d, "per_page":"100" }});
    const games = gamesJs?.data || [];
    for (const g of (games||[])){
      const h = String(g?.home_team?.abbreviation||"").toUpperCase();
      const a = String(g?.visitor_team?.abbreviation||"").toUpperCase();
      if (h) teamAbbrs.push(h);
      if (a) teamAbbrs.push(a);
    }
    teamAbbrs = Array.from(new Set(teamAbbrs));
  }

  const snapshot = { date: d, season_start: seasonStart, teams: {}, meta: { build_id: BUILD_ID, source:"bdl", teams: teamAbbrs.length } };
  const meta = { date: d, season_start: seasonStart, teams: teamAbbrs, players:0, minutes_comp_nonnull:0, minutes_blow_nonnull:0, null_minutes_comp:0, null_minutes_blow:0, ts: new Date().toISOString(), build_id: BUILD_ID };

  for (const abbr of teamAbbrs){
    const teamId = abbrToId.get(abbr);
    if (!teamId) { snapshot.teams[abbr] = { ok:false, error:"team_id_missing", players:[] }; continue; }

    const players = await _fetchTeamActivePlayersBDL(env, teamId);
    const gamesRecent = await _fetchRecentTeamGamesBDL(env, teamId, seasonStart, wantGames);
const gameIds = (gamesRecent||[]).map(g=>g?.id).filter(x=>x!==null && x!==undefined);
const stats = await _fetchStatsForGameIdsBDL(env, gameIds, 8);
    const byPlayer = _groupStatsByPlayer(stats);

    const outPlayers = [];
    for (const p of players){
      const pid = Number(p?.id);
      const logs = byPlayer.get(pid) || [];
      const inf = _inferPlayerMinutesBDL(p, logs);
      outPlayers.push(inf);
      meta.players++;
      if (inf.minutes_comp === null) meta.null_minutes_comp++; else meta.minutes_comp_nonnull++;
      if (inf.minutes_blow === null) meta.null_minutes_blow++; else meta.minutes_blow_nonnull++;
    }
    snapshot.teams[abbr] = { ok:true, team_id: teamId, players: outPlayers };
  }

  // write KV (strictly real output; nulls are allowed, but no synthetic)
  try{
    await kvPutJson(env, _kvKeyBdlMinutes(d), snapshot, { ttl: 86400 * 3 });
    await kvPutJson(env, _kvKeyBdlMinutesMeta(d), meta, { ttl: 86400 * 7 });
  } catch(e){
    return { ok:false, error:"kv_write_failed", data:null, meta:{ build_id: BUILD_ID, message: String(e?.message||e) } };
  }

  return { ok:true, error:null, data: snapshot, meta };
}

async function handleMinutesBdlBuild(req, env, url){
  const date = url.searchParams.get("date") || url.searchParams.get("d") || "";
  const teamsParam = url.searchParams.get("teams") || "";
  const teams = teamsParam ? teamsParam.split(",").map(s=>String(s||"").trim().toUpperCase()).filter(Boolean) : null;
  const maxPages = asInt(url.searchParams.get("pages") || "4");
      const wantGames = asInt(url.searchParams.get("games") || "10");
  const out = await buildMinutesBDLSnapshot(env, { date, teams, maxPages: Math.max(1, Math.min(6, maxPages)) });
  if (!out.ok) return jsonResponse({ ok:false, data:null, meta: out.meta||{ build_id: BUILD_ID }, error: out.error }, 400);
  return jsonResponse({ ok:true, data: out.data, meta: out.meta, error:null }, 200);
}

async function handleMinutesBdlGet(req, env, url){
  const date = _asISODate(url.searchParams.get("date") || "");
  if (!date) return jsonResponse({ ok:false, data:null, meta:{ build_id: BUILD_ID }, error:"bad_date" }, 400);
  const snap = await kvGetJson(env, _kvKeyBdlMinutes(date));
  if (!snap) return jsonResponse({ ok:false, data:null, meta:{ build_id: BUILD_ID, date }, error:"minutes_bdl_snapshot:not_found" }, 404);
  const meta = await kvGetJson(env, _kvKeyBdlMinutesMeta(date));
  return jsonResponse({ ok:true, data: snap, meta: Object.assign({ build_id: BUILD_ID }, meta||{}), error:null }, 200);
}

async function handleMinutesBdlAudit(req, env, url){
  const date = _asISODate(url.searchParams.get("date") || "");
  if (!date) return jsonResponse({ ok:false, data:null, meta:{ build_id: BUILD_ID }, error:"bad_date" }, 400);
  const snap = await kvGetJson(env, _kvKeyBdlMinutes(date));
  if (!snap) return jsonResponse({ ok:false, data:null, meta:{ build_id: BUILD_ID, date }, error:"minutes_bdl_snapshot:not_found" }, 404);

  const teams = snap?.teams || {};
  const out = { date, teams: {}, summary: { teams:0, players:0, comp_nonnull:0, blow_nonnull:0, comp_null:0, blow_null:0 }, build_id: BUILD_ID };

  for (const [abbr, t] of Object.entries(teams)){
    out.summary.teams++;
    const players = t?.players || [];
    const comp_null = players.filter(p=>p?.minutes_comp===null).length;
    const blow_null = players.filter(p=>p?.minutes_blow===null).length;
    const comp_nonnull = players.length - comp_null;
    const blow_nonnull = players.length - blow_null;
    out.summary.players += players.length;
    out.summary.comp_null += comp_null;
    out.summary.blow_null += blow_null;
    out.summary.comp_nonnull += comp_nonnull;
    out.summary.blow_nonnull += blow_nonnull;

    const nullSamples = players.filter(p=>p?.minutes_comp===null).slice(0,6).map(p=>({ player_id:p.player_id, player_name:p.player_name, role:p.role, confidence:p.confidence, evidence:p.evidence||{} }));
    out.teams[abbr] = { players: players.length, comp_null, blow_null, null_samples: nullSamples };
  }

  return jsonResponse({ ok:true, data: out, meta:{ build_id: BUILD_ID }, error:null }, 200);
}


