function _rtp688Ymd(v){
  const s = String(v || "").trim();
  return s ? s.slice(0,10) : "";
}
function _rtp688Season(v){ const n = Number(v || 2026); return Number.isFinite(n) ? n : 2026; }
function _rtp688Team(v){ try{ return canonTeamAbbr(v || ""); }catch(_){ try{return normalizeTeamAbbr(v||"");}catch(__){ return String(v||"").toUpperCase().slice(0,3); } } }
function _rtp688AddDays(ymd, days){
  const d = new Date(`${_rtp688Ymd(ymd)}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + Number(days||0));
  return d.toISOString().slice(0,10);
}
function _rtp688Dates(start, end, maxDates){
  const out = [];
  let cur = _rtp688Ymd(start), stop = _rtp688Ymd(end || start);
  const max = Math.max(1, Number(maxDates || 1));
  for(let i=0; cur && stop && cur <= stop && i<max; i++){
    out.push(cur);
    cur = _rtp688AddDays(cur, 1);
  }
  return out;
}
function _rtp688ArchiveIndexKey(season, kind){ return `nba:archive:index:v1:S${_rtp688Season(season)}:${kind}`; }
function _rtp688ArchiveDateIndexKey(season, date){ return `nba:archive:date:v1:S${_rtp688Season(season)}:${_rtp688Ymd(date)}`; }
