function _rtp688OddsGameKey(season, date, home, away){ return `nba:archive:oddsapi:game:v1:S${_rtp688Season(season)}:${_rtp688Ymd(date)}:${_rtp688Team(home)}:${_rtp688Team(away)}`; }
