// Service-worker wrapper (Cloudflare Dashboard default)

// ===============================
// Props Calibration (v1)  real-or-null
// ===============================
// Goal: calibrate p_raw -> p_cal so "A anchors" are trustworthy.
// Storage uses RTP_CACHE; no synthetic fills.
// Keys:
//  - nba:cal:props:predbatch:<date>
//  - nba:cal:props:pred:<date>:<gameKey>:<playerId>:<market>:<line>:<side>
//  - nba:cal:props:actual:<date>
//  - nba:cal:props:train:<date>
//  - nba:cal:props:model:v1  (global Platt scaling)

const KV_CAL_PROPS_PREDBATCH_PREFIX = "nba:cal:props:predbatch:";
const KV_CAL_PROPS_PRED_PREFIX      = "nba:cal:props:pred:";
const KV_CAL_PROPS_ACTUAL_PREFIX    = "nba:cal:props:actual:";
const KV_CAL_PROPS_TRAIN_PREFIX     = "nba:cal:props:train:";
const KV_CAL_PROPS_MODEL_KEY        = "nba:cal:props:model:v1";

function _isoDateUTC(d=new Date()) { return d.toISOString().slice(0,10); }
function _num(x){ const n=Number(x); return Number.isFinite(n)?n:null; }
function _clip01(p){ if (!Number.isFinite(p)) return null; return Math.max(1e-6, Math.min(1-1e-6, p)); }
function _logit(p){ p=_clip01(p); if (p==null) return null; return Math.log(p/(1-p)); }
function _sigmoid(z){ return 1/(1+Math.exp(-z)); }

function _kvCalPredBatchKey(date){ return `${KV_CAL_PROPS_PREDBATCH_PREFIX}${date}`; }
function _kvCalPredKey(date, gameKey, playerId, market, line, side){
  const g = (gameKey||"").replace(/\s+/g,"").toUpperCase() || "UNK";
  const m = (market||"").replace(/\s+/g,"").toLowerCase() || "unk";
  const s = (side||"").toLowerCase() || "unk";
  const l = (line==null?"":String(line));
  return `${KV_CAL_PROPS_PRED_PREFIX}${date}:${g}:${playerId}:${m}:${l}:${s}`;
}
function _kvCalActualKey(date){ return `${KV_CAL_PROPS_ACTUAL_PREFIX}${date}`; }
function _kvCalTrainKey(date){ return `${KV_CAL_PROPS_TRAIN_PREFIX}${date}`; }

function _marketKey(market){
  const m = (market||"").toLowerCase();
  if (m.includes("pra")) return "pra";
  if (m.includes("pr")) return "pr";
  if (m.includes("pa")) return "pa";
  if (m.includes("ra")) return "ra";
  if (m.includes("pts") || m === "points") return "pts";
  if (m.includes("reb") || m === "rebounds") return "reb";
  if (m.includes("ast") || m === "assists") return "ast";
  if (m.includes("3") || m.includes("threes")) return "fg3m";
  if (m.includes("ft")) return "ftm";
  return "other";
}


function _applyCalPropsModel(p_raw, market, model){
  if (p_raw == null || !isFiniteNumber(p_raw)) return null;
  if (!model || typeof model !== "object") return null;
  const bucket = _marketKey(market);
  const params = (model.buckets && model.buckets[bucket]) ? model.buckets[bucket] : (model.global || null);
  if (!params) return null;
  const a = isFiniteNumber(params.a) ? Number(params.a) : 1;
  const b = isFiniteNumber(params.b) ? Number(params.b) : 0;
  const p = _clip01(Number(p_raw));
  const logit = _logit(p);
  const out = _sigmoid(a * logit + b);
  return _clip01(out);
}
function _detectPlayerStatArrays(box){
  const arrays=[];
  for (const [k,v] of Object.entries(box||{})){
    if (!Array.isArray(v) || !v.length) continue;
    const o=v[0];
    if (!o || typeof o!=="object") continue;
    const hasPlayer = o.player || o.player_id || o.playerId || (o.player && (o.player.id||o.player.player_id));
    const hasAnyStat = ("min" in o) || ("minutes" in o) || ("pts" in o) || ("reb" in o) || ("ast" in o) || ("fg3m" in o) || ("ftm" in o);
    if (hasPlayer && hasAnyStat) arrays.push(v);
  }
  return arrays;
}

function _extractActualsFromBoxScores(items){
  const out = new Map(); // player_id -> {mins,pts,reb,ast,fg3m,ftm,pra}
  for (const box of (items||[])){
    const arrays = _detectPlayerStatArrays(box);
    for (const arr of arrays){
      for (const row of arr){
        const pid = row.player_id ?? row.playerId ?? row?.player?.id ?? row?.player?.player_id ?? null;
        const player_id = _num(pid);
        if (!player_id) continue;
        const mins = _num(row.min ?? row.minutes ?? row.min_sec ?? row.min_total ?? row.mins);
        const pts  = _num(row.pts ?? row.points);
        const reb  = _num(row.reb ?? row.rebounds);
        const ast  = _num(row.ast ?? row.assists);
        const fg3m = _num(row.fg3m ?? row.fg3m_total ?? row.three_pm ?? row.threes_made);
        const ftm  = _num(row.ftm ?? row.ftm_total ?? row.ft_made);
        // keep real-or-null: only write if we saw at least one core stat
        if (pts==null && reb==null && ast==null && fg3m==null && ftm==null && mins==null) continue;
        const prev = out.get(player_id) || {};
        const merged = {
          player_id,
          min: (mins!=null?mins:prev.min??null),
          pts: (pts!=null?pts:prev.pts??null),
          reb: (reb!=null?reb:prev.reb??null),
          ast: (ast!=null?ast:prev.ast??null),
          fg3m:(fg3m!=null?fg3m:prev.fg3m??null),
          ftm: (ftm!=null?ftm:prev.ftm??null),
        };
        merged.pra = (merged.pts!=null && merged.reb!=null && merged.ast!=null) ? (merged.pts+merged.reb+merged.ast) : (prev.pra??null);
        out.set(player_id, merged);
      }
    }
  }
  return out;
}


function _requireCalAuth(req, env){
  // Optional auth guard for calibration endpoints.
  // If CAL_TOKEN is set in env, require Authorization: Bearer <token> OR x-cal-token header.
  const tok = env && env.CAL_TOKEN ? String(env.CAL_TOKEN).trim() : "";
  if (!tok) return null; // no auth required
  const h = req.headers || new Headers();
  const auth = String(h.get("authorization")||"").trim();
  const x = String(h.get("x-cal-token")||"").trim();
  const bearer = auth.toLowerCase().startsWith("bearer ") ? auth.slice(7).trim() : "";
  const provided = x || bearer;
  if (!provided || provided !== tok){
    return fail(env, "cal_auth:unauthorized", { required: true }, 401);
  }
  return null;
}

function _safeProb01(x){
  const v = Number(x);
  if (!Number.isFinite(v)) return { v: null, ok: true };
  if (v < 0 || v > 1) return { v: null, ok: false };
  return { v, ok: true };
}

async function handleCalPropsLog(req, env, url){
  if (!env.RTP_CACHE) return fail(env, "kv_missing:RTP_CACHE", {}, 500);
  const authResp = _requireCalAuth(req, env);
  if (authResp) return authResp;

  let body=null;
  try { body = await req.json(); } catch { body = null; }
  if (!body) return fail(env, "cal_props_log:missing_json", {}, 400);

  const date = (body.date || url.searchParams.get("date") || _isoDateUTC()).slice(0,10);
  const items = Array.isArray(body.items) ? body.items : [body];

  // Load existing daily batch and append/dedupe to make this bulletproof across multiple calls per day.
  const batchKey = _kvCalPredBatchKey(date);
  let existing = null;
  try { existing = await kvGetJson(env, batchKey); } catch { existing = null; }
  const byId = new Map();
  const storedKeys = [];
  let warnings = { p_raw_oob: 0, skipped_missing: 0 };

  if (existing && Array.isArray(existing.items)){
    for (const r of existing.items){
      if (r && r._id) byId.set(String(r._id), r);
    }
  }

  for (const it of items){
    const player_id = _num(it.player_id ?? it.playerId);
    const market = it.market || it.market_key || it.stat || it.type;
    const side = (it.side || it.dir || it.over_under || "").toLowerCase() || (it.is_over===true ? "over" : it.is_over===false ? "under" : "");
    const line = (it.line!=null?it.line:it.line_value!=null?it.line_value:it.line_pts!=null?it.line_pts:null);
    const gameKey = it.game_key || it.matchup_key || it.gameKey || (it.away && it.home ? `${it.away}@${it.home}` : "");
    const mu = (it.mu!=null?Number(it.mu):it.mean!=null?Number(it.mean):it.proj!=null?Number(it.proj):null);
    const sigma = (it.sigma!=null?Number(it.sigma):it.sd!=null?Number(it.sd):null);

    const lineNum = _num(line);
    const side2 = side || (mu!=null && lineNum!=null ? (mu>=lineNum ? "over":"under") : "unk");

    if (!player_id || !market || lineNum==null){
      warnings.skipped_missing++;
      continue;
    }

    // p_raw validation: store only if in [0,1], otherwise null + warning (no synthetic).
    const pCandidate = (it.p_raw!=null?it.p_raw:it.model_prob_over!=null?it.model_prob_over:null);
    const pSafe = _safeProb01(pCandidate);
    if (!pSafe.ok) warnings.p_raw_oob++;

    const key = _kvCalPredKey(date, gameKey, player_id, market, lineNum, side2);
    const row = {
      _id: key, // stable id for dedupe
      date,
      game_key: gameKey || null,
      player_id,
      market,
      market_bucket: _marketKey(market),
      side: side2,
      line: lineNum,
      mu: (Number.isFinite(mu)?mu:null),
      sigma: (Number.isFinite(sigma)?sigma:null),
      p_raw: pSafe.v,
      // keep everything else for audit (minutes source, flags, etc.)
      meta: it.meta || it.meta_cal || it.cal_meta || null,
      build_id: BUILD_ID
    };

    // Store individual prediction row (idempotent by key).
    await kvPutJson(env, key, row, 60*60*24*180); // 180d
    storedKeys.push(key);

    // Merge into batch (latest wins if same id).
    byId.set(String(key), row);
  }

  const merged = [...byId.values()];
  await kvPutJson(env, batchKey, { date, items: merged, count: merged.length, warnings, build_id: BUILD_ID }, 60*60*24*180);

  return ok(env, { date, stored: storedKeys.length, batch_total: merged.length, warnings }, { build_id: BUILD_ID, path: "/cal/props/log" });
}


async function handleCalPropsResolve(req, env, url){
  if (!env.RTP_CACHE) return fail(env, "kv_missing:RTP_CACHE", {}, 500);
  const authResp = _requireCalAuth(req, env);
  if (authResp) return authResp;
  const date = (url.searchParams.get("date") || "").slice(0,10);
  if (!date) return fail(env, "cal_props_resolve:missing_date", { need:["date"] }, 400);

  // Pull box scores for the date (BDL)
  const data = await fetchBDLAll2(env, "/box_scores", { date }, { ttl: 30, maxPages: 10, base: BDL_NBA_BASE });
  const map = _extractActualsFromBoxScores(data);
  const actuals = {};
  for (const [pid, row] of map.entries()) actuals[String(pid)] = row;

  const key = _kvCalActualKey(date);
  await kvPutJson(env, key, { date, count: map.size, actuals, build_id: BUILD_ID }, 60*60*24*365);
  return ok(env, { date, count: map.size, key }, { build_id: BUILD_ID, source: "bdl_box_scores" });
}

async function handleCalPropsJoin(req, env, url){
  if (!env.RTP_CACHE) return fail(env, "kv_missing:RTP_CACHE", {}, 500);
  const authResp = _requireCalAuth(req, env);
  if (authResp) return authResp;
  const date = (url.searchParams.get("date") || "").slice(0,10);
  if (!date) return fail(env, "cal_props_join:missing_date", { need:["date"] }, 400);

  const predBatch = await kvGetJson(env, _kvCalPredBatchKey(date));
  if (!predBatch?.items?.length) return fail(env, "cal_props_join:no_preds", { key:_kvCalPredBatchKey(date) }, 404);

  const actualObj = await kvGetJson(env, _kvCalActualKey(date));
  if (!actualObj?.actuals) return fail(env, "cal_props_join:no_actuals", { key:_kvCalActualKey(date) }, 404);

  const actuals = actualObj.actuals;
  const rows=[];
  for (const p of predBatch.items){
    const pid = String(p.player_id);
    const a = actuals[pid];
    if (!a) continue; // real-or-null: can't label without actual
    const bucket = p.market_bucket || _marketKey(p.market);
    let actualVal = null;
    if (bucket === "pts") actualVal = a.pts;
    else if (bucket === "reb") actualVal = a.reb;
    else if (bucket === "ast") actualVal = a.ast;
    else if (bucket === "fg3m") actualVal = a.fg3m;
    else if (bucket === "ftm") actualVal = a.ftm;
    else if (bucket === "pra") actualVal = a.pra;
    else actualVal = null;
    if (actualVal==null || p.line==null) continue;

    const hit_over = actualVal > p.line;
    const y = (p.side === "under") ? (actualVal < p.line ? 1 : 0) : (hit_over ? 1 : 0);

    const p_raw = _clip01(p.p_raw);
    const row = {
      date,
      player_id: p.player_id,
      game_key: p.game_key || null,
      market: p.market,
      market_bucket: bucket,
      side: p.side,
      line: p.line,
      mu: p.mu ?? null,
      sigma: p.sigma ?? null,
      p_raw: (p_raw!=null?p_raw:null),
      y,
      actual: actualVal,
      min: a.min ?? null,
      build_id: BUILD_ID
    };
    rows.push(row);
  }

  const key = _kvCalTrainKey(date);
  await kvPutJson(env, key, { date, count: rows.length, rows, build_id: BUILD_ID }, 60*60*24*365);
  return ok(env, { date, count: rows.length, key }, { build_id: BUILD_ID });
}

function _fitPlatt(rows){
  // Fit p_cal = sigmoid(a*logit(p_raw) + b)
  let a=1.0, b=0.0;
  const xs=[], ys=[];
  for (const r of rows){
    const x=_logit(r.p_raw);
    if (x==null) continue;
    const y=Number(r.y);
    if (!(y===0||y===1)) continue;
    xs.push(x); ys.push(y);
  }
  const n=xs.length;
  if (n<50) return { ok:false, error:"insufficient_rows", n };
  const lr=0.05;
  for (let it=0; it<400; it++){
    let da=0, db=0;
    for (let i=0;i<n;i++){
      const z=a*xs[i]+b;
      const p=_sigmoid(z);
      const e=p-ys[i];
      da += e*xs[i];
      db += e;
    }
    da/=n; db/=n;
    a -= lr*da;
    b -= lr*db;
    // mild stabilization
    if (!Number.isFinite(a) || !Number.isFinite(b)) { a=1.0; b=0.0; break; }
  }
  return { ok:true, a, b, n };
}

async function handleCalPropsFit(req, env, url){
  if (!env.RTP_CACHE) return fail(env, "kv_missing:RTP_CACHE", {}, 500);
  const authResp = _requireCalAuth(req, env);
  if (authResp) return authResp;
  const days = Number(url.searchParams.get("days") || "30") || 30;
  const end = (url.searchParams.get("end") || _isoDateUTC()).slice(0,10);
  const endDate = new Date(end+"T00:00:00Z");
  if (isNaN(endDate.getTime())) return fail(env, "cal_props_fit:bad_end", { end }, 400);

  const allRows=[];
  const byBucket = new Map();
  for (let i=0;i<days;i++){
    const d=new Date(endDate.getTime()-i*86400000);
    const date=_isoDateUTC(d);
    const train = await kvGetJson(env, _kvCalTrainKey(date));
    const rows = train?.rows || [];
    for (const r of rows){
      if (r.p_raw==null) continue;
      allRows.push(r);
      const b=r.market_bucket || "other";
      if (!byBucket.has(b)) byBucket.set(b, []);
      byBucket.get(b).push(r);
    }
  }

  const globalFit=_fitPlatt(allRows);
  const bucketFits={};
  for (const [b, rows] of byBucket.entries()){
    const fit=_fitPlatt(rows);
    if (fit.ok) bucketFits[b]= { a: fit.a, b: fit.b, n: fit.n };
  }

  const model = {
    version: "v1",
    trained_on: { end, days },
    global: globalFit.ok ? { a: globalFit.a, b: globalFit.b, n: globalFit.n } : null,
    buckets: bucketFits,
    build_id: BUILD_ID,
    ts: new Date().toISOString()
  };

  await kvPutJson(env, KV_CAL_PROPS_MODEL_KEY, model, 60*60*24*365);
  return ok(env, model, { build_id: BUILD_ID });
}

async function handleCalPropsModelGet(env){
  const model = await kvGetJson(env, KV_CAL_PROPS_MODEL_KEY);
  if (!model) return fail(env, "cal_props_model:not_found", { key: KV_CAL_PROPS_MODEL_KEY }, 404);
  return ok(env, model, { build_id: BUILD_ID });
}


