// ===========================
// RTP v4.0 ELITE PATCH
// ===========================

// ---------- REST ----------
function getRestProfile(env, team) {
  try {
    const rows = env?.rest_days_stats || [];
    return rows.find(r => r.team === team) || null;
  } catch { return null; }
}

function computeRestEdge(homeTeam, awayTeam, env) {
  const h = getRestProfile(env, homeTeam);
  const a = getRestProfile(env, awayTeam);

  if (!h || !a) return { edge: 0, used: false };

  const hScore = (h["1_day_aed"] || 0) * 0.6 + (h["2_days_aed"] || 0) * 0.4;
  const aScore = (a["1_day_aed"] || 0) * 0.6 + (a["2_days_aed"] || 0) * 0.4;

  return {
    edge: hScore - aScore,
    used: true
  };
}

function applyRestAdjustments(restEdgeScore) {
  if (!restEdgeScore.used) return { spreadAdj: 0, totalAdj: 0 };

  return {
    spreadAdj: restEdgeScore.edge * 0.08,
    totalAdj: restEdgeScore.edge * 0.03
  };
}

// ---------- MINUTES ----------
async function getMinutesProfile(KV, team, dateISO) {
  try {
    const key = `nba:rw:minutes:${dateISO}:${team}`;
    return await KV.get(key, "json");
  } catch { return null; }
}

function computeMinutesImpact(home, away) {
  if (!home || !away) return { spreadAdj: 0, totalAdj: 0, used: false };

  const sum = arr =>
    (arr?.players || [])
      .sort((a,b)=> (b.minutes||0)-(a.minutes||0))
      .slice(0,8)
      .reduce((acc,p)=> acc + (p.minutes||0), 0);

  const hMin = sum(home);
  const aMin = sum(away);

  if (!hMin || !aMin) return { spreadAdj: 0, totalAdj: 0, used: false };

  const diff = hMin - aMin;

  return {
    spreadAdj: diff * 0.04,
    totalAdj: diff * 0.015,
    used: true
  };
}

// ---------- TRAVEL ----------
const TEAM_TZ = {
  BOS:-5, NYK:-5, MIA:-5,
  LAL:-8, GSW:-8, DEN:-7,
  OKC:-6, MIL:-6
};

function computeTravelEdge(home, away) {
  const tzDiff = Math.abs((TEAM_TZ[home]||0) - (TEAM_TZ[away]||0));

  return {
    spreadAdj: tzDiff * 0.25,
    totalAdj: -tzDiff * 0.1,
    used: tzDiff > 0
  };
}

// ---------- CONFIDENCE ----------
function computeConfidenceElite(edge, sigma) {
  if (!sigma) return 0;
  const z = Math.abs(edge / sigma);
  return 1 / (1 + Math.exp(-z * 1.4));
}

// ---------- CONFIDENCE WRAPPER (v4.1.7 clean) ----------
function computeConfidence(totalEdgeFinal, spreadEdgeFinal, zTot, zSpr) {
  // Prefer z-based confidence when provided; otherwise conservative edge-based fallback.
  const edgeTot = (totalEdgeFinal != null) ? Math.abs(totalEdgeFinal) : null;
  const edgeSpr = (spreadEdgeFinal != null) ? Math.abs(spreadEdgeFinal) : null;

  const zTotAbs = (zTot != null) ? Math.abs(zTot) : null;
  const zSprAbs = (zSpr != null) ? Math.abs(zSpr) : null;

  const total = (zTotAbs != null) ? _clamp(zTotAbs / 3, 0, 1)
              : (edgeTot != null) ? _clamp(edgeTot / 12, 0, 0.25)
              : 0;

  const spread = (zSprAbs != null) ? _clamp(zSprAbs / 3, 0, 1)
               : (edgeSpr != null) ? _clamp(edgeSpr / 7, 0, 0.25)
               : 0;

  return { total, spread, overall: Math.max(total, spread) };
}

// ---------- GRADE WRAPPER (v4.1.7 clean) ----------
function gradeFromEdge(edge, type) {
  const a = (edge != null) ? Math.abs(edge) : null;
  if (a == null) return "";
  if (type === "spread") {
    if (a >= 5) return "A";
    if (a >= 3) return "B";
    if (a >= 1.5) return "C";
  } else {
    if (a >= 8) return "A";
    if (a >= 5) return "B";
    if (a >= 1.5) return "C";
  }
  return "";
}


// ---------- ANCHORS ----------
function buildBetCardElite(data) {
  const sideEdge = Math.abs(data.spread_edge_final);
  const totalEdge = Math.abs(data.total_edge_final);

  const sideConf = data.confidence.spread;
  const totalConf = data.confidence.total;

  let side_action = "PASS";
  let total_action = "PASS";

  if (sideEdge > 5 && sideConf > 0.55 && data.blowout_risk < 0.7) {
    side_action = "ANCHOR";
  } else if (sideEdge > 3 && sideConf > 0.35) {
    side_action = "LEAN";
  }

  if (totalEdge > 5 && totalConf > 0.5 && data.blowout_risk < 0.7) {
    total_action = "ANCHOR";
  } else if (totalEdge > 3 && totalConf > 0.3) {
    total_action = "LEAN";
  }

  return { side_action, total_action };
}


/* === v4.5 STAT DRIFT LAYER === */

function _teamDriftKey(season, team){
  return `nba:team:drift:v1:S${Number(season)}:${normalizeTeamAbbr(team)}`;
}

function _clamp(x, lo, hi){
  const n = Number(x);
  if (!Number.isFinite(n)) return null;
  return Math.max(lo, Math.min(hi, n));
}

// Update per-team drift using a stored attribution row. This is a lightweight EWMA/mean tracker.
async function updateTeamDriftFromCalRow(env, row){
  const season = Number(row?.season);
  const home = normalizeTeamAbbr(row?.home);
  const away = normalizeTeamAbbr(row?.away);
  const game_date = row?.game_date;
  if (!season || !home || !away || !game_date) return;

  const margin_home = _safeNum(row?.final?.margin_home);
  const total_pts = _safeNum(row?.final?.total);

  const model_spread_home = (row?.model?.spread_home==null ? null : _safeNum(row?.model?.spread_home));
  const model_total = (row?.model?.total==null ? null : _safeNum(row?.model?.total));

  // derive predicted team points if model_total/spread exist
  const pred_home_pts = (model_total==null || model_spread_home==null) ? null : (model_total + model_spread_home) / 2;
  const pred_away_pts = (model_total==null || model_spread_home==null) ? null : (model_total - model_spread_home) / 2;

  const act_home_pts = _safeNum(row?.final?.home_score);
  const act_away_pts = _safeNum(row?.final?.away_score);

  // per-team margin: home = margin_home; away = -margin_home
  const act_margin_home = margin_home;
  const act_margin_away = (Number.isFinite(margin_home) ? -margin_home : null);

  const pred_margin_home = (model_spread_home==null ? null : model_spread_home);
  const pred_margin_away = (model_spread_home==null ? null : -model_spread_home);

  // per-team errors (preferred sign: actual - predicted)
  const err_margin_home = (act_margin_home==null || pred_margin_home==null) ? null : (act_margin_home - pred_margin_home);
  const err_margin_away = (act_margin_away==null || pred_margin_away==null) ? null : (act_margin_away - pred_margin_away);

  const err_pts_home = (pred_home_pts==null) ? null : (act_home_pts - pred_home_pts);
  const err_pts_away = (pred_away_pts==null) ? null : (act_away_pts - pred_away_pts);

  // stat edges from factors (home-away diffs); assign away = -diff
  const f = row?.factors || {};
  const diffs = {
    reb: _safeNum(f.reb_diff),
    oreb: _safeNum(f.oreb_diff),
    tov: _safeNum(f.tov_diff),
    ftm: _safeNum(f.ftm_diff),
    fta: _safeNum(f.fta_diff),
    fg3a: _safeNum(f.fg3a_diff),
    pf: _safeNum(f.pf_diff),
    ast: _safeNum(f.ast_diff)
  };

  const homeEdges = {
    reb_edge: Number.isFinite(diffs.reb) ? diffs.reb : null,
    oreb_edge: Number.isFinite(diffs.oreb) ? diffs.oreb : null,
    tov_edge: Number.isFinite(diffs.tov) ? diffs.tov : null,
    ftm_edge: Number.isFinite(diffs.ftm) ? diffs.ftm : null,
    fta_edge: Number.isFinite(diffs.fta) ? diffs.fta : null,
    fg3a_edge: Number.isFinite(diffs.fg3a) ? diffs.fg3a : null,
    pf_edge: Number.isFinite(diffs.pf) ? diffs.pf : null,
    ast_edge: Number.isFinite(diffs.ast) ? diffs.ast : null
  };
  const awayEdges = Object.fromEntries(Object.entries(homeEdges).map(([k,v]) => [k, (v==null ? null : -v)]));

  // Update both teams
  await _updateOneTeamDrift(env, season, home, {
    game_date,
    opp: away,
    side: "home",
    err_margin: err_margin_home,
    err_pts: err_pts_home,
    ...homeEdges
  });

  await _updateOneTeamDrift(env, season, away, {
    game_date,
    opp: home,
    side: "away",
    err_margin: err_margin_away,
    err_pts: err_pts_away,
    ...awayEdges
  });
}

async function _updateOneTeamDrift(env, season, team, obs){
  const key = _teamDriftKey(season, team);
  const prev = await kvGetJSON(env, key);
  const nPrev = Number(prev?.n)||0;
  const n = nPrev + 1;

  // EWMA alpha: slightly decreasing with n, bounded
  const alpha = Math.max(0.10, Math.min(0.30, 2 / (n + 3)));

  const prevE = prev?.ewma || {};
  const ewma = { ...prevE };

  const up = (field, val, capAbs=null) => {
    if (val==null || !Number.isFinite(Number(val))) return;
    let v = Number(val);
    if (capAbs!=null) v = Math.max(-capAbs, Math.min(capAbs, v));
    const p = (ewma[field]==null ? null : Number(ewma[field]));
    ewma[field] = (p==null || !Number.isFinite(p)) ? v : (alpha * v + (1-alpha) * p);
  };

  // caps to prevent blowout tails from poisoning drift too fast
  up("err_margin", obs.err_margin, 25);   // cap single-game margin residual
  up("err_pts", obs.err_pts, 18);         // cap single-game points residual per team
  up("reb_edge", obs.reb_edge, 20);
  up("oreb_edge", obs.oreb_edge, 12);
  up("tov_edge", obs.tov_edge, 12);
  up("ftm_edge", obs.ftm_edge, 20);
  up("fta_edge", obs.fta_edge, 25);
  up("fg3a_edge", obs.fg3a_edge, 30);
  up("pf_edge", obs.pf_edge, 15);
  up("ast_edge", obs.ast_edge, 20);

  const out = {
    v: 1,
    kind: "team_stat_drift",
    ts: new Date().toISOString(),
    season,
    team,
    n,
    alpha,
    ewma,
    last: {
      game_date: obs.game_date,
      opp: obs.opp,
      side: obs.side
    }
  };

  // store
  try { await kvPutJson(env, key, out); } catch (e) {}
}

async function handleTeamDriftGet(env, req, url){
  const season = Number(url.searchParams.get("season"));
  const team = normalizeTeamAbbr(url.searchParams.get("team"));
  if (!season || !team) return json({ ok:false, data:null, meta:{}, error:"team_drift:missing_keys" }, 400);
  const key = _teamDriftKey(season, team);
  const drift = await kvGetJSON(env, key);
  return json({ ok:true, data:{ key, drift: drift || null }, meta:{ build_id: BUILD_ID } });
}

async function handleTeamDriftReset(env, req, url){
  const season = Number(url.searchParams.get("season"));
  const team = normalizeTeamAbbr(url.searchParams.get("team"));
  if (!season || !team) return json({ ok:false, data:null, meta:{}, error:"team_drift:missing_keys" }, 400);
  const key = _teamDriftKey(season, team);
  try {
    // KV has delete; keep consistent with existing env usage
    if (env?.RTP_CACHE?.delete) await env.RTP_CACHE.delete(key);
    return json({ ok:true, data:{ key, deleted:true }, meta:{ build_id: BUILD_ID } });
  } catch (e) {
    return json({ ok:false, data:null, meta:{ key, build_id: BUILD_ID }, error:"team_drift:delete_failed" }, 500);
  }
}


