function _safeGetScores(res){
  const hs = res?.home_score ?? res?.homeScore ?? res?.final?.home_score ?? res?.score?.home;
  const as = res?.away_score ?? res?.awayScore ?? res?.final?.away_score ?? res?.score?.away;
  if(hs == null || as == null) throw new Error("backtest:missing_scores");
  return { home_score: Number(hs), away_score: Number(as) };
}

function _safeGetPred(pred){
  const spread = pred?.spread_final ?? pred?.spread_model ?? pred?.spread_model_raw;
  const total  = pred?.total_final  ?? pred?.total_model  ?? pred?.total_model_raw;
  if(spread == null || total == null) throw new Error("backtest:pred_missing_fields");
  return { spread_home: Number(spread), total: Number(total) };
}

