// ===== PATCH: optimizerRankScore + totals dominance safety =====
function optimizerRankScore(item){
  const best = item?.anchors?.best || {};
  const trust = item?.anchors?.trust || {};

  let score =
    Number(best.score || 0) +
    Number(best.units || 0) * 0.20 +
    Number(best.p_cash || 0) * 0.25;

  if (trust?.totals_elite && best.type === "total") {
    score += 0.18;
  }

  return score;
}



