// ===== RTP PATCH: LOCK EXACT BUCKETS INTO SCRIPT + ANCHORS =====
const RTP_LOCK_BUCKETS_BUILD_ID = (typeof BUILD_ID !== "undefined" && BUILD_ID) ? BUILD_ID : "nba-stats-full-v6.2.3b-promote-minutesctx-lineupctx";

function _rtpBucketRound(p){
  const x = Number(p);
  return Number.isFinite(x) ? Math.round(x * 100) / 100 : null;
}

function _rtpBucketProfile(p){
  const bucket = _rtpBucketRound(p);
  let bucket_label = "noise";
  let bucket_action = "PASS";
  let bucket_grade = "";
  let bucket_rank = 0;
  let is_play_bucket = false;
  let is_worst_bucket = false;

  if (bucket === 0.62) {
    bucket_label = "play_062";
    bucket_action = "PLAY";
    bucket_grade = "A+";
    bucket_rank = 3;
    is_play_bucket = true;
  } else if (bucket === 0.68) {
    bucket_label = "play_068";
    bucket_action = "PLAY";
    bucket_grade = "A";
    bucket_rank = 2;
    is_play_bucket = true;
  } else if (bucket === 0.70) {
    bucket_label = "play_070";
    bucket_action = "PLAY";
    bucket_grade = "A";
    bucket_rank = 1;
    is_play_bucket = true;
  } else if (bucket === 0.63) {
    bucket_label = "worst_063";
    bucket_action = "FADE";
    bucket_grade = "F";
    bucket_rank = -3;
    is_worst_bucket = true;
  } else if (bucket === 0.64) {
    bucket_label = "worst_064";
    bucket_action = "FADE";
    bucket_grade = "F";
    bucket_rank = -3;
    is_worst_bucket = true;
  } else if (bucket === 0.69) {
    bucket_label = "worst_069";
    bucket_action = "FADE";
    bucket_grade = "F";
    bucket_rank = -2;
    is_worst_bucket = true;
  }

  return {
    p_cash_raw: Number.isFinite(Number(p)) ? Number(p) : null,
    p_cash_bucket: bucket,
    bucket_label,
    bucket_action,
    bucket_grade,
    bucket_rank,
    is_play_bucket,
    is_worst_bucket
  };
}

function _rtpAttachBucketLane(lane){
  if (!lane || typeof lane !== "object") return lane;
  const b = _rtpBucketProfile(lane.p_cash);
  lane.p_cash_raw = b.p_cash_raw;
  lane.p_cash_bucket = b.p_cash_bucket;
  lane.bucket_label = b.bucket_label;
  lane.bucket_action = b.bucket_action;
  lane.bucket_grade = b.bucket_grade;
  lane.bucket_rank = b.bucket_rank;
  lane.is_play_bucket = b.is_play_bucket;
  lane.is_worst_bucket = b.is_worst_bucket;
  lane.flags = lane.flags || {};
  lane.flags.p_cash_raw = b.p_cash_raw;
  lane.flags.bucket = b.p_cash_bucket;
  lane.flags.bucket_label = b.bucket_label;
  lane.flags.bucket_action = b.bucket_action;
  lane.flags.bucket_grade = b.bucket_grade;
  lane.flags.is_play_bucket = b.is_play_bucket;
  lane.flags.is_worst_bucket = b.is_worst_bucket;
  if (b.is_worst_bucket) {
    lane.flags.bad_zone = true;
    lane.flags.bad_zone_reason = lane.flags.bad_zone_reason || `worst_bucket_${String(b.p_cash_bucket).replace(".", "")}`;
  }
  return lane;
}

function _rtpChooseBestBucketLane(side, total, priorBest){
  const s = _rtpAttachBucketLane(side || {});
  const t = _rtpAttachBucketLane(total || {});

  if (s.is_play_bucket && !t.is_play_bucket) return { type: "side", ...s };
  if (t.is_play_bucket && !s.is_play_bucket) return { type: "total", ...t };
  if (s.is_worst_bucket && !t.is_worst_bucket) return { type: "total", ...t };
  if (t.is_worst_bucket && !s.is_worst_bucket) return { type: "side", ...s };

  if (s.is_play_bucket && t.is_play_bucket && Number(s.bucket_rank || 0) !== Number(t.bucket_rank || 0)) {
    return Number(s.bucket_rank || 0) > Number(t.bucket_rank || 0) ? { type: "side", ...s } : { type: "total", ...t };
  }

  const sScore = Number(s.score || 0) + Number(s.units || 0) * 0.20 + Number(s.p_cash || 0) * 0.20;
  const tScore = Number(t.score || 0) + Number(t.units || 0) * 0.20 + Number(t.p_cash || 0) * 0.20;
  if (tScore > sScore) return { type: "total", ...t };
  if (sScore > tScore) return { type: "side", ...s };

  if (priorBest && typeof priorBest === "object" && String(priorBest.type || "").toLowerCase() === "total") {
    return { type: "total", ...t };
  }
  return { type: "side", ...s };
}

function _rtpAnnotateAnchorsBuckets(anchors){
  if (!anchors || typeof anchors !== "object") return anchors;
  anchors.side = _rtpAttachBucketLane(anchors.side || {});
  anchors.total = _rtpAttachBucketLane(anchors.total || {});
  anchors.best = _rtpChooseBestBucketLane(anchors.side, anchors.total, anchors.best || null);
  anchors.bucket_model = {
    side_bucket: anchors.side?.p_cash_bucket ?? null,
    total_bucket: anchors.total?.p_cash_bucket ?? null,
    best_bucket: anchors.best?.p_cash_bucket ?? null,
    side_label: anchors.side?.bucket_label ?? "noise",
    total_label: anchors.total?.bucket_label ?? "noise",
    best_label: anchors.best?.bucket_label ?? "noise",
    side_bucket_action: anchors.side?.bucket_action ?? "PASS",
    total_bucket_action: anchors.total?.bucket_action ?? "PASS",
    best_bucket_action: anchors.best?.bucket_action ?? "PASS",
    side_is_play_bucket: !!anchors.side?.is_play_bucket,
    total_is_play_bucket: !!anchors.total?.is_play_bucket,
    best_is_play_bucket: !!anchors.best?.is_play_bucket,
    side_is_worst_bucket: !!anchors.side?.is_worst_bucket,
    total_is_worst_bucket: !!anchors.total?.is_worst_bucket,
    best_is_worst_bucket: !!anchors.best?.is_worst_bucket
  };
  return anchors;
}

function _rtpAnnotateScriptPayload(data){
  if (!data || typeof data !== "object") return data;

  const root = data;
  const target = (root.script && typeof root.script === "object") ? root.script : root;

  const marketSpreadHome = Number.isFinite(Number(target?.market_spread_home)) ? Number(target.market_spread_home)
    : (Number.isFinite(Number(target?.market_spread_input)) ? Number(target.market_spread_input)
    : (Number.isFinite(Number(target?.market?.spread_home)) ? Number(target.market.spread_home)
    : (Number.isFinite(Number(target?.market?.market_spread_home)) ? Number(target.market.market_spread_home) : null)));
  const marketTotal = Number.isFinite(Number(target?.market_total)) ? Number(target.market_total)
    : (Number.isFinite(Number(target?.market?.total)) ? Number(target.market.total)
    : (Number.isFinite(Number(target?.market?.market_total)) ? Number(target.market.market_total) : null));

  const anchors = _rtpAnnotateAnchorsBuckets(target.anchors || {});
  target.anchors = anchors;
  const sideB = anchors?.side || {};
  const totalB = anchors?.total || {};

  target.script_bucket_model = {
    side_bucket: sideB.p_cash_bucket ?? null,
    total_bucket: totalB.p_cash_bucket ?? null,
    side_label: sideB.bucket_label ?? "noise",
    total_label: totalB.bucket_label ?? "noise",
    side_bucket_action: sideB.bucket_action ?? "PASS",
    total_bucket_action: totalB.bucket_action ?? "PASS",
    side_is_play_bucket: !!sideB.is_play_bucket,
    total_is_play_bucket: !!totalB.is_play_bucket,
    side_is_worst_bucket: !!sideB.is_worst_bucket,
    total_is_worst_bucket: !!totalB.is_worst_bucket
  };

  if (target.bet_card && typeof target.bet_card === "object") {
    target.bet_card.side_p_cash = Number.isFinite(Number(anchors?.side?.p_cash_raw)) ? Number(anchors.side.p_cash_raw) : (Number.isFinite(Number(anchors?.side?.p_cash)) ? Number(anchors.side.p_cash) : null);
    target.bet_card.side_p_cash_bucket = sideB.p_cash_bucket ?? null;
    target.bet_card.side_bucket_label = sideB.bucket_label ?? "noise";
    target.bet_card.side_bucket_action = sideB.bucket_action ?? "PASS";
    target.bet_card.side_is_play_bucket = !!sideB.is_play_bucket;
    target.bet_card.side_is_worst_bucket = !!sideB.is_worst_bucket;
    {
      const __home = target?.home || root?.home || root?.home_team || target?.teamwell_snapshot?.home?.team || null;
      const __away = target?.away || root?.away || root?.away_team || target?.teamwell_snapshot?.away?.team || null;
      target.bet_card.side_pick_visible =
        anchors?.side?.pick ||
        inferSidePick(Number(target?.bet_card?.side_edge_pts), __home, __away, marketSpreadHome) ||
        null;
    }
    target.bet_card.total_p_cash = Number.isFinite(Number(anchors?.total?.p_cash_raw)) ? Number(anchors.total.p_cash_raw) : (Number.isFinite(Number(anchors?.total?.p_cash)) ? Number(anchors.total.p_cash) : null);
    target.bet_card.total_p_cash_bucket = totalB.p_cash_bucket ?? null;
    target.bet_card.total_bucket_label = totalB.bucket_label ?? "noise";
    target.bet_card.total_bucket_action = totalB.bucket_action ?? "PASS";
    target.bet_card.total_is_play_bucket = !!totalB.is_play_bucket;
    target.bet_card.total_is_worst_bucket = !!totalB.is_worst_bucket;
    target.bet_card.total_pick_visible =
      anchors?.total?.pick ||
      inferTotalPick(Number(target?.bet_card?.total_edge_pts), marketTotal) ||
      null;
    target.bet_card.total_p_cash_visible =
      Number.isFinite(Number(anchors?.total?.p_cash_raw)) ? Number(anchors.total.p_cash_raw) :
      (Number.isFinite(Number(anchors?.total?.p_cash)) ? Number(anchors.total.p_cash) :
      (Number.isFinite(Number(target?.bet_card?.total_p_cash)) ? Number(target.bet_card.total_p_cash) : null));
  }

  // Promote important nested script fields to the outer payload when handleGameScript wraps them.
  if (root !== target) {
    const promote = [
      'pace','pace_tier','pace_tag','foul_env_score','foul_tag','blowout_risk','rest_edge','rest_edge_days',
      'injury_edge','injury_edge_raw','minutes_edge','minutes_edge_raw','injury_score_home','injury_score_away',
      'total_model','spread_model','market_total','market_spread_input','market_spread_home','market_lines_trust','market_warnings',
      'total_edge_vs_market','spread_edge_vs_market','total_final','spread_final','total_edge_final','spread_edge_final',
      'confidence','bet_card','anchors','gates','script_merge','bucket_model','best_side','best_total','merged_board',
      'model_decision','final_decision','teamwell_snapshot','diagnostics','flags','multipliers','refs_context','refs_impact',
      'notes','injury_lock','lineup_lock','lineup_context','minutes_context','minutes_diag','script_bucket_model'
    ];
    for (const k of promote) {
      if (target[k] !== undefined) root[k] = target[k];
    }
  }

  return data;
}

function _rtpLockBucketRank(rec){
  let score = Number(rec.score || 0) + Number(rec.units || 0) * 0.20 + Number(rec.p_cash || 0) * 0.25;
  score += Number(rec.bucket_rank || 0) * 0.75;
  if (String(rec.action || "") === "ANCHOR") score += 0.50;
  if (String(rec.action || "") === "PLAY") score += 0.25;
  return score;
}

const _rtpOrigHandleGameScript_lock = handleGameScript;
handleGameScript = async function(env, url){
  const resp = await _rtpOrigHandleGameScript_lock(env, url);
  let j = null;
  try { j = await resp.clone().json(); } catch (_) { j = null; }
  if (!j || j.ok !== true || !j.data) return resp;
  j.data = _rtpAnnotateScriptPayload(j.data);
  j.meta = { ...(j.meta || {}), build_id: RTP_LOCK_BUCKETS_BUILD_ID };
  return jsonResponse(j);
};

const _rtpOrigHandleAnchors_lock = handleAnchors;
handleAnchors = async function(env, url){
  const resp = await _rtpOrigHandleAnchors_lock(env, url);
  let j = null;
  try { j = await resp.clone().json(); } catch (_) { j = null; }
  if (!j || j.ok !== true || !j.data) return resp;
  j.data = _rtpAnnotateAnchorsBuckets(j.data);
  j.meta = { ...(j.meta || {}), build_id: RTP_LOCK_BUCKETS_BUILD_ID };
  return jsonResponse(j);
};

const _rtpOrigHandleAnchorsBulk_lock = handleAnchorsBulk;
handleAnchorsBulk = async function(env, req, baseUrl){
  const resp = await _rtpOrigHandleAnchorsBulk_lock(env, req, baseUrl);
  let j = null;
  try { j = await resp.clone().json(); } catch (_) { j = null; }
  if (!j || j.ok !== true || !j.data || !Array.isArray(j.data.items)) return resp;

  for (const item of j.data.items) {
    if (item?.anchors) item.anchors = _rtpAnnotateAnchorsBuckets(item.anchors);
  }

  const recs = [];
  for (const row of j.data.items) {
    const best = row?.anchors?.best;
    if (!best) continue;
    recs.push({
      game_date: row?.meta?.game_date || null,
      home: row?.meta?.home || null,
      away: row?.meta?.away || null,
      type: best?.type || null,
      action: best?.action || null,
      pick: best?.pick || null,
      grade: best?.grade || "",
      units: Number(best?.units || 0),
      p_cash: Number(best?.p_cash || 0),
      p_cash_bucket: best?.p_cash_bucket ?? null,
      bucket_label: best?.bucket_label || "noise",
      bucket_action: best?.bucket_action || "PASS",
      bucket_grade: best?.bucket_grade || "",
      bucket_rank: Number(best?.bucket_rank || 0),
      is_play_bucket: !!best?.is_play_bucket,
      is_worst_bucket: !!best?.is_worst_bucket,
      score: Number(best?.score || 0)
    });
  }

  const top_plays = recs.filter(r => r.is_play_bucket).sort((a,b) => _rtpLockBucketRank(b) - _rtpLockBucketRank(a));
  const duds = recs.filter(r => r.is_worst_bucket || String(r.action || "") === "PASS").sort((a,b) => _rtpLockBucketRank(a) - _rtpLockBucketRank(b));
  const noise = recs.filter(r => !r.is_play_bucket && !r.is_worst_bucket && String(r.action || "") !== "PASS").sort((a,b) => _rtpLockBucketRank(b) - _rtpLockBucketRank(a));

  j.data.optimizer = j.data.optimizer || {};
  j.data.optimizer.play_count = top_plays.length;
  j.data.optimizer.dud_count = duds.length;
  j.data.optimizer.noise_count = noise.length;
  j.data.optimizer.top_plays = top_plays;
  j.data.optimizer.duds = duds;
  j.data.optimizer.noise = noise;
  j.meta = { ...(j.meta || {}), build_id: RTP_LOCK_BUCKETS_BUILD_ID };
  return jsonResponse(j);
};
// ===== END RTP PATCH: LOCK EXACT BUCKETS INTO SCRIPT + ANCHORS =====


