  const primary=(profile?.primary||[]).slice(0,4).map(x=>x.name).filter(Boolean);
  const main = primary[0] || "unknown";
  const dvpTier = _rtp674DvpTierFromRatio(ratio);
  const side = String(edge?.side||"").toUpperCase();
  const tags = [];
  if(main !== "unknown") tags.push(main);
  if(m) tags.push(m.toLowerCase());
  tags.push(dvpTier);
  if(vol >= 0.65) tags.push("volatility_shrink");
  if(blow >= 0.50 && spreadRisk > 0.25) tags.push("blowout_casualty_risk");
  const plus = ratio > 1.04 ? 1 : (ratio < 0.96 ? -1 : 0);
  const sideDir = side === "OVER" ? 1 : side === "UNDER" ? -1 : 0;
  const interactionScore = ((fit - 0.5) * 0.45) + ((ratio - 1) * 1.20 * sideDir) - (vol * 0.08) - (blow * spreadRisk * 0.12);
  const interactionConfidence = _rtp673Clamp((conf * 0.55) + (Math.abs(ratio - 1) * 1.25) + (fit * 0.18), 0, 1);
