    tag,
    tags,
    archetype_tags: primary,
    primary_archetype: main,
    market:m,
    side:side || null,
    dvp_tier:dvpTier,
    dvp_ratio:Number.isFinite(ratio) ? Number(ratio.toFixed(4)) : null,
    market_fit:Number.isFinite(fit) ? Number(fit.toFixed(4)) : null,
    volatility_bomber:Number.isFinite(vol) ? Number(vol.toFixed(4)) : null,
    blowout_casualty:Number.isFinite(blow) ? Number(blow.toFixed(4)) : null,
    spread_risk:Number.isFinite(spreadRisk) ? Number(spreadRisk.toFixed(4)) : null,
    interaction_score:Number(interactionScore.toFixed(4)),
    interaction_confidence:Number(interactionConfidence.toFixed(4)),
    recommendation: (vol >= 0.65 || (blow >= 0.5 && spreadRisk > 0.25)) ? "SHRINK_RISK_ARCHETYPE" : (plus > 0 && fit > 0.60 ? "MATCHUP_PERSONALITY_PLUS" : (plus < 0 && side === "UNDER" ? "UNDER_CONTEXT_PLUS" : "MATCHUP_PERSONALITY_CONTEXT"))
